#!/bin/bash
# shellcheck disable=SC2317

# If the user accidentally runs this script with `sh MRHIS.sh` (which
# does not support many bash extensions used here), re-exec under bash so
# the rest of the file is parsed correctly. This ensures a helpful message
# or automatic re-exec instead of a confusing "unexpected end of file".
if [ -z "${BASH_VERSION:-}" ]; then
    if command -v bash >/dev/null 2>&1; then
        exec bash "$0" "$@"
    else
        echo "MRHIS requires bash. Please install bash and run: bash $0 \"$*\"" >&2
        exit 2
    fi
fi

set -e

# Ensure this script is executed with bash (not /bin/sh). Many parts
# of this script require bash extensions (here-strings, arrays, etc.). If
# the user invoked it with `sh` we'll fail with a clear message instead
# of a misleading "unexpected end of file" parse error.
if [ -z "${BASH_VERSION:-}" ]; then
    echo "MRHIS requires bash. Run with: bash $0 \"$*\"" >&2
    exit 2
fi

MRHIS_EMIT_EXIT_MARKER="${MRHIS_EMIT_EXIT_MARKER:-1}"
trap '_mrhis_rc=$?; if [ "${MRHIS_EMIT_EXIT_MARKER:-1}" = "1" ]; then echo "RHIS_EXIT:${_mrhis_rc}"; fi' EXIT

if [ -t 0 ] && [ -t 1 ]; then
    reset || true
fi

# Global ANSI color helpers (can be disabled via MRHIS_ENABLE_COLORS=0)
# Default to enabled; allow override from environment/vault
MRHIS_ENABLE_COLORS=${MRHIS_ENABLE_COLORS:-1}
if [ "${MRHIS_ENABLE_COLORS}" -ne 0 ] && [ -t 1 ]; then
    RED='\033[0;31m'
    GREEN='\033[0;32m'
    BLUE='\033[0;34m'
    YELLOW='\033[1;33m'
    CYAN='\033[0;36m'
    BOLD='\033[1m'
    DIM='\033[2m'
    NC='\033[0m'
    export ANSIBLE_FORCE_COLOR=1
else
    RED='' GREEN='' BLUE='' YELLOW='' CYAN='' BOLD='' DIM='' NC=''
    export ANSIBLE_FORCE_COLOR=0
fi

# Core path/runtime defaults (kept near the top so all later vars/functions can rely on them).
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MRHIS_SELF_PATH="${SCRIPT_DIR}/$(basename "${BASH_SOURCE[0]}")"
MRHIS_ORIGINAL_ARGS=("$@")
MRHIS_AUTORERUN_AFTER_PROMPT="${MRHIS_AUTORERUN_AFTER_PROMPT:-1}"
ISO_DIR="${ISO_DIR:-/var/lib/libvirt/images}"
ISO_NAME="${ISO_NAME:-rhel-10-everything-x86_64-dvd.iso}"
ISO_PATH="${ISO_PATH:-$ISO_DIR/$ISO_NAME}"
SAT_ISO_NAME="${SAT_ISO_NAME:-rhel-9-everything-x86_64-dvd.iso}"
SAT_ISO_PATH="${SAT_ISO_PATH:-$ISO_DIR/$SAT_ISO_NAME}"
VM_DIR="${VM_DIR:-/var/lib/libvirt/images}"
KS_DIR="${KS_DIR:-/var/lib/libvirt/images/kickstarts}"
FILES_DIR="${FILES_DIR:-/var/lib/libvirt/images/files}"
OEMDRV_ISO="${OEMDRV_ISO:-$ISO_DIR/OEMDRV.iso}"

# Logging defaults - centralize logs under /var/log/MRHIS by default.
# Individual scripts may override these by exporting MRHIS_RUN_LOG_DIR.
MRHIS_RUN_LOG_DIR="${MRHIS_RUN_LOG_DIR:-/var/log/MRHIS}"
MRHIS_LOG="${MRHIS_LOG:-${MRHIS_RUN_LOG_DIR}/mrhis.log}"
MRHIS_TEST_WARNING_FILE="${MRHIS_TEST_WARNING_FILE:-${MRHIS_RUN_LOG_DIR}/test-warnings.log}"
# Try to create the directory if the invoking user can; ignore failures.
mkdir -p "${MRHIS_RUN_LOG_DIR}" >/dev/null 2>&1 || true


# Control whether Satellite installer attempts Insights registration. Default: 0 (disabled for demo).
MRHIS_REGISTER_WITH_INSIGHTS=${MRHIS_REGISTER_WITH_INSIGHTS:-0}
if [ "${MRHIS_REGISTER_WITH_INSIGHTS}" -ne 0 ]; then
    REGISTER_WITH_INSIGHTS_FLAG="--register-with-insights"
else
    REGISTER_WITH_INSIGHTS_FLAG=""
fi

ANSIBLE_ENV_DIR="${ANSIBLE_ENV_DIR:-$HOME/.ansible/conf}"
ANSIBLE_ENV_FILE="${ANSIBLE_ENV_FILE:-$ANSIBLE_ENV_DIR/env.yml}"
DEFAULT_ANSIBLE_VAULT_PASS_FILE_TEXT="$HOME/.ansible/conf/.vaultpass.text"
DEFAULT_ANSIBLE_VAULT_PASS_FILE_TXT="$HOME/.ansible/conf/.vaultpass.txt"
if [ -z "${ANSIBLE_VAULT_PASS_FILE:-}" ]; then
    if [ -s "$DEFAULT_ANSIBLE_VAULT_PASS_FILE_TEXT" ]; then
        ANSIBLE_VAULT_PASS_FILE="$DEFAULT_ANSIBLE_VAULT_PASS_FILE_TEXT"
    elif [ -s "$DEFAULT_ANSIBLE_VAULT_PASS_FILE_TXT" ]; then
        ANSIBLE_VAULT_PASS_FILE="$DEFAULT_ANSIBLE_VAULT_PASS_FILE_TXT"
    else
        ANSIBLE_VAULT_PASS_FILE="$DEFAULT_ANSIBLE_VAULT_PASS_FILE_TEXT"
    fi
fi

MRHIS_ANSIBLE_CFG_BASENAME="${MRHIS_ANSIBLE_CFG_BASENAME:-mrhis-ansible.cfg}"
MRHIS_ANSIBLE_CFG_VAULT_HOST="${MRHIS_ANSIBLE_CFG_VAULT_HOST:-$ANSIBLE_ENV_DIR/${MRHIS_ANSIBLE_CFG_BASENAME}}"
MRHIS_ANSIBLE_CFG_VAULT_CONTAINER="${MRHIS_ANSIBLE_CFG_VAULT_CONTAINER:-/mrhis/vars/vault/${MRHIS_ANSIBLE_CFG_BASENAME}}"
MRHIS_ANSIBLE_CFG_RUNTIME_BASENAME="${MRHIS_ANSIBLE_CFG_RUNTIME_BASENAME:-mrhis-ansible.runtime.cfg}"
MRHIS_ANSIBLE_CFG_HOST="${MRHIS_ANSIBLE_CFG_HOST:-$ANSIBLE_ENV_DIR/${MRHIS_ANSIBLE_CFG_RUNTIME_BASENAME}}"
MRHIS_ANSIBLE_CFG_CONTAINER="${MRHIS_ANSIBLE_CFG_CONTAINER:-/mrhis/vars/vault/${MRHIS_ANSIBLE_CFG_RUNTIME_BASENAME}}"
MRHIS_ANSIBLE_FACT_CACHE_BASENAME="${MRHIS_ANSIBLE_FACT_CACHE_BASENAME:-facts-cache}"
MRHIS_ANSIBLE_FACT_CACHE_HOST="${MRHIS_ANSIBLE_FACT_CACHE_HOST:-$ANSIBLE_ENV_DIR/${MRHIS_ANSIBLE_FACT_CACHE_BASENAME}}"
MRHIS_ANSIBLE_FACT_CACHE_CONTAINER="${MRHIS_ANSIBLE_FACT_CACHE_CONTAINER:-/mrhis/vars/vault/${MRHIS_ANSIBLE_FACT_CACHE_BASENAME}}"
MRHIS_ANSIBLE_FORKS="${MRHIS_ANSIBLE_FORKS:-15}"
MRHIS_ANSIBLE_TIMEOUT="${MRHIS_ANSIBLE_TIMEOUT:-30}"
MRHIS_ANSIBLE_FACT_CACHE_TIMEOUT="${MRHIS_ANSIBLE_FACT_CACHE_TIMEOUT:-86400}"

MRHIS_CONTAINER_IMAGE="${MRHIS_CONTAINER_IMAGE:-quay.io/parmstro/mrhis-provisioner-9-2.5}"
MRHIS_CONTAINER_NAME="${MRHIS_CONTAINER_NAME:-mrhis-provisioner}"
MRHIS_INVENTORY_DIR="${MRHIS_INVENTORY_DIR:-$SCRIPT_DIR/local/vars/external_inventory}"
MRHIS_INVENTORY_FILE="${MRHIS_INVENTORY_FILE:-$MRHIS_INVENTORY_DIR/hosts.yml}"
MRHIS_CONTAINER_INVENTORY_FILE="${MRHIS_CONTAINER_INVENTORY_FILE:-/mrhis/vars/external_inventory/$(basename "${MRHIS_INVENTORY_FILE}")}"
MRHIS_HOST_VARS_DIR="${MRHIS_HOST_VARS_DIR:-$SCRIPT_DIR/host_vars}"
MRHIS_EXECUTION_MODE="${MRHIS_EXECUTION_MODE:-local}"

# Initialize commonly referenced variables to safe defaults to satisfy
# static analysis and ensure predictable behavior when unset.
_mrhis_rc=0
_bundle_ok=1
configured_users=""

# Default flags to pass to shell `dnf` calls (can be overridden externally).
# Includes skip-broken/allowerasing/best and nogpgcheck per user request.
DNF_FLAGS="${DNF_FLAGS:---skip-broken --allowerasing --best --nogpgcheck}"

PRESEED_ENV_FILE="${PRESEED_ENV_FILE:-$SCRIPT_DIR/.env}"
RH_TOKEN_URL="${RH_TOKEN_URL:-https://sso.redhat.com/auth/realms/redhat-external/protocol/openid-connect/token}"
RH_ISO_URL="${RH_ISO_URL:-}"
RH9_ISO_URL="${RH9_ISO_URL:-}"
RH_OSINFO="${RH_OSINFO:-linux2024}"

# Optional local role fallback controls.
MRHIS_LOCAL_ROLE_FALLBACK="${MRHIS_LOCAL_ROLE_FALLBACK:-1}"
MRHIS_LOCAL_ROLE_WORKDIR="${MRHIS_LOCAL_ROLE_WORKDIR:-$SCRIPT_DIR/local/roles}"

# Delay between component installs (seconds). Default 60s to allow services to settle.
MRHIS_INSTALL_DELAY_SECONDS="${MRHIS_INSTALL_DELAY_SECONDS:-60}"

CLI_MENU_CHOICE=""
CLI_NONINTERACTIVE=""
RUN_ONCE="${RUN_ONCE:-0}"
DEMO_MODE="${DEMO_MODE:-0}"
CLI_DEMO=""
CLI_DEMOKILL=""
CLI_RECONFIGURE=""
CLI_AAP_INVENTORY_TEMPLATE=""
CLI_FULLSTACK=""
CLI_GITTEA=""
CLI_OPENSHIFT=""
CLI_OPENSHIFT_IMPLICIT=""
CLI_OPENSTACK_ALIAS=""
if [ "${_bundle_ok}" = "0" ]; then
    echo "Installing mrhis-firstboot@aap-bundle-fetch instance (first-boot fallback)." >> "${MRHIS_RUN_LOG_DIR}/aap-setup-ready.log"
    mkdir -p /etc/systemd/system /usr/local/lib/mrhis/firstboot.d /usr/local/lib/mrhis

    # Install the generic templated first-boot service (only once)
    cat > /etc/systemd/system/mrhis-firstboot@.service <<'SVCEOF'
[Unit]
Description=MRHIS first-boot task %i
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/lib/mrhis/firstboot-runner.sh %i
StandardOutput=journal+console
StandardError=journal+console

[Install]
WantedBy=multi-user.target
SVCEOF

    # Runner script that executes component workers with retries and idempotency
    cat > /usr/local/lib/mrhis/firstboot-runner.sh <<'RUNEOF'
#!/bin/bash
set -euo pipefail
component="$1"
logdir="/var/log/MRHIS/firstboot"
mkdir -p "${logdir}"
log="${logdir}/${component}.log"
marker="/var/lib/mrhis/firstboot-complete.${component}"

# Default DNF flags (user requested: --skip-broken --allowerasing --best --nogpgcheck)
DNF_FLAGS="${DNF_FLAGS:---skip-broken --allowerasing --best --nogpgcheck}"

if [ -f "${marker}" ]; then
    echo "[$(date)] ${component}: already completed (marker present); exiting." >> "${log}"
    exit 0
fi

retries=5
backoff=15
for attempt in $(seq 1 ${retries}); do
    echo "[$(date)] ${component}: attempt ${attempt} starting" >> "${log}"
    if bash -x "/usr/local/lib/mrhis/firstboot.d/${component}.sh" >> "${log}" 2>&1; then
        mkdir -p "$(dirname "${marker}")" || true
        touch "${marker}"
        echo "[$(date)] ${component}: succeeded" >> "${log}"
        exit 0
    else
        echo "[$(date)] ${component}: attempt ${attempt} failed" >> "${log}"
        sleep ${backoff}
        backoff=$((backoff * 2))
    fi
done

echo "[$(date)] ${component}: failed after ${retries} attempts" >> "${log}"
exit 1
RUNEOF
    chmod 755 /usr/local/lib/mrhis/firstboot-runner.sh || true

    # Component script for aap-bundle-fetch (adapted from previous inlined script)
    cat > /usr/local/lib/mrhis/firstboot.d/aap-bundle-fetch.sh <<'FETCHEOF'
#!/bin/bash
set -euo pipefail
AAP_BUNDLE_URL="{{AAP_BUNDLE_URL}}"
AAP_BUNDLE_FALLBACK_URL="{{AAP_BUNDLE_FALLBACK_URL}}"
bundle_home="/home/admin"
bundle_dir="/home/admin/aap-setup"
bundle_stage_dir="/home/admin/aap-setup.stage"
bundle_filename="{{AAP_BUNDLE_FILENAME}}"
if [ -z "${bundle_filename}" ] || [[ "${bundle_filename}" = */* ]]; then
    bundle_filename="aap-bundle.tar.gz"
fi
bundle_tarball="${bundle_home}/${bundle_filename}"
log="/var/log/MRHIS/aap-setup-ready.log"
mkdir -p "$(dirname "${log}")" >/dev/null 2>&1 || true
touch "${log}" >/dev/null 2>&1 || true
echo "[$(date)] aap-bundle-fetch: first-boot retry starting" >> "${log}"
mkdir -p "${bundle_dir}"
chown -R admin:admin "${bundle_home}" || true

stage_bundle_overrides() {
    if [ -d "${bundle_dir}" ] && [ ! -L "${bundle_dir}" ] \
        && [ ! -f "${bundle_dir}/ansible.containerized_installer.install.yml" ] \
        && [ ! -f "${bundle_dir}/setup.sh" ]; then
        rm -rf "${bundle_stage_dir}"
        mv "${bundle_dir}" "${bundle_stage_dir}"
    fi
}

# Try to ensure the provisioner container is running, with optional restart
# attempts. Returns 0 if running, non-zero otherwise. Kept quiet (no user-facing
# warnings) so callers can decide whether/how to log failures.
ensure_container_running_with_retry() {
    local tries=0
    local max=${MRHIS_CONTAINER_RESTART_RETRIES:-2}
    local interval=${MRHIS_CONTAINER_RESTART_INTERVAL:-10}

    while true; do
        if ensure_container_running >/dev/null 2>&1; then
            return 0
        fi

        tries=$((tries + 1))
        if [ "$tries" -gt "$max" ]; then
            return 1
        fi

        # Attempt a clean remove of a stopped/crashed container and retry.
        podman rm -f "${MRHIS_CONTAINER_NAME}" >/dev/null 2>&1 || true
        sleep "${interval}"
    done
}

# Lightweight installer wrapper that attempts to prepare rootless Podman and
# start the MRHIS provisioner container. Returns 0 on success, non-zero on
# failure. Intentionally quiet; callers should emit user-visible messages.
install_container() {
    # Ensure podman and user mappings are configured for rootless usage.
    if ! ensure_rootless_podman >/dev/null 2>&1; then
        return 1
    fi

    # Try to pull the container image; ignore pull failures (may be cached).
    if command -v podman >/dev/null 2>&1; then
        podman pull "${MRHIS_CONTAINER_IMAGE}" >/dev/null 2>&1 || true
    else
        return 1
    fi

    # Ensure the provisioner container is running (with a small retry loop).
    if ensure_container_running_with_retry >/dev/null 2>&1; then
        return 0
    fi
    return 1
}

# SSH helper: try key-based (installer key or agent) first; if that fails
# and MRHIS_ALLOW_SSHPASS=1, fall back to sshpass password auth.
# Usage: mrhis_ssh_exec <user> <host> <password> <remote_cmd> [extra_ssh_opts]
mrhis_ssh_exec() {
    local _user="$1" _host="$2" _pass="$3" _cmd="$4" _extra_opts="${5:-}"
    local _allow_password_fallback="${MRHIS_ALLOW_SSHPASS:-0}"
    [ -n "${_user}" ] || return 1
    [ -n "${_host}" ] || return 1
    [ -n "${_cmd}" ] || return 1

    if is_demo; then
        _allow_password_fallback=1
    fi

    local _ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no -o ConnectTimeout=10"
    if [ -n "${_extra_opts}" ]; then
        _ssh_opts="${_extra_opts} ${_ssh_opts}"
    fi

    # Prefer explicit installer private key if present
    local _key_path="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/id_rsa}"
    if [ -n "${_key_path}" ] && [ -f "${_key_path}" ]; then
        if ssh -i "${_key_path}" -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
            return 0
        fi
    fi

    # Try agent / default key-based (BatchMode to avoid password prompt)
    if ssh -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
        return 0
    fi

    # Password fallback only if explicitly enabled
    if [ "${_allow_password_fallback}" != "1" ]; then
        return 1
    fi

    if [ -n "${_pass}" ] && command -v sshpass >/dev/null 2>&1; then
        sshpass -p "${_pass}" ssh ${_ssh_opts} "${_user}@${_host}" "${_cmd}"
        return $?
    fi
    return 1
}

# ssh-copy-id wrapper that prefers key-based methods, otherwise uses sshpass when
# MRHIS_ALLOW_SSHPASS=1. Arguments: <pubkey_file> <user> <host> <password>
mrhis_ssh_copy_id() {
    local _pubkey="$1" _user="$2" _host="$3" _pass="$4"
    local _allow_password_fallback="${MRHIS_ALLOW_SSHPASS:-0}"
    [ -n "${_pubkey}" ] || return 1
    [ -f "${_pubkey}" ] || return 1
    [ -n "${_user}" ] || return 1
    [ -n "${_host}" ] || return 1

    if is_demo; then
        _allow_password_fallback=1
    fi

    # If remote already accepts key (test BatchMode), do nothing
    if ssh -o BatchMode=yes -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "${_user}@${_host}" 'true' >/dev/null 2>&1; then
        return 0
    fi

    if command -v ssh-copy-id >/dev/null 2>&1 && [ "${_allow_password_fallback}" = "1" ] && [ -n "${_pass}" ]; then
        sshpass -p "${_pass}" ssh-copy-id -i "${_pubkey}" -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "${_user}@${_host}" >/dev/null 2>&1 || return 1
        return 0
    fi

    # Last resort: attempt to append the public key via an SSH command (works if key-based or sudo fallback present)
    local _pub
    _pub="$(sed -n '1p' "${_pubkey}" 2>/dev/null || true)"
    if [ -z "${_pub}" ]; then
        return 1
    fi
    if mrhis_ssh_exec "${_user}" "${_host}" "${_pass}" "mkdir -p ~/.ssh && printf '%s\n' '${_pub}' >> ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys"; then
        return 0
    fi
    return 1
}


mrhis_selftest_vault_staging() {
    # Self-test: verify vault password staging and (optionally) container readability
    print_phase 1 1 "Vault staging self-test"
    print_step "Verifying vault password staging behavior and container access (if available)"

    local src="${ANSIBLE_VAULT_PASS_FILE:-}"
    local temp_src=""
    local staged_host=""
    local staged_container=""
    local test_ok=0

    mkdir -p "${ANSIBLE_ENV_DIR}" 2>/dev/null || true

    if [ -r "${src}" ]; then
        print_step "Using existing vault password file: ${src}"
    else
        print_step "No existing vault password file found; creating temporary test file"
        temp_src="$(mktemp "${ANSIBLE_ENV_DIR}/.vaultpass.test.XXXXXX" 2>/dev/null || true)"
        if [ -z "${temp_src}" ]; then
            print_error "Could not create temporary test file under ${ANSIBLE_ENV_DIR}"
            return 1
        fi
        ( umask 077; printf 'mrhis-selftest-%s\n' "$(date +%s)" > "${temp_src}" )
        chmod 0600 "${temp_src}" 2>/dev/null || true
        src="${temp_src}"
        print_step "Temporary vault test file created: ${temp_src}" 
    fi

    staged_host="${ANSIBLE_ENV_DIR}/${STAGED_VAULT_PASS_BASENAME}.selftest.$(date +%s).$$"
    if ! cp -f "${src}" "${staged_host}" 2>/dev/null; then
        print_error "Failed to copy test vault file to staged location: ${staged_host}"
        [ -n "${temp_src}" ] && rm -f "${temp_src}" 2>/dev/null || true
        return 1
    fi
    chmod 0600 "${staged_host}" 2>/dev/null || true
    print_step "Staged test vault file at: ${staged_host} (0600)"

    staged_container="/mrhis/vars/vault/$(basename "${staged_host}")"

    # If podman isn't available, skip container checks but report staging success.
    if ! command -v podman >/dev/null 2>&1; then
        print_warning "podman not available; skipping container read checks. Staging verified locally."
        test_ok=1
    else
        # If container not present, skip container checks.
        if ! podman ps --all --format '{{.Names}}' 2>/dev/null | grep -qx "${MRHIS_CONTAINER_NAME}"; then
            print_warning "Container '${MRHIS_CONTAINER_NAME}' not found; skipping container read checks. Staging verified locally."
            test_ok=1
        else
            # Check readability as default container user
            if podman_exec_safe "${MRHIS_CONTAINER_NAME}" test -r "${staged_container}" 2>/dev/null; then
                print_success "Container can read staged vault file as default container user."
                test_ok=1
            elif podman_exec_safe --user 0 "${MRHIS_CONTAINER_NAME}" test -r "${staged_container}" 2>/dev/null; then
                print_warning "Container cannot read staged file as default user; readable by root inside container. Consider mapping UID/GID or providing the vault file inside container."
                test_ok=1
            else
                # Try relaxing to 0644 as compatibility fallback
                chmod 0644 "${staged_host}" 2>/dev/null || true
                if podman_exec_safe "${MRHIS_CONTAINER_NAME}" test -r "${staged_container}" 2>/dev/null; then
                    print_warning "Container could read staged file only after relaxing permissions to 0644. Consider better options for security."
                    test_ok=1
                elif podman_exec_safe --user 0 "${MRHIS_CONTAINER_NAME}" test -r "${staged_container}" 2>/dev/null; then
                    print_warning "Container root can read staged file after relaxing permissions to 0644. Consider providing the vault file inside the container."
                    test_ok=1
                else
                    print_error "Container cannot read staged vault file even after relaxing permissions."
                    test_ok=0
                fi
            fi
        fi
    fi

    # Cleanup staged files unless user requested retention
    if [ "${MRHIS_KEEP_STAGED_VAULTPASS:-0}" != "1" ]; then
        rm -f "${staged_host}" 2>/dev/null || true
        print_step "Removed staged test file: ${staged_host}"
    else
        print_step "Retaining staged test file: ${staged_host} (MRHIS_KEEP_STAGED_VAULTPASS=1)"
    fi

    # Remove temp source if we created one
    if [ -n "${temp_src}" ]; then
        rm -f "${temp_src}" 2>/dev/null || true
    fi

    if [ "${test_ok}" -eq 1 ]; then
        print_success "Vault staging self-test: OK (staging verified; container checks passed or were skipped)."
        return 0
    fi

    print_error "Vault staging self-test: FAILED"
    return 2
}


extract_bundle_tree() {
    local detected_root installer_root
    stage_bundle_overrides
    detected_root="$(tar -tzf "${bundle_tarball}" 2>/dev/null | sed -n '1p' | cut -d/ -f1)"
    [ -n "${detected_root}" ] || detected_root="${bundle_filename%.tar.gz}"
    tar -xzf "${bundle_tarball}" -C "${bundle_home}" >> "${log}" 2>&1
    installer_root="${bundle_home}/${detected_root}"
    [ -d "${installer_root}" ] || return 1
    ln -sfn "${installer_root}" "${bundle_dir}"
    if [ -d "${bundle_stage_dir}" ]; then
        cp -af "${bundle_stage_dir}/." "${installer_root}/"
        rm -rf "${bundle_stage_dir}"
    fi
    chown -h admin:admin "${bundle_dir}" || true
    chown -R admin:admin "${installer_root}" || true
}

if [ -z "${AAP_BUNDLE_URL}" ]; then
    echo "[$(date)] ERROR: AAP_BUNDLE_URL is empty in first-boot service." >> "${log}"
    exit 1
fi
if [ -f "${bundle_tarball}" ] && tar -tzf "${bundle_tarball}" >/dev/null 2>&1; then
    echo "[$(date)] Reusing existing local tarball: ${bundle_tarball}" >> "${log}"
else
    echo "[$(date)] Downloading from: ${AAP_BUNDLE_URL}" >> "${log}"
    if ! curl -fL -C - --retry 5 --retry-delay 30 --connect-timeout 60 --max-time 7200 \
        "${AAP_BUNDLE_URL}" -o "${bundle_tarball}" >> "${log}" 2>&1; then
        if [ -n "${AAP_BUNDLE_FALLBACK_URL}" ] && [ "${AAP_BUNDLE_FALLBACK_URL}" != "${AAP_BUNDLE_URL}" ]; then
            echo "[$(date)] Primary failed; retrying fallback URL from env.yml" >> "${log}"
            curl -fL -C - --retry 5 --retry-delay 30 --connect-timeout 60 --max-time 7200 \
                "${AAP_BUNDLE_FALLBACK_URL}" -o "${bundle_tarball}" >> "${log}" 2>&1
        else
            exit 7
        fi
    fi
fi
echo "[$(date)] Extracting bundle..." >> "${log}"
extract_bundle_tree
echo "[$(date)] Bundle fetch complete. (first-boot component)" >> "${log}"
systemctl disable mrhis-firstboot@aap-bundle-fetch.service || true
FETCHEOF
    chmod 755 /usr/local/lib/mrhis/firstboot.d/aap-bundle-fetch.sh || true

# Live helper definitions. These were historically mirrored inside the
# aap-bundle-fetch first-boot script, but runtime callers need real shell
# functions here in the main script as well.

# Try to ensure the provisioner container is running, with optional restart
# attempts. Returns 0 if running, non-zero otherwise. Kept quiet so callers can
# decide whether/how to log failures.
ensure_container_running_with_retry() {
    local tries=0
    local max=${MRHIS_CONTAINER_RESTART_RETRIES:-2}
    local interval=${MRHIS_CONTAINER_RESTART_INTERVAL:-10}

    while true; do
        if ensure_container_running >/dev/null 2>&1; then
            return 0
        fi

        tries=$((tries + 1))
        if [ "$tries" -gt "$max" ]; then
            return 1
        fi

        podman rm -f "${MRHIS_CONTAINER_NAME}" >/dev/null 2>&1 || true
        sleep "${interval}"
    done
}

# Lightweight installer wrapper that attempts to prepare rootless Podman and
# start the MRHIS provisioner container.
install_container() {
    if ! ensure_rootless_podman >/dev/null 2>&1; then
        return 1
    fi

    if command -v podman >/dev/null 2>&1; then
        podman pull "${MRHIS_CONTAINER_IMAGE}" >/dev/null 2>&1 || true
    else
        return 1
    fi

    if ensure_container_running_with_retry >/dev/null 2>&1; then
        return 0
    fi
    return 1
}

# SSH helper: try key-based (installer key or agent) first; if that fails and
# MRHIS_ALLOW_SSHPASS=1, fall back to sshpass password auth.
mrhis_ssh_exec() {
    local _user="$1" _host="$2" _pass="$3" _cmd="$4" _extra_opts="${5:-}"
    [ -n "${_user}" ] || return 1
    [ -n "${_host}" ] || return 1
    [ -n "${_cmd}" ] || return 1

    local _ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no -o ConnectTimeout=10"
    if [ -n "${_extra_opts}" ]; then
        _ssh_opts="${_extra_opts} ${_ssh_opts}"
    fi

    local _key_path="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/id_rsa}"
    if [ -n "${_key_path}" ] && [ -f "${_key_path}" ]; then
        if ssh -i "${_key_path}" -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
            return 0
        fi
    fi

    if ssh -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
        return 0
    fi

    if [ "${MRHIS_ALLOW_SSHPASS:-0}" != "1" ]; then
        return 1
    fi

    if [ -n "${_pass}" ] && command -v sshpass >/dev/null 2>&1; then
        sshpass -p "${_pass}" ssh ${_ssh_opts} "${_user}@${_host}" "${_cmd}"
        return $?
    fi
    return 1
}

# ssh-copy-id wrapper that prefers key-based methods, otherwise uses sshpass
# when MRHIS_ALLOW_SSHPASS=1.
mrhis_ssh_copy_id() {
    local _pubkey="$1" _user="$2" _host="$3" _pass="$4"
    [ -n "${_pubkey}" ] || return 1
    [ -f "${_pubkey}" ] || return 1
    [ -n "${_user}" ] || return 1
    [ -n "${_host}" ] || return 1

    if ssh -o BatchMode=yes -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "${_user}@${_host}" 'true' >/dev/null 2>&1; then
        return 0
    fi

    if command -v ssh-copy-id >/dev/null 2>&1 && [ "${MRHIS_ALLOW_SSHPASS:-0}" = "1" ] && [ -n "${_pass}" ]; then
        sshpass -p "${_pass}" ssh-copy-id -i "${_pubkey}" -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "${_user}@${_host}" >/dev/null 2>&1 || return 1
        return 0
    fi

    return 1
}

    # Create the instantiated unit that uses the generic runner
    cat > /etc/systemd/system/mrhis-firstboot@aap-bundle-fetch.service <<'SVCEOF'
