# Normalize SSH private key path: if user points at a directory, prefer common
# private key filenames inside it (id_rsa, id_ed25519) to avoid 'Is a directory'
# errors when tools call `ssh -i <path>`.
_resolve_ssh_private_key() {
    local candidate="$1"
    if [ -z "${candidate}" ]; then
        return 1
    fi
    if [ -d "${candidate}" ]; then
        if [ -f "${candidate}/id_rsa" ]; then
            printf '%s' "${candidate}/id_rsa"
            return 0
        elif [ -f "${candidate}/id_ed25519" ]; then
            printf '%s' "${candidate}/id_ed25519"
            return 0
        else
            # directory provided but no recognizable key file inside
            return 2
        fi
    fi
    printf '%s' "${candidate}"
    return 0
}

# Try to normalize MRHIS_INSTALLER_SSH_PRIVATE_KEY if it points to a dir
_tmp_key="$(_resolve_ssh_private_key "${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-}")" || true
if [ -n "${_tmp_key}" ] && [ -f "${_tmp_key}" ]; then
    MRHIS_INSTALLER_SSH_PRIVATE_KEY="${_tmp_key}"
fi
unset _tmp_key
# Fail fast when SSH port is reachable but key auth repeatedly fails.
# 18 attempts * 10s = ~3 minutes (after SSH becomes reachable).
AAP_SSH_KEY_FAIL_FAST_ATTEMPTS="${AAP_SSH_KEY_FAIL_FAST_ATTEMPTS:-18}"
