MRHIS_CONTAINER_RESTART_INTERVAL="${MRHIS_CONTAINER_RESTART_INTERVAL:-10}"
# Lightweight fallback for early callers of `run_phase_playbook_with_auth_fallback`.
# Some phases may be invoked before the full, feature-complete implementation
# appears later in the file; provide a minimal safe implementation here so
# early checks (server-bootstrap, pre-config) can run.
run_phase_playbook_with_auth_fallback() {
    local phase_label="$1"
    local phase_limit="$2"
    local phase_playbook="$3"
    local ansible_cfg
    local inv

    ansible_cfg="${MRHIS_ANSIBLE_CFG_HOST:-${HOME}/.ansible/conf/mrhis-ansible.runtime.cfg}"
    inv="${MRHIS_INVENTORY_FILE:-${SCRIPT_DIR}/inventory/hosts}"

    echo "[$(date)] [fallback-run_phase_playbook] ${phase_label} limit=${phase_limit} playbook=${phase_playbook}" >> "${MRHIS_LOG:-/var/log/mrhis/mrhis.log}"

    # Respect vault/env files when present so roles like mrhis-rhsm receive
    # credentials provided by MRHIS.sh via ${ANSIBLE_ENV_FILE}.
    local -a _vault_arg=()
    if [ -f "${ANSIBLE_VAULT_PASS_FILE:-}" ]; then
        _vault_arg=(--vault-password-file "${ANSIBLE_VAULT_PASS_FILE}")
    fi
    local -a _vault_vars=()
    if [ -f "${ANSIBLE_ENV_FILE:-}" ]; then
        _vault_vars=(--extra-vars "@${ANSIBLE_ENV_FILE}")
    fi

    if ANSIBLE_CONFIG="${ansible_cfg}" ansible-playbook -i "${inv}" --limit "${phase_limit}" "${_vault_arg[@]}" "${_vault_vars[@]}" "${phase_playbook}"; then
        return 0
    else
        echo "[$(date)] [fallback-run_phase_playbook] failed: ${phase_label}" >> "${MRHIS_LOG:-/var/log/mrhis/mrhis.log}"
        return 1
    fi
}
# DEMOKILL console behavior controls
# 1 = compact one-line progress messages for DEMOKILL
MRHIS_DEMOKILL_COMPACT="${MRHIS_DEMOKILL_COMPACT:-1}"
# 1 = run terminal reset after DEMOKILL (enabled by default)
MRHIS_DEMOKILL_RESET_TERMINAL="${MRHIS_DEMOKILL_RESET_TERMINAL:-1}"

# Allow deferred SSH mesh bootstrap by default to avoid aborting early when
# VMs are still finishing firstboot tasks. Set to 0 to make bootstrap fatal.
MRHIS_ALLOW_DEFERRED_SSH_MESH="${MRHIS_ALLOW_DEFERRED_SSH_MESH:-1}"

print_step() {
    local msg
    msg="$(sanitize_log_message "$*")"
    # Steps: highlight inline keywords for readability
    echo -e "[STEP] $(highlight_message "${msg}")"
}

print_success() {
    local msg
    msg="$(sanitize_log_message "$*")"
    local colored
    colored="$(highlight_message "${msg}")"
    echo -e "${GREEN}[SUCCESS]${NC} ${colored}"
    # Also emit a plain, machine-friendly marker for logs
    echo "PASS: ${msg}"
}

# Print an updating progress bar for long-running retry loops. Prints a single
# carriage-return-updating line prefixed with [STEP]. Use like:
#   print_progress_bar <current> <total> "Label"
print_progress_bar() {
    local current="${1:-0}"
    local total="${2:-100}"
    local label="${3:-}"
    local width="${4:-30}"

    label="$(sanitize_log_message "${label}")"
    # Sanity guards
    if [ "${total}" -le 0 ]; then total=100; fi
    if [ "${current}" -lt 0 ]; then current=0; fi
    if [ "${current}" -gt "${total}" ]; then current=${total}; fi

    local pct=$(( current * 100 / total ))
    local filled=$(( current * width / total ))
    local empty=$(( width - filled ))
    local bar_filled bar_empty
    bar_filled="$(printf '%*s' "${filled}" '' | tr ' ' '#')"
    bar_empty="$(printf '%*s' "${empty}" '' | tr ' ' '.')"

    # Print carriage-return-updating progress line (no final newline).
    printf '\r%s %s [%s%s] (%d/%d) ' "[STEP]" "${label}" "${bar_filled}" "${bar_empty}" "${current}" "${total}"
}

sleep_with_spinner() {
    # sleep_with_spinner <seconds> [message]
    local secs="${1:-0}"
    local msg="${2:-Waiting...}"
    local spin_chars='|/-\\'
    local i=0
    local start now remaining
    start=$(date +%s)
    end=$((start + secs))
    while [ $(date +%s) -lt $end ]; do
        now=$(date +%s)
        remaining=$(( end - now ))
        local idx=$(( i % 4 ))
        local char="${spin_chars:idx:1}"
        printf '\r\033[K[STEP] %s %s (%ds remaining)' "${msg}" "${char}" "${remaining}"
        i=$((i+1))
        sleep 1
    done
    printf '\r\033[K[STEP] %s (done)\n' "${msg}"
}

# Minimal spinner tick for short polling sleeps (non-verbose)
spinner_tick() {
    # spinner_tick <seconds>
    local secs="${1:-1}"
    local spin_chars='|/-\\'
    local i=0
    local start now end
    start=$(date +%s)
    end=$((start + secs))
    while [ $(date +%s) -lt $end ]; do
        now=$(date +%s)
        local idx=$(( i % 4 ))
        local char="${spin_chars:idx:1}"
        printf '\r\033[K[STEP] %s' "${char}"
        i=$((i+1))
        sleep 1
    done
    printf '\r\033[K'
}

escape_sed_repl() {
    # Safely escape strings for sed replacement contexts.
    printf '%s' "$1" | sed -e 's/[\\&]/\\\\&/g' -e 's|/|\\/|g'
}


# Wait for a pid while showing a one-line spinner and a short command synopsis.
# Usage: wait_for_pid_spinner <pid> [message]
wait_for_pid_spinner() {
    local pid="$1"
    local msg="${2:-Stand by: finishing background task}"
    if [ -z "${pid}" ]; then
        return 0
    fi
    if ! kill -0 "${pid}" >/dev/null 2>&1; then
        return 0
    fi
    local synopsis
    synopsis=$(ps -p "${pid}" -o args= 2>/dev/null | sed -n '1p' | tr -d '\r' | tr '\n' ' ' | tr -s ' ')
    synopsis=$(printf '%s' "${synopsis}" | sed -E 's/[^[:print:][:space:]]//g')
    synopsis=${synopsis:0:96}

    # In non-interactive output (logs, captured terminals), avoid CR-based
    # spinner rendering that appears as garbled repeated fragments.
    if [ ! -t 1 ]; then
        if [ -n "${synopsis}" ]; then
            print_step "${msg} - ${synopsis}"
        else
            print_step "${msg}"
        fi
        while kill -0 "${pid}" >/dev/null 2>&1; do
            sleep 1
        done
        return 0
    fi

    local spin_chars='|/-\\' i=0
    while kill -0 "${pid}" >/dev/null 2>&1; do
        i=$((i+1))
        printf "\r\033[K[%c] %s - %s" "${spin_chars:i%${#spin_chars}:1}" "${msg}" "${synopsis}"
        sleep 0.25
    done
    printf '\r\033[K%s (done)\n' "${msg}"
}

print_warning() {
    local msg
    msg="$(sanitize_log_message "$*")"
    if is_enabled "${MRHIS_TEST_MODE:-0}"; then
        MRHIS_TEST_WARNING_COUNT=$((MRHIS_TEST_WARNING_COUNT + 1))
        printf '%s\n' "${msg}" >> "${MRHIS_TEST_WARNING_FILE:-/dev/null}"
    fi
    # Map warnings to red to make failures/warnings easy to spot
    local colored
    colored="$(highlight_message "${msg}")"
    echo -e "${RED}[WARNING]${NC} ${colored}"
    # Emit plain warning marker for easy grepping in logs
    echo "WARN: ${msg}"
}

print_error() {
    local msg
    msg="$(sanitize_log_message "$*")"
    local colored
    colored="$(highlight_message "${msg}")"
    echo -e "${RED}[ERROR]${NC} ${colored}"
    # Emit plain failure marker for easy grepping in logs
    echo "FAIL: ${msg}" >&2
}

print_phase() {
    local index="$1"
    local total="$2"
    local label="$3"
    label="$(sanitize_log_message "${label}")"
    echo -e "${CYAN}[PHASE ${index}/${total}]${NC} ${BOLD}${label}${NC}"
}

ensure_mrhis_installer_ssh_key() {
    mkdir -p "${MRHIS_INSTALLER_SSH_KEY_DIR}" >/dev/null 2>&1 || true
    chmod 700 "${MRHIS_INSTALLER_SSH_KEY_DIR}" >/dev/null 2>&1 || true

    if [ ! -f "${MRHIS_INSTALLER_SSH_PRIVATE_KEY}" ]; then
        ssh-keygen -q -t rsa -b 4096 -N "" -f "${MRHIS_INSTALLER_SSH_PRIVATE_KEY}" -C "mrhis-installer-host" >/dev/null 2>&1 || return 1
    fi

    chmod 600 "${MRHIS_INSTALLER_SSH_PRIVATE_KEY}" >/dev/null 2>&1 || true
    chmod 644 "${MRHIS_INSTALLER_SSH_PUBLIC_KEY}" >/dev/null 2>&1 || true
    return 0
}

refresh_mrhis_known_hosts() {
    local host
    local -a mrhis_hosts

    if ! is_enabled "${MRHIS_REFRESH_KNOWN_HOSTS:-1}"; then
        return 0
    fi

    [ -d "${HOME}/.ssh" ] || mkdir -p "${HOME}/.ssh" >/dev/null 2>&1 || true
    touch "${HOME}/.ssh/known_hosts" >/dev/null 2>&1 || true
    chmod 600 "${HOME}/.ssh/known_hosts" >/dev/null 2>&1 || true

    mrhis_hosts=(
        "${SAT_IP:-}" "${AAP_IP:-}" "${IDM_IP:-}"
        "${SAT_HOSTNAME:-}" "${AAP_HOSTNAME:-}" "${IDM_HOSTNAME:-}"
    )

    for host in "${mrhis_hosts[@]}"; do
        [ -n "${host}" ] || continue
        ssh-keygen -R "${host}" -f "${HOME}/.ssh/known_hosts" >/dev/null 2>&1 || true
        ssh-keyscan -H -T 3 "${host}" >> "${HOME}/.ssh/known_hosts" 2>/dev/null || true
    done
}

# Remove stale SSH trust entries for rebuilt MRHIS nodes before provisioning.
# This clears host key fingerprints from known_hosts and prunes matching
# hostname/IP comment lines from the local authorized_keys file.
prune_local_ssh_trust_for_component() {
    local component="${1:-all}"
    local known_hosts_file="${HOME}/.ssh/known_hosts"
    local auth_keys_file="${HOME}/.ssh/authorized_keys"
    local host short
    local changed_auth=0
    local tmp_auth
    local -a targets=()

    case "${component}" in
        satellite)
            targets+=("${SAT_IP:-}" "${SAT_HOSTNAME:-}" "satellite")
            ;;
        idm)
            targets+=("${IDM_IP:-}" "${IDM_HOSTNAME:-}")
            ;;
        aap)
            targets+=("${AAP_IP:-}" "${AAP_HOSTNAME:-}" "aap")
            ;;
        all|*)
            targets+=("${SAT_IP:-}" "${SAT_HOSTNAME:-}" "satellite")
            targets+=("${IDM_IP:-}" "${IDM_HOSTNAME:-}")
            targets+=("${AAP_IP:-}" "${AAP_HOSTNAME:-}" "aap")
            ;;
    esac

    # Add short hostnames derived from FQDNs (best-effort)
    for host in "${targets[@]}"; do
        [ -n "${host}" ] || continue
        short="${host%%.*}"
        if [ -n "${short}" ] && [ "${short}" != "${host}" ]; then
            targets+=("${short}")
        fi
    done

    [ -d "${HOME}/.ssh" ] || mkdir -p "${HOME}/.ssh" >/dev/null 2>&1 || true
    touch "${known_hosts_file}" >/dev/null 2>&1 || true
    chmod 600 "${known_hosts_file}" >/dev/null 2>&1 || true

    print_step "Pre-install SSH cleanup (${component}): pruning ~/.ssh/known_hosts and ~/.ssh/authorized_keys entries"

    for host in "${targets[@]}"; do
        [ -n "${host}" ] || continue
        ssh-keygen -R "${host}" -f "${known_hosts_file}" >/dev/null 2>&1 || true
        ssh-keygen -R "[${host}]:22" -f "${known_hosts_file}" >/dev/null 2>&1 || true
    done

    if [ -f "${auth_keys_file}" ]; then
        tmp_auth="$(mktemp)" || return 1
        cp "${auth_keys_file}" "${tmp_auth}" || true
        for host in "${targets[@]}"; do
            [ -n "${host}" ] || continue
            # Remove lines containing hostname/IP comments from older rebuilt nodes.
            grep -Fv -- "${host}" "${tmp_auth}" > "${tmp_auth}.new" 2>/dev/null || true
            mv -f "${tmp_auth}.new" "${tmp_auth}" >/dev/null 2>&1 || true
        done
        if ! cmp -s "${auth_keys_file}" "${tmp_auth}"; then
            mv -f "${tmp_auth}" "${auth_keys_file}" || true
            chmod 600 "${auth_keys_file}" >/dev/null 2>&1 || true
            changed_auth=1
        else
            rm -f "${tmp_auth}" >/dev/null 2>&1 || true
        fi
    fi

    if [ "${changed_auth}" -eq 1 ]; then
        print_step "Pre-install SSH cleanup (${component}): stale authorized_keys entries removed"
    fi
    return 0
}

# Completely wipe installer-node SSH trust state for a clean rebuild cycle.
# Unlike prune_local_ssh_trust_for_component (which removes only named entries),
# this truncates ~/.ssh/known_hosts entirely and removes the MRHIS installer
# keypair so a fresh one is generated before the next set of kickstarts is written.
# Called from demokill_cleanup() and create_mrhis_vms() before VM provisioning.
wipe_installer_node_ssh_trust() {
    local known_hosts="${HOME}/.ssh/known_hosts"
    local auth_keys="${HOME}/.ssh/authorized_keys"
    local key_dir="${MRHIS_INSTALLER_SSH_KEY_DIR:-${HOME}/.ssh/mrhis-installer}"

    print_step "Wiping installer-node SSH trust files for clean rebuild"

    # Truncate known_hosts entirely — all previous VM host keys are invalid
    # after a DEMOKILL/fresh-build cycle.
    if [ -f "${known_hosts}" ]; then
        : > "${known_hosts}" 2>/dev/null || true
        chmod 600 "${known_hosts}" >/dev/null 2>&1 || true
        print_step "  ~/.ssh/known_hosts truncated (all stale VM fingerprints removed)"
    fi

    # Remove the MRHIS installer keypair so ensure_ssh_keys regenerates it
    # before kickstarts are written — new VMs must embed the NEW public key.
    if [ -d "${key_dir}" ]; then
        rm -rf "${key_dir}" >/dev/null 2>&1 || true
        print_step "  MRHIS installer keypair removed (${key_dir}) — will regenerate before kickstart write"
    fi

    # Strip MRHIS-related entries from authorized_keys on the installer node.
    if [ -f "${auth_keys}" ]; then
        local tmp_ak changed_ak=0
        tmp_ak="$(mktemp)" || return 0
        # Remove keys whose comment contains a mrhis marker
        grep -Ev 'mrhis|mrhis-installer|mrhis-aap-setup' "${auth_keys}" > "${tmp_ak}" 2>/dev/null || true
        # Also strip keys whose comment contains a known MRHIS node IP
        local ip
        for ip in "${SAT_IP:-}" "${AAP_IP:-}" "${IDM_IP:-}" "${GITTEA_IP:-}" "${OPENSHIFT_IP:-}"; do
            [ -n "${ip}" ] || continue
            grep -Fv -- "${ip}" "${tmp_ak}" > "${tmp_ak}.new" 2>/dev/null || true
            mv -f "${tmp_ak}.new" "${tmp_ak}" >/dev/null 2>&1 || true
        done
        if ! cmp -s "${auth_keys}" "${tmp_ak}" 2>/dev/null; then
            mv -f "${tmp_ak}" "${auth_keys}" || true
            chmod 600 "${auth_keys}" >/dev/null 2>&1 || true
            print_step "  ~/.ssh/authorized_keys cleaned of stale MRHIS node entries"
        else
            rm -f "${tmp_ak}" >/dev/null 2>&1 || true
        fi
    fi
    return 0
}

init_mrhis_run_logging() {
    local run_ts target_dir log_file

    # Idempotent guard for re-entry.
    if [ "${MRHIS_LOG_STDIO_REDIRECTED:-0}" = "1" ]; then
        return 0
    fi

    target_dir="${MRHIS_RUN_LOG_DIR:-/var/log/MRHIS}"
    run_ts="$(date +%Y%m%d-%H%M%S)"
    log_file="${target_dir}/install_${run_ts}.log"

    # Ensure /var/log/MRHIS exists; requires elevated permissions on most systems.
    if [ ! -d "${target_dir}" ]; then
        if ! sudo mkdir -p "${target_dir}" 2>/dev/null; then
            print_warning "Could not create ${target_dir}; run logging disabled for this invocation."
            return 0
        fi
    fi

    sudo chown "${USER}:${USER}" "${target_dir}" >/dev/null 2>&1 || true
    sudo chmod 0755 "${target_dir}" >/dev/null 2>&1 || true

    if ! touch "${log_file}" 2>/dev/null; then
        if ! sudo touch "${log_file}" 2>/dev/null; then
            print_warning "Could not create run log file at ${log_file}; run logging disabled for this invocation."
            return 0
        fi
    fi

    sudo chown "${USER}:${USER}" "${log_file}" >/dev/null 2>&1 || true
    sudo chmod 0644 "${log_file}" >/dev/null 2>&1 || true

    MRHIS_RUN_LOG_FILE="${log_file}"
    export MRHIS_RUN_LOG_FILE
    export MRHIS_LOG_STDIO_REDIRECTED=1

    # Mirror all script output to console and a per-run logfile.
    exec > >(tee -a "${MRHIS_RUN_LOG_FILE}") 2>&1

    ln -sfn "${MRHIS_RUN_LOG_FILE}" "${target_dir}/latest.log" >/dev/null 2>&1 || true
    print_step "MRHIS run logging enabled: ${MRHIS_RUN_LOG_FILE}"

    prune_mrhis_run_logs || true
}

prune_mrhis_run_logs() {
    local target_dir retention_days

    target_dir="${MRHIS_RUN_LOG_DIR:-/var/log/MRHIS}"
    retention_days="${MRHIS_RUN_LOG_RETENTION_DAYS:-20}"

    case "${retention_days}" in
        ''|*[!0-9]*)
            print_warning "Invalid MRHIS_RUN_LOG_RETENTION_DAYS='${retention_days}'; skipping log pruning."
            return 0
            ;;
    esac

    [ "${retention_days}" -ge 0 ] || {
        print_warning "MRHIS_RUN_LOG_RETENTION_DAYS must be >= 0; skipping log pruning."
        return 0
    }

    [ -d "${target_dir}" ] || return 0

    find "${target_dir}" -maxdepth 1 -type f -name 'install_*.log' -mtime +"${retention_days}" -print0 2>/dev/null | \
        while IFS= read -r -d '' old_log; do
            rm -f "${old_log}" >/dev/null 2>&1 || sudo rm -f "${old_log}" >/dev/null 2>&1 || true
        done

    print_step "Pruned MRHIS run logs older than ${retention_days} day(s) in ${target_dir}."
    return 0
}

