mask_secret() {
    local value="${1:-}"
    local length

    if [ -z "$value" ]; then
        echo "(unset)"
        return 0
    fi

    length="${#value}"
    if [ "$length" -le 4 ]; then
        echo "***"
        return 0
    fi

    printf '%s***%s\n' "${value:0:2}" "${value: -2}"
}

mask_url_secret() {
    local value="${1:-}"
    local base=""

    if [ -z "$value" ]; then
        echo "(unset)"
        return 0
    fi

    # Strip query/hash to avoid leaking auth tokens in logs.
    base="${value%%\?*}"
    base="${base%%#*}"
    if [ "$base" != "$value" ]; then
        printf '%s?<redacted>\n' "$base"
        return 0
    fi

    printf '%s\n' "$base"
}

sed_escape_replacement() {
    # Escape chars that are special in sed replacement context: &, |, \
    printf '%s' "${1:-}" | sed -e 's/[&|\\]/\\&/g'
}

derive_aap_bundle_filename() {
    local source="${1:-${AAP_BUNDLE_URL:-}}"
    local candidate=""

    if [ -n "${source}" ]; then
        candidate="${source%%\?*}"
        candidate="${candidate##*/}"
    fi

    if [ -z "${candidate}" ]; then
        candidate="aap-bundle.tar.gz"
    fi

    printf '%s\n' "${candidate}"
}

write_file_if_changed() {
    local src="$1"
    local dest="$2"
    local mode="${3:-0644}"
    local owner="${4:-}"
    local dest_dir

    MRHIS_LAST_WRITE_CHANGED=0

    [ -f "$src" ] || {
        print_warning "write_file_if_changed: source file not found: $src"
        return 1
    }

    if [ -f "$dest" ] && cmp -s "$src" "$dest"; then
        rm -f "$src"
        print_step "Generated file unchanged: $dest"
        return 0
    fi

    dest_dir="$(dirname "$dest")"
    mkdir -p "$dest_dir" 2>/dev/null || sudo mkdir -p "$dest_dir" >/dev/null 2>&1 || {
        rm -f "$src"
        print_warning "Could not create destination directory: $dest_dir"
        return 1
    }

    if ! install -D -m "$mode" "$src" "$dest" 2>/dev/null; then
        sudo install -D -m "$mode" "$src" "$dest" >/dev/null 2>&1 || {
            rm -f "$src"
            print_warning "Could not install generated file: $dest"
            return 1
        }
    fi

    if [ -n "$owner" ]; then
        chown "$owner" "$dest" 2>/dev/null || sudo chown "$owner" "$dest" >/dev/null 2>&1 || true
    fi

    rm -f "$src"
    MRHIS_LAST_WRITE_CHANGED=1
    print_success "Generated file updated: $dest"
    return 0
}

vault_plaintext_matches_existing() {
    local plaintext_file="$1"
    local existing_plaintext=""
    local rc=1

    [ -f "$plaintext_file" ] || return 1
    [ -f "$ANSIBLE_ENV_FILE" ] || return 1

    existing_plaintext="$(mktemp)"
    ansible-vault view --vault-password-file "$ANSIBLE_VAULT_PASS_FILE" "$ANSIBLE_ENV_FILE" > "$existing_plaintext" 2>/dev/null || {
        rm -f "$existing_plaintext"
        return 1
    }

    if cmp -s "$plaintext_file" "$existing_plaintext"; then
        rc=0
    fi

    rm -f "$existing_plaintext"
    return "$rc"
}

kickstart_password_hash() {
    local plain_password="$1"
    local hashed_password=""

    if [ -z "${plain_password}" ]; then
        if [ "${DEMO_MODE:-0}" = "1" ]; then
            print_warning "Kickstart password is empty; demo mode active — using default demo password."
            # Use a consistent demo password for unattended demo installs. This keeps kickstarts
            # valid even when users omit a password in demo mode.
            plain_password="mrhis"
        else
            print_warning "Kickstart password is empty; cannot generate rootpw/user password entry."
            return 1
        fi
    fi

    if command -v openssl >/dev/null 2>&1; then
        hashed_password="$(printf '%s' "${plain_password}" | openssl passwd -6 -stdin 2>/dev/null || true)"
    elif command -v python3 >/dev/null 2>&1; then
        hashed_password="$(python3 - <<'PY' "${plain_password}"
import crypt
import secrets
import sys

pw = sys.argv[1]
salt = "$6$" + secrets.token_urlsafe(12)
print(crypt.crypt(pw, salt))
PY
        )"
    fi

    if [ -z "${hashed_password}" ]; then
        print_warning "Failed to hash kickstart password (openssl/python3 unavailable or failed)."
        return 1
    fi

    printf '%s\n' "${hashed_password}"
    return 0
}

print_kickstart_effective_values() {
    local component="$1"
    local role_ip="$2"
    local role_hostname="$3"
    local role_netmask="$4"
    local role_gateway="$5"

    print_step "Kickstart effective values (${component}): host=${role_hostname} ip=${role_ip} netmask=${role_netmask} gw=${role_gateway}"
    print_step "Kickstart effective values (${component}): admin_user=${ADMIN_USER:-'(unset)'} installer_user=${INSTALLER_USER:-'(unset)'} domain=${DOMAIN:-'(unset)'}"
    print_step "Kickstart effective values (${component}): rh_user=$(mask_secret "${RH_USER:-}") rh_pass=$(mask_secret "${RH_PASS:-}") admin_pass=$(mask_secret "${ADMIN_PASS:-}") root_pass=$(mask_secret "${ROOT_PASS:-}")"
}

kickstart_nogpg_policy_block() {
    cat <<EOF
# MRHIS policy: disable package signature checks for all dnf/yum repo operations.
mkdir -p /etc/dnf
if [ -f /etc/dnf/dnf.conf ]; then
    if ! grep -q '^gpgcheck=0$' /etc/dnf/dnf.conf; then
        cat >> /etc/dnf/dnf.conf <<'EOF_DNF_GPG'

# MRHIS override: disable GPG checks
gpgcheck=0
repo_gpgcheck=0
localpkg_gpgcheck=0
EOF_DNF_GPG
    fi
fi
[ -e /etc/yum.conf ] || ln -sf /etc/dnf/dnf.conf /etc/yum.conf
EOF
}

kickstart_ssh_baseline_block() {
    cat <<EOF
# 1.1 SSH baseline for automation and internal preflight
ks_log "Phase 1.1: Configure SSH baseline"
mkdir -p /etc/ssh/sshd_config.d
mkdir -p /etc/ssh/ssh_config.d
cat > /etc/ssh/sshd_config.d/99-mrhis-root.conf <<'EOF_SSHD'
PermitRootLogin yes
PasswordAuthentication yes
PubkeyAuthentication yes
X11Forwarding yes
UseDNS no
EOF_SSHD

cat > /etc/ssh/ssh_config.d/99-mrhis-client.conf <<'EOF_SSH'
Host *
    StrictHostKeyChecking no
    UserKnownHostsFile /dev/null
    ForwardX11 no
    ForwardX11Trusted no
EOF_SSH

systemctl enable --now sshd || true
systemctl restart sshd || true
systemctl disable --now firewalld >/dev/null 2>&1 || true
setenforce 0 >/dev/null 2>&1 || true
if [ -f /etc/selinux/config ]; then
    sed -i 's/^SELINUX=.*/SELINUX=permissive/' /etc/selinux/config || true
fi

# Reduce rc.local generator noise during repeated bootstrap/reboot cycles.
# Keep this temporary; host workflow will revert to non-executable at the end.
if [ "${MRHIS_TEMP_ENABLE_RC_LOCAL_EXEC:-1}" = "1" ]; then
    if [ ! -f /etc/rc.d/rc.local ]; then
        cat > /etc/rc.d/rc.local <<'EOF_RCLOCAL'
#!/bin/bash
exit 0
EOF_RCLOCAL
    fi
    chmod +x /etc/rc.d/rc.local >/dev/null 2>&1 || true
fi
EOF
}

#kickstart_user_sudo_bootstrap_block() {
kickstart_user_sudo_bootstrap_block() {
    local role_name="${1:-}"
    cat <<'EOF'
# 1.2 Ensure installer/admin user has passwordless sudo and virtualization groups
ks_log "Phase 1.2: Ensure admin sudo bootstrap"
target_user="${INSTALLER_USER:-${ADMIN_USER}}"
# Ensure we never write an empty sudoers entry; fall back to admin
if [ -z "${target_user:-}" ]; then
    target_user="${ADMIN_USER:-admin}"
fi
if [ "${INSTALLER_USER:-${ADMIN_USER}}" != "${ADMIN_USER}" ] && ! id "${INSTALLER_USER:-${ADMIN_USER}}" >/dev/null 2>&1; then
    useradd -m -G wheel "${INSTALLER_USER:-${ADMIN_USER}}" || true
    echo "${INSTALLER_USER:-${ADMIN_USER}}:${ADMIN_PASS}" | chpasswd || true
fi
# Core virtualization and admin groups for all systems
for grp in libvirt qemu kvm wheel foreman; do
    getent group "$grp" >/dev/null 2>&1 || groupadd -f "$grp" || true
done
usermod -aG libvirt,qemu,kvm,wheel,foreman "$target_user" || true
sed -i -E 's/^#?[[:space:]]*%wheel[[:space:]]+ALL=\(ALL\)[[:space:]]+ALL/%wheel ALL=(ALL) NOPASSWD: ALL/' /etc/sudoers || true
printf '%s\n' "$target_user ALL=(ALL) NOPASSWD: ALL" > /etc/sudoers.d/90-mrhis-nopasswd
chmod 0440 /etc/sudoers.d/90-mrhis-nopasswd
visudo -cf /etc/sudoers >/dev/null 2>&1 || true
EOF
}

kickstart_rhsm_register_block() {
    local include_org_id="${1:-0}"

    cat <<'EOF'
# 2. Registration (retry until network/RHSM are reachable)
ks_log "Phase 2: Register with RHSM"
# Log credential presence (values never printed — only length/presence)
if [ -n "${RH_USER:-}" ]; then
    ks_log "  creds: RH_USER is SET (${#RH_USER} chars)"
else
    ks_log "  creds: RH_USER is EMPTY -- registration will be skipped"
fi
if [ -n "${RH_PASS:-}" ]; then
    ks_log "  creds: RH_PASS is SET (${#RH_PASS} chars)"
else
    ks_log "  creds: RH_PASS is EMPTY -- registration will be skipped"
fi
if [ -n "${CDN_ORGANIZATION_ID:-}" ]; then
    ks_log "  creds: CDN_ORGANIZATION_ID=${CDN_ORGANIZATION_ID}"
else
    ks_log "  creds: CDN_ORGANIZATION_ID is EMPTY"
fi
if [ -n "${CDN_SAT_ACTIVATION_KEY:-}" ]; then
    ks_log "  creds: CDN_SAT_ACTIVATION_KEY is SET"
else
    ks_log "  creds: CDN_SAT_ACTIVATION_KEY is EMPTY"
fi
ks_log "RHSM prereq: current /etc/resolv.conf"
while IFS= read -r _l; do ks_log "  resolv: ${_l}"; done < /etc/resolv.conf || ks_log "  resolv: (empty or missing)"
ks_log "RHSM prereq: route table"
ip route show 2>&1 | while IFS= read -r _l; do ks_log "  route: ${_l}"; done || true
ks_log "RHSM prereq: IPv4 interfaces"
ip -4 -br addr show 2>&1 | while IFS= read -r _l; do ks_log "  addr: ${_l}"; done || true

# %post chroot frequently has no active default route yet. Try a temporary
# DHCP bootstrap on eth0 so RHSM can resolve/reach subscription endpoints.
if ! ip route show | grep -q '^default'; then
    ks_log "RHSM prereq: no default route detected; attempting DHCP bootstrap on eth0"
    ip link set eth0 up >/dev/null 2>&1 || true
    if command -v dhclient >/dev/null 2>&1; then
        dhclient -4 -1 -v eth0 2>&1 | while IFS= read -r _l; do ks_log "  dhcp: ${_l}"; done || true
    else
        ks_log "  dhcp: dhclient not available in target image"
    fi
    ks_log "RHSM prereq: route table after DHCP bootstrap"
    ip route show 2>&1 | while IFS= read -r _l; do ks_log "  route: ${_l}"; done || true
fi

# If resolv.conf is still using public resolvers and DNS lookup fails in this
# environment, fall back to the active default gateway as nameserver.
_default_gw=$(ip route show default 2>/dev/null | awk '/^default/ {print $3; exit}')
if [ -n "${_default_gw:-}" ]; then
    ks_log "RHSM prereq: detected default gateway ${_default_gw}"
fi
ks_log "RHSM prereq: DNS lookup for subscription.rhsm.redhat.com"
_dns_out=$(getent ahostsv4 subscription.rhsm.redhat.com 2>&1 || true)
if [ -n "${_dns_out}" ]; then
    while IFS= read -r _l; do ks_log "  dns: ${_l}"; done <<< "${_dns_out}"
else
    ks_log "  dns: FAILED - no result (DNS not working)"
    if [ -n "${_default_gw:-}" ]; then
        ks_log "  dns: retrying with gateway resolver ${_default_gw}"
        printf 'nameserver %s\n' "${_default_gw}" > /etc/resolv.conf 2>/dev/null || true
        _dns_out=$(getent ahostsv4 subscription.rhsm.redhat.com 2>&1 || true)
        if [ -n "${_dns_out}" ]; then
            while IFS= read -r _l; do ks_log "  dns: ${_l}"; done <<< "${_dns_out}"
        else
            ks_log "  dns: still failed after gateway resolver fallback"
        fi
    fi
fi
ks_log "RHSM prereq: HTTPS reachability test to subscription.rhsm.redhat.com"
_curl_rc=0
curl -s -o /dev/null -w "%{http_code} connect=%{time_connect}s total=%{time_total}s" \
    --connect-timeout 15 --max-time 30 \
    https://subscription.rhsm.redhat.com/subscription/status 2>&1 | \
    while IFS= read -r _l; do ks_log "  https: ${_l}"; done || _curl_rc=$?
[ "${_curl_rc}" -ne 0 ] && ks_log "  https: FAILED (exit code ${_curl_rc}) - cannot reach RHSM" || true

# In deferred component-install mode, do not burn through full RHSM retry loops
# when the installer environment clearly has no network path yet.
MRHIS_SKIP_RHSM_REGISTER=0
if [ "${MRHIS_DEFER_COMPONENT_INSTALL:-1}" = "1" ]; then
    _has_default_route=0
    ip route show | grep -q '^default' && _has_default_route=1 || true
    if [ "${_has_default_route}" -ne 1 ] || [ -z "${_dns_out:-}" ] || [ "${_curl_rc}" -ne 0 ]; then
        MRHIS_SKIP_RHSM_REGISTER=1
        ks_log "RHSM prereq: network not ready in %post; deferring RHSM registration to post-boot config-as-code"
        install -d -m 0755 /var/lib/mrhis >/dev/null 2>&1 || true
        printf '%s\n' "deferred_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)" > /var/lib/mrhis/rhsm-registration-deferred || true
    fi
fi

# If %post chroot has no real interfaces/default route, try running RHSM calls
# in PID 1 network namespace (installer environment) while keeping target root.
MRHIS_SM_REGISTER_CMD="subscription-manager register"
if ! ip -4 -br addr show | awk '{print $1}' | grep -qvE '^(lo)$' || ! ip route show | grep -q '^default'; then
    if command -v nsenter >/dev/null 2>&1 && [ -r /proc/1/ns/net ]; then
        ks_log "RHSM prereq: enabling nsenter network namespace fallback for subscription-manager"
        MRHIS_SM_REGISTER_CMD="nsenter -t 1 -n subscription-manager register"
    else
        ks_log "RHSM prereq: nsenter unavailable; continuing without netns fallback"
    fi
fi

mrhis_sm_register() {
    # shellcheck disable=SC2086
    eval "${MRHIS_SM_REGISTER_CMD} $*"
}
register_rhsm() {
    local try
    for try in $(seq 1 10); do
        ks_log "RHSM registration attempt ${try}/10"
        echo "RHSM registration attempt $try/10..."

        # Attempt registration using the configured registration command.
        # Use the helper wrapper so implementations can vary per platform.
        if mrhis_sm_register register >/dev/null 2>&1; then
            ks_log "RHSM registration successful"
            return 0
        fi

        ks_log "  attempt ${try} failed -- last subscription-manager error:"
        subscription-manager status 2>&1 | while IFS= read -r _l; do ks_log "    sm: ${_l}"; done || true
        subscription-manager clean >/dev/null 2>&1 || true
        sleep_with_spinner 15 "  Retrying subscription-manager registration"
    done

    ks_log "ERROR: RHSM registration failed after 10 retries"
    subscription-manager status 2>&1 | while IFS= read -r _l; do ks_log "  sm: ${_l}"; done || true
    subscription-manager version 2>&1 | while IFS= read -r _l; do ks_log "  sm: ${_l}"; done || true
    return 1
}

if [ "${MRHIS_SKIP_RHSM_REGISTER:-0}" -eq 1 ]; then
    ks_log "RHSM registration skipped in %post (deferred mode + network not ready)."
else
    if ! register_rhsm; then
        if [ "${MRHIS_DEFER_COMPONENT_INSTALL:-1}" = "1" ]; then
            ks_log "WARNING: RHSM registration failed in %post; continuing because component install is deferred."
            install -d -m 0755 /var/lib/mrhis >/dev/null 2>&1 || true
            printf '%s\n' "failed_at=$(date -u +%Y-%m-%dT%H:%M:%SZ)" > /var/lib/mrhis/rhsm-registration-failed-in-post || true
        else
            ks_log "ERROR: RHSM registration failed. Satellite installation will not proceed."
            ks_log "DEBUG: Network diagnostics:"
            ip addr show 2>&1 | while IFS= read -r _l; do ks_log "  net: ${_l}"; done || true
            ip route show 2>&1 | while IFS= read -r _l; do ks_log "  route: ${_l}"; done || true
            ping -c 3 8.8.8.8 2>&1 | while IFS= read -r _l; do ks_log "  ping: ${_l}"; done || ks_log "  ping: FAILED - no external IP connectivity"
            ks_log "DEBUG: RHSM config:"
            cat /etc/rhsm/rhsm.conf 2>&1 | while IFS= read -r _l; do ks_log "  rhsm: ${_l}"; done || true
            exit 1
        fi
    else
        subscription-manager refresh || true
    fi
fi
EOF
}

kickstart_rhc_connect_block() {
    cat <<'EOF'
# 2.1 Red Hat Hybrid Cloud Console registration (rhc)
ks_log "Phase 2.1: Optional rhc registration"
    if [ "${RHC_AUTO_CONNECT:-1}" = "1" ]; then
    dnf install -y ${DNF_FLAGS} rhc >/dev/null 2>&1 || true
    if command -v rhc >/dev/null 2>&1; then
        if ! rhc status >/dev/null 2>&1; then
            if [ -n "${RHC_ORGANIZATION_ID:-}" ] && [ -n "${RHC_ACTIVATION_KEY:-}" ]; then
                rhc connect --activation-key "${RHC_ACTIVATION_KEY}" --organization "${RHC_ORGANIZATION_ID}" >/dev/null 2>&1 || true
            else
                rhc connect --username="${RH_USER}" --password="${RH_PASS}" >/dev/null 2>&1 || true
            fi
        fi
    fi
fi
EOF
}

kickstart_repo_enable_verify_block() {
    local role_label="$1"
    shift
    local -a repos=("$@")
    local i

    printf '%s\n' '# 3. Repositories'
    printf 'ks_log "%s"\n' "Phase 3: Enable ${role_label} repositories"
    printf '%s\n' 'subscription-manager refresh || true'
    printf '%s\n' 'subscription-manager identity || { echo "ERROR: RHSM identity missing before repo enable."; exit 1; }'
    printf '%s\n' 'subscription-manager repos --disable="*" || true'
    printf '%s\n' 'repo_enable_ok=0'
    printf '%s\n' 'for repo_try in $(seq 1 5); do'
    printf '%s' '    subscription-manager repos'
    for i in "${repos[@]}"; do
        printf ' --enable="%s"' "$i"
    done
    printf ' >/dev/null 2>&1 && repo_enable_ok=1 && break\n'
    printf '%s\n' '    subscription-manager refresh >/dev/null 2>&1 || true'
    printf '%s\n' '    sleep 10'
    printf '%s\n' 'done'
    printf '%s\n' 'if [ "$repo_enable_ok" -ne 1 ]; then'
    printf '    echo "ERROR: Could not enable required %s repositories after retries."\n' "$role_label"
    printf '%s\n' '    subscription-manager repos --list || true'
    printf '%s\n' '    exit 1'
    printf '%s\n' 'fi'
    printf '%s\n\n' 'dnf clean all || true'
    printf '%s\n' 'dnf makecache --refresh || true'
    printf '\n'

    printf '%s\n' 'for repo in \'
    for ((i=0; i<${#repos[@]}; i++)); do
        if [ "$i" -lt $(( ${#repos[@]} - 1 )) ]; then
            printf '    %s \\\n' "${repos[$i]}"
        else
            printf '    %s; do\n' "${repos[$i]}"
        fi
    done

    printf '%s\n' '    if ! subscription-manager repos --list-enabled | grep -q "$repo"; then'
    printf '        echo "ERROR: Required %s repository not enabled: $repo"\n' "$role_label"
    printf '%s\n' '        subscription-manager repos --list-enabled || true'
    printf '%s\n' '        exit 1'
    printf '%s\n' '    fi'
    printf '%s\n' 'done'
    printf 'echo "INFO: %s enabled repositories after registration:"\n' "$role_label"
    printf '%s\n' "subscription-manager repos --list-enabled 2>/dev/null | sed -n 's/^Repo ID:[[:space:]]*/  - /p' || true"
    printf '%s\n' 'dnf repolist || true'
}

kickstart_satellite_package_install_block() {
    # Install satellite support packages after repos are enabled
    # Uses dnf with --skip-broken to tolerate missing packages
    cat <<'EOF'
# 3.6 Install Satellite Support Packages
ks_log "Phase 3.6: Install satellite support packages (tolerate failures)"
packages_to_install=(
    "dhcp-server" "tftp-server" "httpd" 
    "shim-x64" "grub2-efi-x64" "grub2-efi-x64-modules" "grub2-tools"
    "bind" "syslinux"
    "bash-completion" "git" "network-scripts" "sos" "setroubleshoot-server"
    "osbuild-composer" "cbootc" "podman" "skopeo" "composer-cli" "cockpit-composer"
    "vim"
)

# Prefer a single dnf transaction so all package output is captured in the
# kickstart %post log (/root/ks-post.log). If the bulk transaction fails,
# fall back to per-package installs (appending to the same log) to identify
# tolerant failures while keeping a single consolidated log file.
ks_log "Attempting single-package-transaction for Satellite support packages"
if dnf install -y --skip-broken --allowerasing --best "${packages_to_install[@]}"; then
    ks_log "Satellite support packages installed in a single transaction"
else
    ks_log "Bulk install failed; falling back to per-package install (appending to same log)"
    install_ok=0
    install_failed=0
    for pkg in "${packages_to_install[@]}"; do
        if dnf install -y --skip-broken --allowerasing --best "${pkg}"; then
            install_ok=$((install_ok + 1))
        else
            install_failed=$((install_failed + 1))
            ks_log "    ⚠ Skipped (tolerated): ${pkg}"
        fi
    done
    ks_log "Satellite support packages - installed: ${install_ok}, skipped/failed: ${install_failed}"
fi
EOF
}

kickstart_runtime_exports_block() {
    local bootstrap_keys_block="$1"
    local installer_user_q admin_user_q admin_pass_q rh_user_q rh_pass_q domain_q host_int_ip_q cmdb_endpoint_ip_q defer_component_install_q mrhis_temp_rc_local_q cockpit_port_q installer_email_q
    local cdn_org_q cdn_sat_key_q rhc_org_q rhc_key_q

    # Inside the kickstart %post the "installer user" is the remote admin account
    # (ADMIN_USER), not the local operator running this script on the install host.
    # The local operator username has no place on the target VMs.
    installer_user_q="$(printf '%q' "${ADMIN_USER}")"
    admin_user_q="$(printf '%q' "${ADMIN_USER}")"
    admin_pass_q="$(printf '%q' "${ADMIN_PASS}")"
    rh_user_q="$(printf '%q' "${RH_USER}")"
    rh_pass_q="$(printf '%q' "${RH_PASS}")"
    domain_q="$(printf '%q' "${DOMAIN:-}")"
    host_int_ip_q="$(printf '%q' "${HOST_INT_IP:-10.168.0.1}")"
    cmdb_endpoint_ip_q="$(printf '%q' "${CMDB_ENDPOINT_IP:-$(default_cmdb_endpoint_ip)}")"
    defer_component_install_q="$(printf '%q' "${MRHIS_DEFER_COMPONENT_INSTALL:-1}")"
    mrhis_temp_rc_local_q="$(printf '%q' "${MRHIS_TEMP_ENABLE_RC_LOCAL_EXEC:-1}")"
    cockpit_port_q="$(printf '%q' "${COCKPIT_PORT:-9443}")"
    installer_email_q="$(printf '%q' "${MRHIS_INSTALLER_EMAIL:-${AAP_LIGHTSPEED_ADMIN_EMAIL:-${ADMIN_USER:-admin}@${DOMAIN:-example.com}}}")"
    cdn_org_q="$(printf '%q' "${CDN_ORGANIZATION_ID:-}")"
    cdn_sat_key_q="$(printf '%q' "${CDN_SAT_ACTIVATION_KEY:-}")"
    rhc_org_q="$(printf '%q' "${RHC_ORGANIZATION_ID:-${CDN_ORGANIZATION_ID:-}}")"
    rhc_key_q="$(printf '%q' "${RHC_ACTIVATION_KEY:-${CDN_SAT_ACTIVATION_KEY:-}}")"

    cat <<EOF
# MRHIS runtime values injected at kickstart generation time
ADMIN_USER=${admin_user_q}
ADMIN_PASS=${admin_pass_q}
INSTALLER_USER=${installer_user_q}
RH_USER=${rh_user_q}
RH_PASS=${rh_pass_q}
DOMAIN=${domain_q}
HOST_INT_IP=${host_int_ip_q}
CMDB_ENDPOINT_IP=${cmdb_endpoint_ip_q}
CDN_ORGANIZATION_ID=${cdn_org_q}
CDN_SAT_ACTIVATION_KEY=${cdn_sat_key_q}
RHC_ORGANIZATION_ID=${rhc_org_q}
RHC_ACTIVATION_KEY=${rhc_key_q}
COCKPIT_PORT=${cockpit_port_q}
MRHIS_INSTALLER_EMAIL=${installer_email_q}
MRHIS_DEFER_COMPONENT_INSTALL=${defer_component_install_q}
MRHIS_TEMP_ENABLE_RC_LOCAL_EXEC=${mrhis_temp_rc_local_q}
bootstrap_ssh_keys="\$(cat <<'MRHIS_BOOTSTRAP_KEYS'
${bootstrap_keys_block}
MRHIS_BOOTSTRAP_KEYS
)"
export ADMIN_USER ADMIN_PASS INSTALLER_USER RH_USER RH_PASS DOMAIN HOST_INT_IP CMDB_ENDPOINT_IP CDN_ORGANIZATION_ID CDN_SAT_ACTIVATION_KEY RHC_ORGANIZATION_ID RHC_ACTIVATION_KEY COCKPIT_PORT MRHIS_INSTALLER_EMAIL MRHIS_DEFER_COMPONENT_INSTALL MRHIS_TEMP_ENABLE_RC_LOCAL_EXEC bootstrap_ssh_keys
EOF
}

kickstart_networkmanager_dual_nic_block() {
    local ext_mac="$1"
    local int_mac="$2"
    local int_ip="$3"
    local int_prefix="$4"
    local int_gw="$5"

    cat <<EOF
# 0. Deterministic NetworkManager keyfiles (persisted for first boot)
ks_log "Phase 0: Configure persistent dual-NIC NetworkManager keyfiles"
mkdir -p /etc/NetworkManager/system-connections /etc/NetworkManager/conf.d
rm -f /etc/NetworkManager/system-connections/*.nmconnection || true

cat > /etc/NetworkManager/system-connections/eth0.nmconnection <<'EOF_NM_ETH0'
[connection]
id=eth0
type=ethernet
autoconnect=true

[ethernet]
mac-address=${ext_mac}

[ipv4]
method=auto
# DHCP primary with explicit resolver fallback for early bootstrap tasks.
dns=10.168.0.1;1.1.1.1;8.8.8.8;
dns-options=rotate;
ignore-auto-dns=false

[ipv6]
method=auto
EOF_NM_ETH0

cat > /etc/NetworkManager/system-connections/eth1.nmconnection <<'EOF_NM_ETH1'
[connection]
id=eth1
type=ethernet
autoconnect=true

[ethernet]
mac-address=${int_mac}

[ipv4]
# Internal management network — static IP, no default route.
# eth0 (DHCP) is the sole default route for internet access.
# Intra-cluster VMs are on the same /16 subnet so no gateway is needed.
method=manual
addresses=${int_ip}/${int_prefix}
never-default=true

[ipv6]
method=ignore
EOF_NM_ETH1

chmod 600 /etc/NetworkManager/system-connections/eth0.nmconnection /etc/NetworkManager/system-connections/eth1.nmconnection

cat > /etc/NetworkManager/conf.d/10-mrhis-no-auto-default.conf <<'EOF_NM_MAIN'
[main]
no-auto-default=${ext_mac},${int_mac}
EOF_NM_MAIN

systemctl enable NetworkManager || true

# Bootstrap DNS for kickstart %post registration.
# Anaconda runs %post in a chroot — NetworkManager is NOT running inside it,
# so /run/NetworkManager/resolv.conf never exists.  Write a static fallback now;
# NM will take over resolv.conf management on first boot.
if [ ! -s /etc/resolv.conf ]; then
    printf 'nameserver 8.8.8.8\nnameserver 1.1.1.1\n' > /etc/resolv.conf || true
fi

# Dynamic DNS fallback: prefer gateways of the first two ethernet devices
# This helps when device ordering varies; it will set the active connection's
# IPv4 DNS list to GW1 GW2 8.8.8.8 1.1.1.1 and add search domain.
cat > /usr/local/bin/mrhis-set-dns.sh <<'EOF_MRHIS_SET_DNS'
#!/bin/bash
set -euo pipefail
ETH_DEVS=(\$(nmcli -t -f DEVICE,TYPE device | grep ethernet | cut -d: -f1 | head -n2))
GW1=""
GW2=""
if [ -n "\${ETH_DEVS[0]:-}" ]; then
    GW1=\$(nmcli -g IP4.GATEWAY device show "\${ETH_DEVS[0]}" 2>/dev/null || true)
fi
if [ -n "\${ETH_DEVS[1]:-}" ]; then
    GW2=\$(nmcli -g IP4.GATEWAY device show "\${ETH_DEVS[1]}" 2>/dev/null || true)
fi
CON_NAME=\$(nmcli -t -f NAME connection show --active | head -n1)
DNS_LIST=""
[ -n "\$GW1" ] && DNS_LIST="\$GW1"
[ -n "\$GW2" ] && DNS_LIST="\$DNS_LIST \$GW2"
DNS_LIST="\$DNS_LIST 8.8.8.8 1.1.1.1"
# Use configured DOMAIN if available, fall back to example.com
DNS_SEARCH="\${DOMAIN:-example.com}"
if [ -n "\$CON_NAME" ]; then
    nmcli connection modify "\$CON_NAME" ipv4.dns "\$DNS_LIST" ipv4.dns-search "\$DNS_SEARCH" ipv4.dns-options "rotate,timeout:1,attempts:1" ipv4.ignore-auto-dns yes || true
    nmcli connection up "\$CON_NAME" || true
fi
EOF_MRHIS_SET_DNS

chmod 0755 /usr/local/bin/mrhis-set-dns.sh || true
/usr/local/bin/mrhis-set-dns.sh || true

# Ensure internal management IP is present on first boot. This is a fallback
# that finds the interface by MAC and assigns the static IP if NetworkManager
# hasn't activated the connection yet.
cat > /usr/local/bin/mrhis-ensure-internal-ip.sh <<EOF_MRHIS_INTERNAL
#!/bin/bash
set -euo pipefail
INT_MAC='${int_mac}'
INT_IP='${int_ip}'
INT_PREFIX='${int_prefix}'

# Find device name by MAC address (case-insensitive)
dev=\$(ip -o link | awk -F': ' -v mac="\${INT_MAC}" 'tolower(\$0) ~ tolower(mac) {print \$2; exit}')
if [ -n "\${dev:-}" ]; then
    if ! ip -4 addr show dev "\${dev}" | grep -q "\${INT_IP}"; then
        /sbin/ip addr add \${INT_IP}/\${INT_PREFIX} dev "\${dev}" || true
        /sbin/ip link set "\${dev}" up || true
    fi
fi

# Derive a live internal IP (prefer eth1 device found above). If missing,
# try to detect any 10.168.x.x address from hostname -I as a last resort.
LIVE_IP=""
if [ -n "\${dev:-}" ]; then
    LIVE_IP=\$(ip -4 -o addr show dev "\${dev}" 2>/dev/null | awk '{print \$4}' | cut -d/ -f1 || true)
fi
if [ -z "\${LIVE_IP:-}" ]; then
    LIVE_IP=\$(hostname -I 2>/dev/null | tr ' ' '\n' | grep '^10\.168\.' | head -n1 || true)
fi

if [ -n "\${LIVE_IP:-}" ] && [ -x /usr/local/bin/mrhis-apply-motd-splash.sh ]; then
    /usr/local/bin/mrhis-apply-motd-splash.sh || true
fi
EOF_MRHIS_INTERNAL
chmod 0755 /usr/local/bin/mrhis-ensure-internal-ip.sh || true

cat > /etc/systemd/system/mrhis-ensure-internal-ip.service <<'EOF_MRHIS_SERVICE'
[Unit]
Description=MRHIS: ensure internal management IP is assigned
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/mrhis-ensure-internal-ip.sh

[Install]
WantedBy=multi-user.target
EOF_MRHIS_SERVICE

systemctl daemon-reload || true
systemctl enable --now mrhis-ensure-internal-ip.service || true
EOF
}

mrhis_component_selected() {
    local component="$1"
    local scope="${CLI_CONFIG_SCOPE:-${MRHIS_COMPONENT_SCOPE:-}}"
    local explicit_cli_components=0

    if [ -n "${CLI_IDM:-}${CLI_SATELLITE:-}${CLI_AAP:-}${CLI_GITTEA:-}${CLI_OPENSHIFT:-}${CLI_OPENSTACK_ALIAS:-}" ]; then
        explicit_cli_components=1
    fi

    case "${scope}" in
        idm)                     [ "${component}" = "idm" ] && return 0 ;;
        satellite)               [ "${component}" = "satellite" ] && return 0 ;;
        aap|rhis-aap)            [ "${component}" = "aap" ] && return 0 ;;
        gittea)                  [ "${component}" = "gittea" ] && return 0 ;;
        openshift|openstack)     [ "${component}" = "openshift" ] && return 0 ;;
        rhis)
            case "${component}" in satellite|aap|idm) return 0 ;; esac
            ;;
        fullstack|all)
            case "${component}" in satellite|aap|idm|gittea|openshift) return 0 ;; esac
            ;;
    esac

    if [ -z "${scope}" ] && [ -n "${MRHIS_INSTALL_COMPONENT:-}" ] && [ "${explicit_cli_components}" -eq 0 ] && [ -z "${CLI_MRHIS:-}" ]; then
        case "${MRHIS_INSTALL_COMPONENT}" in
            idm)        [ "${component}" = "idm" ] && return 0 ;;
            satellite)  [ "${component}" = "satellite" ] && return 0 ;;
            aap)        [ "${component}" = "aap" ] && return 0 ;;
            gittea)     [ "${component}" = "gittea" ] && return 0 ;;
            full)       case "${component}" in satellite|aap|idm) return 0 ;; esac ;;
        esac
    fi

    if [ "${explicit_cli_components}" -eq 1 ] && [ -z "${CLI_MRHIS:-}" ] && [ -z "${CLI_FULLSTACK:-}" ] && [ -z "${scope}" ]; then
        case "${component}" in
            idm)       [ -n "${CLI_IDM:-}" ] && return 0 ;;
            satellite) [ -n "${CLI_SATELLITE:-}" ] && return 0 ;;
            aap)       [ -n "${CLI_AAP:-}" ] && return 0 ;;
            gittea)    [ -n "${CLI_GITTEA:-}" ] && return 0 ;;
            openshift) [ -n "${CLI_OPENSHIFT:-}${CLI_OPENSTACK_ALIAS:-}" ] && return 0 ;;
        esac
        return 1
    fi

    case "${component}" in
        satellite|aap|idm)
            return 0
            ;;
        gittea)
            if [ -n "${CLI_FULLSTACK:-}" ] || [ -n "${CLI_GITTEA:-}" ]; then
                return 0
            fi
            ;;
        openshift)
            if [ -n "${CLI_FULLSTACK:-}" ] || [ -n "${CLI_OPENSHIFT:-}${CLI_OPENSHIFT_IMPLICIT:-}${CLI_OPENSTACK_ALIAS:-}" ]; then
                return 0
            fi
            ;;
    esac

    return 1
}

mrhis_selected_node_specs() {
    local include_satellite=0 include_aap=0 include_idm=0 include_gittea=0 include_openshift=0

    mrhis_component_selected satellite && include_satellite=1
    mrhis_component_selected aap && include_aap=1
    mrhis_component_selected idm && include_idm=1
    mrhis_component_selected gittea && include_gittea=1
    mrhis_component_selected openshift && include_openshift=1

    if [ "${include_satellite}" -eq 1 ]; then
        printf '%s|%s|%s|%s\n' "satellite" "${SAT_IP:-10.168.128.1}" "${SAT_HOSTNAME:-satellite.${DOMAIN:-prod.spg}}" "${SAT_ALIAS:-satellite}"
    fi
    if [ "${include_aap}" -eq 1 ]; then
        printf '%s|%s|%s|%s\n' "aap" "${AAP_IP:-10.168.128.2}" "${AAP_HOSTNAME:-aap.${DOMAIN:-prod.spg}}" "${AAP_ALIAS:-aap}"
    fi
    if [ "${include_idm}" -eq 1 ]; then
        printf '%s|%s|%s|%s\n' "idm" "${IDM_IP:-10.168.128.3}" "${IDM_HOSTNAME:-idm.${DOMAIN:-prod.spg}}" "${IDM_ALIAS:-idm}"
    fi
    if [ "${include_gittea}" -eq 1 ]; then
        printf '%s|%s|%s|%s\n' "gittea" "${GITTEA_IP:-10.168.128.4}" "${GITTEA_HOSTNAME:-gittea.${DOMAIN:-prod.spg}}" "${GITTEA_ALIAS:-gittea}"
    fi
    if [ "${include_openshift}" -eq 1 ]; then
        printf '%s|%s|%s|%s\n' "openshift" "${OPENSHIFT_IP:-10.168.128.5}" "${OPENSHIFT_HOSTNAME:-openshift.${DOMAIN:-prod.spg}}" "${OPENSHIFT_ALIAS:-openshift}"
    fi
}

kickstart_hosts_mapping_block() {
    local vm ip fqdn alias short
    local hosts_lines=""
    local sat_ip sat_fqdn sat_alias
    local aap_ip aap_fqdn aap_alias
    local idm_ip idm_fqdn idm_alias
    local gittea_ip gittea_fqdn gittea_alias
    local openshift_ip openshift_fqdn openshift_alias
    local installer_ip installer_fqdn installer_alias

    _kickstart_hosts_row() {
        local _ip="$1" _fqdn="$2" _alias="$3"
        printf '%s %s %s\n' "${_ip}" "${_fqdn}" "${_alias}"
    }

    sat_ip="${SAT_IP:-10.168.128.1}"
    sat_fqdn="${SAT_HOSTNAME:-satellite.${DOMAIN:-prod.spg}}"
    sat_alias="${SAT_ALIAS:-satellite}"
    hosts_lines+="$(_kickstart_hosts_row "${sat_ip}" "${sat_fqdn}" "${sat_alias}")"

    aap_ip="${AAP_IP:-10.168.128.2}"
    aap_fqdn="${AAP_HOSTNAME:-aap.${DOMAIN:-prod.spg}}"
    aap_alias="${AAP_ALIAS:-aap}"
    hosts_lines+="$(_kickstart_hosts_row "${aap_ip}" "${aap_fqdn}" "${aap_alias}")"

    idm_ip="${IDM_IP:-10.168.128.3}"
    idm_fqdn="${IDM_HOSTNAME:-idm.${DOMAIN:-prod.spg}}"
    idm_alias="${IDM_ALIAS:-idm}"
    hosts_lines+="$(_kickstart_hosts_row "${idm_ip}" "${idm_fqdn}" "${idm_alias}")"

    gittea_ip="${GITTEA_IP:-10.168.128.4}"
    gittea_fqdn="${GITTEA_HOSTNAME:-gittea.${DOMAIN:-prod.spg}}"
    gittea_alias="${GITTEA_ALIAS:-gittea}"
    hosts_lines+="$(_kickstart_hosts_row "${gittea_ip}" "${gittea_fqdn}" "${gittea_alias}")"

    openshift_ip="${OPENSHIFT_IP:-10.168.128.5}"
    openshift_fqdn="${OPENSHIFT_HOSTNAME:-openshift.${DOMAIN:-prod.spg}}"
    openshift_alias="${OPENSHIFT_ALIAS:-openshift}"
    hosts_lines+="$(_kickstart_hosts_row "${openshift_ip}" "${openshift_fqdn}" "${openshift_alias}")"

    installer_ip="${INSTALLER_IP:-${HOST_INT_IP:-10.168.0.1}}"
    installer_fqdn="${INSTALLER_HOSTNAME:-installer.${DOMAIN:-prod.spg}}"
    installer_alias="${INSTALLER_ALIAS:-installer}"
    hosts_lines+="$(_kickstart_hosts_row "${installer_ip}" "${installer_fqdn}" "${installer_alias}")"

    while IFS='|' read -r vm ip fqdn alias; do
        [ -n "${ip:-}" ] || continue
        [ -n "${fqdn:-}" ] || continue
        short="${fqdn%%.*}"
        [ -n "${short:-}" ] || short="${alias:-${vm}}"

        case " ${hosts_lines} " in
            *" ${ip} ${fqdn} "*)
                continue
                ;;
        esac

        hosts_lines+="$(_kickstart_hosts_row "${ip}" "${fqdn}" "${alias:-${short}}")"
    done < <(mrhis_selected_node_specs)

    [ -n "${hosts_lines}" ] || hosts_lines="# No selected node host mappings at generation time"

    cat <<EOF
# 1. Local hosts mapping (temporary DNS-independent bootstrap)
cat > /etc/hosts <<EOF_HOSTS
# Loopback entries; do not change.
# For historical reasons, localhost precedes localhost.localdomain:
127.0.0.1   localhost localhost.localdomain localhost4 localhost4.localdomain4
::1         localhost localhost.localdomain localhost6 localhost6.localdomain6

# BEGIN RHIS INTERNAL HOSTS
# Generated by MRHIS — managed block. Do not hand-edit this block.
# Reminder: The internal MRHIS network defaults to 10.168.0.0/16. You can
# change these values during installer prompts or in ~/.ansible/conf/env.yml
# (the installer persists answers there). Ensure the installer node has an
# entry on the internal network (gateway/DNS at INSTALLER_IP).
#
# Variables populated from ~/.ansible/conf/env.yml (if present):
# SAT_IP, AAP_IP, IDM_IP, INSTALLER_IP, INTERNAL_NETWORK
# BEGIN MRHIS INTERNAL HOSTS
${hosts_lines%$'\n'}
# END MRHIS INTERNAL HOSTS
# END RHIS INTERNAL HOSTS
EOF_HOSTS
EOF
}

kickstart_trust_bootstrap_keys_block() {
    local include_target_user_copy="${1:-1}"

    cat <<'EOF'
# 1.3 Trust installer/orchestration/container SSH keys for root and installer user
ks_log "Phase 1.3: Install bootstrap SSH keys"
mkdir -p /root/.ssh
chmod 700 /root/.ssh

# Ensure root has a local SSH keypair on first boot.
if [ ! -f /root/.ssh/id_rsa ]; then
    ssh-keygen -q -t rsa -b 4096 -N "" -f /root/.ssh/id_rsa || true
fi

cat >> /root/.ssh/authorized_keys <<SSH_KEYS
${bootstrap_ssh_keys}
SSH_KEYS
[ -f /root/.ssh/id_rsa.pub ] && cat /root/.ssh/id_rsa.pub >> /root/.ssh/authorized_keys || true
sort -u /root/.ssh/authorized_keys -o /root/.ssh/authorized_keys || true
chmod 700 /root/.ssh
chmod 600 /root/.ssh/id_rsa 2>/dev/null || true
chmod 644 /root/.ssh/id_rsa.pub 2>/dev/null || true
chmod 600 /root/.ssh/authorized_keys
EOF

    if [ "$include_target_user_copy" = "1" ]; then
        cat <<'EOF'
if id "$target_user" >/dev/null 2>&1; then
    :
fi

configured_users=""
for _user in "${ADMIN_USER:-}" "${INSTALLER_USER:-}"; do
    [ -n "$_user" ] || continue
    case " ${configured_users} " in
        *" ${_user} "*)
            continue
            ;;
    esac
    configured_users="${configured_users} ${_user}"

    id "$_user" >/dev/null 2>&1 || continue

    target_home="$(getent passwd "$_user" | cut -d: -f6)"
    [ -n "$target_home" ] || target_home="/home/$_user"
    install -d -m 700 -o "$_user" -g "$_user" "$target_home/.ssh"

    # Ensure each managed user has a local SSH keypair.
    if [ ! -f "$target_home/.ssh/id_rsa" ]; then
        sudo -u "$_user" ssh-keygen -q -t rsa -b 4096 -N "" -f "$target_home/.ssh/id_rsa" || true
    fi

    cat > "$target_home/.ssh/authorized_keys" <<SSH_KEYS
${bootstrap_ssh_keys}
SSH_KEYS
    [ -f "$target_home/.ssh/id_rsa.pub" ] && cat "$target_home/.ssh/id_rsa.pub" >> "$target_home/.ssh/authorized_keys" || true
    [ -f /root/.ssh/id_rsa.pub ] && cat /root/.ssh/id_rsa.pub >> "$target_home/.ssh/authorized_keys" || true
    [ -f "$target_home/.ssh/id_rsa.pub" ] && cat "$target_home/.ssh/id_rsa.pub" >> /root/.ssh/authorized_keys || true
    sort -u "$target_home/.ssh/authorized_keys" -o "$target_home/.ssh/authorized_keys" || true
    sort -u /root/.ssh/authorized_keys -o /root/.ssh/authorized_keys || true
    chown "$_user:$_user" "$target_home/.ssh/authorized_keys"
    chown "$_user:$_user" "$target_home/.ssh/id_rsa" "$target_home/.ssh/id_rsa.pub" 2>/dev/null || true
    chmod 600 "$target_home/.ssh/id_rsa" 2>/dev/null || true
    chmod 644 "$target_home/.ssh/id_rsa.pub" 2>/dev/null || true
    chmod 600 "$target_home/.ssh/authorized_keys"
done
EOF
    fi
}

kickstart_common_components_block() {
    cat <<'EOF'
# MRHIS common kickstart components (shared across all nodes)
# Keep resolver behavior centralized instead of per-node manual edits.
ks_log "Phase 1.4: Apply common resolver/network bootstrap components"

if command -v systemctl >/dev/null 2>&1; then
    systemctl enable NetworkManager >/dev/null 2>&1 || true
fi

if [ -d /etc/NetworkManager ]; then
    install -d -m 0755 /etc/NetworkManager/dispatcher.d || true
    cat > /etc/NetworkManager/dispatcher.d/99-mrhis-resolv-options <<'EOF_MRHIS_RESOLV_DISPATCH'
#!/bin/sh
set -eu
ACTION="${2:-}"
RESOLV="/etc/resolv.conf"

case "${ACTION}" in
  up|dhcp4-change|dhcp6-change|vpn-up|connectivity-change)
    if [ -f "${RESOLV}" ] && ! grep -Eq '^[[:space:]]*options[[:space:]].*\brotate\b' "${RESOLV}"; then
      printf '%s\n' 'options rotate' >> "${RESOLV}"
    fi
    ;;
esac
EOF_MRHIS_RESOLV_DISPATCH
    chmod 0755 /etc/NetworkManager/dispatcher.d/99-mrhis-resolv-options || true
fi

if command -v systemctl >/dev/null 2>&1 && systemctl list-unit-files systemd-resolved.service >/dev/null 2>&1; then
    install -d -m 0755 /etc/systemd/resolved.conf.d || true
    cat > /etc/systemd/resolved.conf.d/99-mrhis-dns.conf <<'EOF_MRHIS_RESOLVED'
[Resolve]
DNS=10.168.0.1 8.8.8.8 1.1.1.1
FallbackDNS=1.1.1.1 8.8.8.8
EOF_MRHIS_RESOLVED
fi

if command -v systemctl >/dev/null 2>&1; then
    systemctl restart NetworkManager >/dev/null 2>&1 || true
    systemctl restart systemd-resolved >/dev/null 2>&1 || true
fi
EOF
}

kickstart_creator_baseline_block() {
    local role_name="$1"
    local node_hostname="$2"
    local node_ip="$3"
    local product_url_ip=""
    local product_url_dns=""

    case "${role_name}" in
        satellite)
            product_url_ip="https://${node_ip}/"
            product_url_dns="https://${node_hostname}/"
            ;;
        aap)
            product_url_ip="https://${node_ip}/"
            product_url_dns="https://${node_hostname}/"
            ;;
        idm)
            product_url_ip="https://${node_ip}/ipa/ui/"
            product_url_dns="https://${node_hostname}/ipa/ui/"
            ;;
        *)
            product_url_ip="https://${node_ip}/"
            product_url_dns="https://${node_hostname}/"
            ;;
    esac

    cat <<EOF
# MRHIS creator baseline (shared across all kickstarted nodes)
# Ensures common tooling/services expected by creator/bootstrap automation.
    dnf install -y ${DNF_FLAGS} sudo openssh-clients rsync jq ansible-core cockpit cockpit-system insights-client rhc || true
systemctl enable --now chronyd || true

# Configure Cockpit on a non-default port and enable it for immediate access.
cockpit_port="\${COCKPIT_PORT:-9443}"
if ! [[ "\${cockpit_port}" =~ ^[0-9]+$ ]] || [ "\${cockpit_port}" -lt 1 ] || [ "\${cockpit_port}" -gt 65535 ]; then
    cockpit_port="9443"
fi
    if systemctl list-unit-files cockpit.socket >/dev/null 2>&1; then
    mkdir -p /etc/systemd/system/cockpit.socket.d
    cat > /etc/systemd/system/cockpit.socket.d/override.conf <<'MRHIS_COCKPIT_OVERRIDE'
[Socket]
ListenStream=
ListenStream=HOST_IP_PLACEHOLDER:PORT_PLACEHOLDER
MRHIS_COCKPIT_OVERRIDE
    sed -i "s/HOST_IP_PLACEHOLDER/\${HOST_INT_IP}/g" /etc/systemd/system/cockpit.socket.d/override.conf
    sed -i "s/PORT_PLACEHOLDER/\${cockpit_port}/g" /etc/systemd/system/cockpit.socket.d/override.conf
    systemctl daemon-reload || true
    systemctl enable --now cockpit.socket || true
    systemctl restart cockpit.socket || true
fi

# Ensure Insights registration is attempted at first boot as well.
cat > /usr/local/bin/mrhis-register-insights.sh <<'MRHIS_INSIGHTS_SCRIPT'
#!/bin/bash
set -uo pipefail

log_file="/var/log/mrhis-insights-register.log"
mkdir -p /var/log

{
    echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] MRHIS insights registration start"

    if command -v insights-client >/dev/null 2>&1; then
        if ! insights-client --status >/dev/null 2>&1; then
            insights-client --register >/dev/null 2>&1 || true
        fi
        insights-client --status >/dev/null 2>&1 || true
    fi

    if command -v rhc >/dev/null 2>&1; then
        if ! rhc status >/dev/null 2>&1; then
            if [ -n "${RHC_ORGANIZATION_ID:-}" ] && [ -n "${RHC_ACTIVATION_KEY:-}" ]; then
                rhc connect --activation-key "${RHC_ACTIVATION_KEY}" --organization "${RHC_ORGANIZATION_ID}" >/dev/null 2>&1 || true
            elif [ -n "${RH_USER:-}" ] && [ -n "${RH_PASS:-}" ]; then
                rhc connect --username="${RH_USER}" --password="${RH_PASS}" >/dev/null 2>&1 || true
            fi
        fi
        rhc status >/dev/null 2>&1 || true
    fi

    touch /var/lib/mrhis/insights-registration-attempted
    echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] MRHIS insights registration end"
} >>"${log_file}" 2>&1
MRHIS_INSIGHTS_SCRIPT
chmod 0755 /usr/local/bin/mrhis-register-insights.sh || true

cat > /etc/systemd/system/mrhis-register-insights.service <<'MRHIS_INSIGHTS_SVC'
[Unit]
Description=MRHIS first-boot Insights/rhc registration attempt
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/mrhis-register-insights.sh
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
MRHIS_INSIGHTS_SVC
systemctl daemon-reload || true
systemctl enable mrhis-register-insights.service || true
/usr/local/bin/mrhis-register-insights.sh || true

# SSH login access banner with node and RHIS entry points.
cat > /etc/motd <<MRHIS_MOTD
[1;37m@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
[1;37m@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
[1;37m@@@@@@@@@@@[1;31m###########%[1;37m@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
[1;37m@@@@@@@@@@[1;31m###############%[1;37m@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
[1;37m@@@@@@@@@[1;31m#################[1;37m@@@@@@@@@@@@       @@@@@@@@@@@@@@@@@@@@  @@@@   @@@@@   @@@@@@@@@@@@@@@@@@@@
[1;37m@@@@@@@@@[1;31m##################[1;37m@@@@@@@@@@@   @@@   #@@@@@@@@@@@@@@@@@  @@@@   @@@@@   @@@@@@@@@@@   @@@@@@
