                                                     R E D   H A T

MRHIS Access Summary
=======================
Node role: \${role_name}
Node hostname: \${node_hostname}
Node IP: \${node_ip}

Cockpit (enabled, port \${COCKPIT_PORT:-9443}): https://\${node_ip}:\${COCKPIT_PORT:-9443}/  or  https://\${node_hostname}:\${COCKPIT_PORT:-9443}/
Product web UI: \${product_url_ip}  or  \${product_url_dns}

MRHIS internal services:
- Satellite: https://\${SAT_IP}/  (\${SAT_HOSTNAME})
- AAP: https://\${AAP_IP}:9443/  (\${AAP_HOSTNAME})
- AAP Gateway (container on AAP host): https://\${AAP_IP}:9443/  (\${AAP_HOSTNAME})
- IdM: https://\${IDM_IP}/ipa/ui/  (\${IDM_HOSTNAME})
- CMDB: http://\${CMDB_ENDPOINT_IP:-\${SAT_IP}}:18080/  (ansible-cmdb dashboard)

RHSM/Insights quick checks:
- subscription-manager identity
- rhc status
MRHIS_MOTD
chmod 0644 /etc/motd || true

cat > /etc/issue.d/mrhis.issue <<MRHIS_ISSUE
MRHIS node: \${node_hostname} (\${node_ip}) - role: \${role_name}
Cockpit: https://\${node_ip}:\${COCKPIT_PORT:-9443}/
Product UI: \${product_url_ip}
MRHIS_ISSUE
chmod 0644 /etc/issue.d/mrhis.issue || true
cat /etc/issue.d/mrhis.issue > /etc/issue 2>/dev/null || true

# Force a consistent shell title in Konsole and other xterm-compatible terminals.
cat > /etc/profile.d/mrhis-shell-title.sh <<'MRHIS_SHELL_TITLE'
#!/bin/sh
mrhis_title='RHIS: bash -- Konsole'

case "${TERM:-}" in
    xterm*|rxvt*|screen*|tmux*|konsole*|vt100*)
        printf '\033]0;%s\007' "${mrhis_title}" 2>/dev/null || true
        ;;
esac

if [ -n "${BASH_VERSION:-}" ]; then
    __mrhis_set_title() {
        printf '\033]0;%s\007' "${mrhis_title}" 2>/dev/null || true
    }
    case ";${PROMPT_COMMAND:-};" in
        *";__mrhis_set_title;"*) ;;
        *) PROMPT_COMMAND="__mrhis_set_title${PROMPT_COMMAND:+;${PROMPT_COMMAND}}" ;;
    esac
fi
MRHIS_SHELL_TITLE
chmod 0644 /etc/profile.d/mrhis-shell-title.sh || true

# Apply motd-splash-based console/login branding in a homogeneous way.
# This keeps all nodes visually consistent and prevents distro-specific
# defaults (like Cockpit 9090 banner lines) from leaking into /etc/issue.
cat > /usr/local/bin/mrhis-apply-motd-splash.sh <<'EOF_MRHIS_MOTD_SPLASH'
#!/bin/bash
set -uo pipefail

repo_dir="/opt/mrhis/motd-splash"
repo_url="https://github.com/GoKEV/motd-splash.git"
node_role="${role_name}"
node_hostname_static="${node_hostname}"
node_ip_static="${node_ip}"
installer_email="${MRHIS_INSTALLER_EMAIL:-${ADMIN_USER:-admin}@${DOMAIN:-example.com}}"

host_short="$(hostname -s 2>/dev/null || true)"
[ -n "${host_short:-}" ] || host_short="${node_hostname_static%%.*}"

domain_name="$(domainname 2>/dev/null || true)"
if [ -z "${domain_name:-}" ] || [ "${domain_name}" = "(none)" ]; then
    domain_name="${DOMAIN:-}"
fi
if [ -z "${domain_name:-}" ] || [ "${domain_name}" = "(none)" ]; then
    domain_name="${node_hostname_static#*.}"
fi

if [ -n "${domain_name:-}" ]; then
    host_fqdn="${host_short}.${domain_name}"
else
    host_fqdn="${host_short}"
fi

live_ip="$(hostname -I 2>/dev/null | tr ' ' '\n' | awk '/^10\.168\./{print; exit}')"
[ -n "${live_ip:-}" ] || live_ip="${node_ip_static}"
[ -n "${live_ip:-}" ] || live_ip="$(hostname -I 2>/dev/null | awk '{print $1}')"
[ -n "${live_ip:-}" ] || live_ip="127.0.0.1"

kernel_ver="$(uname -r 2>/dev/null || true)"
arch_val="$(uname -m 2>/dev/null || true)"
vendor="$(cat /sys/devices/virtual/dmi/id/sys_vendor 2>/dev/null || echo UnknownVendor)"
product_ver="$(cat /sys/devices/virtual/dmi/id/product_version 2>/dev/null || echo UnknownVersion)"
cores="$(nproc 2>/dev/null || echo 1)"

escape_sed_repl() {
    printf '%s' "$1" | sed -e 's/[\\&]/\\\\&/g' -e 's|/|\\/|g'
}

render_motd_template() {
    local src="$1"
    local dst="$2"

    local host_short_e live_ip_e kernel_e arch_e vendor_e product_ver_e cores_e
    host_short_e="$(escape_sed_repl "${host_short}")"
    live_ip_e="$(escape_sed_repl "${live_ip}")"
    kernel_e="$(escape_sed_repl "${kernel_ver}")"
    arch_e="$(escape_sed_repl "${arch_val}")"
    vendor_e="$(escape_sed_repl "${vendor}")"
    product_ver_e="$(escape_sed_repl "${product_ver}")"
    cores_e="$(escape_sed_repl "${cores}")"

    sed \
        -e "s/{{ ansible_hostname }}/${host_short_e}/g" \
        -e "s/{{ ansible_default_ipv4\\[\"address\"\\] }}/${live_ip_e}/g" \
        -e "s/{{ ansible_kernel }}/${kernel_e}/g" \
        -e "s/{{ ansible_machine }}/${arch_e}/g" \
        -e "s/{{ ansible_system_vendor }}/${vendor_e}/g" \
        -e "s/{{ ansible_product_version }}/${product_ver_e}/g" \
        -e "s/{{ ansible_processor_cores }}/${cores_e}/g" \
        "${src}" > "${dst}"
}

mkdir -p /opt/mrhis /etc/issue.d
if [ ! -d "${repo_dir}/.git" ]; then
    rm -rf "${repo_dir}" >/dev/null 2>&1 || true
    git clone --depth 1 "${repo_url}" "${repo_dir}" >/dev/null 2>&1 || true
fi

rm -f \
    "${repo_dir}/templates/motd_gokev" \
    "${repo_dir}/templates/motd_gokev_bw" \
    "${repo_dir}/motd-splash/templates/motd_gokev" \
    "${repo_dir}/motd-splash/templates/motd_gokev_bw" \
    >/dev/null 2>&1 || true

motd_tpl=""
issue_tpl=""
if [ -f "${repo_dir}/templates/motd_redhat" ] && [ -f "${repo_dir}/templates/issue" ]; then
    motd_tpl="${repo_dir}/templates/motd_redhat"
    issue_tpl="${repo_dir}/templates/issue"
elif [ -f "${repo_dir}/motd-splash/templates/motd_redhat" ] && [ -f "${repo_dir}/motd-splash/templates/issue" ]; then
    motd_tpl="${repo_dir}/motd-splash/templates/motd_redhat"
    issue_tpl="${repo_dir}/motd-splash/templates/issue"
fi

if [ -n "${motd_tpl}" ] && [ -n "${issue_tpl}" ]; then
    render_motd_template "${motd_tpl}" /etc/motd
    sed -e "s/{{ ansible_hostname }}/$(escape_sed_repl "${host_short}")/g" "${issue_tpl}" > /etc/issue
else
    cat > /etc/motd <<'EOF_MRHIS_MOTD_FALLBACK'
MRHIS Node
=============
EOF_MRHIS_MOTD_FALLBACK
    cat > /etc/issue <<'EOF_MRHIS_ISSUE_FALLBACK'
MRHIS managed system
EOF_MRHIS_ISSUE_FALLBACK
fi

{
    echo ""
    echo "MRHIS Login Header"
    echo "Role: ${node_role}"
    echo "WebUI: https://${host_fqdn}/ or https://${live_ip}/"
    echo "Installer email: ${installer_email}"
} >> /etc/motd

{
    echo ""
    echo "MRHIS Login Header"
    echo "Role: ${node_role}"
    echo "WebUI: https://${host_fqdn}/ or https://${live_ip}/"
    echo "Installer email: ${installer_email}"
} >> /etc/issue

cp -f /etc/issue /etc/issue.d/00-mrhis.issue 2>/dev/null || true
chmod 0644 /etc/motd /etc/issue /etc/issue.d/00-mrhis.issue 2>/dev/null || true
EOF_MRHIS_MOTD_SPLASH
chmod 0755 /usr/local/bin/mrhis-apply-motd-splash.sh || true

cat > /etc/systemd/system/mrhis-apply-motd-splash.service <<'EOF_MRHIS_MOTD_SPLASH_SVC'
[Unit]
Description=MRHIS: apply homogeneous motd-splash branding
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/mrhis-apply-motd-splash.sh

[Install]
WantedBy=multi-user.target
EOF_MRHIS_MOTD_SPLASH_SVC
systemctl daemon-reload || true
systemctl enable --now mrhis-apply-motd-splash.service || true
/usr/local/bin/mrhis-apply-motd-splash.sh || true

# Ensure the installer/admin account can run Ansible cleanly on every node.
target_user="${INSTALLER_USER:-${ADMIN_USER}}"
if id "$target_user" >/dev/null 2>&1; then
    :
fi

configured_users=""
for _user in "${ADMIN_USER:-}" "${INSTALLER_USER:-}"; do
    [ -n "$_user" ] || continue
    case " ${configured_users} " in
        *" ${_user} "*)
            continue
            ;;
    esac
    configured_users="${configured_users} ${_user}"

    id "$_user" >/dev/null 2>&1 || continue

    target_home="$(getent passwd "$_user" | cut -d: -f6)"
    [ -n "$target_home" ] || target_home="/home/$_user"
    install -d -m 0755 -o "$_user" -g "$_user" "$target_home/.ansible"
    install -d -m 0700 -o "$_user" -g "$_user" "$target_home/.ansible/tmp"
    install -d -m 0755 -o "$_user" -g "$_user" "$target_home/.ansible/collections"
    install -d -m 0755 -o "$_user" -g "$_user" "$target_home/.ansible/roles"
    cat > "$target_home/.ansible.cfg" <<'MRHIS_ANSIBLE_CFG'
[defaults]
local_tmp = ~/.ansible/tmp
remote_tmp = ~/.ansible/tmp
host_key_checking = False
retry_files_enabled = False
    # Suppress deprecation warnings for demo runs; override in ansible.cfg if needed
    deprecation_warnings = False
MRHIS_ANSIBLE_CFG
    chown "$_user:$_user" "$target_home/.ansible.cfg"
    chmod 0644 "$target_home/.ansible.cfg"
done

install -d -m 0755 /etc/mrhis /var/lib/mrhis /var/lib/mrhis/creator
cat > /etc/mrhis/creator.env <<MRHIS_CREATOR_ENV
MRHIS_CREATOR_MANAGED=1
MRHIS_ROLE=${role_name}
MRHIS_HOSTNAME=${node_hostname}
MRHIS_IP=${node_ip}
MRHIS_BOOTSTRAP_SOURCE=kickstart
MRHIS_BOOTSTRAP_VERSION=1
MRHIS_CREATOR_ENV
chmod 0644 /etc/mrhis/creator.env || true
EOF
}

kickstart_perf_network_snapshot_block() {
    local extra_sysctl_lines="${1:-}"

    cat <<EOF
# Performance baseline for virtual guests
systemctl enable --now qemu-guest-agent || true
systemctl enable --now tuned || true
tuned-adm profile virtual-guest || true
cat > /etc/sysctl.d/99-mrhis-performance.conf <<'EOF_MRHIS_PERF'
vm.swappiness = 10
${extra_sysctl_lines}
EOF_MRHIS_PERF
sysctl -p /etc/sysctl.d/99-mrhis-performance.conf || true

# Network verification snapshot (for ks-post.log troubleshooting)
echo "===== MRHIS NETWORK SNAPSHOT ====="
date
ip -4 addr show eth0 || true
ip -4 addr show eth1 || true
ip route show || true
nmcli -f NAME,DEVICE,TYPE,STATE connection show || true
echo "===== END MRHIS NETWORK SNAPSHOT ====="
EOF
}

prepare_kickstart_shared_blocks() {
    local role_name="$1"
    local node_hostname="$2"
    local node_ip="$3"
    local ext_mac="$4"
    local int_mac="$5"
    local int_ip="$6"
    local int_prefix="$7"
    local int_gw="$8"
    local include_org_id="$9"
    local trust_bootstrap_keys_flag="${10}"
    local repo_role_label="${11}"
    shift 11
    local -a repos=("$@")

    MRHIS_KS_NOGPG_POLICY="$(kickstart_nogpg_policy_block)"
    MRHIS_KS_SSH_BASELINE="$(kickstart_ssh_baseline_block)"
    MRHIS_KS_USER_SUDO_BOOTSTRAP="$(kickstart_user_sudo_bootstrap_block "${role_name}")"
    MRHIS_KS_RHSM_REGISTER="$(kickstart_rhsm_register_block "${include_org_id}")"
    MRHIS_KS_RHC_CONNECT="$(kickstart_rhc_connect_block)"
    MRHIS_KS_REPO_ENABLE_VERIFY="$(kickstart_repo_enable_verify_block "${repo_role_label}" "${repos[@]}")"
    MRHIS_KS_NM_DUAL_NIC="$(kickstart_networkmanager_dual_nic_block "${ext_mac}" "${int_mac}" "${int_ip}" "${int_prefix}" "${int_gw}")"
    MRHIS_KS_TRUST_BOOTSTRAP_KEYS="$(kickstart_trust_bootstrap_keys_block "${trust_bootstrap_keys_flag}")"
    MRHIS_KS_CREATOR_BASELINE="$(kickstart_creator_baseline_block "${role_name}" "${node_hostname}" "${node_ip}")
$(kickstart_common_components_block)"
}

