    echo "  MRHIS_IDM_WEB_UI_INTERVAL=${MRHIS_IDM_WEB_UI_INTERVAL:-15}"
    echo "  MRHIS_ENABLE_POST_HEALTHCHECK=${MRHIS_ENABLE_POST_HEALTHCHECK:-1}"
    echo "  MRHIS_HEALTHCHECK_AUTOFIX=${MRHIS_HEALTHCHECK_AUTOFIX:-1}"
    echo "  MRHIS_HEALTHCHECK_RERUN_COMPONENT=${MRHIS_HEALTHCHECK_RERUN_COMPONENT:-1}"
    echo "  MRHIS_SAT_HEALTHCHECK_RETRIES=${MRHIS_SAT_HEALTHCHECK_RETRIES:-5}"
    echo "  MRHIS_SAT_HEALTHCHECK_INTERVAL=${MRHIS_SAT_HEALTHCHECK_INTERVAL:-15}"
