    echo "  MRHIS_REFRESH_KNOWN_HOSTS=${MRHIS_REFRESH_KNOWN_HOSTS:-1}"
    echo "  MRHIS_INSTALLER_SSH_KEY_DIR=${MRHIS_INSTALLER_SSH_KEY_DIR:-'(unset)'}"
    echo "  MRHIS_ENABLE_PRECHECK_ADHOC=${MRHIS_ENABLE_PRECHECK_ADHOC:-0}"
    echo "  RHC_AUTO_CONNECT=${RHC_AUTO_CONNECT:-1}"
    echo "  COCKPIT_PORT=${COCKPIT_PORT:-9443}"
    echo "  NETWORKS_ACTIVE=SAT(${SAT_IP:-10.168.128.1}/${SAT_NETMASK:-255.255.0.0} gw:${SAT_GW:-10.168.0.1}) AAP(${AAP_IP:-10.168.128.2}/${AAP_NETMASK:-255.255.0.0} gw:${AAP_GW:-10.168.0.1}) IDM(${IDM_IP:-10.168.128.3}/${IDM_NETMASK:-255.255.0.0} gw:${IDM_GW:-10.168.0.1})"
}

generate_mrhis_ansible_cfg() {
    local tmp_cfg
    local tmp_cfg_runtime
    local tmp_cfg_encrypted
    local _ssh_args_common
    local _ssh_identity_arg_container
    local _ssh_identity_arg_host

    mkdir -p "${ANSIBLE_ENV_DIR}" "${MRHIS_ANSIBLE_FACT_CACHE_HOST}" || return 1
    chmod 700 "${ANSIBLE_ENV_DIR}" "${MRHIS_ANSIBLE_FACT_CACHE_HOST}" 2>/dev/null || true
    ensure_ansible_vault || return 1
    ensure_vault_password_file || return 1

    # Prefer explicit vaulted console token; fall back to HUB_TOKEN.
    # This token is used for Automation Hub galaxy server auth entries.
    local ah_token="${VAULT_CONSOLE_REDHAT_TOKEN:-${HUB_TOKEN:-}}"

    _ssh_args_common="-o ControlMaster=auto -o ControlPersist=60s -o ServerAliveInterval=30 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no"
    _ssh_identity_arg_container=""
    _ssh_identity_arg_host=""
    if [ -r "${MRHIS_INSTALLER_SSH_PRIVATE_KEY}" ]; then
        _ssh_identity_arg_container=" -i ${MRHIS_INSTALLER_SSH_KEY_CONTAINER_PATH}"
        _ssh_identity_arg_host=" -i ${MRHIS_INSTALLER_SSH_PRIVATE_KEY}"
    else
        print_warning "Installer SSH key not found at ${MRHIS_INSTALLER_SSH_PRIVATE_KEY}; using default SSH identities for Ansible connections."
    fi

    tmp_cfg="$(mktemp "${ANSIBLE_ENV_DIR}/.mrhis-ansible.cfg.XXXXXX")" || return 1

    cat > "${tmp_cfg}" <<EOF
[defaults]
inventory = ${MRHIS_CONTAINER_INVENTORY_FILE}
host_key_checking = False
retry_files_enabled = False
interpreter_python = auto_silent
roles_path = ${SCRIPT_DIR}/roles:${SCRIPT_DIR}/local/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-satellite/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-idm/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-aap/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-aap/mrhis-builder-aap/roles
remote_tmp = /var/tmp
forks = ${MRHIS_ANSIBLE_FORKS}
timeout = ${MRHIS_ANSIBLE_TIMEOUT}
gathering = smart
fact_caching = jsonfile
fact_caching_connection = ${MRHIS_ANSIBLE_FACT_CACHE_CONTAINER}
fact_caching_timeout = ${MRHIS_ANSIBLE_FACT_CACHE_TIMEOUT}
callbacks_enabled = ansible.posix.profile_tasks,ansible.posix.timer
bin_ansible_callbacks = True
log_path = /mrhis/vars/vault/${AAP_ANSIBLE_LOG_BASENAME}
nocows = 1
inject_facts_as_vars = True

[ssh_connection]
pipelining = True
ssh_args = ${_ssh_args_common}${_ssh_identity_arg_container}
control_path_dir = /tmp/.ansible-cp
retries = 3

[galaxy]
server_list = published, validated, community_galaxy

[galaxy_server.published]
url = https://console.redhat.com/api/automation-hub/content/published/
auth_url = https://sso.redhat.com/auth/realms/redhat-external/protocol/openid-connect/token
# token redacted (use vaulted var vault_console_redhat_token)
token = ${ah_token}

[galaxy_server.validated]
url = https://console.redhat.com/api/automation-hub/content/validated/
auth_url = https://sso.redhat.com/auth/realms/redhat-external/protocol/openid-connect/token
# token redacted (use vaulted var vault_console_redhat_token)
token = ${ah_token}

[galaxy_server.community_galaxy]
url = https://galaxy.ansible.com/
EOF

    chmod 600 "${tmp_cfg}" 2>/dev/null || true
    # write_file_if_changed removes source temp on success, but we still need
    # tmp_cfg for vault comparison/encryption below, so write via a copy.
    tmp_cfg_runtime="$(mktemp "${ANSIBLE_ENV_DIR}/.mrhis-ansible.runtime.XXXXXX")" || {
        rm -f "${tmp_cfg}"
        return 1
    }
    cp -f "${tmp_cfg}" "${tmp_cfg_runtime}" || {
        rm -f "${tmp_cfg}" "${tmp_cfg_runtime}"
        return 1
    }
    sed -i \
        -e "s|^inventory = .*|inventory = ${MRHIS_INVENTORY_FILE}|" \
        -e "s|^fact_caching_connection = .*|fact_caching_connection = ${MRHIS_ANSIBLE_FACT_CACHE_HOST}|" \
        -e "s|^log_path = .*|log_path = ${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}|" \
        -e "s|^ssh_args = .*|ssh_args = ${_ssh_args_common}${_ssh_identity_arg_host}|" \
        "${tmp_cfg_runtime}" || {
        rm -f "${tmp_cfg}" "${tmp_cfg_runtime}"
        return 1
    }
    write_file_if_changed "${tmp_cfg_runtime}" "${MRHIS_ANSIBLE_CFG_HOST}" 0600 || {
        rm -f "${tmp_cfg}"
        return 1
    }

    if vault_plaintext_matches_existing "${tmp_cfg}"; then
        rm -f "${tmp_cfg}"
        touch "${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}" 2>/dev/null || true
        chmod 600 "${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}" 2>/dev/null || true
        return 0
    fi

    tmp_cfg_encrypted="$(mktemp "${ANSIBLE_ENV_DIR}/.mrhis-ansible.cfg.vault.XXXXXX")" || {
        rm -f "${tmp_cfg}"
        return 1
    }
    cp -f "${tmp_cfg}" "${tmp_cfg_encrypted}" || {
        rm -f "${tmp_cfg}" "${tmp_cfg_encrypted}"
        return 1
    }
    ansible-vault encrypt --vault-password-file "${ANSIBLE_VAULT_PASS_FILE}" --encrypt-vault-id default "${tmp_cfg_encrypted}" >/dev/null 2>&1 || {
        rm -f "${tmp_cfg}" "${tmp_cfg_encrypted}"
        return 1
    }
    chmod 600 "${tmp_cfg_encrypted}" 2>/dev/null || true
    mv -f "${tmp_cfg_encrypted}" "${MRHIS_ANSIBLE_CFG_VAULT_HOST}" || {
        rm -f "${tmp_cfg}" "${tmp_cfg_encrypted}"
        return 1
    }
    rm -f "${tmp_cfg}"
    touch "${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}" 2>/dev/null || true
    chmod 600 "${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}" 2>/dev/null || true
    return 0
}

# Keep local developer ansible.cfg in local/roles aligned with the same
# runtime defaults used for MRHIS provisioner runs, including galaxy endpoints
# and token source (vault_console_redhat_token/HUB_TOKEN).
generate_local_roles_ansible_cfg() {
    local tmp_cfg
    local local_cfg
    local local_inventory
    local local_inventory_name
    local local_roles_path
    local local_ssh_key
    local local_fact_cache
    local local_log_path

    local_cfg="${SCRIPT_DIR}/local/roles/ansible.cfg"
    local_inventory_name="$(basename "${MRHIS_INVENTORY_FILE}")"
    local_inventory="${SCRIPT_DIR}/local/roles/inventory/${local_inventory_name}"
    local_roles_path="${SCRIPT_DIR}/roles:${SCRIPT_DIR}/local/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-satellite/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-idm/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-aap/roles:${SCRIPT_DIR}/local/roles/mrhis-builder-aap/mrhis-builder-aap/roles"
    local_ssh_key="${HOME}/.ssh/id_rsa"
    local_fact_cache="${HOME}/.ansible/conf/${MRHIS_ANSIBLE_FACT_CACHE_BASENAME}"
    local_log_path="${HOME}/.ansible/conf/${AAP_ANSIBLE_LOG_BASENAME}"
    mkdir -p "${SCRIPT_DIR}/local/roles" "${local_fact_cache}" "${ANSIBLE_ENV_DIR}" || return 1

    tmp_cfg="$(mktemp "${ANSIBLE_ENV_DIR}/.local-roles-ansible.cfg.XXXXXX")" || return 1

    cat > "${tmp_cfg}" <<EOF
[defaults]
inventory = ${local_inventory}
host_key_checking = False
retry_files_enabled = False
roles_path = ${local_roles_path}
stdout_callback = ansible.builtin.default
result_format = yaml
interpreter_python = auto_silent
remote_tmp = /var/tmp
forks = ${MRHIS_ANSIBLE_FORKS}
timeout = ${MRHIS_ANSIBLE_TIMEOUT}
gathering = smart
fact_caching = jsonfile
fact_caching_connection = ${local_fact_cache}
fact_caching_timeout = ${MRHIS_ANSIBLE_FACT_CACHE_TIMEOUT}
callbacks_enabled = ansible.posix.profile_tasks,ansible.posix.timer
bin_ansible_callbacks = True
log_path = ${local_log_path}
nocows = 1
inject_facts_as_vars = True

[ssh_connection]
pipelining = True
ssh_args = -o ControlMaster=auto -o ControlPersist=60s -o ServerAliveInterval=30 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no -i ${local_ssh_key}
control_path_dir = /tmp/.ansible-cp
retries = 3

[galaxy]
server_list = published, validated, community_galaxy

[galaxy_server.published]
url = https://console.redhat.com/api/automation-hub/content/published/
auth_url = https://sso.redhat.com/auth/realms/redhat-external/protocol/openid-connect/token
# token sourced from vaulted var vault_console_redhat_token (fallback HUB_TOKEN)
token =

[galaxy_server.validated]
url = https://console.redhat.com/api/automation-hub/content/validated/
auth_url = https://sso.redhat.com/auth/realms/redhat-external/protocol/openid-connect/token
# token sourced from vaulted var vault_console_redhat_token (fallback HUB_TOKEN)
token =

[galaxy_server.community_galaxy]
url = https://galaxy.ansible.com/
EOF

    chmod 600 "${tmp_cfg}" 2>/dev/null || true
    write_file_if_changed "${tmp_cfg}" "${local_cfg}" 0600 || return 1
    print_step "Local roles ansible.cfg sync complete: ${local_cfg}"
    return 0
}

# Persist a consolidated view of runtime credentials/config into the encrypted
# ~/.ansible/conf/env.yml vault so the workflow has a single source of truth.
# This intentionally runs after stale container teardown in ensure_container_running().
sync_runtime_values_to_ansible_vault() {
    [ -f "${ANSIBLE_ENV_FILE}" ] || return 0

    print_step "Consolidating runtime variables into encrypted vault file: ${ANSIBLE_ENV_FILE}"

    # Load existing vaulted values first, then merge any runtime-sourced values.
    load_ansible_env_file || return 1

    # Bidirectional fallback between dedicated Automation Hub token and legacy HUB_TOKEN.
    if [ -z "${VAULT_CONSOLE_REDHAT_TOKEN:-}" ] && [ -n "${HUB_TOKEN:-}" ]; then
        VAULT_CONSOLE_REDHAT_TOKEN="${HUB_TOKEN}"
    fi
    if [ -z "${HUB_TOKEN:-}" ] && [ -n "${VAULT_CONSOLE_REDHAT_TOKEN:-}" ]; then
        HUB_TOKEN="${VAULT_CONSOLE_REDHAT_TOKEN}"
    fi

    normalize_shared_env_vars

    # Ensure common prompts (global + node groups) are available for product-specific choices
    prompt_use_existing_env || return 1
    write_ansible_env_file
}

# ─── Test suite helpers ─────────────────────────────────────────────────────

    # Render a 14-char filled/empty progress bar using block characters.
    _mrhis_test_bar() {
        local n="$1" total="$2" width=14
        local bar="" fill i
        [ "${total}" -le 0 ] && { printf '░░░░░░░░░░░░░░'; return; }
        fill=$(( n * width / total ))
        i=0
        while [ "$i" -lt "$fill"   ]; do bar="${bar}█"; i=$((i+1)); done
        while [ "$i" -lt "$width"  ]; do bar="${bar}░"; i=$((i+1)); done
        printf '%s' "${bar}"
    }

    # One-line "why we test this" shown in the per-test step header.
    _mrhis_test_why() {
        case "$1" in
            *"Ansible config"*)    printf '%s' "Verifies pipelining, forks, fact-cache, and log path before the container ever starts." ;;
            *"Generate inventory") printf '%s' "Builds the hosts file that defines every group (satellite, mrhis, fullstack, aap_hosts, idm_primary) for playbooks." ;;
            *"host_vars"*)         printf '%s' "Creates per-node connection details (IP, ansible_host, user) read by playbooks at run time." ;;
            *"inventory model"*)   printf '%s' "Validates the chosen AAP topology resolves to a real template before kickstart writes it." ;;
            *"Container Deploy"*)  printf '%s' "Starts mrhis-provisioner — the sole execution engine for all config-as-code phases." ;;
            *"OEMDRV"*)            printf '%s' "Exercises kickstart + ISO build pipeline (genisoimage/xorriso) without a live Satellite." ;;
            *"Dashboard"*)         printf '%s' "Renders the runtime monitor and exercises the ansible-provisioner.log tail path." ;;
            *"Local Install"*)     printf '%s' "Verifies the local npm/Node.js toolchain or confirms fall-through to fallback provisioning." ;;
            *"Virt-Manager"*)      printf '%s' "Tests libvirt connectivity and VM definition logic — most common blocker on new installs." ;;
            *"Config-Only"*)       printf '%s' "End-to-end run of IdM -> Satellite -> AAP config sequence inside the provisioner container." ;;
            *)                     printf '%s' "Validates this component functions correctly in the current environment." ;;
        esac
    }

    # One-line "what a passing result means for you" shown in the summary.
    _mrhis_test_impact() {
        case "$1" in
            *"Ansible config"*)    printf '%s' "Provisioner inherits correct tuning — missing config causes silent container failures." ;;
            *"Generate inventory") printf '%s' "All platform VMs (IdM / Satellite / AAP) are reachable by group name from every playbook." ;;
            *"host_vars"*)         printf '%s' "Node details match env.yml — SSH auth will succeed on first contact with each VM." ;;
            *"inventory model"*)   printf '%s' "AAP_INVENTORY_TEMPLATE and AAP_INVENTORY_GROWTH_TEMPLATE resolve to valid files on disk." ;;
            *"Container Deploy"*)  printf '%s' "Container healthy and vault bind-mount accessible — playbooks can execute immediately." ;;
            *"OEMDRV"*)            printf '%s' "Satellite kickstart + OEMDRV ISO build — the VM will boot to unattended OS installation." ;;
            *"Dashboard"*)         printf '%s' "Option 8 is functional — live provisioning progress is visible without leaving the script." ;;
            *"Local Install"*)     printf '%s' "Menu options 1 and 4 are viable on this host." ;;
            *"Virt-Manager"*)      printf '%s' "KVM/libvirt is accessible — VM definitions can be created; menu options 3-5 are viable." ;;
            *"Config-Only"*)       printf '%s' "Config-as-code phases run in order — the full platform can be provisioned from this host." ;;
            *)                     printf '%s' "This stage will not block platform provisioning." ;;
        esac
    }

    # Print the numbered per-test step header and increment the step counter.
    _mrhis_test_step_header() {
        local label="$1" why
        _MRHIS_TEST_STEP=$((_MRHIS_TEST_STEP + 1))
        why="$(_mrhis_test_why "${label}")"
        echo ""
        printf "${CYAN}  ┌─ [%d/%d]  ${BOLD}%s${NC}\n" "${_MRHIS_TEST_STEP}" "${_MRHIS_TEST_TOTAL}" "${label}"
        printf "${DIM}  │   %s${NC}\n" "${why}"
        printf "${CYAN}  └──────────────────────────────────────────────────────────────${NC}\n"
    }

    # ─── Core test machinery ────────────────────────────────────────────────────

    mrhis_test_record_result() {
        local label="$1"
        local status="$2"
        local details="${3:-}"
        MRHIS_TEST_RESULTS+=("${label}|${status}|${details}")
        if [ "$status" = "fail" ]; then
            MRHIS_TEST_FAILURE_COUNT=$((MRHIS_TEST_FAILURE_COUNT + 1))
        fi
    }

# Create per-status detail files and (optionally) expose clickable file:// links
mrhis_create_detail_files() {
    local ts
    ts="$(date -u +%Y%m%dT%H%M%SZ)"
    MRHIS_TEST_PASSED_FILE="${MRHIS_RUN_LOG_DIR}/mrhis_test_passed_${ts}.txt"
    MRHIS_TEST_FAILED_FILE="${MRHIS_RUN_LOG_DIR}/mrhis_test_failed_${ts}.txt"
    MRHIS_TEST_SKIPPED_FILE="${MRHIS_RUN_LOG_DIR}/mrhis_test_skipped_${ts}.txt"
    MRHIS_TEST_WARNINGS_FILE="${MRHIS_RUN_LOG_DIR}/mrhis_test_warnings_${ts}.txt"

    : > "${MRHIS_TEST_PASSED_FILE}"
    : > "${MRHIS_TEST_FAILED_FILE}"
    : > "${MRHIS_TEST_SKIPPED_FILE}"
    : > "${MRHIS_TEST_WARNINGS_FILE}"

    local item label status details
    for item in "${MRHIS_TEST_RESULTS[@]}"; do
        IFS='|' read -r label status details <<< "${item}"
        case "${status}" in
            success) printf '%s\n' "${label}${details:+ — ${details}}" >> "${MRHIS_TEST_PASSED_FILE}" ;; 
            fail)    printf '%s\n' "${label}${details:+ — ${details}}" >> "${MRHIS_TEST_FAILED_FILE}" ;; 
            skipped) printf '%s\n' "${label}${details:+ — ${details}}" >> "${MRHIS_TEST_SKIPPED_FILE}" ;; 
            *)       printf '%s\n' "${label}${details:+ — ${details}}" >> "${MRHIS_TEST_PASSED_FILE}" ;; 
        esac
    done

    # Copy any warning lines recorded during the run into the warnings file for review
    if [ -s "${MRHIS_TEST_WARNING_FILE:-/dev/null}" ]; then
        printf 'Warnings collected during run (%s):\n\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "${MRHIS_TEST_WARNINGS_FILE}"
        tail -n 500 "${MRHIS_TEST_WARNING_FILE}" >> "${MRHIS_TEST_WARNINGS_FILE}" || true
    fi
}

# Print a terminal-friendly hyperlink to a local file when supported by the terminal
create_hyperlink() {
    local file="$1" label="$2"
    # Allow disabling hyperlinks with MRHIS_ENABLE_HYPERLINKS=0
    if [ "${MRHIS_ENABLE_HYPERLINKS:-1}" -ne 1 ] || [ ! -t 1 ]; then
        printf '%s' "${label}"
        return 0
    fi
    # OSC 8 hyperlink: ESC ] 8 ; ; URI BEL text ESC ] 8 ; ; BEL
    local uri
    uri="file://$(realpath "${file}" 2>/dev/null || printf '%s' "${file}")"
    printf '\033]8;;%s\007%s\033]8;;\007' "${uri}" "${label}"
}

# Colorize a file/stream: highlight PASS -> green, FAIL/WARN -> red, SKIP -> blue
mrhis_colorize_file() {
    local file="$1"
    if [ ! -f "${file}" ]; then
        return 1
    fi
    if command -v perl >/dev/null 2>&1; then
        perl -pe '
            s/\b(pass(?:ed)?|ok)\b/\e[0;32m$&\e[0m/ig;
            s/\b(skip(?:ped)?)\b/\e[0;34m$&\e[0m/ig;
            s/\b(warn(?:ing)?|warning)\b/\e[0;31m$&\e[0m/ig;
            s/\b(fail(?:ed)?|error)\b/\e[0;31m$&\e[0m/ig;
        ' < "${file}"
    else
        # Fallback: basic sed (uppercase only)
        sed -e 's/\bPASS\b/\x1b[0;32m&\x1b[0m/g' -e 's/\bFAILED\b/\x1b[0;31m&\x1b[0m/g' -e 's/\bFAIL\b/\x1b[0;31m&\x1b[0m/g' -e 's/\bSKIP\b/\x1b[0;34m&\x1b[0m/g' -e 's/\bSKIPPED\b/\x1b[0;34m&\x1b[0m/g' "${file}"
    fi
}

# Colorize stdin stream (useful for piping log output through the highlighter)
mrhis_colorize_stream() {
    if command -v perl >/dev/null 2>&1; then
        perl -pe '
            s/\b(pass(?:ed)?|ok)\b/\e[0;32m$&\e[0m/ig;
            s/\b(skip(?:ped)?)\b/\e[0;34m$&\e[0m/ig;
            s/\b(warn(?:ing)?|warning)\b/\e[0;31m$&\e[0m/ig;
            s/\b(fail(?:ed)?|error)\b/\e[0;31m$&\e[0m/ig;
        '
    else
        sed -e 's/\bPASS\b/\x1b[0;32m&\x1b[0m/g' -e 's/\bFAILED\b/\x1b[0;31m&\x1b[0m/g' -e 's/\bFAIL\b/\x1b[0;31m&\x1b[0m/g' -e 's/\bSKIP\b/\x1b[0;34m&\x1b[0m/g' -e 's/\bSKIPPED\b/\x1b[0;34m&\x1b[0m/g'
    fi
}

# Tail a file with colorized keyword highlighting
mrhis_tail_colorized() {
    local file="$1"
    shift || true
    if [ ! -f "${file}" ]; then
        print_warning "File not found: ${file}"
        return 1
    fi
    if command -v tail >/dev/null 2>&1; then
        tail -n +1 -F "${file}" "$@" 2>/dev/null | mrhis_colorize_stream
    else
        mrhis_colorize_stream < "${file}"
    fi
}

# Inline-highlight keywords inside a single message string (returns colored text)
highlight_message() {
    local input
    input="$*"
    if [ "${MRHIS_ENABLE_COLORS:-1}" -ne 1 ] || [ ! -t 1 ]; then
        printf '%s' "${input}"
        return 0
    fi
    if command -v perl >/dev/null 2>&1; then
        printf '%s' "$(printf '%s' "${input}" | perl -pe 's/\b(pass(?:ed)?|ok)\b/\e[0;32m$&\e[0m/ig; s/\b(skip(?:ped)?)\b/\e[0;34m$&\e[0m/ig; s/\b(warn(?:ing)?|warning)\b/\e[0;31m$&\e[0m/ig; s/\b(fail(?:ed)?|error)\b/\e[0;31m$&\e[0m/ig')"
    else
        printf '%s' "${input}"
    fi
}

# Interactive display of a selected results file
mrhis_show_test_details() {
    local sel="$1" file label
    case "${sel}" in
        1) file="${MRHIS_TEST_PASSED_FILE}"; label="Passed" ;; 
        2) file="${MRHIS_TEST_FAILED_FILE}"; label="Failed" ;; 
        3) file="${MRHIS_TEST_SKIPPED_FILE}"; label="Skipped" ;; 
        4) file="${MRHIS_TEST_WARNINGS_FILE}"; label="Warnings" ;; 
        *) return 1 ;; 
    esac

    if [ ! -f "${file}" ]; then
        print_warning "No details available for ${label}."
        return 1
    fi

    reset_menu_view || true
    print_mrhis_header
    printf "%s details:\n\n" "${label}"
    if [ "${MRHIS_ENABLE_COLORS:-1}" -eq 1 ]; then
        mrhis_colorize_file "${file}"
    else
        cat "${file}"
    fi
    echo ""
    read -r -p "Press Enter to return to summary..." _dummy || true
    return 0
}

    mrhis_test_run_case() {
        local label="$1"
        shift
        _mrhis_test_step_header "${label}"
        if "$@"; then
            printf "${GREEN}  ✔  ${BOLD}%s${NC}${GREEN}  [ PASS ]${NC}\n" "${label}"
            mrhis_test_record_result "${label}" "success"
        else
            printf "${RED}  ✘  ${BOLD}%s${NC}${RED}  [ FAIL ]${NC}\n" "${label}"
            mrhis_test_record_result "${label}" "fail" \
                "See ${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}, ${AAP_HTTP_LOG}, and option 8 dashboard."
        fi
    }

    mrhis_test_print_summary() {
        local run_exit_code="${1:-${MRHIS_LAST_EXIT_CODE:-0}}"
        local item label status details impact
        local total_count passed_count skipped_count
        local overall_status pass_bar fail_bar
        local effective_total effective_failures effective_warnings effective_skipped effective_passed
        local ansible_log recap_totals warnings_count fatal_markers host_breakdown
        local recap_pass recap_total recap_fail recap_skip

        passed_count=0; skipped_count=0
        for item in "${MRHIS_TEST_RESULTS[@]}"; do
            IFS='|' read -r label status details <<< "${item}"
            [ "${status}" = "success" ] && passed_count=$((passed_count + 1))
            [ "${status}" = "skipped" ] && skipped_count=$((skipped_count + 1))
        done
        total_count="${#MRHIS_TEST_RESULTS[@]}"
        overall_status="PASS"; (( ${MRHIS_TEST_FAILURE_COUNT:-0} == 0 )) || overall_status="FAIL"
        echo ""

        for item in "${MRHIS_TEST_RESULTS[@]}"; do
            IFS='|' read -r label status details <<< "${item}"
            impact="$(_mrhis_test_impact "${label}")"
            case "${status}" in
                success)
                    printf "${GREEN}  ✔  ${BOLD}%s${NC}${GREEN}   [ PASS ]${NC}\n" "${label}"
                    printf "${DIM}       ↳  %s${NC}\n" "${impact}"
                    echo ""
                    ;;
                fail)
                    printf "${RED}  ✘  ${BOLD}%s${NC}${RED}   [ FAIL ]${NC}\n" "${label}"
                    printf "${DIM}       ↳  %s${NC}\n" "${impact}"
                    [ -n "${details}" ] && printf "${RED}       ⚑  %s${NC}\n" "${details}"
                    echo ""
                    ;;
                skipped)
                    printf "${BLUE}  ⊘  ${BOLD}%s${NC}${BLUE}   [ SKIP ]${NC}\n" "${label}"
                    [ -n "${details}" ] && printf "${DIM}       ↳  %s${NC}\n" "${details}"
                    echo ""
                    ;;
            esac
        done

        printf "${CYAN}  ───────────────────────────────────────────────────────────────${NC}\n"
        echo ""
        effective_total="${total_count}"
        effective_failures="${MRHIS_TEST_FAILURE_COUNT:-0}"
        effective_warnings="${MRHIS_TEST_WARNING_COUNT:-0}"
        effective_skipped="${skipped_count}"
        effective_passed="${passed_count}"

        # Create per-status detail files and clickable file:// links where supported
        mrhis_create_detail_files || true
        local passed_label failed_label skipped_label warnings_label
        passed_label="$(create_hyperlink "${MRHIS_TEST_PASSED_FILE}" "Passed")"
        failed_label="$(create_hyperlink "${MRHIS_TEST_FAILED_FILE}" "Failed")"
        skipped_label="$(create_hyperlink "${MRHIS_TEST_SKIPPED_FILE}" "Skipped")"
        warnings_label="$(create_hyperlink "${MRHIS_TEST_WARNINGS_FILE}" "Warnings")"

        # If the test harness didn't populate test results, fall back to Ansible
        # log parsing so the summary still reflects real task/failure/warning counts.
        if [ "${total_count:-0}" -le 0 ]; then
            ansible_log="${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME:-ansible.log}"
            if [ -f "${ansible_log}" ]; then
                recap_totals="$(awk '
                    /^[[:space:]]*[^[:space:]]+[[:space:]]*:[[:space:]]+ok=/ {
                        ok=changed=unreachable=failed=skipped=rescued=ignored=0
                        if (match($0,/ok=([0-9]+)/,m)) ok=m[1]
                        if (match($0,/changed=([0-9]+)/,m)) changed=m[1]
                        if (match($0,/unreachable=([0-9]+)/,m)) unreachable=m[1]
                        if (match($0,/failed=([0-9]+)/,m)) failed=m[1]
                        if (match($0,/skipped=([0-9]+)/,m)) skipped=m[1]
                        if (match($0,/rescued=([0-9]+)/,m)) rescued=m[1]
                        if (match($0,/ignored=([0-9]+)/,m)) ignored=m[1]
                        pass += ok + changed + rescued + ignored
                        fail += failed + unreachable
                        skip += skipped
                        total += ok + changed + unreachable + failed + skipped + rescued + ignored
                    }
                    END { printf "%d|%d|%d|%d", pass+0, total+0, fail+0, skip+0 }
                ' "${ansible_log}" 2>/dev/null)" || recap_totals="0|0|0|0"
                IFS='|' read -r recap_pass recap_total recap_fail recap_skip <<< "${recap_totals}"

                warnings_count="$(awk '
                    /^\[WARNING\] / {
                        msg=$0; sub(/^\[WARNING\] /, "", msg)
                        pending[msg]++
                        count++
                        next
                    }
                    /^WARN: / {
                        msg=$0; sub(/^WARN: /, "", msg)
                        if (pending[msg] > 0) {
                            pending[msg]--
                            next
                        }
                        count++
                    }
                    END { print count+0 }
                ' "${ansible_log}" 2>/dev/null)" || warnings_count=0

                fatal_markers="$(awk '
                    /^\[ERROR\] FATAL: / {
                        msg=$0; sub(/^\[ERROR\] /, "", msg)
                        pending[msg]++
                        count++
                        next
                    }
                    /^FAIL: FATAL: / {
                        msg=$0; sub(/^FAIL: /, "", msg)
                        if (pending[msg] > 0) {
                            pending[msg]--
                            next
                        }
                        count++
                        next
                    }
                    END { print count+0 }
                ' "${ansible_log}" 2>/dev/null)" || fatal_markers=0

                host_breakdown="$(awk '
                    /^[[:space:]]*[^[:space:]]+[[:space:]]*:[[:space:]]+ok=/ {
                        host=$1
                        sub(/:$/, "", host)
                        unreachable=failed=skipped=0
                        if (match($0,/unreachable=([0-9]+)/,m)) unreachable=m[1]
                        if (match($0,/failed=([0-9]+)/,m)) failed=m[1]
                        if (match($0,/skipped=([0-9]+)/,m)) skipped=m[1]
                        host_failed[host] += failed
                        host_unreachable[host] += unreachable
                        host_skipped[host] += skipped
                    }
                    END {
                        for (host in host_failed) {
                            if ((host_failed[host] + host_unreachable[host]) > 0) {
                                printf "  - %s  failed=%d unreachable=%d skipped=%d\n", host, host_failed[host], host_unreachable[host], host_skipped[host]
                            }
                        }
                    }
                ' "${ansible_log}" 2>/dev/null)" || host_breakdown=""
            else
                recap_pass=0; recap_total=0; recap_fail=0; recap_skip=0; warnings_count=0; fatal_markers=0; host_breakdown=""
            fi
            effective_passed="${recap_pass:-0}"
            effective_total="${recap_total:-0}"
            effective_failures="${recap_fail:-0}"
            effective_warnings="${warnings_count}"
            effective_skipped="${recap_skip:-0}"
            if [ "${fatal_markers:-0}" -gt "${effective_failures:-0}" ]; then
                effective_failures="${fatal_markers}"
            fi
        fi

        # If the overall run exited non-zero, avoid reporting a false-green
        # summary when parsed Ansible recap counters are empty.
        if [ "${run_exit_code:-0}" -ne 0 ] && [ "${effective_failures:-0}" -eq 0 ]; then
            effective_failures=1
        fi

        pass_bar="$(_mrhis_test_bar "${effective_passed}" "${effective_total}")"
        fail_bar="$(_mrhis_test_bar "${effective_failures}" "${effective_total}")"

        printf "  ${GREEN}%s${NC}   :  %d / %d   ${BOLD}%s${NC}\n" "${passed_label}" "${effective_passed}" "${effective_total}" "${pass_bar}"
        printf "  ${RED}%s${NC}   :  %d / %d   ${BOLD}%s${NC}\n" "${failed_label}" "${effective_failures}" "${effective_total}" "${fail_bar}"
        printf "  ${BLUE}%s${NC}  :  %-3d${NC}\n" "${skipped_label}" "${effective_skipped}"
        printf "  ${RED}%s${NC} :  %-3d${NC}\n" "${warnings_label}" "${effective_warnings}"

        if [ -n "${host_breakdown:-}" ]; then
            echo ""
            printf "${RED}  Host Issues:${NC}\n"
            printf "%s" "${host_breakdown}"
        fi

        if [ -s "${MRHIS_TEST_WARNING_FILE}" ]; then
            echo ""
            printf "${RED}  ⚠  Warnings collected during this run:${NC}\n"
            while IFS= read -r wline; do
                printf "  ${RED}  · %s${NC}\n" "${wline}"
            done < <(tail -n 20 "${MRHIS_TEST_WARNING_FILE}")
        fi

        echo ""
        printf "${CYAN}  ───────────────────────────────────────────────────────────────${NC}\n"
        echo ""
        if (( ${effective_failures:-0} == 0 )); then
            printf "${BOLD}${GREEN}════════════════════════════════════════════════════════════════${NC}\n"
            printf "${BOLD}${GREEN}  ✔  ALL SYSTEMS GO — Your MRHIS stack is ready to build.${NC}\n"
            printf "${BOLD}${GREEN}════════════════════════════════════════════════════════════════${NC}\n"
            echo ""
            return 0
        fi

        printf "${BOLD}${RED}════════════════════════════════════════════════════════════════${NC}\n"
        printf "${BOLD}${RED}  ✘  FAILURES DETECTED — Review the items above before${NC}\n"
        printf "${BOLD}${RED}     attempting a full platform provisioning run.${NC}\n"
        printf "${BOLD}${RED}════════════════════════════════════════════════════════════════${NC}\n"
        echo ""
        return 1
    }

    mrhis_run_test_suite() {
        MRHIS_TEST_MODE=1
        NONINTERACTIVE=1
        RUN_ONCE=1
        MRHIS_TEST_RESULTS=()
        MRHIS_TEST_FAILURE_COUNT=0
        MRHIS_TEST_WARNING_COUNT=0
        _MRHIS_TEST_STEP=0
        : > "${MRHIS_TEST_WARNING_FILE:-/dev/null}"

        local demo_display="OFF"
        [ "${DEMO_MODE:-0}" = "1" ] && demo_display="ON"

        echo ""
        printf "${BOLD}${CYAN}════════════════════════════════════════════════════════════════${NC}\n"
        printf "${BOLD}${CYAN}   MRHIS Integration Test Suite  ·  Curated Validation Run${NC}\n"
        printf "${BOLD}${CYAN}════════════════════════════════════════════════════════════════${NC}\n"
        printf "   Profile : %-12s  Demo : %-6s  Host : %s\n" \
            "${CLI_TEST_PROFILE:-full}" "${demo_display}" "$(hostname -s 2>/dev/null)"
        printf "   Started : %s\n" "$(date '+%Y-%m-%d %H:%M:%S')"
        printf "${BOLD}${CYAN}════════════════════════════════════════════════════════════════${NC}\n"
        echo ""
        printf "${DIM}   Each component runs non-interactively.  Results are recorded\n"
        printf "   and presented in the Status Report at the end of this run.${NC}\n"
        echo ""

        if [ "${CLI_TEST_PROFILE:-full}" = "fast" ]; then
            _MRHIS_TEST_TOTAL=6
            mrhis_test_run_case "Generate MRHIS Ansible config"            generate_mrhis_ansible_cfg
            mrhis_test_run_case "Generate inventory"                      generate_mrhis_inventory
            mrhis_test_run_case "Generate host_vars"                      generate_mrhis_host_vars
            mrhis_test_run_case "AAP installer inventory model selection"  select_aap_inventory_templates
            mrhis_test_run_case "Generate OEMDRV Kickstarts"              generate_oemdrv_kickstarts_only
            _mrhis_test_step_header "Live Status Dashboard snapshot"
            MRHIS_DASHBOARD_SINGLE_SHOT=1
            if show_live_status_dashboard; then
                printf "${GREEN}  ✔  ${BOLD}Live Status Dashboard snapshot${NC}${GREEN}  [ PASS ]${NC}\n"
                mrhis_test_record_result "Live Status Dashboard snapshot" "success" \
                    "Rendered single-shot dashboard snapshot."
            else
                printf "${RED}  ✘  ${BOLD}Live Status Dashboard snapshot${NC}${RED}  [ FAIL ]${NC}\n"
                mrhis_test_record_result "Live Status Dashboard snapshot" "fail" \
                    "Dashboard snapshot could not be rendered."
            fi
            MRHIS_DASHBOARD_SINGLE_SHOT=0
            mrhis_test_print_summary
            return $?
        fi

        _MRHIS_TEST_TOTAL=6
        mrhis_test_run_case "AAP installer inventory model selection"  select_aap_inventory_templates
        mrhis_test_run_case "1) Local App Mode (legacy/optional)"     install_local
        mrhis_test_run_case "3) Setup Virt-Manager Only"              setup_virt_manager
        echo ""
        printf "${BLUE}  ⊘  ${BOLD}4) Full Setup (Local + Virt-Manager)${NC}${BLUE}   [ SKIP ]${NC}\n"
        printf "${DIM}       ↳  Covered by items 1 + 3 — avoids duplicate heavy provisioning.${NC}\n"
        mrhis_test_record_result "4) Full Setup (Local + Virt-Manager)" "skipped" \
            "Covered by test items 1 + 3 to avoid duplicate heavy provisioning."
        echo ""
        printf "${BLUE}  ⊘  ${BOLD}5) Full Setup (Container + Virt-Manager)${NC}${BLUE}   [ SKIP ]${NC}\n"
        printf "${DIM}       ↳  Container-based workflows removed; this path is deprecated and skipped.${NC}\n"
        mrhis_test_record_result "5) Full Setup (Container + Virt-Manager)" "skipped" \
            "Container-based workflows removed; this path is deprecated and skipped."
        echo ""
        mrhis_test_run_case "6) Generate All OEMDRV Kickstarts"  generate_oemdrv_kickstarts_only
        mrhis_test_run_case "7) Config-Only"                     run_mrhis_config_as_code
        _mrhis_test_step_header "8) Live Status Dashboard"
        MRHIS_DASHBOARD_SINGLE_SHOT=1
        if show_live_status_dashboard; then
            printf "${GREEN}  ✔  ${BOLD}8) Live Status Dashboard${NC}${GREEN}  [ PASS ]${NC}\n"
            mrhis_test_record_result "8) Live Status Dashboard" "success" \
                "Rendered single-shot dashboard snapshot."
        else
            printf "${RED}  ✘  ${BOLD}8) Live Status Dashboard${NC}${RED}  [ FAIL ]${NC}\n"
            mrhis_test_record_result "8) Live Status Dashboard" "fail" \
                "Dashboard snapshot could not be rendered."
        fi
        MRHIS_DASHBOARD_SINGLE_SHOT=0
        mrhis_test_print_summary
    }
parse_args() {
    while [ "$#" -gt 0 ]; do
        case "$1" in
            --non-interactive|--noninteractive|--notouch)
                # `--notouch` is a short alias for `--non-interactive` (hands-free)
                CLI_NONINTERACTIVE="1"
                RUN_ONCE=1
                ;;
            --menu-choice)
                shift
                [ "$#" -gt 0 ] || {
                    print_warning "--menu-choice requires a value"
                    exit 1
                }
                CLI_MENU_CHOICE="$1"
                RUN_ONCE=1
                ;;
            --env-file)
                shift
                [ "$#" -gt 0 ] || {
                    print_warning "--env-file requires a path"
                    exit 1
                }
                PRESEED_ENV_FILE="$1"
                ;;
            --inventory)
                shift
                [ "$#" -gt 0 ] || {
                    print_warning "--inventory requires a template name or absolute path"
                    exit 1
                }
                CLI_AAP_INVENTORY_TEMPLATE="$1"
                ;;
            --inventory-growth)
                shift
                [ "$#" -gt 0 ] || {
                    print_warning "--inventory-growth requires a template name or absolute path"
                    exit 1
                }
                CLI_AAP_INVENTORY_GROWTH_TEMPLATE="$1"
                ;;
            --enterprise)
                CLI_ENTERPRISE="1"
                ;;
            --standalone)
                CLI_STANDALONE="1"
                ;;
            --container-config-only)
                CLI_CONTAINER_CONFIG_ONLY="1"
                RUN_ONCE=1
                ;;
            --config-idm)
                CLI_CONFIG_SCOPE="idm"
                RUN_ONCE=1
                ;;
            --config-satellite)
                CLI_CONFIG_SCOPE="satellite"
                RUN_ONCE=1
                ;;
            --config-aap)
                CLI_CONFIG_SCOPE="aap"
                RUN_ONCE=1
                ;;
            --config-gittea)
                CLI_CONFIG_SCOPE="gittea"
                RUN_ONCE=1
                ;;
            --config-openstack)
                CLI_CONFIG_SCOPE="openstack"
                CLI_OPENSHIFT="1"
                RUN_ONCE=1
                ;;
            --config-rhis)
                CLI_CONFIG_SCOPE="rhis"
                RUN_ONCE=1
                ;;
            --config-fullstack)
                CLI_CONFIG_SCOPE="fullstack"
                CLI_GITTEA="1"
                CLI_OPENSHIFT="1"
                RUN_ONCE=1
                ;;
            --config-rhis-aap|--rhis-aap-config)
                CLI_CONFIG_SCOPE="rhis-aap"
                RUN_ONCE=1
                ;;
            --config-all)
                CLI_CONFIG_SCOPE="rhis"
                RUN_ONCE=1
                ;;
            --satellite)
                CLI_SATELLITE="1"
                RUN_ONCE=1
                ;;
            --idm)
                CLI_IDM="1"
                RUN_ONCE=1
                ;;
            --aap)
                CLI_AAP="1"
                RUN_ONCE=1
                ;;
            --gittea)
                CLI_GITTEA="1"
                RUN_ONCE=1
                ;;
            --fullstack)
                CLI_MRHIS="1"
                CLI_FULLSTACK="1"
                RUN_ONCE=1
                ;;
            --mrhis|--rhis|--[rR][hH][iI][sS])
                CLI_MRHIS="1"
                RUN_ONCE=1
                ;;
            --libvirt)
                CLI_LIBVIRT="1"
                RUN_ONCE=1
                ;;
            --baremetal|--bare-metal)
                CLI_BAREMETAL="1"
                RUN_ONCE=1
                ;;
            --aws)
                CLI_AWS="1"
                RUN_ONCE=1
                ;;
            --azure)
                CLI_AZURE="1"
                RUN_ONCE=1
                ;;
            --gcp)
                CLI_GCP="1"
                RUN_ONCE=1
                ;;
            --nutanix)
                CLI_NUTANIX="1"
                RUN_ONCE=1
                ;;
            --openshift)
                CLI_OPENSHIFT="1"
                RUN_ONCE=1
                ;;
            --openstack)
                CLI_OPENSHIFT="1"
                CLI_OPENSTACK_ALIAS="1"
                RUN_ONCE=1
                ;;
            --openshift-virt|--openshift_virt)
                CLI_OPENSHIFT_VIRT="1"
                RUN_ONCE=1
                ;;
            --vmware)
                CLI_VMWARE="1"
                RUN_ONCE=1
                ;;
            --local)
                CLI_LOCAL="1"
                RUN_ONCE=1
                ;;
            --container)
                CLI_CONTAINER="1"
                RUN_ONCE=1
                ;;
            --attach-consoles)
                CLI_ATTACH_CONSOLES="1"
                RUN_ONCE=1
                ;;
            --status)
                CLI_STATUS="1"
                CLI_NONINTERACTIVE="1"
                RUN_ONCE=1
                ;;
            --status-live)
                CLI_STATUS_LIVE="1"
                CLI_NONINTERACTIVE="1"
                RUN_ONCE=1
                ;;
            --test|--TEST)
                CLI_TEST="1"
                CLI_TEST_PROFILE="full"
                RUN_ONCE=1
                ;;
            --test=fast|--TEST=fast)
                CLI_TEST="1"
                CLI_TEST_PROFILE="fast"
                RUN_ONCE=1
                ;;
            --test=full|--TEST=full)
                CLI_TEST="1"
                CLI_TEST_PROFILE="full"
                RUN_ONCE=1
                ;;
            --selftest-vault)
                CLI_SELFTEST_VAULT="1"
                RUN_ONCE=1
                ;;
            --remediate-satellite)
                CLI_REMEDIATE_SATELLITE="1"
                RUN_ONCE=1
                ;;
            --DEMO|--[dD][eE][mM][oO])
                CLI_DEMO="1"
                ;;
            --DEMOKILL|--[dD][eE][mM][oO][kK][iI][lL][lL])
                CLI_DEMOKILL="1"
                RUN_ONCE=1
                ;;
            --reconfigure)
                CLI_RECONFIGURE="1"
                ;;
            --secrets-setup|--secrets)
                CLI_SECRETS_SETUP="1"
                RUN_ONCE=1
                ;;
            --menutest|--menu-test)
                CLI_MENUTEST="1"
                ;;
            --help|-h)
                print_usage
                exit 0
                ;;
            --validate|--preflight)
                CLI_VALIDATE="1"
                RUN_ONCE=1
                ;;
            --generate-env)
                # Optional next arg: output path for the generated template
                if [ "$#" -gt 1 ] && [[ "${2:-}" != --* ]]; then
                    shift
                    CLI_GENERATE_ENV="$1"
                else
                    CLI_GENERATE_ENV="${SCRIPT_DIR}/mrhis-headless.env.template"
                fi
                RUN_ONCE=1
                ;;
            --package-approvals)
                # Optional next arg: output directory for the packaged approvals tarball
                if [ "$#" -gt 1 ] && [[ "${2:-}" != --* ]]; then
                    shift
                    CLI_PACKAGE_APPROVALS_OUTDIR="$1"
                else
                    CLI_PACKAGE_APPROVALS_OUTDIR="${SCRIPT_DIR}/build"
                fi
                CLI_PACKAGE_APPROVALS="1"
                RUN_ONCE=1
                ;;
            *)
                print_warning "Unknown option: $1"
                print_usage
                exit 1
                ;;
        esac
        shift
    done
}

apply_cli_overrides() {
    if [ -n "${CLI_ENTERPRISE:-}" ] && [ -n "${CLI_STANDALONE:-}" ]; then
        print_warning "--enterprise and --standalone cannot be used together."
        exit 1
    fi

    if [ -n "${CLI_DEMO:-}" ] && { [ -n "${CLI_ENTERPRISE:-}" ] || [ -n "${CLI_STANDALONE:-}" ]; }; then
        print_warning "--DEMO cannot be combined with --enterprise or --standalone."
        exit 1
    fi

    if [ -n "$CLI_NONINTERACTIVE" ]; then
        NONINTERACTIVE="$CLI_NONINTERACTIVE"
    fi

    if [ -n "$CLI_MENU_CHOICE" ]; then
        MENU_CHOICE="$CLI_MENU_CHOICE"
    fi

    if [ -n "$CLI_DEMO" ]; then
        DEMO_MODE="$CLI_DEMO"
        AAP_TOPOLOGY="standalone"
    fi

    # When the user explicitly requests a demo full-stack run, prefer a
    # non-interactive fast-path (skip the entry/menu prompts) so callers like
    # `bash MRHIS.sh --DEMO --rhis` do not unexpectedly drop into the menu.
    # Only set these defaults when the caller did not explicitly pass
    # --non-interactive or --menu-choice.
    # If demo + mrhis shortcuts were requested, default to a noninteractive
    # fast-path only when the caller did not explicitly request reconfigure.
    if [ -n "${CLI_DEMO:-}" ] && [ -n "${CLI_MRHIS:-}" ] && [ -z "${CLI_RECONFIGURE:-}" ]; then
        if [ -z "${CLI_NONINTERACTIVE:-}" ]; then
            NONINTERACTIVE=1
        fi
        if [ -z "${CLI_MENU_CHOICE:-}" ]; then
            # Full Stack Build is now menu option 3
            MENU_CHOICE="3"
        fi
    fi

    if [ -n "$CLI_DEMOKILL" ]; then
        :
    fi

    if [ -n "$CLI_RECONFIGURE" ]; then
        FORCE_PROMPT_ALL=1
        # If caller only requested reconfigure (no explicit menu choice or
        # other fast-path CLI flags) and the run is interactive, jump
        # straight to the Prompts Only menu so the user is immediately
        # prompted to reconfigure values (equivalent to selecting menu 6).
        if [ -z "${CLI_MENU_CHOICE:-}" ] && [ -z "${CLI_DEMOKILL:-}${CLI_GENERATE_ENV:-}${CLI_VALIDATE:-}${CLI_STATUS:-}${CLI_TEST:-}${CLI_MRHIS:-}${CLI_IDM:-}${CLI_SATELLITE:-}${CLI_AAP:-}${CLI_CONFIG_SCOPE:-}" ] && ! is_noninteractive; then
            MENU_CHOICE="6"
        fi
    fi

    if [ -n "$CLI_AAP_INVENTORY_TEMPLATE" ]; then
        AAP_INVENTORY_TEMPLATE="$CLI_AAP_INVENTORY_TEMPLATE"
        case "$(basename "${AAP_INVENTORY_TEMPLATE}")" in
            inventory.j2|inventory)
                AAP_TOPOLOGY="enterprise"
                ;;
            *)
                AAP_TOPOLOGY="standalone"
                ;;
        esac
    fi

    if [ -n "$CLI_AAP_INVENTORY_GROWTH_TEMPLATE" ]; then
        AAP_INVENTORY_GROWTH_TEMPLATE="$CLI_AAP_INVENTORY_GROWTH_TEMPLATE"
    fi

    if [ -n "${CLI_ENTERPRISE:-}" ]; then
        AAP_INVENTORY_TEMPLATE="inventory.j2"
        AAP_INVENTORY_GROWTH_TEMPLATE="inventory-growth.j2"
        AAP_TOPOLOGY="enterprise"
    fi

    if [ -n "${CLI_STANDALONE:-}" ]; then
        AAP_INVENTORY_TEMPLATE="inventory-growth.j2"
        AAP_INVENTORY_GROWTH_TEMPLATE="inventory-growth.j2"
        AAP_TOPOLOGY="standalone"
    fi

    if [ -n "$CLI_CONTAINER_CONFIG_ONLY" ]; then
        # Container config-only corresponds to Full Stack Build fast-path
        MENU_CHOICE="3"
    fi

    # Execution-mode preference (last one wins when both are provided).
    if [ -n "$CLI_LOCAL" ]; then
        MRHIS_EXECUTION_MODE="local"
        MRHIS_LOCAL_ROLE_FALLBACK=1
    fi
    if [ -n "$CLI_CONTAINER" ]; then
        print_warning "CLI --container specified, but container workflows are removed; forcing local execution."
        MRHIS_EXECUTION_MODE="local"
    fi

    # Component shortcuts map into the Install Components submenu (4).
    # Explicit --config-* flags use dedicated fast-path execution and do not
    # remap menu choices. If the caller explicitly asked for the Prompts Only
    # menu (6), keep it.
    if [ -z "${CLI_CONFIG_SCOPE:-}" ] && [ "${CLI_MENU_CHOICE:-}" != "6" ]; then
        # Base stack takes precedence when explicitly requested. Optional
        # component flags remain additive (for example --rhis --gittea).
        if [ -n "$CLI_MRHIS" ]; then
            MENU_CHOICE="3"
            RUN_INSTALL_COMPONENT_NAME=""
            # Only --fullstack implies optional components automatically.
            if [ -n "${CLI_FULLSTACK:-}" ]; then
                CLI_GITTEA="1"
                CLI_OPENSHIFT="1"
                CLI_OPENSHIFT_IMPLICIT="1"
            fi
        else
            # Precedence order (last one wins if multiple are provided).
            if [ -n "$CLI_SATELLITE" ]; then
                MENU_CHOICE="4"
                RUN_INSTALL_COMPONENT_NAME="satellite"
            fi
            if [ -n "$CLI_IDM" ]; then
                MENU_CHOICE="4"
                RUN_INSTALL_COMPONENT_NAME="idm"
            fi
            if [ -n "$CLI_AAP" ]; then
                MENU_CHOICE="4"
                RUN_INSTALL_COMPONENT_NAME="aap"
            fi
            if [ -n "$CLI_GITTEA" ]; then
                MENU_CHOICE="4"
                RUN_INSTALL_COMPONENT_NAME="gittea"
            fi
            if [ -n "$CLI_OPENSHIFT" ]; then
                MENU_CHOICE="4"
                RUN_INSTALL_COMPONENT_NAME="openshift"
            fi
        fi
    fi

    # Platform flags set target platform for all components
    if [ -n "$CLI_LIBVIRT" ]; then
        MRHIS_TARGET_PLATFORM="libvirt"
        SAT_TARGET_PLATFORM="libvirt"
        AAP_TARGET_PLATFORM="libvirt"
        IDM_TARGET_PLATFORM="libvirt"
        MRHIS_PLATFORM_FAMILY="virtual"
    fi
    if [ -n "$CLI_BAREMETAL" ]; then
        MRHIS_TARGET_PLATFORM="baremetal"
        SAT_TARGET_PLATFORM="baremetal"
        AAP_TARGET_PLATFORM="baremetal"
        IDM_TARGET_PLATFORM="baremetal"
        MRHIS_PLATFORM_FAMILY="baremetal"
    fi
    if [ -n "$CLI_AWS" ]; then
        MRHIS_TARGET_PLATFORM="aws"
        SAT_TARGET_PLATFORM="aws"
        AAP_TARGET_PLATFORM="aws"
        IDM_TARGET_PLATFORM="aws"
        MRHIS_PLATFORM_FAMILY="cloud"
    fi
    if [ -n "$CLI_AZURE" ]; then
        MRHIS_TARGET_PLATFORM="azure"
        SAT_TARGET_PLATFORM="azure"
        AAP_TARGET_PLATFORM="azure"
        IDM_TARGET_PLATFORM="azure"
        MRHIS_PLATFORM_FAMILY="cloud"
    fi
    if [ -n "$CLI_GCP" ]; then
        MRHIS_TARGET_PLATFORM="gcp"
        SAT_TARGET_PLATFORM="gcp"
        AAP_TARGET_PLATFORM="gcp"
        IDM_TARGET_PLATFORM="gcp"
        MRHIS_PLATFORM_FAMILY="cloud"
    fi
    if [ -n "$CLI_NUTANIX" ]; then
        MRHIS_TARGET_PLATFORM="nutanix"
        SAT_TARGET_PLATFORM="nutanix"
        AAP_TARGET_PLATFORM="nutanix"
        IDM_TARGET_PLATFORM="nutanix"
        MRHIS_PLATFORM_FAMILY="virtual"
    fi
    if [ -n "$CLI_OPENSHIFT" ] && [ -z "$CLI_OPENSHIFT_IMPLICIT" ]; then
        MRHIS_TARGET_PLATFORM="openshift"
        SAT_TARGET_PLATFORM="openshift"
        AAP_TARGET_PLATFORM="openshift"
        IDM_TARGET_PLATFORM="openshift"
        MRHIS_PLATFORM_FAMILY="cloud"
    fi
    if [ -n "$CLI_OPENSHIFT_VIRT" ]; then
        MRHIS_TARGET_PLATFORM="openshift-virt"
        SAT_TARGET_PLATFORM="openshift-virt"
        AAP_TARGET_PLATFORM="openshift-virt"
        IDM_TARGET_PLATFORM="openshift-virt"
        MRHIS_PLATFORM_FAMILY="virtual"
    fi
    # If OpenShift is selected as a target platform, ensure the `ocm` CLI is present
    if [[ "${MRHIS_TARGET_PLATFORM:-}" == openshift* ]] || { [ -n "$CLI_OPENSHIFT" ] && [ -z "$CLI_OPENSHIFT_IMPLICIT" ]; } || [ -n "$CLI_OPENSHIFT_VIRT" ]; then
        if [ -x "${SCRIPT_DIR}/tools/get_ocm.sh" ]; then
            printf "%b\n" "${CYAN}OpenShift target selected: ensuring 'ocm' CLI is available...${NC}"
            # Install into repo-local tools/ocm; do not fail the installer if this helper fails
            "${SCRIPT_DIR}/tools/get_ocm.sh" --dest "${SCRIPT_DIR}/tools/ocm" || printf "%b\n" "${YELLOW}Warning:${NC} failed to obtain 'ocm' CLI; continuing without it"
        fi
    fi
    if [ -n "$CLI_VMWARE" ]; then
        MRHIS_TARGET_PLATFORM="vmware"
        SAT_TARGET_PLATFORM="vmware"
        AAP_TARGET_PLATFORM="vmware"
        IDM_TARGET_PLATFORM="vmware"
        MRHIS_PLATFORM_FAMILY="virtual"
    fi

    if [ -n "$CLI_ATTACH_CONSOLES" ]; then
        MENU_CHOICE="4"
    fi

    if [ -n "${CLI_OPENSTACK_ALIAS:-}" ]; then
        print_warning "--openstack is mapped to --openshift in this build."
    fi

    if [ -n "$CLI_TEST" ]; then
        MRHIS_TEST_MODE=1
        NONINTERACTIVE=1
        RUN_ONCE=1
    fi

    if [ -n "$CLI_STATUS" ]; then
        NONINTERACTIVE=1
        RUN_ONCE=1
    fi

    if [ -n "$CLI_VALIDATE" ]; then
        NONINTERACTIVE=1
        RUN_ONCE=1
    fi

    if [ -n "$CLI_GENERATE_ENV" ]; then
        NONINTERACTIVE=1
        RUN_ONCE=1
    fi

    # When OpenShift target is explicitly requested, prefer a hands-free
    # non-interactive fast-path so callers like `bash MRHIS.sh --openshift`
    # do not unexpectedly drop into interactive prompts. Preserve explicit
    # reconfigure intent (caller asked for `--reconfigure`).
    if { [ -n "${CLI_OPENSHIFT:-}" ] || [ -n "${CLI_OPENSHIFT_VIRT:-}" ]; } && [ -z "${CLI_RECONFIGURE:-}" ]; then
        NONINTERACTIVE=1
        RUN_ONCE=1
    fi

    # Full-stack demo CLI shortcut should run unattended from command line,
    # unless the caller explicitly asked to reconfigure and needs prompts.
    if [ -n "${CLI_DEMO:-}" ] && [ -n "${CLI_MRHIS:-}" ] && [ -z "${CLI_RECONFIGURE:-}" ]; then
        NONINTERACTIVE=1
        RUN_ONCE=1
    fi

    if [ -n "$CLI_MENUTEST" ]; then
        MRHIS_MENU_TEST_MODE=1
        # Respect an explicit --non-interactive passed by the caller; otherwise
        # preserve the previous menutest behavior of interactive prompts.
        if [ -n "${CLI_NONINTERACTIVE:-}" ]; then
            NONINTERACTIVE="$CLI_NONINTERACTIVE"
        else
            NONINTERACTIVE=0
        fi
        # If running menutest in non-interactive/headless mode, make it a
        # one-shot run; otherwise keep the interactive menutest loop.
        if is_noninteractive; then
            RUN_ONCE=1
        else
            RUN_ONCE=0
        fi
    fi

    return 0
}

is_menutest() {
    is_enabled "${MRHIS_MENU_TEST_MODE:-0}"
}

is_noninteractive() {
    case "${NONINTERACTIVE:-0}" in
        1|true|TRUE|yes|YES|on|ON)
            return 0
            ;;
        *)
            return 1
            ;;
    esac
}

is_demo() {
    case "${DEMO_MODE:-0}" in
        1|true|TRUE|yes|YES|on|ON)
            return 0
            ;;
        *)
            return 1
            ;;
    esac
}

is_enabled() {
    case "${1:-0}" in
        1|true|TRUE|yes|YES|on|ON)
            return 0
            ;;
        *)
            return 1
            ;;
    esac
}

probe_ssh_endpoint() {
    local ip="$1"
    local err
    local ssh_key="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/mrhis-installer/id_rsa}"
    local ssh_user="${INSTALLER_USER:-admin}"

    # 1) Try key-based auth as installer/admin user (fast, preferred)
    if [ -n "${ssh_key}" ] && [ -f "${ssh_key}" ]; then
        if timeout 5 ssh -i "${ssh_key}" \
            -o BatchMode=yes \
            -o StrictHostKeyChecking=no \
            -o UserKnownHostsFile=/dev/null \
            -o ForwardX11=no \
            -o ConnectTimeout=3 \
            "${ssh_user}@${ip}" true >/dev/null 2>&1; then
            return 0
        fi
    fi

    # 2) Fallback: probe SSH port and attempt a no-auth probe to detect "auth failure" vs closed port
    if timeout 3 bash -c "</dev/tcp/${ip}/22" >/dev/null 2>&1; then
        err="$(timeout 5 ssh \
            -o BatchMode=yes \
            -o PreferredAuthentications=none \
            -o PasswordAuthentication=no \
            -o PubkeyAuthentication=no \
            -o StrictHostKeyChecking=no \
            -o UserKnownHostsFile=/dev/null \
            -o ForwardX11=no \
            -o ConnectTimeout=3 \
            "root@${ip}" true 2>&1 || true)"

        # If SSH is reachable but auth is denied, treat as reachable (caller can handle auth failures)
        printf '%s' "$err" | grep -Eqi 'permission denied|authentication failed|denied \(publickey\)|too many authentication failures' && return 0
    fi

    return 1
}

# Wait for SSH to become available on a host. Uses scripts/wait_for_ssh.sh when present,
# otherwise falls back to an internal loop based on probe_ssh_endpoint.
# Usage: wait_for_ssh [script-opts] host
wait_for_ssh() {
    local script="$SCRIPT_DIR/scripts/wait_for_ssh.sh"
    if [ -f "$script" ]; then
        # pass all args through to the helper script
        bash "$script" "$@"
        return $?
    fi

    # Fallback: basic timeout loop using probe_ssh_endpoint
    local timeout=300
    local interval=5
    # parse optional -t and -i before host
    local OPTIND=1 opt
    while getopts ":t:i:" opt; do
        case "$opt" in
            t) timeout=$OPTARG ;;
            i) interval=$OPTARG ;;
            *) break ;;
        esac
    done
    shift $((OPTIND - 1))
    local host="$1"
    local start_ts; start_ts=$(date +%s)

    while true; do
        if probe_ssh_endpoint "$host"; then
            return 0
        fi
        if [ $(( $(date +%s) - start_ts )) -ge "$timeout" ]; then
            echo "[TIMEOUT] ${host} did not become reachable via SSH within ${timeout}s"
            return 3
        fi
        sleep "$interval"
    done
}

load_preseed_env() {
    if [ -f "$PRESEED_ENV_FILE" ]; then
        print_step "Loading preseed variables from $PRESEED_ENV_FILE"
        set -a
        # shellcheck disable=SC1090
        . "$PRESEED_ENV_FILE"
        set +a
    fi
}

to_upper() {
    printf '%s' "$1" | tr '[:lower:]' '[:upper:]'
}

derive_gateway_from_network() {
    local network_addr="${1:-}"
    if printf '%s' "$network_addr" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'; then
        printf '%s\n' "$network_addr" | sed -E 's/\.[0-9]+$/\.1/'
        return 0
    fi
    if printf '%s' "${INTERNAL_NETWORK:-}" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'; then
        printf '%s\n' "${INTERNAL_NETWORK}" | sed -E 's/\.[0-9]+$/\.1/'
        return 0
    fi
    printf '%s\n' "10.0.0.1"
}

default_cmdb_endpoint_ip() {
    local prefix_a="10"
    local prefix_b="168"
    local prefix_c="128"
    local host_octet

    if printf '%s' "${SAT_IP:-}" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'; then
        prefix_a="$(printf '%s' "${SAT_IP}" | awk -F. '{print $1}')"
        prefix_b="$(printf '%s' "${SAT_IP}" | awk -F. '{print $2}')"
        prefix_c="$(printf '%s' "${SAT_IP}" | awk -F. '{print $3}')"
    elif printf '%s' "${INTERNAL_NETWORK:-}" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'; then
        prefix_a="$(printf '%s' "${INTERNAL_NETWORK}" | awk -F. '{print $1}')"
        prefix_b="$(printf '%s' "${INTERNAL_NETWORK}" | awk -F. '{print $2}')"
    fi

    host_octet=$(( (${RANDOM:-73} % 120) + 50 ))
    printf '%s.%s.%s.%s\n' "${prefix_a}" "${prefix_b}" "${prefix_c}" "${host_octet}"
}

is_unresolved_template_value() {
    local value="${1:-}"
    case "$value" in
        *"{{"*|*"}}"*)
            return 0
            ;;
        "example.com"|"example.org"|"EXAMPLE.COM"|"EXAMPLE.ORG")
            return 0
            ;;
        *)
            return 1
            ;;
    esac
}

needs_prompt_var() {
    local var_name="$1"
    local value="${!var_name:-}"
    if [ -z "$value" ] || is_unresolved_template_value "$value"; then
        return 0
    fi
    return 1
}

strip_wrapping_quotes() {
    local raw="${1:-}"
    # Trim leading/trailing whitespace first.
    raw="$(printf '%s' "${raw}" | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//')"
    case "${raw}" in
        \"*\") raw="${raw#\"}"; raw="${raw%\"}" ;;
        \'*\') raw="${raw#\'}"; raw="${raw%\'}" ;;
    esac
    printf '%s' "${raw}"
}

normalize_shared_env_vars() {
    # Map common lowercase vault/env aliases to canonical UPPERCASE names.
    # This helps compatibility with older vaults or environment files that
    # used lowercase keys (e.g. "aap_admin_pass") while the script expects
    # uppercase variables (e.g. `AAP_ADMIN_PASS`). Do NOT override values
    # already set in uppercase.
    local _aliases=(
        "RH_USER:rh_user"
        "RH_PASS:rh_pass"
        "ADMIN_PASS:admin_pass"
        "ADMIN_USER:admin_user"
        "DOMAIN:domain"
        "REALM:realm"
        "IDM_DOMAIN:idm_domain"
        "SAT_DOMAIN:sat_domain"
        "AAP_DOMAIN:aap_domain"
        "IDM_REALM:idm_realm"
        "SAT_REALM:sat_realm"
        "AAP_ADMIN_PASS:aap_admin_pass"
        "SAT_ADMIN_PASS:sat_admin_pass"
        "IDM_ADMIN_PASS:idm_admin_pass"
        "IPADM_PASSWORD:ipadm_password"
        "IPAADMIN_PASSWORD:ipaadmin_password"
        "ROOT_PASS:root_pass"
        "IDM_DS_PASS:idm_ds_pass"
        "HUB_TOKEN:hub_token"
        "AAP_BUNDLE_URL:aap_bundle_url"
        "RH_OFFLINE_TOKEN:rh_offline_token"
        "SAT_IP:sat_ip"
        "AAP_IP:aap_ip"
        "IDM_IP:idm_ip"
        "SAT_HOSTNAME:sat_hostname"
        "AAP_HOSTNAME:aap_hostname"
        "IDM_HOSTNAME:idm_hostname"
        "SAT_ORG:sat_org"
        "SAT_LOC:sat_loc"
        "SAT_NETMASK:sat_netmask"
        "AAP_NETMASK:aap_netmask"
        "IDM_NETMASK:idm_netmask"
        "SAT_GW:sat_gw"
        "AAP_GW:aap_gw"
        "IDM_GW:idm_gw"
    )
    local _pair _u _l
    for _pair in "${_aliases[@]}"; do
        _u=${_pair%%:*}
        _l=${_pair##*:}
        if [ -z "${!_u:-}" ] && [ -n "${!_l:-}" ]; then
            printf -v "${_u}" '%s' "${!_l}"
        fi
    done
    unset _aliases _pair _u _l

    # Sensible fallbacks for demo/headless runs: reuse shared admin creds
    # for CDN/RH accesses when explicit RH_* vars are not provided in the vault.
    if [ -z "${RH_USER:-}" ] && [ -n "${ADMIN_USER:-}" ]; then
        RH_USER="${ADMIN_USER}"
    fi
    if [ -z "${RH_PASS:-}" ] && [ -n "${ADMIN_PASS:-}" ]; then
        RH_PASS="${ADMIN_PASS}"
    fi

    # If ISO URLs are not provided in the vault, prefer configured ISO paths.
    RH_ISO_URL="${RH_ISO_URL:-${ISO_PATH:-}}"
    RH9_ISO_URL="${RH9_ISO_URL:-${SAT_ISO_PATH:-}}"

    # Guard against unresolved templating artifacts such as '{{ DOMAIN }}'.
    if is_unresolved_template_value "${DOMAIN:-}"; then
        DOMAIN=""
    fi
    if is_unresolved_template_value "${SAT_DOMAIN:-}"; then
        SAT_DOMAIN=""
    fi
    if is_unresolved_template_value "${AAP_DOMAIN:-}"; then
        AAP_DOMAIN=""
    fi
    if is_unresolved_template_value "${IDM_DOMAIN:-}"; then
        IDM_DOMAIN=""
    fi

    DOMAIN="${DOMAIN:-${SAT_DOMAIN:-${AAP_DOMAIN:-${IDM_DOMAIN:-example.com}}}}"
    # Clear placeholder values so a real domain can always seed REALM.
    is_unresolved_template_value "${REALM:-}" && REALM=""
    is_unresolved_template_value "${IDM_REALM:-}" && IDM_REALM=""
    is_unresolved_template_value "${SAT_REALM:-}" && SAT_REALM=""
    REALM="${REALM:-${IDM_REALM:-${SAT_REALM:-}}}"
    [ -n "${REALM:-}" ] || REALM="$(to_upper "$DOMAIN")"
    [ -n "${REALM:-}" ] || REALM="EXAMPLE.COM"

    ADMIN_USER="${ADMIN_USER:-admin}"
    GLOBAL_ADMIN="${GLOBAL_ADMIN:-${ADMIN_USER:-admin}}"
    # Canonical shared admin password source: AAP_ADMIN_PASS (loaded from vault: ~/.ansible/conf/env.yml → aap_admin_pass).
    # Keep ADMIN_PASS/SAT_ADMIN_PASS/IDM_ADMIN_PASS as compatibility aliases.
    AAP_ADMIN_PASS="${AAP_ADMIN_PASS:-${ADMIN_PASS:-}}"
    if [ -z "${AAP_ADMIN_PASS:-}" ]; then
        echo "[WARNING] AAP_ADMIN_PASS is empty — ensure ~/.ansible/conf/env.yml has aap_admin_pass set and vault is loaded" >&2
    fi
    ADMIN_PASS="${ADMIN_PASS:-${AAP_ADMIN_PASS}}"
    GLOBAL_ADMIN_PASSWORD="${GLOBAL_ADMIN_PASSWORD:-${AAP_ADMIN_PASS:-${ADMIN_PASS:-}}}"
    SAT_ADMIN_PASS="${SAT_ADMIN_PASS:-${AAP_ADMIN_PASS}}"
    SAT_INITIAL_ADMIN_PASS="${SAT_INITIAL_ADMIN_PASS:-${SAT_ADMIN_PASS}}"
    ROOT_PASS="${ROOT_PASS:-${ADMIN_PASS}}"
    IDM_ADMIN_PASS="${IDM_ADMIN_PASS:-${AAP_ADMIN_PASS}}"
    IPADM_PASSWORD="${IPADM_PASSWORD:-${IDM_ADMIN_PASS:-${AAP_ADMIN_PASS}}}"
    IPAADMIN_PASSWORD="${IPAADMIN_PASSWORD:-${IDM_ADMIN_PASS:-${AAP_ADMIN_PASS}}}"
    SAT_COMPUTE_PASSWORD="${SAT_COMPUTE_PASSWORD:-${AAP_ADMIN_PASS}}"
    SAT_IMAGE_PASSWORD="${SAT_IMAGE_PASSWORD:-${AAP_ADMIN_PASS}}"

    # FreeIPA requires admin/DS passwords to be at least 8 characters.
    # Keep ADMIN_PASS unchanged (it may be used for host logins), but normalize
    # IdM-specific credentials to a safe minimum for unattended ipa-server-install.
    if [ -n "${IDM_ADMIN_PASS:-}" ] && [ "${#IDM_ADMIN_PASS}" -lt 8 ]; then
        local _idm_seed _idm_fallback
        _idm_seed="${IDM_ADMIN_PASS:-${ADMIN_PASS:-mrhis}}"
        _idm_fallback="${_idm_seed}"
        while [ "${#_idm_fallback}" -lt 8 ]; do
            _idm_fallback="${_idm_fallback}9"
        done
        print_warning "IDM_ADMIN_PASS is shorter than 8 characters; using a normalized IdM-specific password for FreeIPA install."
        IDM_ADMIN_PASS="${_idm_fallback}"
    fi

    if [ -z "${IPADM_PASSWORD:-}" ] || [ "${#IPADM_PASSWORD}" -lt 8 ]; then
        IPADM_PASSWORD="${IDM_ADMIN_PASS}"
    fi
    if [ -z "${IPAADMIN_PASSWORD:-}" ] || [ "${#IPAADMIN_PASSWORD}" -lt 8 ]; then
        IPAADMIN_PASSWORD="${IDM_ADMIN_PASS}"
    fi

    INTERNAL_NETWORK="${INTERNAL_NETWORK:-10.168.0.0}"
    NETMASK="${NETMASK:-${SAT_NETMASK:-${AAP_NETMASK:-${IDM_NETMASK:-255.255.0.0}}}}"
    INTERNAL_GW="${INTERNAL_GW:-${SAT_GW:-${AAP_GW:-${IDM_GW:-$(derive_gateway_from_network "${INTERNAL_NETWORK}")}}}}"
    HOST_INT_IP="${HOST_INT_IP:-${INTERNAL_GW:-10.168.0.1}}"
    CMDB_ENDPOINT_IP="${CMDB_ENDPOINT_IP:-$(default_cmdb_endpoint_ip)}"

    SAT_IP="${SAT_IP:-10.168.128.1}"
    AAP_IP="${AAP_IP:-10.168.128.2}"
    IDM_IP="${IDM_IP:-10.168.128.3}"

    # Global MRHIS policy: all managed SSH traffic must use the internal network.
    if is_enabled "${MRHIS_MANAGED_SSH_OVER_ETH0:-0}"; then
        print_warning "MRHIS_MANAGED_SSH_OVER_ETH0 is deprecated and ignored; enforcing internal SSH over 10.168.x.x."
    fi
    MRHIS_MANAGED_SSH_OVER_ETH0="0"

    # Guardrails: MRHIS node-to-node addresses must remain on the internal 10.168/16.
    case "${SAT_IP}" in 10.168.*) ;; *) print_error "SAT_IP='${SAT_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac
    case "${AAP_IP}" in 10.168.*) ;; *) print_error "AAP_IP='${AAP_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac
    case "${IDM_IP}" in 10.168.*) ;; *) print_error "IDM_IP='${IDM_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac
    case "${HOST_INT_IP}" in 10.168.*) ;; *) print_error "HOST_INT_IP='${HOST_INT_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac
    case "${CMDB_ENDPOINT_IP}" in 10.168.*) ;; *) print_warning "CMDB_ENDPOINT_IP='${CMDB_ENDPOINT_IP}' is outside 10.168.x.x; resetting to $(default_cmdb_endpoint_ip)."; CMDB_ENDPOINT_IP="$(default_cmdb_endpoint_ip)" ;; esac

    SAT_ORG="${SAT_ORG:-REDHAT}"
    SAT_LOC="${SAT_LOC:-CORE}"
    # Guardrail: MRHIS supports only containerized AAP installs.
    AAP_DEPLOYMENT_TYPE="container"
    # Guardrail: MRHIS lab uses single-node AAP topology only.
    if [ "${AAP_TOPOLOGY:-standalone}" != "standalone" ]; then
        print_warning "AAP_TOPOLOGY='${AAP_TOPOLOGY}' is not supported for standalone MRHIS labs; forcing standalone."
    fi
    AAP_TOPOLOGY="standalone"

    # Guardrail: avoid enterprise multi-node inventory in standalone mode.
    case "$(basename "${AAP_INVENTORY_TEMPLATE:-}")" in
        "" )
            AAP_INVENTORY_TEMPLATE="inventory-growth.j2"
            ;;
        DEMO-inventory.j2|DEMO-inventory)
            ;;
        inventory.j2|inventory)
            print_warning "AAP inventory template '${AAP_INVENTORY_TEMPLATE}' is enterprise/multi-node; forcing inventory-growth.j2 for standalone mode."
            AAP_INVENTORY_TEMPLATE="inventory-growth.j2"
            ;;
        *)
            ;;
    esac
    AAP_INVENTORY_GROWTH_TEMPLATE="${AAP_INVENTORY_GROWTH_TEMPLATE:-inventory-growth.j2}"
    INSTALLER_USER="${INSTALLER_USER:-${USER}}"
    if [ "${MRHIS_ALLOW_SSHPASS:-0}" = "1" ]; then
        SSHPASS_CMD="${SSHPASS_CMD:-sshpass}"
    else
        SSHPASS_CMD="${SSHPASS_CMD:-}"
    fi

    # Defensive normalization: env.yml may contain single-quoted identifiers.
    # Strip wrapping quotes so RHSM/rhc receive raw org/key values.
    CDN_ORGANIZATION_ID="$(strip_wrapping_quotes "${CDN_ORGANIZATION_ID:-}")"
    CDN_SAT_ACTIVATION_KEY="$(strip_wrapping_quotes "${CDN_SAT_ACTIVATION_KEY:-}")"
    RHC_ORGANIZATION_ID="$(strip_wrapping_quotes "${RHC_ORGANIZATION_ID:-}")"
    RHC_ACTIVATION_KEY="$(strip_wrapping_quotes "${RHC_ACTIVATION_KEY:-}")"

    case "${SATELLITE_DISCONNECTED:-false}" in
        1|true|TRUE|yes|YES|on|ON)
            SATELLITE_DISCONNECTED="true"
            ;;
        *)
            SATELLITE_DISCONNECTED="false"
            ;;
    esac

    case "${REGISTER_TO_SATELLITE:-false}" in
        1|true|TRUE|yes|YES|on|ON)
            REGISTER_TO_SATELLITE="true"
            ;;
        *)
            REGISTER_TO_SATELLITE="false"
            ;;
    esac

    case "${SATELLITE_VALIDATE_CERTS:-false}" in
        1|true|TRUE|yes|YES|on|ON)
            SATELLITE_VALIDATE_CERTS="true"
            ;;
        *)
            SATELLITE_VALIDATE_CERTS="false"
            ;;
    esac

    case "${SATELLITE_PRE_USE_IDM:-false}" in
        1|true|TRUE|yes|YES|on|ON)
            SATELLITE_PRE_USE_IDM="true"
            ;;
        *)
            SATELLITE_PRE_USE_IDM="false"
            ;;
    esac

    case "${SAT_USE_NON_IDM_CERTS:-}" in
        1|true|TRUE|yes|YES|on|ON)
            SAT_USE_NON_IDM_CERTS="true"
            ;;
        0|false|FALSE|no|NO|off|OFF)
            SAT_USE_NON_IDM_CERTS="false"
            ;;
        *)
            SAT_USE_NON_IDM_CERTS=""
            ;;
    esac

    case "${RHC_AUTO_CONNECT:-1}" in
        1|true|TRUE|yes|YES|on|ON)
            RHC_AUTO_CONNECT="1"
            ;;
        *)
            RHC_AUTO_CONNECT="0"
            ;;
    esac

    SAT_SSL_CERTS_DIR="${SAT_SSL_CERTS_DIR:-/root/.sat_ssl/}"
    case "${SAT_SSL_CERTS_DIR}" in
        */) ;;
        *) SAT_SSL_CERTS_DIR="${SAT_SSL_CERTS_DIR}/" ;;
    esac

    SAT_DOMAIN="${SAT_DOMAIN:-$DOMAIN}"
    AAP_DOMAIN="${AAP_DOMAIN:-$DOMAIN}"
    IDM_DOMAIN="${IDM_DOMAIN:-$DOMAIN}"
    SAT_FIREWALLD_ZONE="${SAT_FIREWALLD_ZONE:-public}"
    SAT_FIREWALLD_INTERFACE="${SAT_FIREWALLD_INTERFACE:-eth0}"
    SAT_FIREWALLD_SERVICES_JSON="${SAT_FIREWALLD_SERVICES_JSON:-[\"ssh\",\"http\",\"https\"]}"
    SAT_PROVISIONING_SUBNET="${SAT_PROVISIONING_SUBNET:-10.168.0.0}"
    SAT_PROVISIONING_NETMASK="${SAT_PROVISIONING_NETMASK:-$NETMASK}"
    SAT_PROVISIONING_GW="${SAT_PROVISIONING_GW:-$INTERNAL_GW}"

    # Keep Satellite service endpoints pinned to the internal MRHIS network.
    if ! is_enabled "${MRHIS_ENFORCE_SAT_INTERNAL_NETWORK:-1}"; then
        print_warning "MRHIS_ENFORCE_SAT_INTERNAL_NETWORK=0 is not supported for MRHIS stack coherence; forcing to 1."
    fi
    MRHIS_ENFORCE_SAT_INTERNAL_NETWORK="1"
    SAT_PROVISIONING_DHCP_START="${SAT_PROVISIONING_DHCP_START:-10.168.130.1}"
    SAT_PROVISIONING_DHCP_END="${SAT_PROVISIONING_DHCP_END:-10.168.255.254}"
    SAT_PROVISIONING_DNS_PRIMARY="${SAT_PROVISIONING_DNS_PRIMARY:-${SAT_IP}}"
    SAT_PROVISIONING_DNS_SECONDARY="${SAT_PROVISIONING_DNS_SECONDARY:-8.8.8.8}"
    SAT_DNS_ZONE="${SAT_DNS_ZONE:-${DOMAIN}}"
    if [ -z "${SAT_DNS_REVERSE_ZONE:-}" ]; then
        local _sat_reverse_prefix
        _sat_reverse_prefix="$(printf '%s' "${SAT_PROVISIONING_SUBNET:-10.168.0.0}" | awk -F. '{print $1"."$2"."$3}')"
        SAT_DNS_REVERSE_ZONE="$(printf '%s' "${_sat_reverse_prefix:-10.168.0}" | awk -F. '{print $3"."$2"."$1".in-addr.arpa"}')"
    fi

    if is_unresolved_template_value "${SAT_HOSTNAME:-}"; then
        SAT_HOSTNAME=""
    fi
    if is_unresolved_template_value "${AAP_HOSTNAME:-}"; then
        AAP_HOSTNAME=""
    fi
    if is_unresolved_template_value "${IDM_HOSTNAME:-}"; then
        IDM_HOSTNAME=""
    fi

    # Only append the domain when it's non-empty to avoid trailing dots
    local _domain_suffix="${DOMAIN:+.${DOMAIN}}"
    SAT_HOSTNAME="${SAT_HOSTNAME:-satellite${_domain_suffix}}"
    AAP_HOSTNAME="${AAP_HOSTNAME:-aap${_domain_suffix}}"
    IDM_HOSTNAME="${IDM_HOSTNAME:-idm${_domain_suffix}}"

    while [ -n "${SAT_HOSTNAME:-}" ] && [ "${SAT_HOSTNAME: -1}" = "." ]; do
        SAT_HOSTNAME="${SAT_HOSTNAME%?}"
    done
    while [ -n "${AAP_HOSTNAME:-}" ] && [ "${AAP_HOSTNAME: -1}" = "." ]; do
        AAP_HOSTNAME="${AAP_HOSTNAME%?}"
    done
    while [ -n "${IDM_HOSTNAME:-}" ] && [ "${IDM_HOSTNAME: -1}" = "." ]; do
        IDM_HOSTNAME="${IDM_HOSTNAME%?}"
    done

    # Hostname validation helper: basic permissive check for typical hostnames
    validate_hostname() {
        local hn="$1"
        # non-empty and length limits
        [ -n "$hn" ] || return 1
        if [ "${#hn}" -gt 253 ]; then
            return 1
        fi
        # must not end with dot
        case "$hn" in
            *.) return 1 ;;
        esac
        # allowed chars: a-z, A-Z, 0-9, -, . and must start/end with alnum
        if ! printf '%s' "$hn" | grep -Eq '^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$'; then
            return 1
        fi
        return 0
    }

    # Validate hostnames and warn/fallback if somehow invalid after sanitization.
    for _h in SAT_HOSTNAME AAP_HOSTNAME IDM_HOSTNAME; do
        _val="${!_h}"
        if ! validate_hostname "$_val"; then
            print_warning "Computed ${_h}='${_val}' looks invalid; falling back to safe default without domain."
            case "${_h}" in
                SAT_HOSTNAME) eval "${_h}=satellite" ;;
                AAP_HOSTNAME) eval "${_h}=aap" ;;
                IDM_HOSTNAME) eval "${_h}=idm" ;;
            esac
        fi
    done
    SAT_ALIAS="${SAT_ALIAS:-satellite}"
    AAP_ALIAS="${AAP_ALIAS:-aap}"
    IDM_ALIAS="${IDM_ALIAS:-idm}"

    SAT_REALM="${SAT_REALM:-$REALM}"
    IDM_REALM="${IDM_REALM:-$REALM}"

    # Per-system admin passwords default to the shared admin password, but do
    # not override explicit per-role values when they are provided.
    SAT_ADMIN_PASS="${SAT_ADMIN_PASS:-${AAP_ADMIN_PASS}}"
    AAP_ADMIN_PASS="${AAP_ADMIN_PASS:-${ADMIN_PASS}}"
    SAT_INITIAL_ADMIN_PASS="${SAT_INITIAL_ADMIN_PASS:-${SAT_ADMIN_PASS}}"
    IDM_ADMIN_PASS="${IDM_ADMIN_PASS:-${AAP_ADMIN_PASS}}"
    IDM_DS_PASS="${IDM_DS_PASS:-${IDM_ADMIN_PASS:-${AAP_ADMIN_PASS}}}"

    if [ -z "${IDM_DS_PASS:-}" ] || [ "${#IDM_DS_PASS}" -lt 8 ]; then
        IDM_DS_PASS="${IDM_ADMIN_PASS}"
    fi

    SAT_NETMASK="${SAT_NETMASK:-$NETMASK}"
    AAP_NETMASK="${AAP_NETMASK:-$NETMASK}"
    IDM_NETMASK="${IDM_NETMASK:-$NETMASK}"

    SAT_GW="${SAT_GW:-$INTERNAL_GW}"
    AAP_GW="${AAP_GW:-$INTERNAL_GW}"
    IDM_GW="${IDM_GW:-$INTERNAL_GW}"

    # Guardrails: gateways must remain on the MRHIS internal network.
    case "${SAT_GW}" in 10.168.*) ;; *) print_warning "SAT_GW='${SAT_GW}' is outside 10.168.x.x; forcing INTERNAL_GW='${INTERNAL_GW}'."; SAT_GW="${INTERNAL_GW}" ;; esac
    case "${AAP_GW}" in 10.168.*) ;; *) print_warning "AAP_GW='${AAP_GW}' is outside 10.168.x.x; forcing INTERNAL_GW='${INTERNAL_GW}'."; AAP_GW="${INTERNAL_GW}" ;; esac
    case "${IDM_GW}" in 10.168.*) ;; *) print_warning "IDM_GW='${IDM_GW}' is outside 10.168.x.x; forcing INTERNAL_GW='${INTERNAL_GW}'."; IDM_GW="${INTERNAL_GW}" ;; esac
}

set_or_prompt() {
    local var_name="$1"
    local prompt_text="$2"
    local is_secret="${3:-0}"
    local prompt_value
    local lower_prompt prompt_label

    lower_prompt="$(printf '%s' "$prompt_text" | tr '[:upper:]' '[:lower:]')"
    prompt_label="$prompt_text"
    if [[ "$lower_prompt" != *"optional"* ]] && [[ "$lower_prompt" != *"required"* ]]; then
        prompt_label="${prompt_text} [Required]"
    fi

    if [ -n "${!var_name:-}" ]; then
        return 0
    fi

    # Treat explicit CLI request for demo full-stack as hands-free as well
    if is_noninteractive || { [ -n "${CLI_DEMO:-}" ] && [ -n "${CLI_MRHIS:-}" ]; }; then
        print_warning "NONINTERACTIVE mode requires $var_name to be set."
        return 1
    fi

    if [ "$is_secret" = "1" ]; then
        local confirm_value
        while true; do
            read -r -s -p "$prompt_label" prompt_value
            echo ""

            if [ -z "${prompt_value}" ]; then
                print_warning "$var_name is required. Please provide a value."
                continue
            fi

            read -r -s -p "Confirm ${prompt_text} [Required]" confirm_value
            echo ""

            if [ "${prompt_value}" != "${confirm_value}" ]; then
                print_warning "Values did not match for $var_name. Please try again."
                continue
            fi
            break
        done
    else
        read -r -p "$prompt_label" prompt_value
    fi

    printf -v "$var_name" '%s' "$prompt_value"

    [ -n "${!var_name:-}" ]
}

set_or_prompt_optional() {
    local var_name="$1"
    local prompt_text="$2"
    local is_secret="${3:-0}"
    local prompt_value
    local prompt_label
    prompt_label="$prompt_text"

    if [ -n "${!var_name:-}" ]; then
        return 0
    fi

    if is_noninteractive; then
        return 0
    fi

    if [ "$is_secret" = "1" ]; then
        local confirm_value
        while true; do
            read -r -s -p "$prompt_label" prompt_value
            echo ""

            # Optional secret prompts can be left blank without confirmation.
            if [ -z "${prompt_value}" ]; then
                break
            fi

            read -r -s -p "Confirm ${prompt_text}" confirm_value
            echo ""

            if [ "${prompt_value}" != "${confirm_value}" ]; then
                print_warning "Values did not match for $var_name. Please try again."
                continue
            fi
            break
        done
    else
        read -r -p "$prompt_label" prompt_value
    fi

    printf -v "$var_name" '%s' "$prompt_value"
    return 0
}

prompt_with_default() {
    local var_name="$1"
    local prompt_label="$2"
    local default_value="${3:-}"
    local is_secret="${4:-0}"
    local is_required="${5:-0}"
    local input_value=""
    local prompt_with_meta
    prompt_with_meta="$prompt_label"

    if is_noninteractive; then
        if [ -n "${!var_name:-}" ] && ! is_unresolved_template_value "${!var_name:-}"; then
            return 0
        fi
        if [ -n "$default_value" ] && ! is_unresolved_template_value "$default_value"; then
            printf -v "$var_name" '%s' "$default_value"
            return 0
        fi
        [ "$is_required" = "1" ] && {
            print_warning "NONINTERACTIVE mode requires $var_name to be set."
            return 1
        }
        return 0
    fi

    # Skip prompting for values already loaded from env.yml unless reconfiguring.
    if [ "${FORCE_PROMPT_ALL:-0}" != "1" ] && [ -n "${!var_name:-}" ] && ! is_unresolved_template_value "${!var_name:-}"; then
        return 0
    fi

    while true; do
        if [ "$is_secret" = "1" ]; then
            local confirm_value using_default="0"
            if [ -n "$default_value" ]; then
                read -r -s -p "$prompt_with_meta (hidden; press Enter to keep current): " input_value
            else
                read -r -s -p "$prompt_with_meta: " input_value
            fi
            echo ""

            if [ -z "$input_value" ] && [ -n "$default_value" ]; then
                input_value="$default_value"
                using_default="1"
            fi

            if [ "$is_required" = "1" ] && [ -z "$input_value" ]; then
                print_warning "$var_name is required. Please provide a value."
                continue
            fi

            if is_unresolved_template_value "$input_value"; then
                print_warning "$var_name contains an unresolved template placeholder. Please provide an actual value."
                continue
            fi

            # Require confirmation only when user typed a new secret value.
            if [ -n "$input_value" ] && [ "$using_default" != "1" ]; then
                read -r -s -p "Confirm ${prompt_with_meta}: " confirm_value
                echo ""
                if [ "$input_value" != "$confirm_value" ]; then
                    print_warning "Values did not match for $var_name. Please try again."
                    continue
                fi
            fi

            printf -v "$var_name" '%s' "$input_value"
            return 0
        else
            if [ -n "$default_value" ]; then
                read -r -p "$prompt_with_meta [$default_value]: " input_value
            else
                read -r -p "$prompt_with_meta: " input_value
            fi

            [ -n "$input_value" ] || input_value="$default_value"

            if [ "$is_required" = "1" ] && [ -z "$input_value" ]; then
                print_warning "$var_name is required. Please provide a value."
                continue
            fi

            if is_unresolved_template_value "$input_value"; then
                print_warning "$var_name contains an unresolved template placeholder. Please provide an actual value."
                continue
            fi

            printf -v "$var_name" '%s' "$input_value"
            return 0
        fi
    done
}

should_prompt_component_overrides() {
    case "${FORCE_PROMPT_ALL:-0}" in
        1|true|TRUE|yes|YES|on|ON)
            return 0
            ;;
    esac
    case "${MRHIS_PROMPT_COMPONENT_OVERRIDES:-0}" in
        1|true|TRUE|yes|YES|on|ON)
            return 0
            ;;
    esac
    return 1
}

set_if_unset() {
    local var_name="$1"
    local default_value="$2"
    if [ -z "${!var_name:-}" ] || is_unresolved_template_value "${!var_name:-}"; then
        printf -v "$var_name" '%s' "$default_value"
    fi
}

# Platform helper functions (hoisted to top-level so prompts can call them
# from any call site). These were previously nested inside
# `prompt_platform_choice()` which caused "command not found" when the
# outer function had not yet executed.
platform_family_for_provider() {
    case "$(normalize_platform_value "$1")" in
        aws|azure|gcp|openshift)
            printf '%s' "cloud"
            ;;
        baremetal)
            printf '%s' "baremetal"
            ;;
        *)
            printf '%s' "virtual"
            ;;
    esac
}

set_platform_targets() {
