normalize_platform_value() {
    local raw="${1:-libvirt}"
    local v
    v="$(printf '%s' "$raw" | tr '[:upper:]' '[:lower:]' | tr ' ' '-' | tr '_' '-')"
    case "$v" in
        libvirt|kvm)
            printf '%s' "libvirt"
            ;;
        vmware|vsphere)
            printf '%s' "vmware"
            ;;
        nutanix|nutanix-ahv|ahv)
            printf '%s' "nutanix"
            ;;
        openshift|ocp)
            printf '%s' "openshift"
            ;;
        openshift-virt|openshiftvirt|kubevirt)
            printf '%s' "openshift-virt"
            ;;
        aws|ec2)
            printf '%s' "aws"
            ;;
        gcp|gce|google)
            printf '%s' "gcp"
            ;;
        azure)
            printf '%s' "azure"
            ;;
        baremetal|bare-metal|metal)
            printf '%s' "baremetal"
            ;;
        *)
            printf '%s' "$v"
            ;;
    esac
}

