    echo ""
    echo "  1) AWS (Planned)"
    echo "  2) Azure (Planned)"
    echo "  3) Bare Metal (Planned)"
    echo "  4) GCP (Planned)"
    echo "  5) libvirt (Current)"
    echo "  6) Nutanix (Planned)"
    echo "  7) OpenShift (Planned)"
    echo "  8) OpenShift Virt (Planned)"
    echo "  9) VMware (Planned)"
    echo ""
    echo "  Default: libvirt"
    echo ""
    read -r -p "  Choice [1-9, Enter=default ${default_value}]: " choice

    case "${choice}" in
        "") selected="${default_value}" ;;
        1) selected="aws" ;;
        2) selected="azure" ;;
        3) selected="baremetal" ;;
        4) selected="gcp" ;;
        5) selected="libvirt" ;;
        6) selected="nutanix" ;;
        7) selected="openshift" ;;
        8) selected="openshift-virt" ;;
        9) selected="vmware" ;;
        *) selected="${default_value}" ;;
    esac

    printf -v "$var_name" '%s' "$(normalize_platform_value "$selected")"
    return 0
}

count_missing_vars() {
    local missing=0
    local var_name
    local value

    for var_name in "$@"; do
        value="${!var_name:-}"
        if [ -z "$value" ] || is_unresolved_template_value "$value"; then
            missing=$((missing + 1))
        fi
    done

    printf '%s' "$missing"
}

is_sensitive_env_var() {
    local var_name="$1"
    case "$var_name" in
        *PASS*|*PASSWORD*|*TOKEN*|*SECRET*|*KEY*) return 0 ;;
        *) return 1 ;;
    esac
}

default_for_required_var() {
    local var_name="$1"
    case "$var_name" in
        ADMIN_USER) printf '%s' "${ADMIN_USER:-admin}" ;;
        DOMAIN) printf '%s' "${DOMAIN:-example.com}" ;;
        REALM) printf '%s' "${REALM:-$(to_upper "${DOMAIN:-example.com}")}" ;;
        INTERNAL_NETWORK) printf '%s' "${INTERNAL_NETWORK:-10.168.0.0}" ;;
        NETMASK) printf '%s' "${NETMASK:-255.255.0.0}" ;;
        INTERNAL_GW) printf '%s' "${INTERNAL_GW:-$(derive_gateway_from_network "${INTERNAL_NETWORK:-10.168.0.0}")}" ;;
        HOST_INT_IP) printf '%s' "${HOST_INT_IP:-10.168.0.1}" ;;
        SAT_IP) printf '%s' "${SAT_IP:-10.168.128.1}" ;;
        AAP_IP) printf '%s' "${AAP_IP:-10.168.128.2}" ;;
        IDM_IP) printf '%s' "${IDM_IP:-10.168.128.3}" ;;
        SAT_NETMASK) printf '%s' "${SAT_NETMASK:-${NETMASK:-255.255.0.0}}" ;;
        AAP_NETMASK) printf '%s' "${AAP_NETMASK:-${NETMASK:-255.255.0.0}}" ;;
        IDM_NETMASK) printf '%s' "${IDM_NETMASK:-${NETMASK:-255.255.0.0}}" ;;
        SAT_GW) printf '%s' "${SAT_GW:-${INTERNAL_GW:-$(derive_gateway_from_network "${INTERNAL_NETWORK:-10.168.0.0}")}}" ;;
        AAP_GW) printf '%s' "${AAP_GW:-${INTERNAL_GW:-$(derive_gateway_from_network "${INTERNAL_NETWORK:-10.168.0.0}")}}" ;;
        IDM_GW) printf '%s' "${IDM_GW:-${INTERNAL_GW:-$(derive_gateway_from_network "${INTERNAL_NETWORK:-10.168.0.0}")}}" ;;
        SAT_HOSTNAME) printf '%s' "${SAT_HOSTNAME:-satellite.${DOMAIN:-prod.spg}}" ;;
        AAP_HOSTNAME) printf '%s' "${AAP_HOSTNAME:-aap.${DOMAIN:-prod.spg}}" ;;
        IDM_HOSTNAME) printf '%s' "${IDM_HOSTNAME:-idm.${DOMAIN:-prod.spg}}" ;;
        SAT_ALIAS) printf '%s' "${SAT_ALIAS:-satellite}" ;;
        AAP_ALIAS) printf '%s' "${AAP_ALIAS:-aap}" ;;
        IDM_ALIAS) printf '%s' "${IDM_ALIAS:-idm}" ;;
        SAT_ORG) printf '%s' "${SAT_ORG:-REDHAT}" ;;
        SAT_LOC) printf '%s' "${SAT_LOC:-CORE}" ;;
        SAT_DOMAIN) printf '%s' "${SAT_DOMAIN:-${DOMAIN:-prod.spg}}" ;;
        AAP_DOMAIN) printf '%s' "${AAP_DOMAIN:-${DOMAIN:-prod.spg}}" ;;
        IDM_DOMAIN) printf '%s' "${IDM_DOMAIN:-${DOMAIN:-prod.spg}}" ;;
        AAP_ADMIN_PASS) printf '%s' "${AAP_ADMIN_PASS:-${ADMIN_PASS:-}}" ;;
        ADMIN_PASS) printf '%s' "${ADMIN_PASS:-${AAP_ADMIN_PASS:-}}" ;;
        RH_USER) printf '%s' "${RH_USER:-${ADMIN_USER:-}}" ;;
        RH_PASS) printf '%s' "${RH_PASS:-${ADMIN_PASS:-${AAP_ADMIN_PASS:-}}}" ;;
        RH_ISO_URL) printf '%s' "${RH_ISO_URL:-${ISO_PATH:-}}" ;;
        RH9_ISO_URL) printf '%s' "${RH9_ISO_URL:-${SAT_ISO_PATH:-}}" ;;
        *) printf '%s' "${!var_name:-}" ;;
    esac
}

prompt_label_for_required_var() {
    local var_name="$1"
    case "$var_name" in
        RH_USER) printf '%s' "Red Hat CDN Username" ;;
        RH_PASS) printf '%s' "Red Hat CDN Password" ;;
        AAP_ADMIN_PASS) printf '%s' "AAP admin password" ;;
        ADMIN_PASS) printf '%s' "Shared Admin Password" ;;
        ADMIN_USER) printf '%s' "Shared Admin Username" ;;
        DOMAIN) printf '%s' "Shared Domain" ;;
        REALM) printf '%s' "Shared Kerberos Realm" ;;
        *) printf '%s' "${var_name}" ;;
    esac
}

ensure_required_values_resolved() {
    local context_label="${1:-run}"
    shift || true
    local var_name current_value prompt_default prompt_label
    local secret_flag=0
    local prompted_any=0
    local forced_interactive=0
    local saved_noninteractive="${NONINTERACTIVE:-0}"
    local forced_tty_input=0
    local saved_stdin_fd=9
    local -a missing_vars=()

    for var_name in "$@"; do
        current_value="${!var_name:-}"
        if [ -z "$current_value" ] || is_unresolved_template_value "$current_value"; then
            missing_vars+=("$var_name")
        fi
    done

    if [ "${#missing_vars[@]}" -eq 0 ]; then
        return 0
    fi

    if is_noninteractive; then
        if [ -t 0 ] && [ -t 1 ]; then
            print_warning "NONINTERACTIVE mode is set, but an interactive terminal is available. Prompting for missing values."
            NONINTERACTIVE=0
            forced_interactive=1
        elif [ -t 1 ] && [ -r /dev/tty ]; then
            print_warning "NONINTERACTIVE mode is set and stdin is redirected; using /dev/tty for missing-value prompts."
            NONINTERACTIVE=0
            forced_interactive=1
            forced_tty_input=1
        else
            print_warning "Missing required value(s) for ${context_label}: ${missing_vars[*]}"
            print_warning "NONINTERACTIVE mode cannot pause for prompts; update ${ANSIBLE_ENV_FILE} and retry."
            return 1
        fi
    fi

    if [ "$forced_tty_input" -eq 1 ]; then
        exec {saved_stdin_fd}<&0
        exec < /dev/tty
    fi

    print_warning "Missing required value(s) for ${context_label}: ${missing_vars[*]}"
    print_step "Pausing to collect missing values and persist them to ${ANSIBLE_ENV_FILE}."

    for var_name in "${missing_vars[@]}"; do
        prompt_default="$(default_for_required_var "$var_name")"
        prompt_label="$(prompt_label_for_required_var "$var_name")"
        secret_flag=0
        if is_sensitive_env_var "$var_name"; then
            secret_flag=1
        fi
        prompt_with_default "$var_name" "$prompt_label" "$prompt_default" "$secret_flag" 1 || {
            if [ "$forced_tty_input" -eq 1 ]; then
                exec 0<&${saved_stdin_fd}
                exec {saved_stdin_fd}<&-
            fi
            [ "$forced_interactive" -eq 1 ] && NONINTERACTIVE="$saved_noninteractive"
            return 1
        }
        prompted_any=1
    done

    if [ "$prompted_any" -eq 1 ]; then
        normalize_shared_env_vars
        write_ansible_env_file || {
            if [ "$forced_tty_input" -eq 1 ]; then
                exec 0<&${saved_stdin_fd}
                exec {saved_stdin_fd}<&-
            fi
            [ "$forced_interactive" -eq 1 ] && NONINTERACTIVE="$saved_noninteractive"
            return 1
        }
        if [ "$forced_tty_input" -eq 1 ]; then
            exec 0<&${saved_stdin_fd}
            exec {saved_stdin_fd}<&-
        fi
        [ "$forced_interactive" -eq 1 ] && NONINTERACTIVE="$saved_noninteractive"
        trigger_post_prompt_autorerun
    fi

    for var_name in "$@"; do
        current_value="${!var_name:-}"
        if [ -z "$current_value" ] || is_unresolved_template_value "$current_value"; then
            print_warning "Required value still missing after prompt: ${var_name}"
            if [ "$forced_tty_input" -eq 1 ]; then
                exec 0<&${saved_stdin_fd}
                exec {saved_stdin_fd}<&-
            fi
            [ "$forced_interactive" -eq 1 ] && NONINTERACTIVE="$saved_noninteractive"
            return 1
        fi
    done

    if [ "$forced_tty_input" -eq 1 ]; then
        exec 0<&${saved_stdin_fd}
        exec {saved_stdin_fd}<&-
    fi

    if [ "$forced_interactive" -eq 1 ]; then
        NONINTERACTIVE="$saved_noninteractive"
    fi

    return 0
}

trigger_post_prompt_autorerun() {
    if ! is_enabled "${MRHIS_AUTORERUN_AFTER_PROMPT:-1}"; then
        return 0
    fi

    if [ "${MRHIS_AUTORERUN_DONE:-0}" = "1" ]; then
        return 0
    fi

    if ! [ -t 1 ] && ! [ -r /dev/tty ]; then
        return 0
    fi

    export MRHIS_AUTORERUN_DONE=1

    print_step "Prompted values were saved to ${ANSIBLE_ENV_FILE}; running DEMOKILL before automatic restart."
    demokill_cleanup || print_warning "DEMOKILL encountered issues during auto-rerun recovery; continuing with restart."

    print_step "Re-running original command after DEMOKILL: ${MRHIS_SELF_PATH} ${MRHIS_ORIGINAL_ARGS[*]:-}"
    exec "${MRHIS_SELF_PATH}" "${MRHIS_ORIGINAL_ARGS[@]}"
}

startup_env_precheck() {
    local scope="all"
    local -a required_vars=()

    if [ -n "${CLI_SATELLITE:-}" ] && [ -z "${CLI_AAP:-}${CLI_IDM:-}${CLI_MRHIS:-}" ]; then
        scope="satellite"
    elif [ -n "${CLI_AAP:-}" ] && [ -z "${CLI_SATELLITE:-}${CLI_IDM:-}${CLI_MRHIS:-}" ]; then
        scope="aap"
    elif [ -n "${CLI_IDM:-}" ] && [ -z "${CLI_SATELLITE:-}${CLI_AAP:-}${CLI_MRHIS:-}" ]; then
        scope="idm"
    fi

    case "${scope}" in
        satellite)
            required_vars=(
                ADMIN_USER AAP_ADMIN_PASS DOMAIN REALM
                INTERNAL_NETWORK SAT_IP SAT_NETMASK SAT_GW SAT_HOSTNAME SAT_ALIAS SAT_ORG SAT_LOC
                RH_USER RH_PASS RH9_ISO_URL
            )
            ;;
        aap)
            required_vars=(
                ADMIN_USER AAP_ADMIN_PASS DOMAIN REALM
                INTERNAL_NETWORK AAP_IP AAP_NETMASK AAP_GW AAP_HOSTNAME AAP_ALIAS
                RH_USER RH_PASS RH_ISO_URL
            )
            ;;
        idm)
            required_vars=(
                ADMIN_USER AAP_ADMIN_PASS DOMAIN REALM IDM_DS_PASS
                INTERNAL_NETWORK IDM_IP IDM_NETMASK IDM_GW IDM_HOSTNAME IDM_ALIAS
                RH_USER RH_PASS RH_ISO_URL
            )
            ;;
        all|*)
            required_vars=(
                ADMIN_USER AAP_ADMIN_PASS DOMAIN REALM INTERNAL_NETWORK
                SAT_IP AAP_IP IDM_IP
                SAT_NETMASK AAP_NETMASK IDM_NETMASK
                SAT_GW AAP_GW IDM_GW
                SAT_HOSTNAME AAP_HOSTNAME IDM_HOSTNAME
                SAT_ALIAS AAP_ALIAS IDM_ALIAS
                SAT_ORG SAT_LOC
                RH_USER RH_PASS RH_ISO_URL RH9_ISO_URL
            )
            ;;
    esac

    ensure_required_values_resolved "startup precheck (${scope})" "${required_vars[@]}" || return 1
    return 0
}

validate_resolved_kickstart_inputs() {
    local failed=0
    local var_name value
    local -a required_vars=(
        DOMAIN INTERNAL_NETWORK
        SAT_IP AAP_IP IDM_IP
        SAT_NETMASK AAP_NETMASK IDM_NETMASK
        SAT_GW AAP_GW IDM_GW
        SAT_HOSTNAME AAP_HOSTNAME IDM_HOSTNAME
        SAT_ORG SAT_LOC
        RH_USER RH_PASS RH_ISO_URL RH9_ISO_URL
        AAP_BUNDLE_URL RH_OFFLINE_TOKEN HUB_TOKEN
    )
    local -a effective_required_vars=()

    effective_required_vars=("${required_vars[@]}")
    if [ "${DEMO_MODE:-0}" = "1" ]; then
        effective_required_vars=()
        for var_name in "${required_vars[@]}"; do
            case "${var_name}" in
                AAP_BUNDLE_URL|RH_OFFLINE_TOKEN|HUB_TOKEN)
                    continue
                    ;;
            esac
            effective_required_vars+=("${var_name}")
        done
    fi

    ensure_required_values_resolved "kickstart generation" "${effective_required_vars[@]}" || failed=1

    for var_name in "${required_vars[@]}"; do
        value="${!var_name:-}"
        if [ "${DEMO_MODE:-0}" = "1" ]; then
            # Demo fast-path: treat placeholder values (example.com / EXAMPLE.COM)
            # as acceptable and skip bundle/token requirements which are not
            # necessary for local demo runs.
            case "${var_name}" in
                AAP_BUNDLE_URL|RH_OFFLINE_TOKEN|HUB_TOKEN)
                    continue
                    ;;
            esac
            if [ -z "$value" ]; then
                print_warning "Missing required value for demo: $var_name"
                failed=1
            fi
        else
            if [ -z "$value" ] || is_unresolved_template_value "$value"; then
                print_warning "Missing or unresolved required value: $var_name"
                failed=1
            fi
        fi
    done

    if [ "$failed" -ne 0 ]; then
        print_warning "Cannot generate kickstarts until required values are resolved."
        return 1
    fi

    return 0
}

ensure_kickstart_prereqs_ready() {
    local scope="${1:-all}"
    local missing=0
    local -a required_vars=()
    local -a effective_required_vars=()
    local _v _val

    if [ ! -s "$ANSIBLE_ENV_FILE" ]; then
        print_warning "Missing encrypted environment file: $ANSIBLE_ENV_FILE"
        print_warning "Please select option 4 before creating kickstarts."
        return 1
    fi

    if [ ! -s "$ANSIBLE_VAULT_PASS_FILE" ]; then
        print_warning "Missing vault password file: $ANSIBLE_VAULT_PASS_FILE"
        print_warning "Please select option 4 before creating kickstarts."
        return 1
    fi

    load_ansible_env_file || {
        print_warning "Could not load saved kickstart configuration from $ANSIBLE_ENV_FILE"
        print_warning "Please select option 4 before creating kickstarts."
        return 1
    }
    normalize_shared_env_vars

    case "$scope" in
        satellite)
            required_vars=(
                RH_USER RH_PASS ADMIN_USER ADMIN_PASS
                SAT_IP SAT_NETMASK SAT_GW SAT_HOSTNAME SAT_ALIAS SAT_DOMAIN SAT_ORG SAT_LOC
                CDN_ORGANIZATION_ID CDN_SAT_ACTIVATION_KEY RH9_ISO_URL
            )
            ;;
        aap)
            required_vars=(
                RH_USER RH_PASS ADMIN_USER ADMIN_PASS
                AAP_IP AAP_NETMASK AAP_GW AAP_HOSTNAME AAP_ALIAS
                HUB_TOKEN HOST_INT_IP AAP_BUNDLE_URL RH_ISO_URL
                AAP_INVENTORY_TEMPLATE AAP_INVENTORY_GROWTH_TEMPLATE
            )
            ;;
        idm)
            required_vars=(
                RH_USER RH_PASS ADMIN_PASS DOMAIN
                IDM_IP IDM_NETMASK IDM_GW IDM_HOSTNAME IDM_ALIAS IDM_DS_PASS
                RH_ISO_URL
            )
            ;;
        all|*)
            required_vars=(
                RH_USER RH_PASS ADMIN_USER ADMIN_PASS DOMAIN
                SAT_IP SAT_NETMASK SAT_GW SAT_HOSTNAME SAT_ALIAS SAT_DOMAIN SAT_ORG SAT_LOC
                AAP_IP AAP_NETMASK AAP_GW AAP_HOSTNAME AAP_ALIAS AAP_BUNDLE_URL HUB_TOKEN HOST_INT_IP AAP_INVENTORY_TEMPLATE AAP_INVENTORY_GROWTH_TEMPLATE
                IDM_IP IDM_NETMASK IDM_GW IDM_HOSTNAME IDM_ALIAS IDM_DS_PASS
                CDN_ORGANIZATION_ID CDN_SAT_ACTIVATION_KEY
                RH_ISO_URL RH9_ISO_URL
            )
            ;;
    esac

    effective_required_vars=("${required_vars[@]}")
    if [ "${DEMO_MODE:-0}" = "1" ]; then
        effective_required_vars=()
        for _v in "${required_vars[@]}"; do
            case "${_v}" in
                AAP_BUNDLE_URL|HUB_TOKEN|RH_OFFLINE_TOKEN|CDN_ORGANIZATION_ID|CDN_SAT_ACTIVATION_KEY)
                    continue
                    ;;
                DOMAIN|REALM)
                    _val="${!_v:-}"
                    if [ -n "${_val}" ] && ! is_unresolved_template_value "${_val}"; then
                        continue
                    fi
                    ;;
            esac
            effective_required_vars+=("${_v}")
        done
    fi

    ensure_required_values_resolved "kickstart prereqs (${scope})" "${effective_required_vars[@]}" || return 1

    missing="$(count_missing_vars "${required_vars[@]}")"
    # For demo fast-paths, relax heavy external requirements (bundle/tokens/CDN)
    # and accept placeholder DOMAIN/REALM values (example.com / EXAMPLE.COM).
    if [ "${DEMO_MODE:-0}" = "1" ]; then
        local -a _effective_required=()
        local _v _val
        for _v in "${required_vars[@]}"; do
            case "${_v}" in
                AAP_BUNDLE_URL|HUB_TOKEN|RH_OFFLINE_TOKEN|CDN_ORGANIZATION_ID|CDN_SAT_ACTIVATION_KEY)
                    # Skip external dependencies for demo runs
                    continue
                    ;;
                DOMAIN|REALM)
                    # Only require DOMAIN/REALM when truly empty; placeholder
                    # values like "example.com" are acceptable in demo mode.
                    _val="${!_v:-}"
                    if [ -z "${_val}" ]; then
                        _effective_required+=("${_v}")
                    fi
                    ;;
                *)
                    _effective_required+=("${_v}")
                    ;;
            esac
        done

        missing=0
        local -a _missing_vars=()
        for _v in "${_effective_required[@]}"; do
            _val="${!_v:-}"
            if [ -z "${_val}" ] || is_unresolved_template_value "${_val}"; then
                missing=$((missing + 1))
                _missing_vars+=("${_v}")
            fi
        done

        if [ "${missing}" -ne 0 ]; then
            print_warning "Saved kickstart configuration is incomplete for '${scope}' (${missing} required value(s) missing)."
            print_warning "Missing vars: ${_missing_vars[*]}"
            print_warning "Please select option 4 before creating kickstarts."
            return 1
        fi
    else
        missing="$(count_missing_vars "${required_vars[@]}")"
        if [ "${missing}" -ne 0 ]; then
            print_warning "Saved kickstart configuration is incomplete for '${scope}' (${missing} required value(s) missing)."
            print_warning "Please select option 4 before creating kickstarts."
            return 1
        fi
    fi

    # Ensure the persistent installer SSH key exists so kickstarts can embed it.
    if ! ensure_mrhis_installer_ssh_key; then
        print_error "Failed to create or access MRHIS installer SSH key: ${MRHIS_INSTALLER_SSH_PRIVATE_KEY}"
        return 1
    fi

    return 0
}

# Menu selection
print_mrhis_header() {
    echo ""
    echo "=============================================================="
    echo "                         MRHIS"
    echo "        Red Hat Infrastructure Standard Orchestrator"
    echo "=============================================================="
}

show_menu() {
    if [ -n "${MENU_CHOICE:-}" ]; then
        choice="$MENU_CHOICE"
        if ! is_noninteractive; then
            print_step "Using preseeded menu choice: $choice"
        fi
        MENU_CHOICE_CONSUMED=1
        if ! is_noninteractive && [ "${RUN_ONCE:-0}" != "1" ]; then
            MENU_CHOICE=""
        fi
        return 0
    fi

    print_mrhis_header
    echo "Deployment Scope : ${DEPLOYMENT_SCOPE:-local}"
    echo "Workspace        : ${SCRIPT_DIR}"
    echo "Container Roles  : ${SCRIPT_DIR}/local/roles"
    echo ""
    echo "Main Menu - choose an action"
    echo "  1) Platform Selection"
    echo "  2) Configure Installer"
    echo "  3) Full Stack Build"
    echo "  4) Install Individual System Components"
    echo "  5) Configure Only Individual System Components"
    echo "  6) Build ~/.ansible/conf/env.yml (Prompts Only)"
    echo "  7) Generate Kickstarts / OEMDRV"
    echo "  8) Documentation"
    echo "  9) Report"
    echo "  0) Exit"
    echo ""
    read -r -p "Enter choice [0-9]: " choice
}


show_documentation_menu() {
    # Enumerate README* and CHECKLIST* files in repo root and docs/ and present a numeric menu
    local docs_root
    local -a docs_files=()
    local idx file_count sel file

    docs_root="${SCRIPT_DIR}"

    # Collect files from root and docs/ (case-insensitive)
    while IFS= read -r -d $'\0' f; do
        docs_files+=("${f}")
    done < <(find "${docs_root}" -maxdepth 1 -type f \( -iname 'README*' -o -iname 'CHECKLIST*' \) -print0 2>/dev/null || true)

    if [ -d "${docs_root}/docs" ]; then
        while IFS= read -r -d $'\0' f; do
            docs_files+=("${f}")
        done < <(find "${docs_root}/docs" -maxdepth 2 -type f \( -iname 'README*' -o -iname 'CHECKLIST*' \) -print0 2>/dev/null || true)
    fi

    if [ "${#docs_files[@]}" -eq 0 ]; then
        print_step "No README or CHECKLIST files found in ${docs_root} or ${docs_root}/docs"
        return 0
    fi

    # Interactive loop: allow viewing multiple docs without immediately returning
    while true; do
        print_mrhis_header
        echo "Documentation"
        echo "Select a document to view (0 = back)"
        echo ""
        idx=1
        for file in "${docs_files[@]}"; do
            printf '  %2d) %s\n' "${idx}" "${file#${docs_root}/}"
            idx=$((idx + 1))
        done
        echo "  0) Back"
        echo ""

        if is_noninteractive; then
            print_step "Non-interactive mode: listing documentation files only."
            return 0
        fi

        read -r -p "Choose document [0-${#docs_files[@]}]: " sel
        case "${sel}" in
            0|"" ) return 0 ;;
            *)
                if ! [[ "${sel}" =~ ^[0-9]+$ ]]; then
                    print_warning "Invalid selection"
                    continue
                fi
                if [ "${sel}" -lt 1 ] || [ "${sel}" -gt "${#docs_files[@]}" ]; then
                    print_warning "Selection out of range"
                    continue
                fi
                file="${docs_files[$((sel-1))]}"
                if [ -f "${file}" ]; then
                    print_step "Displaying: ${file}"
                    if [ -n "${PAGER:-}" ] && command -v "${PAGER}" >/dev/null 2>&1; then
                        "${PAGER}" "${file}"
                    elif command -v less >/dev/null 2>&1; then
                        less -R "${file}"
                    else
                        sed -n '1,200p' "${file}" || cat "${file}"
                    fi
                    echo ""
                    read -r -p "Press Enter to return to the documentation list..." _dummy
                    continue
                else
                    print_warning "File not found: ${file}"
                    continue
                fi
                ;;
        esac
    done
}

select_stack_sizing_profile() {
    local _size_choice=""

    if is_noninteractive; then
        print_step "NONINTERACTIVE mode: keeping DEMO_MODE=${DEMO_MODE:-0} (0=SOE, 1=Demo)."
        return 0
    fi

    if is_demo; then
        DEMO_MODE="1"
        print_step "DEMO mode requested: auto-selecting Demo/Education/PoC sizing (option 2)."
        return 0
    fi

    print_mrhis_header
    echo "Sizing Profile"
    echo "  MRHIS Full Stack sizing profile"
    echo ""
    echo "  1) SOE"
    echo "     - supported enterprise sizing"
    echo "  2) Demo / Education / PoC"
    echo "     - reduced hardware per node (IdM + Satellite + AAP remain separate servers)"
    echo ""
    read -r -p "Choose profile [1-2, default 1]: " _size_choice

    case "${_size_choice:-1}" in
        2)
            DEMO_MODE="1"
            print_step "Sizing profile set to Demo/Education/PoC (DEMO_MODE=1)."
            ;;
        *)
            DEMO_MODE="0"
            print_step "Sizing profile set to SOE (DEMO_MODE=0)."
            ;;
    esac
    return 0
}

configure_platform_selection() {
    local selected=""

    prompt_platform_choice selected "Select target platform for MRHIS deployments" "${MRHIS_TARGET_PLATFORM:-libvirt}" || return 1
    MRHIS_TARGET_PLATFORM="${selected}"
    SAT_TARGET_PLATFORM="${selected}"
    AAP_TARGET_PLATFORM="${selected}"
    IDM_TARGET_PLATFORM="${selected}"
    MRHIS_PLATFORM_FAMILY="$(platform_family_for_provider "${selected}")"

