# Install individual components submenu (single selection)
show_install_components_submenu() {
    local _subchoice=""

    # Fast-path: if a component install was requested via CLI flags,
    # perform it immediately without rendering the interactive submenu.
    if [ -n "${RUN_INSTALL_COMPONENT_NAME:-}" ]; then
        case "${RUN_INSTALL_COMPONENT_NAME}" in
            idm)
                if is_menutest; then print_step "MENUTEST: simulated IdM-only install"; return 0; fi
                install_idm_only || { print_warning "IdM-only workflow failed"; return 1; }
                return 0
                ;;
            satellite)
                if is_menutest; then print_step "MENUTEST: simulated Satellite-only install"; return 0; fi
                install_satellite_only || { print_warning "Satellite-only workflow failed"; return 1; }
                return 0
                ;;
            aap)
                if is_menutest; then print_step "MENUTEST: simulated AAP-only install"; return 0; fi
                install_aap_only || { print_warning "AAP-only workflow failed"; return 1; }
                return 0
                ;;
            gittea)
                if is_menutest; then print_step "MENUTEST: simulated Gitea-only install"; return 0; fi
                install_gittea_only || { print_warning "Gitea-only workflow failed"; return 1; }
                return 0
                ;;
            openshift)
                if is_menutest; then print_step "MENUTEST: simulated OpenShift-only install"; return 0; fi
                if [ -n "${CLI_OPENSHIFT_VIRT:-}" ]; then
                    install_openshift_virt_only || { print_warning "OpenShift Virtualization workflow failed"; return 1; }
                else
                    install_openshift_only || { print_warning "OpenShift-target workflow failed"; return 1; }
                fi
                return 0
                ;;
            *)
                print_warning "Unknown install target requested: ${RUN_INSTALL_COMPONENT_NAME}"
