                    *) print_warning "Invalid choice. Please select 0-2." ;;
                esac
                ;;
            0|"")
                return 0
                ;;
            *) print_warning "Invalid choice. Please select 0-5." ;;
        esac
    done
}

# Configure-only scopes: accept comma-separated list and run config-as-code per scope.
# Mirrors CLI --config-* scope behavior.
show_configure_components_csv_menu() {
    local comps raw comps_array comp
    reset_menu_view
    print_mrhis_header
    echo "Configure Only (CLI Scope Equivalent)"
    echo "Enter comma-separated scopes (e.g. idm,satellite,aap or rhis)"
    echo "  Supported:"
    echo "    idm, satellite, aap, gittea, openshift, openstack"
    echo "    rhis, fullstack, rhis-aap, all"
    echo "  Aliases: openstack -> openshift, all -> rhis"
    echo "  0) Back"
    echo ""
    read -r -p "Components (comma-separated, blank to cancel): " raw
    if [ -z "${raw// /}" ]; then
        return 0
    fi
    if is_menutest; then
        print_step "MENUTEST: simulated configure-only for: ${raw}"
        return 0
    fi
    # Split and iterate
    IFS=',' read -r -a comps_array <<< "${raw}"
    for comp in "${comps_array[@]}"; do
        # trim whitespace
        comp="$(printf '%s' "${comp}" | sed -E 's/^[[:space:]]+|[[:space:]]+$//g' | tr '[:upper:]' '[:lower:]')"
        case "${comp}" in
            idm)
                run_component_config_scope idm || { print_warning "IdM configure-only failed"; return 1; }
                ;;
            satellite)
                run_component_config_scope satellite || { print_warning "Satellite configure-only failed"; return 1; }
                ;;
            aap)
                run_component_config_scope aap || { print_warning "AAP configure-only failed"; return 1; }
                ;;
            gittea)
                run_component_config_scope gittea || { print_warning "Gitea configure-only failed"; return 1; }
                ;;
            openshift|openstack)
                print_warning "OpenShift configure-only is experimental; attempting config-as-code"
                run_component_config_scope "${comp}" || { print_warning "OpenShift configure-only failed or not implemented"; return 1; }
                ;;
            rhis-aap)
                run_component_config_scope rhis-aap || { print_warning "RHIS AAP-only configure workflow failed"; return 1; }
                ;;
            rhis)
                MRHIS_COMPONENT_SCOPE="rhis" run_mrhis_config_as_code || { print_warning "RHIS configure-only failed"; return 1; }
                ;;
            fullstack)
                MRHIS_COMPONENT_SCOPE="fullstack" run_mrhis_config_as_code || { print_warning "Fullstack configure-only failed"; return 1; }
                ;;
            all)
                MRHIS_COMPONENT_SCOPE="rhis" run_mrhis_config_as_code || { print_warning "All configure-only failed"; return 1; }
                ;;
            *)
                print_warning "Unknown component: ${comp}. Skipping."
                ;;
        esac
    done
    print_success "Requested configure-only components complete"
    return 0
}

# Documentation topics submenu (curated)
show_documentation_topics_menu() {
    local _doc_choice=""
    while true; do
        reset_menu_view
        print_mrhis_header
        echo "Documentation"
        echo "  1) RHIS"
        echo "  2) IdM"
        echo "  3) Satellite"
        echo "  4) AAP"
        echo "  5) Gitea"
        echo "  6) OpenShift"
        echo ""
        echo "  0) Back"
        echo ""
        read -r -p "Select topic [0-6]: " _doc_choice
        case "${_doc_choice}" in
            0|"") return 0 ;;
            1) doc_filter="rhis" ;;
            2) doc_filter="idm" ;;
            3) doc_filter="satellite" ;;
            4) doc_filter="aap" ;;
            5) doc_filter="gitea" ;;
            6) doc_filter="openshift" ;;
            *) print_warning "Invalid choice. Please select 0-6."; continue ;;
        esac

        # Find docs for topic and present a quick viewer
        local docs_root="${SCRIPT_DIR}"
        local -a docs_files=()
        while IFS= read -r -d $'\0' f; do docs_files+=("${f}"); done < <(find "${docs_root}" -type f -iname "*${doc_filter}*.md" -o -iname "*${doc_filter}*.MD" -print0 2>/dev/null || true)
        if [ "${#docs_files[@]}" -eq 0 ]; then
            print_step "No documentation files found for topic: ${doc_filter}"
            read -r -p "Press Enter to continue..." _dummy
            continue
        fi

        # Present results similar to show_documentation_menu
        local idx sel file
        while true; do
            reset_menu_view
            print_mrhis_header
            echo "Documentation: ${doc_filter}"
            echo "Select a document to view (0 = back)"
            echo ""
            idx=1
            for file in "${docs_files[@]}"; do
                printf '  %2d) %s\n' "${idx}" "${file#${docs_root}/}"
                idx=$((idx + 1))
            done
            echo "  0) Back"
            echo ""
            read -r -p "Choose document [0-${#docs_files[@]}]: " sel
            case "${sel}" in
                0|"") break ;;
                *)
                    if ! [[ "${sel}" =~ ^[0-9]+$ ]]; then print_warning "Invalid selection"; continue; fi
                    if [ "${sel}" -lt 1 ] || [ "${sel}" -gt "${#docs_files[@]}" ]; then print_warning "Selection out of range"; continue; fi
                    file="${docs_files[$((sel-1))]}"
                    if [ -f "${file}" ]; then
                        if [ -n "${PAGER:-}" ] && command -v "${PAGER}" >/dev/null 2>&1; then
                            "${PAGER}" "${file}"
                        elif command -v less >/dev/null 2>&1; then
                            less -R "${file}"
                        else
                            sed -n '1,200p' "${file}" || cat "${file}"
                        fi
                        read -r -p "Press Enter to return to the topic list..." _dummy
                    else
                        print_warning "File not found: ${file}"
                    fi
                    ;;
            esac
        done
    done
}

