    esac

    return 0
}

show_entry_menu() {
    local entry_choice=""

    while true; do
        echo "  1) Setup and Install Wizard"
        echo "  2) Primary Menu"
        echo ""
        echo "  0) Exit"
        echo ""
        read -r -p "  Choice [1-2, or 0 to exit]: " entry_choice
        case "${entry_choice}" in
            1) return 0 ;;
            2) run_menutest_mode; exit $? ;;
            0)
                command -v clear >/dev/null 2>&1 && clear
                echo "Exiting installation script"
                MRHIS_EXITED_VIA_MENU=1
                exit 0
                ;;
            *)
                print_warning "Invalid choice. Please select 1, 2, or 0."
                ;;
        esac
    done
}

run_menutest_mode() {
    local choice=""

    print_step "MENUTEST mode enabled: menu walkthrough only, no provisioning/actions will run."
    print_step "Use normal interactive menus; all action options are simulated."

    while true; do
        reset_menu_view
        show_menu
        case "$choice" in
            1)
                show_platform_selection_submenu || { print_warning "Platform selection failed"; return 1; }
                print_step "MENUTEST: simulated platform selection (no changes made)."
                ;;
            2)
                configure_installer_rhel10_fedora || { print_warning "Installer configuration simulation failed"; return 1; }
                ;;
            3)
                select_stack_sizing_profile || { print_warning "Could not determine sizing profile"; return 1; }
                print_step "MENUTEST: simulated Full Stack Build + Configure (no changes made)."
                ;;
            4)
                show_install_components_submenu || { print_warning "Install components submenu failed"; return 1; }
                ;;
            5)
                print_step "MENUTEST: simulated Configure-only components (no changes made)."
                ;;
            6)
                print_step "MENUTEST: simulated Prompts Only workflow (no changes made)."
                ;;
            7)
                generate_oemdrv_kickstarts_only_menutest
                ;;
            8)
                show_documentation_topics_menu || { print_warning "Documentation submenu failed"; return 1; }
                ;;
            9)
                print_step "MENUTEST: simulated Report (no changes made)."
                ;;
            0)
                command -v clear >/dev/null 2>&1 && clear
                echo "Exiting menu test mode"
                MRHIS_EXITED_VIA_MENU=1
                return 0
                ;;
            *)
                print_warning "Invalid choice. Please select 0-9."
                ;;
        esac
        reset_menu_view
        echo ""
    done
}

