    local container_name="${MRHIS_CONTAINER_NAME:-mrhis-provisioner}"
    local container_state="stopped"
    local container_status_line=""
    command -v clear >/dev/null 2>&1 && clear

    # Phase badge inference (best-effort)
    echo "============================================================"
    echo " MRHIS Live Status Dashboard"
    echo " Phase: ${phase_label:-unknown}"
    echo "============================================================"
    echo ""
    while true; do

        echo "[VM states]"
        sudo -n virsh list --all 2>/dev/null || sudo virsh list --all 2>/dev/null || true
        echo ""

        echo "[VM network addresses]"
        for vm in satellite aap idm; do
            echo "- ${vm}"
            sudo -n virsh domifaddr "${vm}" 2>/dev/null | sed '1,2d' || sudo virsh domifaddr "${vm}" 2>/dev/null | sed '1,2d' || true
        done
        echo ""

        echo "[Script / provisioning activity]"
        pgrep -af "run_mrhis_install_sequence.sh|python3 -m http.server 8080|ansible-playbook|virsh console|podman exec" 2>/dev/null || echo "(no matching activity processes found)"
        echo ""

        echo "[Container status]"
        echo "- Container workflows removed; no container status is available."
        echo ""

        echo "[Ansible provisioner log]"
        echo "- Log file: ${ansible_log_host}"
        if [ -f "${ansible_log_host}" ]; then
            tail -n 12 "${ansible_log_host}" 2>/dev/null || true
        else
            echo "(log file not created yet)"
        fi
        echo ""

        echo "[AAP bundle HTTP log]"
        echo "- Log file: ${AAP_HTTP_LOG}"
        if [ -f "${AAP_HTTP_LOG}" ]; then
            tail -n 8 "${AAP_HTTP_LOG}" 2>/dev/null || true
        else
            echo "(log file not created yet)"
        fi
        echo ""

        echo "[AAP callback logs]"
        ls -lt /tmp/aap-setup-*.log 2>/dev/null | head -5 || echo "(no AAP callback log yet)"
        echo ""

        sat_ip="${SAT_IP:-}"
        if [ -z "$sat_ip" ]; then
            sat_ip="$(sudo -n virsh domifaddr satellite 2>/dev/null | awk '/ipv4/ {print $4}' | cut -d/ -f1 | awk '$1 ~ /^10\.168\./ {print; exit}' || true)"
        fi
        if [ -z "$sat_ip" ]; then
            sat_ip="$(sudo -n virsh domifaddr satellite 2>/dev/null | awk '/ipv4/ {print $4}' | cut -d/ -f1 | head -1 || true)"
        fi
        cmdb_ip="${CMDB_ENDPOINT_IP:-${sat_ip}}"
        if [ -n "$cmdb_ip" ]; then
            if timeout 2 bash -lc "cat < /dev/tcp/${cmdb_ip}/18080" >/dev/null 2>&1; then
                cmdb_status="OPEN"
            else
                cmdb_status="CLOSED"
            fi
            echo "[Satellite CMDB dashboard]"
            echo "- URL: http://${cmdb_ip}:18080/"
            echo "- Port 18080: ${cmdb_status}"
        else
            echo "[Satellite CMDB dashboard]"
            echo "- CMDB endpoint IP not detected yet"
        fi
        echo ""

        if is_enabled "${MRHIS_DASHBOARD_SINGLE_SHOT:-0}"; then
            return 0
        fi

        echo "Press [q] to return to menu. Auto-refresh every ${refresh_seconds}s..."
        read -r -t "${refresh_seconds}" -n 1 key || true
        case "${key}" in
            q|Q)
                echo ""
                return 0
                ;;
        esac
    done
}

reattach_vm_consoles() {
    print_step "Reattaching VM console monitors for Satellite/AAP/IdM"
    launch_vm_console_monitors_auto || {
        print_warning "Could not reattach VM console monitors automatically."
        return 1
    }

    if ! has_gui_desktop_session; then
        print_step "Headless session detected; console monitors were not opened."
        print_headless_monitor_summary
    fi

    print_success "VM console monitors reattached."
    return 0
}

get_vm_console_label() {
    case "$1" in
        satellite) printf '%s\n' "${SAT_HOSTNAME:-satellite}" ;;
        aap)        printf '%s\n' "${AAP_HOSTNAME:-aap}" ;;
        idm)           printf '%s\n' "${IDM_HOSTNAME:-idm}" ;;
        *)             printf '%s\n' "$1" ;;
    esac
}

has_gui_desktop_session() {
    [ -n "${DISPLAY:-}" ] || [ -n "${WAYLAND_DISPLAY:-}" ]
}

launch_gui_monitor_terminal() {
    local title="$1"
    local monitor_cmd="$2"
    local pid_file="$3"
    local term_pid=""

    [ -n "${title:-}" ] || return 1
    [ -n "${monitor_cmd:-}" ] || return 1
    has_gui_desktop_session || return 1

    if command -v konsole >/dev/null 2>&1; then
        konsole --title "${title}" -e bash -lc "${monitor_cmd}" >/dev/null 2>&1 &
        term_pid=$!
    elif command -v gnome-terminal >/dev/null 2>&1; then
        gnome-terminal --title="${title}" -- bash -lc "${monitor_cmd}" >/dev/null 2>&1 &
        term_pid=$!
    elif command -v x-terminal-emulator >/dev/null 2>&1; then
        x-terminal-emulator -e bash -lc "${monitor_cmd}" >/dev/null 2>&1 &
        term_pid=$!
    elif command -v xterm >/dev/null 2>&1; then
        xterm -T "${title}" -e bash -lc "${monitor_cmd}" >/dev/null 2>&1 &
        term_pid=$!
    else
        return 1
    fi

    if [ -n "${pid_file:-}" ] && [ -n "${term_pid:-}" ]; then
        echo "${term_pid}" >> "${pid_file}"
    fi

    return 0
}

stop_progress_monitors() {
    local pid

    if [ -f "${MRHIS_PROGRESS_MONITOR_PID_FILE}" ]; then
        while IFS= read -r pid; do
            [ -n "$pid" ] || continue
            kill "$pid" >/dev/null 2>&1 || true
            kill -9 "$pid" >/dev/null 2>&1 || true
        done < "${MRHIS_PROGRESS_MONITOR_PID_FILE}"
        rm -f "${MRHIS_PROGRESS_MONITOR_PID_FILE}"
    fi

    return 0
}

launch_progress_dashboard_auto() {
    local dashboard_cmd=""

    is_enabled "${MRHIS_AUTO_POPUP_MONITORS:-1}" || return 0

    stop_progress_monitors >/dev/null 2>&1 || true
    : > "${MRHIS_PROGRESS_MONITOR_PID_FILE:-/dev/null}"

    dashboard_cmd="printf '\033]0;%s\007' 'MRHIS Progress'; cd '${SCRIPT_DIR}'; exec bash '${SCRIPT_DIR}/MRHIS.sh' --status-live"

    if launch_gui_monitor_terminal "MRHIS Progress" "${dashboard_cmd}" "${MRHIS_PROGRESS_MONITOR_PID_FILE}"; then
        print_step "Opened progress monitor terminal for MRHIS status/logs."
        return 0
    fi

    if ! has_gui_desktop_session; then
        print_headless_monitor_summary
        return 0
    fi

    print_warning "No GUI terminal emulator found; skipping progress monitor launch."
    return 0
}

ensure_live_progress_monitors() {
    is_enabled "${MRHIS_AUTO_POPUP_MONITORS:-1}" || return 0
    launch_progress_dashboard_auto || true
    reattach_vm_consoles || true
    return 0
}

print_headless_monitor_summary() {
    if is_enabled "${MRHIS_HEADLESS_MONITOR_HINT_SHOWN:-0}"; then
        return 0
    fi

    MRHIS_HEADLESS_MONITOR_HINT_SHOWN=1

    echo ""
    echo "[HEADLESS] Monitor progress with these commands:"
    echo "  sudo virsh console satellite"
    echo "  sudo virsh console aap"
    echo "  sudo virsh console idm"
    echo "  tail -f ${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}"
    echo "  bash ${SCRIPT_DIR}/MRHIS.sh --status"
    echo ""
    echo "[HEADLESS] Notes:"
    echo "  - virsh console shows guest boot, reboot, and kickstart %post output."
    echo "  - ansible-provisioner.log shows callback/configuration progress after the guests are reachable."
    echo "  - Use Ctrl+] to detach from a virsh console without stopping the VM."
    echo ""
    return 0
}

console_attach_cmd_for_vm() {
    local vm="$1"
    if is_enabled "${MRHIS_VM_MONITOR_FILTER_NOISE:-1}"; then
        cat <<EOF
sudo virsh console ${vm} 2>&1 | stdbuf -oL awk '/systemd-rc-local-generator.*\/etc\/rc\\.d\/rc\\.local is not marked executable, skipping\\./{n++;next} /SELinux:  Converting [0-9]+ SID table entries\\.\\.\\./{n++;next} /SELinux:  policy capability /{n++;next} /systemd-journald\\[[0-9]+\\]: Received SIGTERM from PID 1 \\(systemd\\)\\./{n++;next} {print} END{if(n>0) printf("[monitor] filtered %d expected reboot-noise lines\\n", n) > "/dev/stderr"}'; true
EOF
    else
        printf 'sudo virsh console %s || true\n' "${vm}"
    fi
}

launch_single_vm_console_monitor_auto() {
    local vm="$1"
    local vm_label
    local launched=0
    local monitor_cmd
    local console_attach_cmd

    [ -n "${vm:-}" ] || return 1
    vm_label="$(get_vm_console_label "${vm}")"
    console_attach_cmd="$(console_attach_cmd_for_vm "${vm}")"
    monitor_cmd="printf '\033]0;%s\007' '${vm_label}'; echo '[${vm_label}] monitor active (auto-reconnect enabled)'; while true; do while ! sudo virsh domstate ${vm} 2>/dev/null | grep -E 'running|inshutdown|paused|blocked' >/dev/null; do sleep 5; done; echo '[${vm_label}] connecting virsh console (Ctrl+] to detach)'; ${console_attach_cmd}; echo '[${vm_label}] console disconnected (reboot/install transition); retrying in 5s...'; sleep 5; done"

    if ! command -v virsh >/dev/null 2>&1; then
        print_warning "virsh not found; skipping VM console monitor auto-launch."
        return 0
    fi

    if has_gui_desktop_session; then
        if launch_gui_monitor_terminal "${vm_label}" "${monitor_cmd}" "${MRHIS_VM_MONITOR_PID_FILE}"; then
            launched=1
        fi
    fi

    if [ "$launched" = "1" ]; then
        print_step "Opened console monitor terminal for ${vm_label}."
        return 0
    fi

    if ! has_gui_desktop_session; then
        print_step "Headless session detected; skipping auto console monitor launch for ${vm_label}."
        print_headless_monitor_summary
        return 0
    fi

    print_warning "No GUI terminal emulator found; skipping auto console monitor launch."
    return 0
}

launch_vm_console_monitors_auto() {
    local -a vms=("satellite" "aap" "idm")
    if [ -n "${CLI_GITTEA:-}" ] || [ -n "${GITTEA_HOSTNAME:-}" ] || [ -n "${GITTEA_IP:-}" ]; then
        vms+=("gittea")
    fi
    if [ -n "${CLI_OPENSHIFT:-}" ] || [ -n "${OPENSHIFT_HOSTNAME:-}" ] || [ -n "${OPENSHIFT_IP:-}" ]; then
        vms+=("openshift")
    fi
    local vm vm_label launched=0
    local monitor_cmd
    local console_attach_cmd

    stop_vm_console_monitors >/dev/null 2>&1 || true
    : > "${MRHIS_VM_MONITOR_PID_FILE:-/dev/null}"

    if ! command -v virsh >/dev/null 2>&1; then
        print_warning "virsh not found; skipping VM console monitor auto-launch."
        return 0
    fi

    # GUI terminal popups (preferred)
    if has_gui_desktop_session; then
        for vm in "${vms[@]}"; do
            vm_label="$(get_vm_console_label "${vm}")"
            console_attach_cmd="$(console_attach_cmd_for_vm "${vm}")"
            monitor_cmd="printf '\033]0;%s\007' '${vm_label}'; echo '[${vm_label}] monitor active (auto-reconnect enabled)'; while true; do while ! sudo virsh domstate ${vm} 2>/dev/null | grep -E 'running|inshutdown|paused|blocked' >/dev/null; do sleep 5; done; echo '[${vm_label}] connecting virsh console (Ctrl+] to detach)'; ${console_attach_cmd}; echo '[${vm_label}] console disconnected (reboot/install transition); retrying in 5s...'; sleep 5; done"
            if launch_gui_monitor_terminal "${vm_label}" "${monitor_cmd}" "${MRHIS_VM_MONITOR_PID_FILE}"; then
                launched=1
            fi
        done
    fi

    if [ "$launched" = "1" ]; then
        print_step "Opened console monitor terminals."
        return 0
    fi

    if ! has_gui_desktop_session; then
        print_step "Headless session detected; skipping auto console monitor launch."
        print_headless_monitor_summary
        return 0
    fi

    print_warning "No GUI terminal emulator found; skipping auto console monitor launch."
    return 0
}

stop_vm_console_monitors() {
    local pid

    if command -v tmux >/dev/null 2>&1; then
        tmux has-session -t "$MRHIS_VM_MONITOR_SESSION" 2>/dev/null && tmux kill-session -t "$MRHIS_VM_MONITOR_SESSION" || true
    fi

    if [ -f "$MRHIS_VM_MONITOR_PID_FILE" ]; then
        while IFS= read -r pid; do
            [ -n "$pid" ] || continue
            kill "$pid" >/dev/null 2>&1 || true
            kill -9 "$pid" >/dev/null 2>&1 || true
        done < "$MRHIS_VM_MONITOR_PID_FILE"
        rm -f "$MRHIS_VM_MONITOR_PID_FILE"
    fi

    return 0
}

start_vm_power_watchdog() {
    local duration_sec="${1:-10800}"  # default: 3 hours
    local interval_sec=15

    stop_vm_power_watchdog >/dev/null 2>&1 || true

    (
        local end_ts now state vm
        local -a vms=("satellite" "aap" "idm")
        if [ -n "${CLI_GITTEA:-}" ] || [ -n "${GITTEA_HOSTNAME:-}" ] || [ -n "${GITTEA_IP:-}" ]; then
            vms+=("gittea")
        fi
        if [ -n "${CLI_OPENSHIFT:-}" ] || [ -n "${OPENSHIFT_HOSTNAME:-}" ] || [ -n "${OPENSHIFT_IP:-}" ]; then
            vms+=("openshift")
        fi

        end_ts=$(( $(date +%s) + duration_sec ))
        while true; do
            now="$(date +%s)"
            [ "$now" -lt "$end_ts" ] || break

            for vm in "${vms[@]}"; do
                if ! sudo virsh dominfo "$vm" >/dev/null 2>&1; then
                    continue
                fi

                sudo virsh autostart "$vm" >/dev/null 2>&1 || true
                state="$(sudo virsh domstate "$vm" 2>/dev/null | tr -d '[:space:]' || true)"
                case "$state" in
                    running|inshutdown|paused|blocked)
                        ;;
                    shutoff|crashed|pmsuspended)
                        sudo virsh start "$vm" >/dev/null 2>&1 || true
                        ;;
                esac
            done

            sleep "$interval_sec"
        done
    ) >/dev/null 2>&1 &

    MRHIS_VM_WATCHDOG_PID="$!"
    print_step "Started VM power watchdog (PID ${MRHIS_VM_WATCHDOG_PID}) to keep Satellite/AAP/IdM ON"
    return 0
}

stop_vm_power_watchdog() {
    if [ -n "${MRHIS_VM_WATCHDOG_PID:-}" ]; then
        kill "${MRHIS_VM_WATCHDOG_PID}" >/dev/null 2>&1 || true
        wait "${MRHIS_VM_WATCHDOG_PID}" >/dev/null 2>&1 || true
        MRHIS_VM_WATCHDOG_PID=""
    fi
    return 0
}

force_kill_mrhis_leftovers() {
    local -a patterns=(
        "python3 -m http.server 8080 --bind"
        "virsh console satellite"
        "virsh console aap"
        "virsh console idm"
        "mrhis-vm-consoles"
        "curl -fL --retry 3 --retry-delay 10"
        "aap-bundle.tar.gz"
        "setup.sh 2>&1"
        "ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no -i ${AAP_SSH_PRIVATE_KEY}"
    )
    local pattern pid cmdline
    local self_pid="$$"
    local parent_pid="${PPID:-0}"

    print_step "Force-killing MRHIS leftover processes from current/past runs"
    for pattern in "${patterns[@]}"; do
        while IFS= read -r pid; do
            [ -n "${pid}" ] || continue
            case "${pid}" in
                ''|*[!0-9]*) continue ;;
            esac
            [ "${pid}" -gt 1 ] || continue
            [ "${pid}" -ne "${self_pid}" ] || continue
            [ "${pid}" -ne "${parent_pid}" ] || continue

            cmdline="$(sudo tr '\0' ' ' < "/proc/${pid}/cmdline" 2>/dev/null || true)"
            # Guard: never kill our own process matchers/executors.
            if printf '%s' "${cmdline}" | grep -Eq '(^|[[:space:]])(pkill|pgrep)([[:space:]]|$)'; then
                continue
            fi

            sudo kill -9 "${pid}" >/dev/null 2>&1 || true
        done < <(sudo pgrep -f "${pattern}" 2>/dev/null || true)
    done

    # Also hard-kill any tracked monitor terminal PIDs from previous runs.
    if [ -f "$MRHIS_VM_MONITOR_PID_FILE" ]; then
        while IFS= read -r pid; do
            [ -n "$pid" ] || continue
            kill -9 "$pid" >/dev/null 2>&1 || true
        done < "$MRHIS_VM_MONITOR_PID_FILE"
        rm -f "$MRHIS_VM_MONITOR_PID_FILE"
    fi

    return 0
}

# Ensure Node.js is installed
ensure_node() {
    if command -v node >/dev/null 2>&1; then
        return 0
    fi

    print_warning "Node.js not found. Attempting installation..."
    sudo dnf install -y ${DNF_FLAGS} nodejs npm
    command -v node >/dev/null 2>&1
}

# Security helper functions
ensure_selinux() {
    if ! command -v getenforce >/dev/null 2>&1; then
        print_warning "SELinux tools not found; skipping SELinux checks."
        return 0
    fi

    local mode
    mode="$(getenforce || true)"
    case "$mode" in
        Enforcing)
            print_step "SELinux is Enforcing"
            ;;
        Permissive)
            print_warning "SELinux is Permissive; switching to Enforcing (runtime)"
            sudo setenforce 1 || print_warning "Could not set SELinux to Enforcing at runtime."
            ;;
        Disabled)
            print_warning "SELinux is Disabled. Enable it in /etc/selinux/config and reboot."
            ;;
        *)
            print_warning "Unknown SELinux state: $mode"
            ;;
    esac
}

ensure_firewalld() {
    # ── Ansible-first path ──────────────────────────────────────────────────
    # mrhis_host_setup covers firewalld install + enable + port/service rules.
    # We call it here so all three related functions share one Ansible run.
    # If Ansible is unavailable the bash fallback below is used.
    if run_local_role "mrhis_host_setup" "installer" 2>/dev/null; then
        return 0
    fi
    print_warning "Ansible role mrhis_host_setup unavailable; running bash fallback for ensure_firewalld"
    # ── Bash fallback ───────────────────────────────────────────────────────
    if ! command -v firewall-cmd >/dev/null 2>&1; then
        print_warning "firewalld not found. Attempting installation..."
        sudo dnf install -y ${DNF_FLAGS} firewalld
    fi

    sudo systemctl enable --now firewalld
    sudo firewall-cmd --state >/dev/null
    print_step "firewalld is enabled and running"
}

configure_mrhis_network_policy() {
    # ── Ansible-first path ──────────────────────────────────────────────────
    if run_local_role "mrhis_host_setup" "installer" 2>/dev/null; then
        return 0
    fi
    print_warning "Ansible role mrhis_host_setup unavailable; running bash fallback for configure_mrhis_network_policy"
    # ── Bash fallback ───────────────────────────────────────────────────────
    ensure_selinux
    ensure_firewalld || return 0

    # MRHIS dashboard/API
    sudo firewall-cmd --permanent --add-port=3000/tcp
    sudo firewall-cmd --reload

    # SELinux port label for web-style service on 3000
    if command -v semanage >/dev/null 2>&1; then
        if ! sudo semanage port -l | grep -qE '^http_port_t.*\btcp\b.*\b3000\b'; then
            sudo semanage port -a -t http_port_t -p tcp 3000 2>/dev/null \
                || sudo semanage port -m -t http_port_t -p tcp 3000
        fi
    else
        print_warning "semanage not found; install policycoreutils-python-utils if SELinux port labeling is required."
    fi

    print_step "Security policy applied for MRHIS (SELinux + firewalld port 3000)"
}

configure_libvirt_firewall_policy() {
    # ── Ansible-first path ──────────────────────────────────────────────────
    if run_local_role "mrhis_host_setup" "installer" 2>/dev/null; then
        return 0
    fi
    print_warning "Ansible role mrhis_host_setup unavailable; running bash fallback for configure_libvirt_firewall_policy"
    # ── Bash fallback ───────────────────────────────────────────────────────
    ensure_selinux
    ensure_firewalld || return 0

    # Keep remote/libvirt management reachable where applicable.
    sudo firewall-cmd --permanent --add-service=ssh
    sudo firewall-cmd --permanent --add-service=libvirt 2>/dev/null || true
    sudo firewall-cmd --reload

    print_step "Security policy applied for libvirt/virt-manager"
}

configure_libvirt_networks() {
    print_step "Configuring libvirt networks (ensure external + create internal)"

    # ── Ansible-first path ──────────────────────────────────────────────────
    load_ansible_env_file 2>/dev/null || true
    normalize_shared_env_vars 2>/dev/null || true
    if run_local_role "mrhis_libvirt_networks" "installer" \
            --extra-vars "internal_gw=${INTERNAL_GW:-10.168.0.1} netmask=${NETMASK:-255.255.0.0}" 2>/dev/null; then
        return 0
    fi
    print_warning "Ansible role mrhis_libvirt_networks unavailable; running bash fallback"
    # ── Bash fallback ───────────────────────────────────────────────────────
    if ! command -v virsh >/dev/null 2>&1; then
        print_warning "virsh not found; skipping libvirt network configuration."
        return 0
    fi

    # Keep libvirt's default network untouched; only ensure 'external' exists.
    if ! sudo virsh net-info external >/dev/null 2>&1; then
        print_step "Creating network: external (NAT/DHCP fallback for first guest interface)"
        cat <<'EOF' | sudo tee /tmp/external.xml >/dev/null
<network>
    <name>external</name>
    <forward mode='nat'/>
    <bridge name='virbr-external' stp='on' delay='0'/>
    <ip address='192.168.122.1' netmask='255.255.255.0'>
        <dhcp>
            <range start='192.168.122.2' end='192.168.122.254'/>
        </dhcp>
    </ip>
</network>
EOF
        sudo virsh net-define /tmp/external.xml
    else
        print_step "Network 'external' already exists"
    fi

    sudo virsh net-start external >/dev/null 2>&1 || true
    sudo virsh net-autostart external

        # Create internal static network with no DHCP
    if ! sudo virsh net-info internal >/dev/null 2>&1; then
                print_step "Creating network: internal (${INTERNAL_NETWORK}/${NETMASK}, static, no DHCP)"
                cat <<EOF | sudo tee /tmp/internal.xml >/dev/null
<network>
  <name>internal</name>
  <bridge name='virbr-internal' stp='on' delay='0'/>
  <dns enable='no'/>
    <ip address='${INTERNAL_GW}' netmask='${NETMASK}'/>
</network>
EOF
        sudo virsh net-define /tmp/internal.xml
    else
        print_step "Network 'internal' already exists"
    fi

    sudo virsh net-start internal >/dev/null 2>&1 || true
    sudo virsh net-autostart internal

    print_success "Libvirt network configuration complete"
    sudo virsh net-list --all
}

ensure_installer_networkmanager_dns() {
    local desired_internal_dns default_dev primary_conn active_conn dns_list dns_search
    local probe_ip

    # Prefer project-owned Ansible implementation for persistent NM profile state.
    if run_local_role "mrhis_host_setup" "installer" --tags network_dns 2>/dev/null; then
        return 0
    fi
    print_warning "Ansible role mrhis_host_setup (tag: network_dns) unavailable; running bash fallback for installer DNS policy"

    desired_internal_dns="${HOST_INT_IP:-${INTERNAL_GW:-10.168.0.1}}"
    case "${desired_internal_dns}" in
        10.168.*) ;;
        *) desired_internal_dns="10.168.0.1" ;;
    esac

    if ! command -v nmcli >/dev/null 2>&1; then
        print_warning "NetworkManager CLI not found; cannot enforce installer DNS policy."
        return 0
    fi

    if ! systemctl is-active --quiet NetworkManager 2>/dev/null; then
        print_warning "NetworkManager service is not active; cannot enforce installer DNS policy."
        return 0
    fi

    default_dev="$(ip route show default 2>/dev/null | awk '/default/ {print $5; exit}')"
    primary_conn=""
    if [ -n "${default_dev}" ]; then
        primary_conn="$(nmcli -t -f NAME,DEVICE connection show --active 2>/dev/null | awk -F: -v dev="${default_dev}" '$2==dev {print $1; exit}')"
    fi
    if [ -z "${primary_conn}" ]; then
        primary_conn="$(nmcli -t -f NAME connection show --active 2>/dev/null | head -n1)"
    fi

    if [ -z "${primary_conn}" ]; then
        print_warning "No active NetworkManager connection found on installer; skipping DNS policy enforcement."
        return 0
    fi

    dns_list="${desired_internal_dns} 8.8.8.8 1.1.1.1"
    dns_search="${DOMAIN:-example.com}"

    if ! sudo nmcli connection modify "${primary_conn}" \
        ipv4.ignore-auto-dns yes \
        ipv4.dns "${dns_list}" \
        ipv4.dns-search "${dns_search}" \
        ipv4.dns-options "rotate,timeout:1,attempts:1" >/dev/null 2>&1; then
        print_warning "Failed to update NetworkManager DNS policy for connection '${primary_conn}'."
        return 0
    fi

    sudo nmcli connection up "${primary_conn}" >/dev/null 2>&1 || true
    sudo systemctl reload NetworkManager >/dev/null 2>&1 || true

    active_conn="$(nmcli -t -f NAME,DEVICE connection show --active 2>/dev/null | awk -F: -v conn="${primary_conn}" '$1==conn {print $0; exit}')"
    print_step "Installer NetworkManager DNS policy applied to '${primary_conn}' (${active_conn:-device unknown})."

    probe_ip="${SAT_IP:-10.168.128.1}"
    if ip route get "${probe_ip}" >/dev/null 2>&1; then
        print_step "Installer routing check: route to ${probe_ip} is present."
    else
        print_warning "Installer routing check: no route to ${probe_ip}. Verify libvirt 'internal' network and bridge are up."
    fi

    return 0
}

# Local Installation
install_local() {
    print_step "Starting Local Installation"
    configure_mrhis_network_policy

    if ! ensure_node; then
        print_warning "Node.js installation failed. Please install Node.js first."
        return 1
    fi

    print_step "Resolving MRHIS project directory"
    cd "$SCRIPT_DIR"

    if [ -f "package.json" ]; then
        print_step "Using script directory as MRHIS project: $SCRIPT_DIR"
    elif [ -n "$REPO_URL" ] && [[ "$REPO_URL" != *"your-org/MRHIS.git"* ]]; then
        print_step "No local package.json found, cloning from REPO_URL"
        if [ ! -d "MRHIS/.git" ]; then
            git clone "$REPO_URL" MRHIS
        fi
        cd MRHIS
    else
        print_warning "No local package.json found in $SCRIPT_DIR (npm app mode unavailable)."
        print_warning "MRHIS in this repository is infrastructure/container-first."
        print_warning "Use menu option 3 (Full Stack Build) or 5 (Configure Only Stack)."
        print_step "Container workflows removed; skipping container deployment and falling back to local guidance."
        print_step "Use the Local Full Stack Build or the Configure-only flows instead."
        return 0
    fi

    print_step "Installing dependencies"
    npm install

    print_step "Skipping local .env creation (credentials are centralized in ${ANSIBLE_ENV_FILE})"

    print_step "Starting MRHIS service"
    npm start &

    print_success "Local installation complete"
    echo "Access dashboard at http://localhost:3000"
}

# ─── Container lifecycle and managed provisioner patches ─────────────────────
ensure_rootless_podman() {
    # Prefer an explicitly provided user, else fall back to SUDO_USER or USER env
    local _user
    _user="${MRHIS_ROOTLESS_USER:-${SUDO_USER:-${USER}}}"

    if [ "$(id -u)" -eq 0 ]; then
        print_warning "Run this script as a regular user (not root) for rootless Podman. Suggested user: ${_user}"
        return 1
    fi

    if ! command -v podman >/dev/null 2>&1; then
        print_warning "Podman not found. Installing..."
        sudo dnf install -y ${DNF_FLAGS} podman uidmap shadow-utils slirp4netns fuse-overlayfs
    fi

    local _subuids_added=0
    if ! grep -q "^${_user}:" /etc/subuid 2>/dev/null; then
        print_step "Adding subuid mapping for ${_user}..."
        sudo usermod --add-subuids 100000-165535 "${_user}" || true
        _subuids_added=1
    fi
    if ! grep -q "^${_user}:" /etc/subgid 2>/dev/null; then
        print_step "Adding subgid mapping for ${_user}..."
        sudo usermod --add-subgids 100000-165535 "${_user}" || true
        _subuids_added=1
    fi

    # Enable linger so the user's systemd session persists across logins.
    sudo loginctl enable-linger "${_user}" >/dev/null 2>&1 || true

    # Always derive XDG_RUNTIME_DIR from the actual UID — never trust an
    # inherited value that may be empty or stale (e.g. /run/user/ with no UID).
    local _uid
    _uid="$(id -u)"
    export XDG_RUNTIME_DIR="/run/user/${_uid}"
    if [ ! -d "${XDG_RUNTIME_DIR}" ]; then
        print_step "Runtime directory ${XDG_RUNTIME_DIR} missing; starting user@${_uid}.service..."
        sudo systemctl start "user@${_uid}.service" 2>/dev/null || true
        # Wait up to 5 s for systemd-logind to create the dir.
        local _i=0
        while [ ! -d "${XDG_RUNTIME_DIR}" ] && [ "${_i}" -lt 10 ]; do
            _i=$(( _i + 1 ))
            read -r -t 0.5 < /dev/null 2>/dev/null || true
        done
    fi

    # Ensure the D-Bus session bus socket is available for user-session tools.
    if [ -z "${DBUS_SESSION_BUS_ADDRESS:-}" ] && [ -S "${XDG_RUNTIME_DIR}/bus" ]; then
        export DBUS_SESSION_BUS_ADDRESS="unix:path=${XDG_RUNTIME_DIR}/bus"
    fi

    # Migrate storage after any subuid/subgid change (idempotent on reruns).
    podman system migrate >/dev/null 2>&1 || true

    # Ensure user systemd podman socket is enabled for rootless operation.
    # Use runuser to operate against the target user's systemd --user scope
    runuser -l "${_user}" -c 'systemctl --user enable --now podman.socket' >/dev/null 2>&1 || true

    # If podman fails due to newuidmap/uid_map permission, attempt a safe sysctl fallback
    # to enable unprivileged user namespaces (requires sudo to persist).
    if ! podman info >/dev/null 2>&1; then
        if podman info 2>&1 | grep -E "newuidmap|open of uid_map failed" >/dev/null 2>&1; then
            if sudo -n true 2>/dev/null; then
                print_step "Attempting to enable unprivileged user namespaces (kernel.unprivileged_userns_clone=1)"
                sudo sysctl -w kernel.unprivileged_userns_clone=1 >/dev/null 2>&1 || true
                echo 'kernel.unprivileged_userns_clone = 1' | sudo tee /etc/sysctl.d/99-mrhis-rootless.conf >/dev/null 2>&1 || true
                sudo sysctl --system >/dev/null 2>&1 || true
            else
                print_warning "Podman newuidmap error detected; sudo is required to enable unprivileged user namespaces."
                print_warning "Please run: sudo sysctl -w kernel.unprivileged_userns_clone=1 && sudo sysctl --system"
            fi
        fi
    fi

    if [ "$(podman info --format '{{.Host.Security.Rootless}}' 2>/dev/null)" != "true" ]; then
        print_warning "Podman is not operating rootless for user '${_user}'."
        print_warning "  XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR}"
        print_warning "  subuid entry  : $(grep "^${_user}:" /etc/subuid 2>/dev/null || echo '(none)')"
        print_warning "  subgid entry  : $(grep "^${_user}:" /etc/subgid 2>/dev/null || echo '(none)')"
        if [ "${_subuids_added}" = "1" ]; then
            print_warning "Subuid/subgid mappings were just added — a full log-out/log-in is required for the kernel to load them."
        else
            print_warning "Try: sudo systemctl start user@${_uid}.service  (or log out and back in)"
        fi
        export MRHIS_PODMAN_ROOTLESS_AVAILABLE=0
        return 1
    fi

    print_success "Rootless Podman is configured for user: ${_user}"
    export MRHIS_PODMAN_ROOTLESS_AVAILABLE=1
    return 0
}

# Ensure the MRHIS provisioner container is running.  Idempotent: no-op if it is
# already up.  The container's entrypoint drops to an interactive bash shell, so
# it needs a pseudo-TTY (-t) to stay alive in detached (-d) mode.
# Three host directories are bind-mounted inside the container:
#   external_inventory  -> inventory file(s) consumed by mrhis-builder playbooks
#   host_vars           -> per-node variable files (satellite.yml, aap.yml, …)
#   vault               -> Ansible vault env.yml + optional .vaultpass.txt

# Pin ansible.utils to 4.1.0 when ansible-core inside the container is 2.14.x.
# ansible.utils >=5.x declares requires_ansible >=2.15 which would flood the
# output with [WARNING] Collection ansible.utils does not support Ansible
# version 2.14.x on every playbook run.  4.1.0 declares >=2.14.0 and is
# functionally equivalent for the tasks we run.
# NOTE: redhat.rhel_system_roles has the same version-declaration mismatch but
# Red Hat Automation Hub only serves the current release; no older compatible
# version is available.  That warning cannot be suppressed via a version pin.
ensure_container_collection_compat() {
    local core_ver
    core_ver=$(podman_exec_safe "${MRHIS_CONTAINER_NAME}" ansible --version 2>/dev/null \
        | awk '/^ansible \[core/{gsub(/[\[\]]/,"",$3); print $3}')

    # Only needed for ansible-core 2.14.x; newer images are already fine.
    [[ "${core_ver}" == 2.14.* ]] || return 0

    local utils_ver
    utils_ver=$(podman_exec_safe "${MRHIS_CONTAINER_NAME}" ansible-galaxy collection list 2>/dev/null \
        | awk '/^ansible\.utils[[:space:]]/{print $2}')

    # Already pinned to 4.x — nothing to do.
    [[ "${utils_ver}" == 4.* ]] && return 0

    print_step "Pinning ansible.utils to 4.1.0 for ansible-core ${core_ver} compatibility"
    if podman exec "${MRHIS_CONTAINER_NAME}" \
           ansible-galaxy collection install "ansible.utils:4.1.0" --force >/dev/null 2>&1; then
        print_success "ansible.utils pinned to 4.1.0 (was ${utils_ver:-unknown})."
    else
        print_warning "Could not pin ansible.utils to 4.1.0; version-compatibility warning will appear during playbook runs."
    fi
    return 0
}

# Maintain MRHIS-managed hotfixes inside the provisioner container so each newly
# deployed container gets the same compatibility/workaround patches before any
# playbooks are executed.
ensure_container_managed_chrony_template() {
    local _tpl_path="/mrhis/mrhis-builder-satellite/roles/satellite_pre/templates/chrony.j2"
    local _mk_cmd='mkdir -p /mrhis/mrhis-builder-satellite/roles/satellite_pre/templates && cat > /mrhis/mrhis-builder-satellite/roles/satellite_pre/templates/chrony.j2 <<'"'"'EOF'"'"'
# MRHIS fallback chrony template (auto-generated when upstream template is missing)
driftfile /var/lib/chrony/drift
makestep 1.0 3
rtcsync
logdir /var/log/chrony
pool 2.rhel.pool.ntp.org iburst
EOF'

    if podman_exec_safe "${MRHIS_CONTAINER_NAME}" test -f "${_tpl_path}" 2>/dev/null; then
        return 0
    fi

    print_warning "Managed container patch: chrony.j2 missing; applying fallback template."

     if podman_exec_safe "${MRHIS_CONTAINER_NAME}" bash -lc "${_mk_cmd}" >/dev/null 2>&1 || \
         podman_exec_safe --user 0 "${MRHIS_CONTAINER_NAME}" bash -lc "${_mk_cmd}" >/dev/null 2>&1; then
        print_success "Managed container patch applied: fallback chrony.j2 created."
        return 0
    fi

    print_warning "Managed container patch failed: could not create fallback chrony.j2."
    return 1
}

ensure_container_managed_idm_chrony_template() {
    local _tpl_path="/mrhis/mrhis-builder-idm/roles/idm_pre/templates/chrony.j2"
