ensure_container_managed_satellite_foreman_patch() {
    local _root="/mrhis/mrhis-builder-satellite/roles/satellite_pre/tasks"
    local _py='import pathlib
import re

root = pathlib.Path("/mrhis/mrhis-builder-satellite/roles/satellite_pre/tasks")
if not root.exists():
    print("UPDATED=0")
    raise SystemExit(0)

updated = 0
for path in root.rglob("*.yml"):
    text = path.read_text(encoding="utf-8", errors="ignore")
    if "Get the state of the foreman service" not in text:
        continue

    lines = text.splitlines()
    start = None
    for i, line in enumerate(lines):
        if "Get the state of the foreman service" in line:
            start = i
            break
    if start is None:
        continue

    end = len(lines)
    for j in range(start + 1, len(lines)):
        if re.match(r"^\s*-\s+name:\s+", lines[j]):
            end = j
            break

    register_idx = None
    changed_idx = None
    failed_idx = None
    indent = "      "

    for j in range(start + 1, end):
        if re.match(r"^\s*register:\s*", lines[j]):
            register_idx = j
            indent = re.match(r"^(\s*)", lines[j]).group(1)
        if re.match(r"^\s*changed_when:\s*", lines[j]):
            changed_idx = j
            indent = re.match(r"^(\s*)", lines[j]).group(1)
        if re.match(r"^\s*failed_when:\s*", lines[j]):
            failed_idx = j
            indent = re.match(r"^(\s*)", lines[j]).group(1)

    changed = False

    if changed_idx is not None:
        normalized = f"{indent}changed_when: false"
        if lines[changed_idx].strip() != "changed_when: false":
            lines[changed_idx] = normalized
            changed = True
    else:
        insert_at = register_idx + 1 if register_idx is not None else end
        lines.insert(insert_at, f"{indent}changed_when: false")
        changed_idx = insert_at
        end += 1
        changed = True

    if failed_idx is None:
        lines.insert(changed_idx + 1, f"{indent}failed_when: false")
        changed = True
    elif lines[failed_idx].strip() != "failed_when: false":
        lines[failed_idx] = f"{indent}failed_when: false"
        changed = True

    if changed:
        path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        updated += 1

print(f"UPDATED={updated}")'

    local _cmd=$'python3 - <<\'PY\'\n'"${_py}"$'\nPY'
    local _out=""

    _out="$(podman_exec_safe "${MRHIS_CONTAINER_NAME}" bash -lc "${_cmd}" 2>/dev/null || true)"
    if [ -z "${_out}" ]; then
        _out="$(podman_exec_safe --user 0 "${MRHIS_CONTAINER_NAME}" bash -lc "${_cmd}" 2>/dev/null || true)"
    fi

    if printf '%s\n' "${_out}" | grep -q 'UPDATED='; then
        if printf '%s\n' "${_out}" | grep -q 'UPDATED=0'; then
            print_step "Managed container patch: Satellite foreman service check already compatible or absent."
        else
            print_success "Managed container patch applied: Satellite foreman service check made non-fatal."
        fi
        return 0
    fi

    print_warning "Managed container patch failed: could not confirm Satellite foreman service compatibility patch."
    return 1
}

ensure_container_managed_idm_update_patch() {
    local _py='import pathlib
import re

path = pathlib.Path("/mrhis/mrhis-builder-idm/roles/idm_pre/tasks/ensure_update_system.yml")
if not path.exists():
    print("MISSING_IDM_UPDATE_TASK")
    raise SystemExit(0)

lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
updated = False

start = None
for i, line in enumerate(lines):
    if "name: \"Update the system\"" in line:
        start = i
        break

if start is None:
    print("UPDATED=0")
    raise SystemExit(0)

end = len(lines)
for j in range(start + 1, len(lines)):
    if re.match(r"^\s*-\s+name:\s+", lines[j]):
        end = j
        break

module_idx = None
module_indent = ""
async_idx = None
disable_idx = None
exclude_idx = None

for j in range(start + 1, end):
    if re.match(r"^\s*ansible\.builtin\.dnf:\s*$", lines[j]):
        module_idx = j
        module_indent = re.match(r"^(\s*)", lines[j]).group(1)
    if re.match(r"^\s*async:\s*", lines[j]) and async_idx is None:
        async_idx = j
    if re.match(r"^\s*disable_gpg_check:\s*", lines[j]):
        disable_idx = j
    if re.match(r"^\s*exclude:\s*", lines[j]):
        exclude_idx = j

if module_idx is None:
    print("UPDATED=0")
    raise SystemExit(0)

arg_indent = module_indent + "  "

if disable_idx is not None:
    desired = f"{arg_indent}disable_gpg_check: true"
    if lines[disable_idx].strip() != "disable_gpg_check: true":
        lines[disable_idx] = desired
        updated = True

if exclude_idx is not None:
    desired = f"{arg_indent}exclude: \"intel-audio-firmware*\""
    if lines[exclude_idx].strip() != "exclude: \"intel-audio-firmware*\"":
        lines[exclude_idx] = desired
        updated = True

insert_at = async_idx if async_idx is not None else end

if disable_idx is None:
    lines.insert(insert_at, f"{arg_indent}disable_gpg_check: true")
    updated = True
    insert_at += 1

if exclude_idx is None:
    lines.insert(insert_at, f"{arg_indent}exclude: \"intel-audio-firmware*\"")
    updated = True

if updated:
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("UPDATED=1")
else:
    print("UPDATED=0")'

    local _cmd=$'python3 - <<\'PY\'\n'"${_py}"$'\nPY'
    local _out=""
    _out="$(podman_exec_safe "${MRHIS_CONTAINER_NAME}" bash -lc "${_cmd}" 2>/dev/null || true)"
    if [ -z "${_out}" ]; then
        _out="$(podman_exec_safe --user 0 "${MRHIS_CONTAINER_NAME}" bash -lc "${_cmd}" 2>/dev/null || true)"
    fi

    if printf '%s\n' "${_out}" | grep -q 'UPDATED=1'; then
        print_success "Managed container patch applied: IdM update task GPG guard enabled."
        return 0
    fi
    if printf '%s\n' "${_out}" | grep -q 'UPDATED=0'; then
        print_step "Managed container patch: IdM update task already compatible or absent."
        return 0
    fi

    print_warning "Managed container patch failed: could not confirm IdM update task patch."
    return 1
}

sync_local_roles_to_container() {
    local local_roles_dir="${SCRIPT_DIR}/local/roles"
    local tree sync_failed=0
    local rel_file
    local extra_role_dir
    local -a extra_role_dirs=(
        "mrhis_sat_config"
        "mrhis_host_setup"
        "mrhis_hosts_sync"
        "mrhis_ssh_mesh"
        "mrhis_vm_hardening"
        "mrhis_vm_lifecycle"
        "mrhis_installer"
    )
    local -a top_level_assets=(
        "ansible.cfg"
        "requirements.txt"
        "requirements.yml"
    )

    if [ ! -d "${local_roles_dir}" ]; then
        print_warning "Local roles directory not found: ${local_roles_dir}; skipping sync."
        return 0
    fi

    # Only sync local roles into the provisioner container when the execution
    # mode is explicitly set to 'container'.  By default MRHIS runs in
    # 'local' mode and should not perform any container-side syncs unless the
    # caller passed --container or set MRHIS_EXECUTION_MODE=container.
    if [ "${MRHIS_EXECUTION_MODE:-local}" != "container" ]; then
        print_step "Skipping syncing local local/roles/* (MRHIS_EXECUTION_MODE=${MRHIS_EXECUTION_MODE:-local})"
        return 0
    fi

    print_step "Syncing local local/roles/* to provisioner container /mrhis/"
    for tree in "${local_roles_dir}"/mrhis-builder-*/; do
        tree="$(basename "${tree}")"
        podman_exec_safe "${MRHIS_CONTAINER_NAME}" mkdir -p "/mrhis/${tree}" >/dev/null 2>&1 || true
        if podman cp "${local_roles_dir}/${tree}/." \
               "${MRHIS_CONTAINER_NAME}:/mrhis/${tree}/" >/dev/null 2>&1; then
            print_step "  synced: ${tree}"
        else
            print_warning "  failed to sync: ${tree}"
            sync_failed=1
        fi
    done

    # Keep shared non-builder role trees in sync as they are included by the
    # compatibility builder playbooks (for example mrhis_sat_config).
    for extra_role_dir in "${extra_role_dirs[@]}"; do
        if [ -d "${local_roles_dir}/${extra_role_dir}" ]; then
            podman_exec_safe "${MRHIS_CONTAINER_NAME}" mkdir -p "/mrhis/${extra_role_dir}" >/dev/null 2>&1 || true
            if podman cp "${local_roles_dir}/${extra_role_dir}/." \
                   "${MRHIS_CONTAINER_NAME}:/mrhis/${extra_role_dir}/" >/dev/null 2>&1; then
                print_step "  synced: ${extra_role_dir}"
            else
                print_warning "  failed to sync: ${extra_role_dir}"
                sync_failed=1
            fi
        fi
    done

    # Keep top-level local/roles assets in sync for local/adhoc runs inside
    # mrhis-provisioner (ansible.cfg and requirements files).
    for rel_file in "${top_level_assets[@]}"; do
        if [ -f "${local_roles_dir}/${rel_file}" ]; then
            if podman cp "${local_roles_dir}/${rel_file}" \
                   "${MRHIS_CONTAINER_NAME}:/mrhis/${rel_file}" >/dev/null 2>&1; then
                print_step "  synced: ${rel_file}"
            else
                print_warning "  failed to sync: ${rel_file}"
                sync_failed=1
            fi
        fi
    done

    if [ "${sync_failed}" -eq 1 ]; then
        print_warning "One or more role trees failed to sync; container may have stale content."
        return 1
    fi

    print_success "Local roles synced to container."
    return 0
}

apply_managed_container_patches() {
    local _verify_cmd='test -f /mrhis/mrhis-builder-satellite/roles/satellite_pre/templates/chrony.j2 && test -f /mrhis/mrhis-builder-idm/roles/idm_pre/templates/chrony.j2 && { ! test -f /mrhis/mrhis-builder-satellite/roles/satellite_pre/tasks/is_satellite_installed.yml || grep -q "failed_when: false" /mrhis/mrhis-builder-satellite/roles/satellite_pre/tasks/is_satellite_installed.yml; } && grep -q "disable_gpg_check: true" /mrhis/mrhis-builder-idm/roles/idm_pre/tasks/ensure_update_system.yml && grep -q "exclude: \"intel-audio-firmware\\*\"" /mrhis/mrhis-builder-idm/roles/idm_pre/tasks/ensure_update_system.yml'

    if ! is_enabled "${MRHIS_ENABLE_CONTAINER_HOTFIXES:-1}"; then
        print_step "Managed container patches disabled (MRHIS_ENABLE_CONTAINER_HOTFIXES=${MRHIS_ENABLE_CONTAINER_HOTFIXES})."
        return 0
    fi

    print_step "Applying MRHIS-managed patches to provisioner container components"

    ensure_container_managed_chrony_template || true
    ensure_container_managed_idm_chrony_template || true
    ensure_container_managed_satellite_foreman_patch || true
    ensure_container_managed_idm_update_patch || true

    if podman exec "${MRHIS_CONTAINER_NAME}" bash -lc "${_verify_cmd}" >/dev/null 2>&1 || \
       podman exec --user 0 "${MRHIS_CONTAINER_NAME}" bash -lc "${_verify_cmd}" >/dev/null 2>&1; then
        print_success "Managed container patch verification passed."
        return 0
    fi

    if is_enabled "${MRHIS_ENFORCE_CONTAINER_HOTFIXES:-1}"; then
        print_warning "Managed container patch verification failed and enforcement is ON."
        return 1
    fi

    print_warning "Managed container patch verification failed, but enforcement is OFF; continuing."
    return 0
}

ensure_container_running() {
    # Auto-generate required host mount directories for runtime artifacts.
    mkdir -p "${MRHIS_INVENTORY_DIR}" "${MRHIS_HOST_VARS_DIR}" "${ANSIBLE_ENV_DIR}" || {
        print_warning "Failed to create required runtime directories for container mounts."
        return 1
    }

    generate_mrhis_ansible_cfg || {
        print_warning "Could not generate MRHIS Ansible config at ${MRHIS_ANSIBLE_CFG_VAULT_HOST}"
        return 1
    }

    generate_local_roles_ansible_cfg || {
        print_warning "Could not generate local roles ansible config at ${SCRIPT_DIR}/local/roles/ansible.cfg"
        return 1
    }

 #   if podman ps --filter "name=^${MRHIS_CONTAINER_NAME}$" --format '{{.Names}}' 2>/dev/null \
 #          | grep -q "^${MRHIS_CONTAINER_NAME}$"; then
 #       print_success "MRHIS provisioner container '${MRHIS_CONTAINER_NAME}' is already running."
 #       ensure_container_collection_compat || true
 #       sync_local_roles_to_container || print_warning "Role sync had errors; continuing."
 #       apply_managed_container_patches || return 1
 #       return 0
 #   fi

#    # Remove a stopped/crashed remnant so the name is free
#    podman rm -f "${MRHIS_CONTAINER_NAME}" >/dev/null 2>&1 || true#

    # Right after container teardown, consolidate runtime values from a#ny
    # active sources (preseed, shell exports, prior vault state) back into
    # encrypted ~/.ansible/conf/env.yml.
#    sync_runtime_values_to_ansible_vault || print_warning "Could not consolidate runtime values into ${ANSIBLE_ENV_FILE}; continuing."

    # Start the MRHIS provisioner container. Capture the container ID
    # for internal use but suppress the detached ID output to avoid noisy
    # STEP-style lines in the run log.
#    CONTAINER_ID=$(podman run -d -t \
#        --name "${MRHIS_CONTAINER_NAME}" \
#        --network host \
#        -e "ANSIBLE_CONFIG=${MRHIS_ANSIBLE_CFG_CONTAINER}" \
#        -v "${MRHIS_INVENTORY_DIR}:/mrhis/vars/external_inventory:Z" \
#        -v "${MRHIS_HOST_VARS_DIR}:/mrhis/vars/host_vars:Z" \
#        -v "${ANSIBLE_ENV_DIR}:/mrhis/vars/vault:z" \
#        -v "${MRHIS_INSTALLER_SSH_KEY_DIR}:${MRHIS_INSTALLER_SSH_KEY_CONTAINER_DIR}:z,ro" \
#        "${MRHIS_CONTAINER_IMAGE}" 2>/dev/null) || {
#        print_warning "Failed to start container '${MRHIS_CONTAINER_NAME}'"
#        return 1
#    }

 #   ensure_container_collection_compat || true
 #   sync_local_roles_to_container || print_warning "Role sync had errors; continuing."
 #   apply_managed_container_patches || return 1
 #   print_success "Container '${MRHIS_CONTAINER_NAME}' started."
 #   echo "Exec into the container : podman exec -it ${MRHIS_CONTAINER_NAME} /bin/bash"
 #   echo "Ansible config vault    : ${MRHIS_ANSIBLE_CFG_VAULT_HOST}"
 #   echo "Ansible config runtime  : ${MRHIS_ANSIBLE_CFG_HOST}"
 #   echo "Ansible log file        : ${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}"
 #   echo "Ansible fact cache      : ${MRHIS_ANSIBLE_FACT_CACHE_HOST}"
 #   echo "Run a playbook example  : podman exec -it ${MRHIS_CONTAINER_NAME} ansible-playbook \\"
 #   echo "    --inventory ${MRHIS_CONTAINER_INVENTORY_FILE} \\" 
 #   echo "    --user ansiblerunner --ask-pass --ask-vault-pass \\" 
 #   echo "    --extra-vars 'vault_dir=/mrhis/vars/vault/' \\"
 #   echo "    --limit idm_primary /mrhis/mrhis-builder-idm/main.yml"
}

# Try to ensure the provisioner container is running, with optional restart
# attempts. Keep this near the container lifecycle helpers so config-only and
# repair paths share the same start/restart behavior.
ensure_container_running_with_retry() {
    local tries=0
    local max=${MRHIS_CONTAINER_RESTART_RETRIES:-2}
    local interval=${MRHIS_CONTAINER_RESTART_INTERVAL:-10}

    while true; do
        if ensure_container_running >/dev/null 2>&1; then
            return 0
        fi

        tries=$((tries + 1))
        if [ "$tries" -gt "$max" ]; then
            return 1
        fi

        podman rm -f "${MRHIS_CONTAINER_NAME}" >/dev/null 2>&1 || true
        sleep "${interval}"
    done
}

install_container() {
    ensure_rootless_podman >/dev/null 2>&1 || return 1
    configure_mrhis_network_policy >/dev/null 2>&1 || true

    if ! command -v podman >/dev/null 2>&1; then
        return 1
    fi

    podman pull "${MRHIS_CONTAINER_IMAGE}" >/dev/null 2>&1 || true
    podman images -f "dangling=true" -q | xargs --no-run-if-empty podman rmi >/dev/null 2>&1 || true

    ensure_container_running_with_retry >/dev/null 2>&1
}

#    print_success "Container deployment complete"
