# ---------------------------------------------------------------------------
# repair_web_uis — top-level hands-free Web UI repair
#
# Probes all three UIs (IdM, Satellite, AAP) from the installer host.
# For each unreachable endpoint it runs targeted remediation:
#   IdM       — installs FreeIPA if absent, else restarts ipa/httpd
#   Satellite — restarts satellite-maintain services
#   AAP       — triggers containerised installer if containers absent,
#               else restarts automation-gateway
# Re-probes after each fix and prints a final reachability summary.
# Called automatically after every orchestration run (no human input).
# ---------------------------------------------------------------------------
repair_web_uis() {
    local _root_pass="${ROOT_PASS:-${ADMIN_PASS:-}}"
    local _cfg="${SCRIPT_DIR}/local/roles/ansible.cfg"
    local _vault_arg=""
    local _inv="${MRHIS_INVENTORY_FILE}"
    local _repair_failures=0
    local _idm_ok=0 _sat_ok=0 _aap_ok=0
    local _gittea_ok=-1 _openshift_ok=-1
    local _gittea_enabled=0 _openshift_enabled=0
    local _gittea_ui_url="" _openshift_ui_url=""
    local _aap_https_port="${AAP_GATEWAY_HTTPS_PORT:-443}"

    [ -f "${_cfg}" ] || _cfg="${MRHIS_ANSIBLE_CFG_HOST}"

    if [ -r "${ANSIBLE_VAULT_PASS_FILE}" ]; then
        _vault_arg="--vault-password-file ${ANSIBLE_VAULT_PASS_FILE}"
    fi

    # ── Helper: probe a URL from the installer host ────────────────────────
    _rwu_probe() {
        local _label="$1" _url="$2" _code
        _code="$(curl -k -sS -o /dev/null -w "%{http_code}" --connect-timeout 8 --max-time 25 "${_url}" 2>/dev/null || true)"
        case "${_code}" in
            200|301|302|303|307|308|401|403)
                print_success "Web UI reachable: ${_label} (HTTP ${_code})"
                return 0 ;;
            *)
                print_warning "Web UI unreachable: ${_label} (HTTP ${_code:-no-response})"
                return 1 ;;
        esac
    }

    # ── Helper: run ad-hoc shell on an inventory target ────────────────────
    _rwu_shell() {
        local _target="$1" _cmd="$2" _extra="${3:---one-line}"
        if [ -n "${_root_pass}" ]; then
            ANSIBLE_CONFIG="${_cfg}" \
                ansible "${_target}" --inventory "${_inv}" ${_vault_arg} \
                --extra-vars "@${ANSIBLE_ENV_FILE}" \
                -e "ansible_user=root" \
                -e "ansible_password=${_root_pass}" \
                -e "ansible_become=false" \
                -e "ansible_become_password=${_root_pass}" \
                -m shell -a "${_cmd}" ${_extra} 2>&1
        else
            ANSIBLE_CONFIG="${_cfg}" \
                ansible "${_target}" --inventory "${_inv}" ${_vault_arg} \
                --extra-vars "@${ANSIBLE_ENV_FILE}" \
                -m shell -a "${_cmd}" ${_extra} 2>&1
        fi
    }

        # ── Helper: run ad-hoc shell as admin user (with sudo) on an inventory target ──
        _rwu_admin_shell() {
            local _target="$1" _cmd="$2" _extra="${3:---one-line}"
            local _apass="${ADMIN_PASS:-${AAP_ADMIN_PASS:-${_root_pass:-}}}"
            local _out _rc

            # If we still do not have an admin sudo password, fall back to the
            # root transport helper to avoid interactive sudo prompts.
            if [ -z "${_apass}" ]; then
                _rwu_shell "${_target}" "${_cmd}" "${_extra}"
                return $?
            fi

            _out="$(ANSIBLE_CONFIG="${_cfg}" \
                ansible "${_target}" --inventory "${_inv}" ${_vault_arg} \
                --extra-vars "@${ANSIBLE_ENV_FILE}" \
                -e "ansible_user=${ADMIN_USER:-admin}" \
                -e "ansible_password=${_apass}" \
                -e "ansible_become=true" \
                -e "ansible_become_method=sudo" \
                -e "ansible_become_password=${_apass}" \
                -m shell -a "${_cmd}" ${_extra} 2>&1)"
            _rc=$?
            printf '%s\n' "${_out}"

            if [ ${_rc} -ne 0 ] && printf '%s' "${_out}" | grep -qi 'Missing sudo password'; then
                print_warning "Admin sudo execution failed (missing sudo password); retrying as root transport on ${_target}."
                _rwu_shell "${_target}" "${_cmd}" "${_extra}"
                return $?
            fi

            return ${_rc}
        }

        # Run _rwu_admin_shell but show a spinner and live tail of a temp log
        # Usage: _rwu_admin_shell_spinner <target> <cmd> [extra-args]
        _rwu_admin_shell_spinner() {
            local _target="$1" _cmd="$2" _extra="${3:---one-line}"
            local _tmp logtail_pid ret
            _tmp=$(mktemp /tmp/mrhis-rwu.XXXXXX) || _tmp=/tmp/mrhis-rwu.$$

            # Launch the command in background, capture output to temp file
            (
                _rwu_admin_shell "${_target}" "${_cmd}" "${_extra}"
            ) >"${_tmp}" 2>&1 &
            local _rpid=$!

            # Start a tail -f so the user sees live log lines
            tail -n 10 -f "${_tmp}" &
            logtail_pid=$!

            # Show a one-line spinner + synopsis while the remote command runs
            wait_for_pid_spinner "${_rpid}" "Waiting for remote task (press Ctrl-C to cancel)"

            wait "${_rpid}" || ret=$?
            sleep 0.2
            kill "${logtail_pid}" >/dev/null 2>&1 || true
            echo
            # Show the final tail so the caller can see the end of output (mimics previous behavior)
            tail -n 60 "${_tmp}" || true
            rm -f "${_tmp}" >/dev/null 2>&1 || true
            return ${ret:-0}
        }

        # ── Helper: SSH shell direct via root key (bypasses Ansible inventory) ──
        _rwu_root_key_shell() {
            local _host="$1" _cmd="$2"
            local _key="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/id_ed25519}"
            ssh -i "${_key}" -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null \
                -o ConnectTimeout=10 -o BatchMode=yes \
                "root@${_host}" "${_cmd}" 2>&1
        }

    print_step "===== Repair Web UIs: probing endpoints from installer host ====="

    # Optional nodes are reported dynamically when requested/present.
    if [ -n "${CLI_GITTEA:-}" ] || [ -n "${GITTEA_IP:-}" ] || [ -n "${GITTEA_HOSTNAME:-}" ]; then
        _gittea_enabled=1
        _gittea_ui_url="http://${GITTEA_IP:-10.168.128.4}:3000/"
    fi
    if [ -n "${CLI_OPENSHIFT:-}" ] || [ -n "${OPENSHIFT_IP:-}" ] || [ -n "${OPENSHIFT_HOSTNAME:-}" ]; then
        _openshift_enabled=1
        _openshift_ui_url="https://${OPENSHIFT_IP:-10.168.128.5}:443/"
    fi

    # ── IdM ─────────────────────────────────────────────────────────────────
    if _rwu_probe "IdM" "https://${IDM_IP}/ipa/ui/"; then
        _idm_ok=1
    else
        print_step "Repair IdM: checking FreeIPA installation state..."
        local _ipa_state
        _ipa_state="$(_rwu_shell "idm" \
            'test -f /etc/ipa/default.conf && echo IPA_CONFIGURED || echo IPA_NOT_CONFIGURED' \
            "--one-line" 2>/dev/null || echo "IPA_UNREACHABLE")"

        if printf '%s\n' "${_ipa_state}" | grep -q 'IPA_NOT_CONFIGURED'; then
            # FreeIPA is absent — run the full install playbook
            print_step "Repair IdM: FreeIPA not installed — running idm-install.yml (this takes ~5 min)..."
            local _ipapass="${IPAADMIN_PASSWORD:-${IPADM_PASSWORD:-${IDM_ADMIN_PASS:-${_root_pass}}}}"
            # Enforce FreeIPA 8-character minimum
            while [ "${#_ipapass}" -lt 8 ]; do _ipapass="${_ipapass}9"; done
            ANSIBLE_CONFIG="${_cfg}" \
            ANSIBLE_ROLES_PATH="${SCRIPT_DIR}/roles:${SCRIPT_DIR}/local/roles" \
            ANSIBLE_LOG_PATH="${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME:-rhis-repair.log}" \
                ansible-playbook \
                    --inventory "${_inv}" \
                    ${_vault_arg} \
                    --extra-vars "@${ANSIBLE_ENV_FILE}" \
                    -e "admin_pass=${_root_pass}" \
                    -e "global_admin_password=${_root_pass}" \
                    -e "idm_admin_pass=${_ipapass}" \
                    -e "ipaadmin_password=${_ipapass}" \
                    -e "idm_realm=${IDM_REALM:-PROD.SPG}" \
                    -e "idm_domain=${IDM_DOMAIN:-prod.spg}" \
                    -e "ansible_user=root" \
                    -e "ansible_password=${_root_pass}" \
                    -e "ansible_become=false" \
                    --limit idm_primary \
                    "${SCRIPT_DIR}/playbooks/idm-install.yml" 2>&1 | tail -60 || \
                print_warning "Repair IdM: idm-install.yml did not complete cleanly; see log."
        elif printf '%s\n' "${_ipa_state}" | grep -q 'IPA_CONFIGURED'; then
            # FreeIPA installed but services down — restart
            print_step "Repair IdM: FreeIPA installed — restarting ipa/httpd services..."
            _rwu_shell "idm" \
                'ipactl status >/dev/null 2>&1 || ipactl start >/dev/null 2>&1 || true; systemctl restart httpd pki-tomcatd@pki-tomcat >/dev/null 2>&1 || true' \
                "--one-line" >/dev/null 2>&1 || true
        else
            print_warning "Repair IdM: VM unreachable — skipping IdM repair."
        fi

        if _rwu_probe "IdM (post-repair)" "https://${IDM_IP}/ipa/ui/"; then
            _idm_ok=1
        else
            _repair_failures=$((_repair_failures + 1))
        fi
    fi

    # ── Satellite ───────────────────────────────────────────────────────────
    if _rwu_probe "Satellite" "https://${SAT_IP}/users/login"; then
        _sat_ok=1
    else
        print_step "Repair Satellite: restarting Satellite services..."
        _rwu_shell "scenario_satellite" \
            'satellite-maintain service restart >/dev/null 2>&1 || true; systemctl restart httpd >/dev/null 2>&1 || true' \
            "--one-line" >/dev/null 2>&1 || true

        if _rwu_probe "Satellite (post-repair)" "https://${SAT_IP}/users/login"; then
            _sat_ok=1
        else
            _repair_failures=$((_repair_failures + 1))
        fi
    fi

    # ── AAP ─────────────────────────────────────────────────────────────────
    if _rwu_probe "AAP" "https://${AAP_IP}:${_aap_https_port}/"; then
        _aap_ok=1
    else
        print_step "Repair AAP: bootstrapping node prerequisites (podman, admin keys, bundle)..."
        local _aap_nat_ip _aap_key
        _aap_nat_ip="$(virsh domifaddr aap 2>/dev/null | awk '/ipv4/{gsub("/.*","",$4); print $4}' | head -1)"
        _aap_key="${HOME}/.ssh/id_ed25519"
        [ -r "${HOME}/.ssh/id_rsa" ] && _aap_key="${HOME}/.ssh/id_rsa"
        [ -r "${HOME}/.ssh/id_ed25519" ] && _aap_key="${HOME}/.ssh/id_ed25519"

        if [ -n "${_aap_nat_ip}" ]; then
            local _bs_cmd
            _bs_cmd='rpm -q podman >/dev/null 2>&1 || dnf install -y --skip-broken --allowerasing --best --nogpgcheck podman uidmap 2>&1 | tail -3; '
            _bs_cmd="${_bs_cmd}"'echo "admin:'"${ADMIN_PASS}"'" | chpasswd; '
            _bs_cmd="${_bs_cmd}"'grep -q "^PasswordAuthentication yes" /etc/ssh/sshd_config || { sed -i '"'"'s/^#\?PasswordAuthentication.*/PasswordAuthentication yes/'"'"' /etc/ssh/sshd_config && systemctl restart sshd; }; '
            _bs_cmd="${_bs_cmd}"'mkdir -p /home/admin/.ssh && chmod 700 /home/admin/.ssh && chown admin:admin /home/admin/.ssh; '
            _bs_cmd="${_bs_cmd}"'[ -f /home/admin/.ssh/id_rsa ] || su - admin -c "ssh-keygen -t rsa -N \"\" -f /home/admin/.ssh/id_rsa" 2>&1; '
            _bs_cmd="${_bs_cmd}"'su - admin -c "cat /home/admin/.ssh/id_rsa.pub >> /home/admin/.ssh/authorized_keys && sort -u /home/admin/.ssh/authorized_keys > /tmp/_ak && mv /tmp/_ak /home/admin/.ssh/authorized_keys && chmod 600 /home/admin/.ssh/authorized_keys" 2>&1; '
            _bs_cmd="${_bs_cmd}"'su - admin -c "ssh-keyscan -H localhost >> /home/admin/.ssh/known_hosts 2>/dev/null; sort -u /home/admin/.ssh/known_hosts > /tmp/_kh && mv /tmp/_kh /home/admin/.ssh/known_hosts" 2>&1; '
            _bs_cmd="${_bs_cmd}"'loginctl enable-linger admin 2>/dev/null || true; '
            _bs_cmd="${_bs_cmd}"'printf "%s\n" "admin ALL=(ALL) NOPASSWD: ALL" > /etc/sudoers.d/90-mrhis-nopasswd && chmod 0440 /etc/sudoers.d/90-mrhis-nopasswd; '
            _bs_cmd="${_bs_cmd}"'dnf clean all >/dev/null 2>&1 || true; '
            _bs_cmd="${_bs_cmd}"'{ _blink=/home/admin/bundle; _found=""; for _d in /home/admin/aap-setup /home/admin/ansible-automation-platform-containerized-setup-bundle-*/; do [ -d "${_d}/bundle" ] && { _found="${_d}/bundle"; break; }; done; [ -n "${_found}" ] && { ln -sfn "${_found}" "${_blink}"; chown -h admin:admin "${_blink}"; } || true; }; '
            _bs_cmd="${_bs_cmd}"'echo AAP_BOOTSTRAP_DONE'
                # Fix known inventory issues: bundle_dir nested-quote bug, missing [database], collocated execution_nodes, placeholder lightspeed host
                _bs_cmd="${_bs_cmd}"'; INV=/home/admin/aap-setup/inventory; [ -f "${INV}" ] && python3 -c "
    import re, sys
    with open(\"${INV}\") as f: c = f.read()
    c = re.sub(r\"bundle_dir=.*\", \"bundle_dir=/home/admin/bundle\", c)
    if \"[database]\" not in c: c = c.replace(\"[all:vars]\", \"[database]\naap.prod.spg\n\n[all:vars]\")
    c = re.sub(r\"(\[execution_nodes\]\s*\n)(aap\.prod\.spg[^\n]*)\", r\"\1# \2  # collocated with controller - disabled\", c)
    c = c.replace(\"[ansiblelightspeed]\naap.example.com\", \"# [ansiblelightspeed]\n# aap.example.com\")
    c = re.sub(r\"lightspeed_pg_host=[^\\n]+\", \"lightspeed_pg_host=${AAP_HOSTNAME:-aap.prod.spg}\", c)
    with open(\"${INV}\", \"w\") as f: f.write(c)
    print(\"INV_FIXED\")
    " 2>&1 || true'
            _rwu_root_key_shell "${_aap_nat_ip}" "${_bs_cmd}" | grep -q 'AAP_BOOTSTRAP_DONE' && \
                print_success "Repair AAP: node bootstrap complete." || \
                print_warning "Repair AAP: bootstrap via ${_aap_nat_ip} may have had issues."
        else
            print_warning "Repair AAP: virsh NAT IP not found; using inventory-based bootstrap fallback."
            _rwu_shell "aap" "${_bs_cmd}" "--one-line" 2>&1 | grep -q 'AAP_BOOTSTRAP_DONE' && \
                print_success "Repair AAP: node bootstrap complete via inventory." || \
                print_warning "Repair AAP: inventory bootstrap may have had issues."
        fi

        # Check container state (admin user; fall back to root via _rwu_shell)
        local _aap_ctr_state
        _aap_ctr_state="$(_rwu_admin_shell "aap" \
            'su - admin -c "podman ps 2>/dev/null | grep -q gateway && echo AAP_CTR_UP || echo AAP_CTR_DOWN"' \
            "--one-line" 2>/dev/null || \
          _rwu_shell "aap" \
            'id admin >/dev/null 2>&1 && su - admin -c "podman ps 2>/dev/null | grep -q gateway && echo AAP_CTR_UP || echo AAP_CTR_DOWN" || echo AAP_CTR_DOWN' \
            "--one-line" 2>/dev/null || echo "AAP_CTR_DOWN")"

        if printf '%s\n' "${_aap_ctr_state}" | grep -q 'AAP_CTR_DOWN'; then
            # Containers absent — run the containerised installer
            print_step "Repair AAP: containers not running — starting AAP installer (30-60 min)..."
            # Reset stale database schema (drop+recreate gateway db) if postgresql container is running
            # This prevents migration conflicts from partial prior installs
            local _db_reset_cmd
            _db_reset_cmd='su - admin -c "podman exec postgresql psql -U postgres -tc \"SELECT 1 FROM pg_database WHERE datname='"'"'gateway'"'"'\" 2>/dev/null | grep -q 1" && su - admin -c "podman stop automation-gateway automation-gateway-proxy 2>/dev/null; podman exec postgresql psql -U postgres -c \"DROP DATABASE IF EXISTS gateway;\" && podman exec postgresql psql -U postgres -c \"CREATE DATABASE gateway OWNER gateway;\"" && echo DB_RESET_OK || echo DB_RESET_SKIP'
            if [ -n "${_aap_nat_ip}" ]; then
                _rwu_root_key_shell "${_aap_nat_ip}" "${_db_reset_cmd}" 2>&1 | grep -qE 'DB_RESET_OK|DB_RESET_SKIP' && \
                    print_step "Repair AAP: gateway database reset for clean migration." || true
            else
                _rwu_shell "aap" "${_db_reset_cmd}" "--one-line" 2>&1 | grep -qE 'DB_RESET_OK|DB_RESET_SKIP' && \
                    print_step "Repair AAP: gateway database reset for clean migration." || true
            fi
            local _aap_setup _aap_cols _aap_pb _aap_inv _install_cmd
            _aap_setup="/home/admin/aap-setup"
            _aap_cols="${_aap_setup}/collections"
            _aap_pb="${_aap_cols}/ansible_collections/ansible/containerized_installer/playbooks/install.yml"
            _aap_inv="${_aap_setup}/inventory"
            # Ensure PostgreSQL contrib extensions are present for Automation Hub (hstore),
            # then run the installer with explicit bundle_dir and validate_certs args.
            _install_cmd='if command -v podman >/dev/null 2>&1 && podman ps -a --format "{% raw %}{{.Names}}{% endraw %}" | grep -qx postgresql; then podman start postgresql >/dev/null 2>&1 || true; podman exec postgresql sh -lc "dnf install -y --skip-broken --allowerasing --best --nogpgcheck postgresql-contrib >/dev/null 2>&1 || true" || true; podman exec postgresql psql -U postgres -d postgres -tAc "SELECT 1 FROM pg_available_extensions WHERE name='"'"'hstore'"'"'" | grep -q 1 && echo AAP_PG_HSTORE_OK || echo AAP_PG_HSTORE_WARN; fi; touch /tmp/aap-install.log && chown admin:admin /tmp/aap-install.log; su - admin -c "cd ${_aap_setup} && ANSIBLE_COLLECTIONS_PATHS=${_aap_cols} ansible-playbook -i ${_aap_inv} ${_aap_pb} -e bundle_dir=/home/admin/bundle -e validate_certs=false > /tmp/aap-install.log 2>&1 && echo AAP_INSTALL_OK || { tail -30 /tmp/aap-install.log >&2; echo AAP_INSTALL_FAIL; }"'
            if [ -n "${_aap_nat_ip}" ]; then
                _rwu_root_key_shell "${_aap_nat_ip}" "${_install_cmd}" 2>&1 | tail -30 || \
                    print_warning "Repair AAP: installer run via ${_aap_nat_ip} may have had issues."
            else
                if ! _rwu_admin_shell_spinner "aap" \
                    "if command -v podman >/dev/null 2>&1 && podman ps -a --format \"{% raw %}{{.Names}}{% endraw %}\" | grep -qx postgresql; then podman start postgresql >/dev/null 2>&1 || true; podman exec postgresql sh -lc 'dnf install -y --skip-broken --allowerasing --best --nogpgcheck postgresql-contrib >/dev/null 2>&1 || true' || true; podman exec postgresql psql -U postgres -d postgres -tAc \"SELECT 1 FROM pg_available_extensions WHERE name='hstore'\" | grep -q 1 && echo AAP_PG_HSTORE_OK || echo AAP_PG_HSTORE_WARN; fi; cd ${_aap_setup} && ANSIBLE_COLLECTIONS_PATHS=${_aap_cols} ansible-playbook -i ${_aap_inv} ${_aap_pb} -e bundle_dir=/home/admin/bundle -e validate_certs=false > /tmp/aap-install.log 2>&1 && echo AAP_INSTALL_OK || { tail -20 /tmp/aap-install.log; echo AAP_INSTALL_FAIL; }" \
                    "--timeout 5400"; then
                    print_warning "Repair AAP: installer did not complete cleanly; check /tmp/aap-install.log on ${AAP_IP}."
                fi
            fi
            # Fix TLS key/cert permissions so nginx (UID 999 inside container) can read them.
            # The AAP installer creates certs as 0400 admin:admin; the automation-gateway container
            # runs nginx as UID 999 (no user namespace) which cannot read owner-only files.
            # Also ensure directory traversal is open so the bind-mounted files are reachable.
            local _tls_fix_cmd
            _tls_fix_cmd='chmod o+rx /home/admin /home/admin/aap /home/admin/aap/gateway /home/admin/aap/gateway/etc 2>/dev/null || true; chmod 0444 /home/admin/aap/gateway/etc/gateway.key /home/admin/aap/gateway/etc/gateway.cert /home/admin/aap/gateway/etc/redis.key /home/admin/aap/gateway/etc/redis.cert 2>/dev/null || true; echo TLS_FIX_DONE'
            if [ -n "${_aap_nat_ip}" ]; then
                _rwu_root_key_shell "${_aap_nat_ip}" "${_tls_fix_cmd}" 2>&1 | grep -q 'TLS_FIX_DONE' && \
                    print_step "Repair AAP: gateway TLS permissions fixed." || true
            else
                _rwu_shell "aap" "${_tls_fix_cmd}" "--one-line" 2>&1 | grep -q 'TLS_FIX_DONE' && \
                    print_step "Repair AAP: gateway TLS permissions fixed." || true
            fi
            # Start (or restart) automation-gateway via systemd user service
            local _gw_start_cmd
            _gw_start_cmd='su - admin -c "XDG_RUNTIME_DIR=/run/user/$(id -u admin) DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/$(id -u admin)/bus systemctl --user restart automation-gateway.service 2>&1"; sleep 20; ss -tlnp | grep -q :'"${_aap_https_port}"' && echo GW_UP || echo GW_DOWN'
            if [ -n "${_aap_nat_ip}" ]; then
                _rwu_root_key_shell "${_aap_nat_ip}" "${_gw_start_cmd}" 2>&1 | grep -q 'GW_UP' && \
                    print_success "Repair AAP: automation-gateway started on port ${_aap_https_port}." || \
                    print_warning "Repair AAP: port ${_aap_https_port} not listening after gateway start attempt."
            else
                _rwu_shell "aap" "${_gw_start_cmd}" "--one-line" 2>&1 | grep -q 'GW_UP' && \
                    print_success "Repair AAP: automation-gateway started on port ${_aap_https_port}." || \
                    print_warning "Repair AAP: port ${_aap_https_port} not listening after gateway start attempt."
            fi
        else
            # Containers present but gateway not responding — fix TLS perms and restart via systemd
            print_step "Repair AAP: containers present — fixing TLS perms and restarting automation-gateway..."
            local _ctr_fix_cmd
            _ctr_fix_cmd='chmod o+rx /home/admin /home/admin/aap /home/admin/aap/gateway /home/admin/aap/gateway/etc 2>/dev/null || true; chmod 0444 /home/admin/aap/gateway/etc/gateway.key /home/admin/aap/gateway/etc/gateway.cert /home/admin/aap/gateway/etc/redis.key /home/admin/aap/gateway/etc/redis.cert 2>/dev/null || true; su - admin -c "XDG_RUNTIME_DIR=/run/user/$(id -u admin) DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/$(id -u admin)/bus systemctl --user restart automation-gateway.service 2>&1"; sleep 20; ss -tlnp | grep -q :'"${_aap_https_port}"' && echo GW_UP || echo GW_DOWN'
            if [ -n "${_aap_nat_ip}" ]; then
                _rwu_root_key_shell "${_aap_nat_ip}" "${_ctr_fix_cmd}" 2>&1 | grep -q 'GW_UP' && \
                    print_success "Repair AAP: automation-gateway restarted on port ${_aap_https_port}." || \
                    print_warning "Repair AAP: port ${_aap_https_port} not listening after restart."
            else
                _rwu_shell "aap" "${_ctr_fix_cmd}" "--one-line" 2>&1 | grep -q 'GW_UP' && \
                    print_success "Repair AAP: automation-gateway restarted on port ${_aap_https_port}." || \
                    print_warning "Repair AAP: port ${_aap_https_port} not listening after restart."
            fi
        fi

        if _rwu_probe "AAP (post-repair)" "https://${AAP_IP}:${_aap_https_port}/"; then
            _aap_ok=1
        else
            _repair_failures=$((_repair_failures + 1))
        fi
    fi

    # Optional endpoint probes (reported, but not treated as fatal for the
    # core IdM/Satellite/AAP completion gate).
    if [ "${_gittea_enabled}" -eq 1 ]; then
        if _rwu_probe "Gitea" "${_gittea_ui_url}"; then
            _gittea_ok=1
        else
            _gittea_ok=0
        fi
    fi
    if [ "${_openshift_enabled}" -eq 1 ]; then
        if _rwu_probe "OpenShift" "${_openshift_ui_url}"; then
            _openshift_ok=1
        else
            _openshift_ok=0
        fi
    fi

    # ── Retry probe loop (services may take time to start after repair) ──────
    # After repair actions are applied, services (especially AAP gateway) can take
    # several minutes to fully start. Poll up to MRHIS_WEB_UI_PROBE_RETRIES
    # times (default 10) with MRHIS_WEB_UI_PROBE_INTERVAL seconds (default 90)
    # between attempts before declaring a hard failure.
    local _max_probe_retries="${MRHIS_WEB_UI_PROBE_RETRIES:-10}"
    local _probe_interval="${MRHIS_WEB_UI_PROBE_INTERVAL:-90}"
    local _probe_attempt=1
    while [ "${_repair_failures}" -gt 0 ] && [ "${_probe_attempt}" -lt "${_max_probe_retries}" ]; do
        _probe_attempt=$((_probe_attempt + 1))
        print_step "Web UI(s) still down — re-probe ${_probe_attempt}/${_max_probe_retries} in ${_probe_interval}s (services may still be starting)..."
        sleep_with_spinner "${_probe_interval}" "Waiting for web UI(s) to come up"
        _repair_failures=0
        if [ "${_idm_ok}" -eq 0 ]; then
            if _rwu_probe "IdM (retry ${_probe_attempt})" "https://${IDM_IP}/ipa/ui/"; then
                _idm_ok=1
            else
                _repair_failures=$((_repair_failures + 1))
            fi
        fi
        if [ "${_sat_ok}" -eq 0 ]; then
            if _rwu_probe "Satellite (retry ${_probe_attempt})" "https://${SAT_IP}/users/login"; then
                _sat_ok=1
            else
                _repair_failures=$((_repair_failures + 1))
            fi
        fi
        if [ "${_aap_ok}" -eq 0 ]; then
            if _rwu_probe "AAP (retry ${_probe_attempt})" "https://${AAP_IP}:${_aap_https_port}/"; then
                _aap_ok=1
            else
                _repair_failures=$((_repair_failures + 1))
            fi
        fi
        if [ "${_gittea_enabled}" -eq 1 ] && [ "${_gittea_ok}" -eq 0 ]; then
            if _rwu_probe "Gitea (retry ${_probe_attempt})" "${_gittea_ui_url}"; then
                _gittea_ok=1
            fi
        fi
        if [ "${_openshift_enabled}" -eq 1 ] && [ "${_openshift_ok}" -eq 0 ]; then
            if _rwu_probe "OpenShift (retry ${_probe_attempt})" "${_openshift_ui_url}"; then
                _openshift_ok=1
            fi
        fi
    done
    # ── Summary ─────────────────────────────────────────────────────────────
    echo ""
    printf "  %-12s  https://%s/ipa/ui/      %s\n"     "IdM"       "${IDM_IP}" "$([ "${_idm_ok}" -eq 1 ] && echo '✔ UP' || echo '✘ DOWN')"
    printf "  %-12s  https://%s/users/login  %s\n"  "Satellite"  "${SAT_IP}" "$([ "${_sat_ok}" -eq 1 ] && echo '✔ UP' || echo '✘ DOWN')"
    printf "  %-12s  https://%s:%s/        %s\n"        "AAP"  "${AAP_IP}" "${_aap_https_port}" "$([ "${_aap_ok}" -eq 1 ] && echo '✔ UP' || echo '✘ DOWN')"
    if [ "${_gittea_enabled}" -eq 1 ]; then
        printf "  %-12s  %-28s  %s\n" "Gitea" "${_gittea_ui_url}" "$([ "${_gittea_ok}" -eq 1 ] && echo '✔ UP' || echo '✘ DOWN')"
    fi
    if [ "${_openshift_enabled}" -eq 1 ]; then
        printf "  %-12s  %-28s  %s\n" "OpenShift" "${_openshift_ui_url}" "$([ "${_openshift_ok}" -eq 1 ] && echo '✔ UP' || echo '✘ DOWN')"
    fi
    echo ""

    if [ "${_repair_failures}" -eq 0 ]; then
        print_success "All required Web UIs are reachable and healthy."
        return 0
    fi

    print_error "FATAL: ${_repair_failures} Web UI(s) still unreachable after all repair and retry attempts."
    print_error "IdM, Satellite, and AAP Web UIs must ALL be accessible for the installation to be complete."
    print_error "Review the component logs above, fix the underlying issue, then re-run menu option 9."
    return 1
}

run_container_prescribed_sequence() {
    if ! is_enabled "${MRHIS_AUTO_CONFIG_ON_CONTAINER_ONLY:-1}"; then
        print_step "Container auto-config is disabled (MRHIS_AUTO_CONFIG_ON_CONTAINER_ONLY=${MRHIS_AUTO_CONFIG_ON_CONTAINER_ONLY})."
        return 0
    fi

    if ! preflight_config_as_code_targets; then
        print_step "Prerequisites for container auto-config are missing; auto-running VM provisioning workflow"
        print_step "This will generate kickstarts/OEMDRV, create MRHIS VMs, and continue configuration automatically"
        create_mrhis_vms || return 1
        return 0
    fi

    print_step "Provisioner available; running prescribed config sequence automatically"
    print_step "Prescribed order: IdM -> Satellite -> AAP -> Gitea -> OpenShift"
    run_mrhis_config_as_code || {
        print_warning "Automatic prescribed sequence did not complete cleanly."
        print_step "Attempting Web UI repair pass — all three Web UIs must be accessible before declaring failure..."
        if repair_web_uis; then
            print_success "All Web UIs came up after repair — installation is successful despite earlier errors."
            return 0
        fi
        print_error "FATAL: One or more Web UIs failed to come up after config-as-code failure and repair attempts."
        return 1
    }

    print_success "Automatic prescribed sequence completed."
    print_step "Running hands-free Web UI readiness check and repair pass..."
    if ! repair_web_uis; then
        print_error "FATAL: One or more Web UIs are still unreachable after all repair attempts."
        print_error "Installation cannot be declared complete. All three Web UIs must be accessible."
        return 1
    fi
}

# Wrapper around `podman exec` that ensures the MRHIS provisioner
# container is running before attempting to exec. This avoids noisy
# "can only create exec sessions on running containers" errors when the
# container is stopped or crashed. Emits a short stderr warning and
# returns non-zero when the container cannot be started.
podman_exec_safe() {
    # Usage: podman_exec_safe <podman-exec-args...>
    if ! command -v podman >/dev/null 2>&1; then
        echo "WARN: podman not available; cannot exec" >&2
        return 127
    fi

    # Attempt to ensure the provisioner container is running. This uses the
    # existing ensure_container_running_with_retry helper which is aware of
    # MRHIS_CONTAINER_NAME and runtime mounts.
    if ! ensure_container_running_with_retry >/dev/null 2>&1; then
        echo "WARN: Provisioner container ${MRHIS_CONTAINER_NAME} not running; cannot exec" >&2
        return 254
    fi

    # Forward all args to podman exec unchanged.
    podman exec "$@"
}

run_container_config_only() {
    # If Podman rootless is unavailable, proceed with direct VM provisioning.
    if ! install_container; then
        # Podman/rootless container provisioning unavailable — fall back to
        # the VM-based provisioning workflow (no noisy container-related
        # warnings emitted here; callers may log as needed).
        create_mrhis_vms || return 1
        print_step "Running hands-free Web UI readiness check and repair pass..."
        repair_web_uis || { print_error "FATAL: One or more Web UIs are still unreachable after all repair attempts."; return 1; }
        return 0
    fi

    if ! preflight_config_as_code_targets; then
        print_step "Prerequisites for config-only are missing; auto-running VM provisioning workflow"
        print_step "This will generate kickstarts/OEMDRV, create MRHIS VMs, and continue configuration automatically"
        create_mrhis_vms || return 1
        print_step "Running hands-free Web UI readiness check and repair pass..."
        repair_web_uis || { print_error "FATAL: One or more Web UIs are still unreachable after all repair attempts."; return 1; }
        return 0
    fi

    run_container_prescribed_sequence || return 1
    return 0
}

prompt_deployment_scope() {
    # Ask once per interactive run; default stays local.
    if is_noninteractive || [ "${RUN_ONCE:-0}" = "1" ]; then
        return 0
    fi

    if [ "${DEPLOYMENT_SCOPE_PROMPTED:-0}" = "1" ]; then
        return 0
    fi

    DEPLOYMENT_SCOPE_PROMPTED=1
    print_mrhis_header
    echo "Deployment Scope"
    echo ""
    echo "  0) Exit"
    echo "  1) Local"
    echo "     - this machine: $(hostname -f 2>/dev/null || hostname) [default]"
    echo "  2) Remote systems"
    echo ""
    read -r -p "Choose scope [0-2, default 1]: " _scope_choice
    case "${_scope_choice:-1}" in
        0)
            return 2
            ;;
        2)
            DEPLOYMENT_SCOPE="remote"
            ;;
        *)
            DEPLOYMENT_SCOPE="local"
            ;;
    esac

    read -r -p "Start guided deployment workflow now? [Y/n]: " _guided_choice
    case "${_guided_choice:-Y}" in
        Y|y|"") MRHIS_GUIDED_SCOPE_FLOW=1 ;;
        *) MRHIS_GUIDED_SCOPE_FLOW=0 ;;
    esac
}

detect_host_os_family() {
    local os_id=""
    local os_like=""

    if [ -f /etc/os-release ]; then
        # shellcheck disable=SC1091
        . /etc/os-release
        os_id="${ID:-}"
        os_like="${ID_LIKE:-}"
    fi

    case "${OSTYPE:-}" in
        linux*)
            case "${os_id}:${os_like}" in
                rhel*:*|centos*:*|rocky*:*|almalinux*:*|fedora*:*|*:rhel*|*:fedora*)
                    MRHIS_DETECTED_OS="linux-rhel-family"
                    ;;
                *)
                    MRHIS_DETECTED_OS="linux"
                    ;;
            esac
            ;;
        darwin*) MRHIS_DETECTED_OS="macos" ;;
        msys*|cygwin*|win32*) MRHIS_DETECTED_OS="windows" ;;
        *) MRHIS_DETECTED_OS="unknown" ;;
    esac

    print_step "Detected host OS profile: ${MRHIS_DETECTED_OS}"
    return 0
}
prompt_remote_virtualization_platform() {
    local choice=""
    print_mrhis_header
    echo "Remote Virtualization Platform"
    echo ""
    echo "  0) Back"
    echo "  1) VMware vSphere"
    echo "  2) Nutanix"
    echo "  3) OpenShift"
    echo "  4) OpenShift Virtualization"
    echo "  5) AWS"
    echo "  6) Azure"
    echo "  7) GCP"
    echo ""
    read -r -p "Choose platform [0-7, default 1]: " choice
    case "${choice:-1}" in
        0) return 10 ;;
        2) MRHIS_REMOTE_PLATFORM="nutanix" ;;
        3) MRHIS_REMOTE_PLATFORM="openshift" ;;
        4) MRHIS_REMOTE_PLATFORM="openshift-virt" ;;
        5) MRHIS_REMOTE_PLATFORM="aws" ;;
        6) MRHIS_REMOTE_PLATFORM="azure" ;;
        7) MRHIS_REMOTE_PLATFORM="gcp" ;;
        *) MRHIS_REMOTE_PLATFORM="vmware" ;;
    esac

    print_step "Selected remote platform: ${MRHIS_REMOTE_PLATFORM}"
    print_warning "Remote platform provisioning integration is best-effort; local orchestration path remains primary."
    return 0
}

prompt_install_component_choice() {
    local choice=""
    print_mrhis_header
    echo "Install Target"
    echo ""
    echo "  0) Exit"
    echo "  1) Ansible Automation Platform 2.6"
    echo "  2) IdM 5.0"
    echo "  3) Satellite 6.18"
    echo "  4) MRHIS Integrated Full Stack"
    echo "  5) Gitea (optional)"
    echo "     - AAP + IdM + Satellite"
    echo ""
    read -r -p "Choose component [0-5, default 4]: " choice
    case "${choice:-4}" in
        0)
            print_step "Exiting MRHIS installer by user request."
            exit 0
            ;;
        1) MRHIS_INSTALL_COMPONENT="aap" ;;
        2) MRHIS_INSTALL_COMPONENT="idm" ;;
        3) MRHIS_INSTALL_COMPONENT="satellite" ;;
        5) MRHIS_INSTALL_COMPONENT="gittea" ;;
        *) MRHIS_INSTALL_COMPONENT="full" ;;
    esac
    print_step "Selected install target: ${MRHIS_INSTALL_COMPONENT}"
    return 0
}

run_guided_scope_workflow() {
    local rc=0
    detect_host_os_family || return 1

    if [ "${DEPLOYMENT_SCOPE:-local}" = "local" ]; then
        while true; do
            prompt_local_vm_client
            rc=$?
            if [ "${rc}" -eq 10 ]; then
                return 10
            elif [ "${rc}" -ne 0 ]; then
                return "${rc}"
            fi

            prepare_selected_local_vm_client || return 1

            while true; do
                prompt_install_component_choice
                rc=$?
                if [ "${rc}" -eq 10 ]; then
                    break
                elif [ "${rc}" -ne 0 ]; then
                    return "${rc}"
                fi

                print_step "Starting kickstart generation and installation workflow for selected target"
                case "${MRHIS_INSTALL_COMPONENT:-full}" in
                    satellite)
                        install_satellite_only || return 1
                        ;;
                    idm)
                        install_idm_only || return 1
                        ;;
                    aap)
                        install_aap_only || return 1
                        ;;
                    gittea)
                        install_gittea_only || return 1
                        ;;
                    full)
                        run_container_config_only || return 1
                        ;;
                    *)
                        print_warning "Unknown component target '${MRHIS_INSTALL_COMPONENT}'."
                        return 1
                        ;;
                esac

                print_success "Guided deployment workflow completed."
                return 0
            done
        done
    else
        while true; do
            prompt_remote_virtualization_platform
            rc=$?
            if [ "${rc}" -eq 10 ]; then
                return 10
            elif [ "${rc}" -ne 0 ]; then
                return "${rc}"
            fi

            while true; do
                prompt_install_component_choice
                rc=$?
                if [ "${rc}" -eq 10 ]; then
                    break
                elif [ "${rc}" -ne 0 ]; then
                    return "${rc}"
                fi

                print_step "Starting kickstart generation and installation workflow for selected target"
                case "${MRHIS_INSTALL_COMPONENT:-full}" in
                    satellite)
                        install_satellite_only || return 1
                        ;;
                    idm)
                        install_idm_only || return 1
                        ;;
                    aap)
                        install_aap_only || return 1
                        ;;
                    full)
                        run_container_config_only || return 1
                        ;;
                    *)
                        print_warning "Unknown component target '${MRHIS_INSTALL_COMPONENT}'."
                        return 1
                        ;;
                esac

                print_success "Guided deployment workflow completed."
                return 0
            done
        done
    fi
}

run_component_config_scope() {
    local scope="$1"
    local sat_pre_use_idm="${SATELLITE_PRE_USE_IDM:-false}"
    local -a targets=()

    if [ "${MRHIS_EXECUTION_MODE:-local}" = "container" ]; then
        if ! install_container; then
            MRHIS_EXECUTION_MODE="local"
            # Attempt to ensure VMs exist so component configuration can proceed
            create_mrhis_vms || print_warning "VM creation did not complete. Component configuration may be skipped."
        fi
    fi

    case "${scope}" in
        idm)
            targets=("idm:${IDM_IP}")
            ;;
        satellite)
            if [ "${sat_pre_use_idm}" = "true" ]; then
                targets=("idm:${IDM_IP}" "satellite:${SAT_IP}")
            else
                targets=("satellite:${SAT_IP}")
            fi
            ;;
        aap)
            targets=("aap:${AAP_IP}")
            ;;
        gittea)
            targets=("gittea:${GITTEA_IP}")
            ;;
        openshift|openstack)
            targets=("openshift:${OPENSHIFT_IP}")
            ;;
        rhis)
            targets=("idm:${IDM_IP}" "satellite:${SAT_IP}" "aap:${AAP_IP}")
            ;;
        fullstack|all)
            targets=("idm:${IDM_IP}" "satellite:${SAT_IP}" "aap:${AAP_IP}" "gittea:${GITTEA_IP}" "openshift:${OPENSHIFT_IP}")
            ;;
        rhis-aap)
            # No AAP install – only ensures the RHIS builder objects exist in a
            # running AAP Controller.  Runs the standalone rhis_aap_config.yml
            # playbook directly on the platform_installer host.
            targets=("aap:${AAP_IP}")
            ;;
        *)
            print_warning "Unknown component scope: ${scope}"
            return 1
            ;;
    esac

    if ! preflight_config_as_code_targets "${targets[@]}"; then
        print_step "Prerequisites for ${scope}-only are missing; auto-running VM provisioning workflow"

        case "${scope}" in
            satellite)
                create_satellite_vm_only || return 1
                ;;
            idm)
                create_idm_vm_only || return 1
                ;;
            aap)
                create_aap_vm_only || return 1
                ;;
            gittea)
                create_gittea_vm_only || return 1
                ;;
            openshift|openstack|rhis|fullstack|all)
                create_mrhis_vms || return 1
                ;;
            rhis-aap)
                # No VM creation needed — assumes AAP is already running.
                print_step "rhis-aap scope: assuming AAP is already running; skipping VM provisioning."
                ;;
            *)
                create_mrhis_vms || return 1
                return 0
                ;;
        esac

        preflight_config_as_code_targets "${targets[@]}" || return 1
    fi

    MRHIS_COMPONENT_SCOPE="${scope}" run_mrhis_config_as_code || return 1
    return 0
}

ensure_satellite_content_profile_bootstrap() {
                local profile_path="${MRHIS_HOST_VARS_DIR}/satellite_content_profile.yml"
                local sync_date_default
                local sync_date
                local include_product_links="1"
                local include_repo_sets="1"
                local answer=""

                mkdir -p "${MRHIS_HOST_VARS_DIR}" || return 1

                if [ -f "${profile_path}" ]; then
                                print_step "Satellite content profile already exists: ${profile_path}"
                                return 0
                fi

                # weekly Sunday 02:00 by default
                sync_date_default="$(date +%Y-%m-%d) 02:00:00"
                sync_date="${sync_date_default}"

                if ! is_noninteractive && [ "${RUN_ONCE:-0}" != "1" ]; then
                                echo ""
                                print_step "Satellite first-run bootstrap: generating host_vars/satellite_content_profile.yml"
                                read -r -p "Create default Satellite content profile now? [Y/n]: " answer
                                if [[ "${answer:-Y}" =~ ^[Nn]$ ]]; then
                                                print_warning "Skipping automatic profile bootstrap by user choice."
                                                return 0
                                fi

                                read -r -p "Weekly sync date/time (YYYY-MM-DD HH:MM:SS) [${sync_date_default}]: " answer
                                if [ -n "${answer}" ]; then
                                                sync_date="${answer}"
                                fi

                                read -r -p "Attach sync plan to common default products (best-effort)? [Y/n]: " answer
                                if [[ "${answer:-Y}" =~ ^[Nn]$ ]]; then
                                                include_product_links="0"
                                fi

                                read -r -p "Enable baseline Red Hat repository sets (RHEL 9/10 + Satellite Client)? [Y/n]: " answer
                                if [[ "${answer:-Y}" =~ ^[Nn]$ ]]; then
                                                include_repo_sets="0"
                                fi
                fi

                cat > "${profile_path}" <<EOF
---
# satellite_content_profile.yml — generated by mrhis_install.sh (Satellite bootstrap)

satellite_username: "admin"
satellite_password: "{{ sat_admin_pass | default(global_admin_password) | default('') }}"

satellite_organization: "{{ sat_org | default('REDHAT') }}"
satellite_location: "{{ sat_loc | default('CORE') }}"

# Service/UI endpoint policy: internal network only
satellite_url: "https://${SAT_IP:-10.168.128.1}"

sync_plans:
    - name: "weekly_mrhis_sync"
      interval: "weekly"
      enabled: true
      sync_date: "${sync_date}"

EOF

                if [ "${include_product_links}" = "1" ]; then
                                cat >> "${profile_path}" <<'EOF'
product_plans:
    - name: "Red Hat Enterprise Linux for x86_64"
      plan: "weekly_mrhis_sync"
    - name: "Red Hat Satellite Client"
      plan: "weekly_mrhis_sync"
    - name: "Red Hat Ansible Automation Platform"
      plan: "weekly_mrhis_sync"
    - name: "Red Hat Enterprise Linux Server"
      plan: "weekly_mrhis_sync"

EOF
                else
                                cat >> "${profile_path}" <<'EOF'
product_plans: []

EOF
                fi

                if [ "${include_repo_sets}" = "1" ]; then
                                cat >> "${profile_path}" <<'EOF'
repository_sets:
    - name: "Red Hat Enterprise Linux 9 for x86_64 - BaseOS (RPMs)"
      product: "Red Hat Enterprise Linux for x86_64"
      repository_list:
        - releasever: "9"
          basearch: "x86_64"
    - name: "Red Hat Enterprise Linux 9 for x86_64 - AppStream (RPMs)"
      product: "Red Hat Enterprise Linux for x86_64"
      repository_list:
        - releasever: "9"
          basearch: "x86_64"
    - name: "Red Hat Satellite Client 6 for RHEL 9 x86_64 (RPMs)"
      product: "Red Hat Enterprise Linux for x86_64"
      repository_list:
        - basearch: "x86_64"
    - name: "Red Hat Enterprise Linux 10 for x86_64 - BaseOS (RPMs)"
      product: "Red Hat Enterprise Linux for x86_64"
      repository_list:
        - releasever: "10"
          basearch: "x86_64"
    - name: "Red Hat Enterprise Linux 10 for x86_64 - AppStream (RPMs)"
      product: "Red Hat Enterprise Linux for x86_64"
      repository_list:
        - releasever: "10"
          basearch: "x86_64"

EOF
                else
                                cat >> "${profile_path}" <<'EOF'
repository_sets: []

EOF
                fi

                cat >> "${profile_path}" <<'EOF'
lifecycle_environments:
    - name: "DEV_RHEL_9_X86_64"
      label: "dev_rhel_9_x86_64"
      description: "Development lifecycle for RHEL 9"
