sync_mrhis_external_hosts_entries() {
    local block_file_internal block_file_external rendered_file
    local vm ext_ip fqdn alias internal_ip row
    local sat_ip sat_fqdn sat_alias
    local aap_ip aap_fqdn aap_alias
    local idm_ip idm_fqdn idm_alias
    local gittea_ip gittea_fqdn gittea_alias
    local openshift_ip openshift_fqdn openshift_alias
    local installer_ip installer_fqdn installer_alias
    local -a rows_internal=()
    local -a rows_external=()
    local -a specs=()
    while IFS='|' read -r vm internal_ip fqdn alias; do
        specs+=("${vm}:${fqdn}:${alias}:${internal_ip}")
    done < <(mrhis_selected_node_specs)

    if [ "${#specs[@]}" -eq 0 ]; then
        print_step "No selected nodes resolved for /etc/hosts sync yet."
        return 0
    fi

     # ── Optional Ansible path (internal /etc/hosts block only) ───────────────
     # Default to bash-based sync for reliability; enable Ansible path explicitly
     # with MRHIS_USE_ANSIBLE_HOSTS_SYNC=1 when needed for debugging.
    local _entries_json
     if is_enabled "${MRHIS_USE_ANSIBLE_HOSTS_SYNC:-0}"; then
        _entries_json="["
        for spec in "${specs[@]}"; do
            vm="${spec%%:*}"
            fqdn="${spec#*:}"; fqdn="${fqdn%%:*}"
            alias="${spec#*:*:}"; alias="${alias%%:*}"
            internal_ip="${spec##*:}"
            [ -n "${internal_ip:-}" ] || continue
            [ -n "${fqdn:-}" ] || continue
            [ "${_entries_json}" = "[" ] || _entries_json+=","
            _entries_json+="{\"ip\":\"${internal_ip}\",\"fqdn\":\"${fqdn}\",\"shortname\":\"${alias:-${vm}}\"}"
        done
        _entries_json+="]"
        if [ -n "${_entries_json}" ] && \
           run_local_role "mrhis_hosts_sync" "installer" \
               --extra-vars "{\"mrhis_hosts_entries\": ${_entries_json}}" 2>/dev/null; then
            : # Internal block handled by Ansible; fall through to handle external IPs below
        else
            print_warning "Ansible role mrhis_hosts_sync unavailable; using bash path for internal /etc/hosts block"
        fi
    else
        print_step "Using bash /etc/hosts sync path (MRHIS_USE_ANSIBLE_HOSTS_SYNC=0)."
    fi
    # ── Bash fallback (and external IP handling) ────────────────────────────

    # Build a single /etc/hosts row while avoiding duplicate name tokens
    # (e.g. 'idm idm' when FQDN and alias are the same).
    _build_hosts_row() {
        local ip="$1"; shift
        local token
        local row="${ip}"
        local seen=" "

        [ -n "${ip}" ] || return 1

        for token in "$@"; do
            [ -n "${token}" ] || continue
            case "${seen}" in
                *" ${token} "*)
                    continue
                    ;;
            esac
            row+=" ${token}"
            seen+="${token} "
        done

        printf '%s\n' "${row}"
        return 0
    }

    if is_enabled "${MRHIS_SYNC_EXTERNAL_HOSTS:-0}"; then
        if ! command -v virsh >/dev/null 2>&1; then
            print_warning "Skipping /etc/hosts external-entry sync: virsh not found."
            return 0
        fi
    fi

    sat_ip="${SAT_IP:-10.168.128.1}"
    sat_fqdn="${SAT_HOSTNAME:-satellite.${DOMAIN:-prod.spg}}"
    sat_alias="${SAT_ALIAS:-satellite}"
    row="$(_build_hosts_row "${sat_ip}" "${sat_fqdn}" "${sat_alias}" 2>/dev/null || true)"
    [ -n "${row}" ] && rows_internal+=("${row}")

    aap_ip="${AAP_IP:-10.168.128.2}"
    aap_fqdn="${AAP_HOSTNAME:-aap.${DOMAIN:-prod.spg}}"
    aap_alias="${AAP_ALIAS:-aap}"
    row="$(_build_hosts_row "${aap_ip}" "${aap_fqdn}" "${aap_alias}" 2>/dev/null || true)"
    [ -n "${row}" ] && rows_internal+=("${row}")

    idm_ip="${IDM_IP:-10.168.128.3}"
    idm_fqdn="${IDM_HOSTNAME:-idm.${DOMAIN:-prod.spg}}"
    idm_alias="${IDM_ALIAS:-idm}"
    row="$(_build_hosts_row "${idm_ip}" "${idm_fqdn}" "${idm_alias}" 2>/dev/null || true)"
    [ -n "${row}" ] && rows_internal+=("${row}")

    gittea_ip="${GITTEA_IP:-10.168.128.4}"
    gittea_fqdn="${GITTEA_HOSTNAME:-gittea.${DOMAIN:-prod.spg}}"
    gittea_alias="${GITTEA_ALIAS:-gittea}"
    row="$(_build_hosts_row "${gittea_ip}" "${gittea_fqdn}" "${gittea_alias}" 2>/dev/null || true)"
    [ -n "${row}" ] && rows_internal+=("${row}")

    openshift_ip="${OPENSHIFT_IP:-10.168.128.5}"
    openshift_fqdn="${OPENSHIFT_HOSTNAME:-openshift.${DOMAIN:-prod.spg}}"
    openshift_alias="${OPENSHIFT_ALIAS:-openshift}"
    row="$(_build_hosts_row "${openshift_ip}" "${openshift_fqdn}" "${openshift_alias}" 2>/dev/null || true)"
    [ -n "${row}" ] && rows_internal+=("${row}")

    installer_ip="${INSTALLER_IP:-${HOST_INT_IP:-10.168.0.1}}"
    installer_fqdn="${INSTALLER_HOSTNAME:-installer.${DOMAIN:-prod.spg}}"
    installer_alias="${INSTALLER_ALIAS:-installer}"
    row="$(_build_hosts_row "${installer_ip}" "${installer_fqdn}" "${installer_alias}" 2>/dev/null || true)"
    [ -n "${row}" ] && rows_internal+=("${row}")

    for spec in "${specs[@]}"; do
        vm="${spec%%:*}"
        fqdn="${spec#*:}"; fqdn="${fqdn%%:*}"
        alias="${spec#*:*:}"; alias="${alias%%:*}"
        internal_ip="${spec##*:}"

        if ! is_enabled "${MRHIS_SYNC_EXTERNAL_HOSTS:-0}"; then
            continue
        fi

        ext_ip="$(sudo -n virsh domifaddr "${vm}" 2>/dev/null | awk '/ipv4/ {print $4}' | cut -d/ -f1 | awk '$1 !~ /^10\.168\./ {print; exit}' || true)"
        [ -n "${ext_ip}" ] || continue

        row="$(_build_hosts_row "${ext_ip}" "${fqdn}" "${alias}" 2>/dev/null || true)"
        [ -n "${row}" ] && rows_external+=("${row}")
    done

    if [ "${#rows_internal[@]}" -eq 0 ] && [ "${#rows_external[@]}" -eq 0 ]; then
        print_step "No MRHIS VM addresses discovered for /etc/hosts sync yet."
        return 0
    fi

    block_file_internal="$(mktemp /tmp/mrhis-hosts-int-block.XXXXXX)"
    block_file_external="$(mktemp /tmp/mrhis-hosts-ext-block.XXXXXX)"
    rendered_file="$(mktemp /tmp/mrhis-hosts-rendered.XXXXXX)"

    if [ "${#rows_internal[@]}" -gt 0 ]; then
        {
            echo "# BEGIN RHIS INTERNAL HOSTS"
            echo "# Generated by MRHIS — managed block. Do not hand-edit this block."
            echo "# Reminder: The internal MRHIS network defaults to 10.168.0.0/16. You can"
            echo "# change these values during installer prompts or in ~/.ansible/conf/env.yml"
            echo "# (the installer persists answers there). Ensure the installer node has an"
            echo "# entry on the internal network (gateway/DNS at INSTALLER_IP)."
            echo "#"
            echo "# Variables populated from ~/.ansible/conf/env.yml (if present):"
            echo "# SAT_IP, AAP_IP, IDM_IP, INSTALLER_IP, INTERNAL_NETWORK"
            echo "# BEGIN MRHIS INTERNAL HOSTS"
            for row in "${rows_internal[@]}"; do
                printf '%s\n' "${row}"
            done
            echo "# END MRHIS INTERNAL HOSTS"
            echo "# END RHIS INTERNAL HOSTS"
        } > "${block_file_internal}"
    else
        : > "${block_file_internal:-/dev/null}"
    fi

    if [ "${#rows_external[@]}" -gt 0 ]; then
        {
            echo "# BEGIN MRHIS EXTERNAL HOSTS"
            for row in "${rows_external[@]}"; do
                printf '%s\n' "${row}"
            done
            echo "# END MRHIS EXTERNAL HOSTS"
        } > "${block_file_external}"
    else
        : > "${block_file_external:-/dev/null}"
    fi

    # Remove previously managed MRHIS blocks, then append refreshed blocks.
    sudo awk '
        /^# BEGIN RHIS INTERNAL HOSTS$/      {in_rhis=1; next}
        /^# END RHIS INTERNAL HOSTS$/        {in_rhis=0; next}
        /^# BEGIN MRHIS INTERNAL HOSTS$/ {in_internal=1; next}
        /^# END MRHIS INTERNAL HOSTS$/   {in_internal=0; next}
        /^# BEGIN MRHIS EXTERNAL HOSTS$/ {in_external=1; next}
        /^# END MRHIS EXTERNAL HOSTS$/   {in_external=0; next}
        !in_rhis && !in_internal && !in_external { print }
    ' /etc/hosts > "${rendered_file}" || true

    {
        cat "${rendered_file}"
        [ -s "${block_file_internal}" ] && cat "${block_file_internal}"
        [ -s "${block_file_external}" ] && cat "${block_file_external}"
    } > "${rendered_file}.new" || true
    mv -f "${rendered_file}.new" "${rendered_file}" >/dev/null 2>&1 || true

    if [ -s "${rendered_file}" ] && sudo cp -f "${rendered_file}" /etc/hosts 2>/dev/null; then
        print_success "Updated /etc/hosts with MRHIS internal/external interface entries."
    else
        print_warning "Could not update /etc/hosts with MRHIS internal/external interface entries."
    fi

    rm -f "${block_file_internal}" "${block_file_external}" "${rendered_file}" || true
    return 0
}

preflight_config_as_code_targets() {
    local missing_vm=0
    local unreachable_target=0
    local vm_name vm_state target_ip configured_ip
    local wait_deadline wait_start now remaining elapsed
    local last_progress_log=0
    local show_detail_logs=0
    local target_count=0
    local missing_count=0
    local -a missing_vms=()
    local all_ready reached
    local -a vm_specs

    if [ "$#" -gt 0 ]; then
        vm_specs=("$@")
    else
        vm_specs=(
            "satellite:${SAT_IP}"
            "aap:${AAP_IP}"
            "idm:${IDM_IP}"
        )
    fi

    if ! command -v virsh >/dev/null 2>&1; then
        print_warning "virsh not found; cannot verify MRHIS VM state before config-as-code."
        return 0
    fi

    discover_vm_ipv4() {
        local vm="$1"
        local configured_ip="${2:-}"
        local discovered_ips=""
        local ip=""

        if [ -n "${configured_ip}" ]; then
            # Global policy: always target configured internal MRHIS IPs.
            printf '%s\n' "${configured_ip}"
            return 0
        fi

        discovered_ips="$(timeout 10 sudo -n virsh domifaddr "$vm" 2>/dev/null \
            | awk '/ipv4/ {print $4}' \
            | cut -d/ -f1 \
            | grep -E '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$' || true)"

        # Prefer the configured internal address when libvirt reports multiple NICs.
        if [ -n "${configured_ip}" ] && printf '%s\n' "${discovered_ips}" | grep -Fxq "${configured_ip}"; then
            printf '%s\n' "${configured_ip}"
            return 0
        fi

        ip="$(printf '%s\n' "${discovered_ips}" | grep -E '^10\.168\.' | head -1 || true)"
        if [ -n "${ip}" ]; then
            printf '%s\n' "${ip}"
            return 0
        fi

        printf '%s\n' "${discovered_ips}" | head -1
    }

    resolve_preflight_ip() {
        local vm="$1"
        local configured="$2"
        local discovered=""

        if [ -n "${configured}" ]; then
            printf '%s\n' "$configured"
            return 0
        fi

        if probe_ssh_endpoint "$configured"; then
            printf '%s\n' "$configured"
            return 0
        fi

        discovered="$(discover_vm_ipv4 "$vm" "$configured" || true)"
        if [ -n "$discovered" ]; then
            printf '%s\n' "$discovered"
            return 0
        fi

        printf '%s\n' "$configured"
    }

    # Build a human-friendly display list resolving discovered IPs when possible
    local -a _display_targets=()
    for spec in "${vm_specs[@]}"; do
        vm_name="${spec%%:*}"
        configured_ip="${spec#*:}"
        resolved_ip="$(discover_vm_ipv4 "${vm_name}" "${configured_ip}" 2>/dev/null || true)"
        if [ -n "${resolved_ip}" ]; then
            _display_targets+=("${vm_name}:${resolved_ip}")
        elif [ -n "${configured_ip}" ]; then
            _display_targets+=("${vm_name}:${configured_ip}")
        else
            _display_targets+=("${vm_name}:(unset)")
        fi
    done

    print_step "Preflight: validating MRHIS VM state and internal SSH reachability"
    print_step "Preflight targets: ${_display_targets[*]}"
    target_count="${#vm_specs[@]}"
    for spec in "${vm_specs[@]}"; do
        vm_name="${spec%%:*}"
        configured_ip="${spec#*:}"

        if ! sudo virsh dominfo "$vm_name" >/dev/null 2>&1; then
            missing_vms+=("${vm_name}")
            missing_count=$((missing_count + 1))
            missing_vm=1
            continue
        fi

        vm_state="$(sudo virsh domstate "$vm_name" 2>/dev/null | tr -d '[:space:]' || true)"
        if [ "$vm_state" != "running" ]; then
            print_warning "Required VM is not running: ${vm_name} (state=${vm_state:-unknown})"
            missing_vm=1
            continue
        fi

        target_ip="$(resolve_preflight_ip "${vm_name}" "${configured_ip}")"
        if [ "$target_ip" != "$configured_ip" ]; then
            print_step "Preflight target update: ${vm_name} configured=${configured_ip} discovered=${target_ip}"
        fi

        if ! probe_ssh_endpoint "$target_ip"; then
            unreachable_target=1
        fi
    done

    if [ "$missing_vm" -ne 0 ]; then
        if [ "$missing_count" -eq "$target_count" ]; then
            print_step "Expected on fresh installs or right after --DEMOKILL: target VMs are not defined yet (${missing_vms[*]})."
        else
            for vm_name in "${missing_vms[@]}"; do
                print_warning "Required VM is not defined: ${vm_name}"
            done
        fi
        print_step "Preflight prerequisites are not met yet (expected during fresh installs / post-DEMOKILL)."
        if is_demo && [ "${MRHIS_PREFLIGHT_DEMO_TOLERATE:-1}" = "1" ]; then
            print_warning "DEMO mode: tolerating preflight VM-state failures and continuing."
            return 0
        fi
        return 1
    fi

    if [ "$unreachable_target" -ne 0 ]; then
        # Progress-bar helper — draws/updates a single line in place.
        # Usage: _ssh_progress <elapsed> <timeout> <detail_mode> [warn_msg]
        _ssh_progress() {
            local elapsed="$1" timeout="$2" detail="$3" warn_msg="${4:-}"
            local pct=$(( elapsed * 100 / timeout ))
            [ "$pct" -gt 100 ] && pct=100
            local filled=$(( pct * 30 / 100 ))
            local empty=$(( 30 - filled ))
            local bar=""
            local i
            for (( i=0; i<filled; i++ )); do bar="${bar}█"; done
            for (( i=0; i<empty;  i++ )); do bar="${bar}░"; done
            local remaining=$(( timeout - elapsed ))
            if [ "$detail" -eq 1 ] && [ -n "$warn_msg" ]; then
                # Warn lines go on a new line so they are preserved in logs
                printf '\r\033[K'
                echo -e "${RED}[WARNING]${NC} ${warn_msg}"
            fi
            printf '\r\033[K'"[SSH-WAIT] [%s] %3d%%  %ds/%ds (~%ds remaining)" \
                "${bar}" "${pct}" "${elapsed}" "${timeout}" "${remaining}"
        }

        printf '\n'
        : ${MRHIS_INTERNAL_SSH_WAIT_TIMEOUT:=600}
        : ${MRHIS_INTERNAL_SSH_WAIT_INTERVAL:=5}
        : ${MRHIS_INTERNAL_SSH_WARN_GRACE:=30}
        : ${MRHIS_INTERNAL_SSH_LOG_EVERY:=60}
        # Progress/logging state initialization
        last_progress_log=0
        show_detail_logs=0
        print_step "Waiting for internal SSH readiness (timeout=${MRHIS_INTERNAL_SSH_WAIT_TIMEOUT}s)"
        wait_start="$(date +%s)"
        wait_deadline=$(( wait_start + MRHIS_INTERNAL_SSH_WAIT_TIMEOUT ))

        while true; do
            all_ready=1
            local _unreachable_vms=()
            for spec in "${vm_specs[@]}"; do
                vm_name="${spec%%:*}"
                configured_ip="${spec#*:}"

                vm_state="$(sudo virsh domstate "$vm_name" 2>/dev/null | tr -d '[:space:]' || true)"
                if [ "$vm_state" != "running" ]; then
                    print_warning "${vm_name} became non-running during preflight (state=${vm_state:-unknown}); attempting start"
                    sudo virsh start "$vm_name" >/dev/null 2>&1 || true
                    all_ready=0
                    continue
                fi

                target_ip="$(resolve_preflight_ip "${vm_name}" "${configured_ip}")"
                if probe_ssh_endpoint "$target_ip"; then
                    reached=1
                else
                    reached=0
                    all_ready=0
                    _unreachable_vms+=("${vm_name}(${target_ip})")
                fi
            done

            if [ "$all_ready" -eq 1 ]; then
                # Clear the progress line before printing success
                printf '\r\033[K\n'
                break
            fi

            now="$(date +%s)"
            if [ "$now" -ge "$wait_deadline" ]; then
                printf '\r\033[K\n'
                print_warning "MRHIS VMs exist, but internal SSH did not become reachable before timeout."
                print_warning "Check VM console output and network config for the 10.168.0.0/16 interfaces."
                if is_demo && [ "${MRHIS_PREFLIGHT_DEMO_TOLERATE:-1}" = "1" ]; then
                    print_warning "DEMO mode: tolerating SSH preflight timeout and continuing."
                    return 0
                fi
                return 1
            fi

            elapsed=$(( now - wait_start ))

            if [ "$elapsed" -ge "${MRHIS_INTERNAL_SSH_WARN_GRACE}" ]; then
                show_detail_logs=1
            fi

            if [ "$show_detail_logs" -eq 1 ] && \
               [ $((now - last_progress_log)) -ge "${MRHIS_INTERNAL_SSH_LOG_EVERY}" ]; then
                local _detail_msg="Still waiting: ${_unreachable_vms[*]:-} (${elapsed}s/${MRHIS_INTERNAL_SSH_WAIT_TIMEOUT}s)"
                _ssh_progress "$elapsed" "${MRHIS_INTERNAL_SSH_WAIT_TIMEOUT}" 1 "$_detail_msg"
                last_progress_log="$now"
            else
                _ssh_progress "$elapsed" "${MRHIS_INTERNAL_SSH_WAIT_TIMEOUT}" 0
            fi

            sleep "$MRHIS_INTERNAL_SSH_WAIT_INTERVAL"
        done
    fi

    print_success "Preflight passed: MRHIS VMs are running and reachable on the internal network."
    return 0
}

# ---------------------------------------------------------------------------
# validate_headless_config
#
# Standalone pre-flight checker for headless / non-interactive deployments.
# Checks required variables per menu choice, system requirements, commands,
# SSH keys, IP/FQDN format, storage (≥300 GB), memory (≥64 GB), and CDN/DNS
# reachability.
#
# Called by --validate / --preflight, or automatically before a non-interactive
# run when PRESEED_ENV_FILE is loaded.
# ---------------------------------------------------------------------------
validate_headless_config() {
    local choice="${MENU_CHOICE:-${CLI_MENU_CHOICE:-5}}"

    # Self-contained ANSI helpers (callable before main print_* are defined)
    local _vRED='\033[0;31m'
    local _vGREEN='\033[0;32m'
    local _vYELLOW='\033[1;33m'
    local _vBLUE='\033[0;34m'
    local _vNC='\033[0m'
    local VPASS=0 VWARN=0 VFAIL=0

    _vok()   { printf "${_vGREEN}✓${_vNC} %s\n" "$1"; (( VPASS++ )) || true; }
    _vwarn() { printf "${_vYELLOW}⚠${_vNC} %s\n" "$1"; (( VWARN++ )) || true; }
    _vfail() { printf "${_vRED}✗${_vNC} %s\n"   "$1"; (( VFAIL++ )) || true; }
    _vhead() { printf "\n${_vBLUE}━━ %s${_vNC}\n" "$1"; }

    printf "${_vBLUE}╔══════════════════════════════════════════════════════════════╗${_vNC}\n"
    printf "${_vBLUE}║  MRHIS Headless Environment Validation                       ║${_vNC}\n"
    printf "${_vBLUE}╚══════════════════════════════════════════════════════════════╝${_vNC}\n\n"

    # ── Env file check ──────────────────────────────────────────────────────────
    _vhead "Environment File"
    if [ -n "${PRESEED_ENV_FILE:-}" ]; then
        if [ -f "${PRESEED_ENV_FILE}" ]; then
            _vok "Env file found: ${PRESEED_ENV_FILE}"
        else
            _vwarn "Env file not found: ${PRESEED_ENV_FILE} (relying on already-exported vars)"
        fi
    else
        _vwarn "--env-file not specified; relying on already-exported environment"
    fi

    # ── Required variables per menu choice ─────────────────────────────────────
    _vhead "Required Variables (menu choice ${choice})"
    local -a required_vars=()
    local mode_label=""
    case "${choice}" in
        1|2)
            required_vars=(RH_USER RH_PASS ADMIN_PASS)
            mode_label="Local App / Container"
            ;;
        3)
            required_vars=(IDM_IP IDM_HOSTNAME SAT_IP SAT_HOSTNAME AAP_IP AAP_HOSTNAME ADMIN_PASS)
            mode_label="Virt-Manager Only"
            ;;
        4)
            required_vars=(RH_USER RH_PASS ADMIN_PASS ADMIN_USER DOMAIN
                           IDM_IP IDM_HOSTNAME IDM_DS_PASS
                           SAT_IP SAT_HOSTNAME SAT_ORG SAT_LOC
                           AAP_IP AAP_HOSTNAME HUB_TOKEN)
            mode_label="Full Setup (Local + Virt-Manager)"
            ;;
        5)
            required_vars=(RH_USER RH_PASS ADMIN_PASS ADMIN_USER DOMAIN
                           IDM_IP IDM_HOSTNAME IDM_DS_PASS
                           SAT_IP SAT_HOSTNAME SAT_ORG SAT_LOC
                           AAP_IP AAP_HOSTNAME HUB_TOKEN)
            mode_label="Full Setup (Container + Virt-Manager)"
            ;;
        7)
            required_vars=(RH_USER RH_PASS ADMIN_PASS DOMAIN IDM_DS_PASS
                           IDM_IP SAT_IP AAP_IP HUB_TOKEN)
            mode_label="Full Auto (Container + Provision + Config)"
            ;;
        9)
            required_vars=(RH_USER RH_PASS ADMIN_PASS DOMAIN SAT_IP SAT_HOSTNAME SAT_ORG SAT_LOC)
            mode_label="Satellite 6.18 Only"
            ;;
        10)
            required_vars=(RH_USER RH_PASS ADMIN_PASS DOMAIN IDM_IP IDM_HOSTNAME IDM_DS_PASS)
            mode_label="IdM 5.0 Only"
            ;;
        11)
            required_vars=(RH_USER RH_PASS ADMIN_PASS DOMAIN AAP_IP AAP_HOSTNAME HUB_TOKEN)
            mode_label="AAP 2.6 Only"
            ;;
        *)
            _vfail "Unknown menu choice: ${choice} (valid: 1-5, 7, 9-11)"
            ;;
    esac
    printf "  Mode: %s\n" "${mode_label}"
    local var val
    for var in "${required_vars[@]}"; do
        val="${!var:-}"
        if [ -z "${val}" ]; then
            _vfail "${var} is required but not set"
        else
            if [[ "${var}" == *PASS* ]] || [[ "${var}" == *TOKEN* ]] || [[ "${var}" == *SECRET* ]]; then
                val="***REDACTED***"
            fi
            _vok "${var} is set (${val})"
        fi
    done

    _vhead "Credential Pair Consistency"
    if { [ -n "${RH_USER:-}" ] && [ -z "${RH_PASS:-}" ]; } || { [ -z "${RH_USER:-}" ] && [ -n "${RH_PASS:-}" ]; }; then
        _vfail "RH_USER and RH_PASS must be set together"
    else
        _vok "RH_USER / RH_PASS pairing is consistent"
    fi
    if { [ -n "${CDN_ORGANIZATION_ID:-}" ] && [ -z "${CDN_SAT_ACTIVATION_KEY:-}" ]; } || { [ -z "${CDN_ORGANIZATION_ID:-}" ] && [ -n "${CDN_SAT_ACTIVATION_KEY:-}" ]; }; then
        _vwarn "CDN_ORGANIZATION_ID and CDN_SAT_ACTIVATION_KEY should be set together when using activation-key registration"
    else
        _vok "CDN activation-key pairing is consistent"
    fi
    if { [ -n "${RHC_ORGANIZATION_ID:-}" ] && [ -z "${RHC_ACTIVATION_KEY:-}" ]; } || { [ -z "${RHC_ORGANIZATION_ID:-}" ] && [ -n "${RHC_ACTIVATION_KEY:-}" ]; }; then
        _vwarn "RHC_ORGANIZATION_ID and RHC_ACTIVATION_KEY should be set together when overriding rhc registration"
    else
        _vok "RHC activation-key pairing is consistent"
    fi
    if [ -n "${SAT_MANIFEST_PATH:-}" ]; then
        if [ -f "${SAT_MANIFEST_PATH}" ]; then
            _vok "SAT_MANIFEST_PATH exists: ${SAT_MANIFEST_PATH}"
        else
            _vfail "SAT_MANIFEST_PATH does not exist: ${SAT_MANIFEST_PATH}"
        fi
    else
        _vwarn "SAT_MANIFEST_PATH not set; Satellite manifest auto-import will fall back to ${HOME}/Downloads/manifest_*.zip"
    fi

    # ── System requirements ────────────────────────────────────────────────────
    _vhead "System Requirements"
    if [[ "${OSTYPE:-}" == "linux-gnu"* ]]; then
        _vok "Running on Linux"
    else
        _vfail "Linux required (detected: ${OSTYPE:-unknown})"
    fi
    if [ "${EUID:-$(id -u)}" -eq 0 ]; then
        _vok "Running as root"
    elif sudo -n true 2>/dev/null; then
        _vok "Passwordless sudo available"
    else
        _vwarn "Not root and sudo requires a password"
    fi

    # ── Required commands ──────────────────────────────────────────────────────
    _vhead "Required Commands"
    local cmd
    for cmd in virsh podman ssh ssh-keygen jq curl; do
        if command -v "${cmd}" >/dev/null 2>&1; then
            _vok "${cmd} is available"
        else
            _vfail "${cmd} is not installed / not in PATH"
        fi
    done

    # ── SSH keys ───────────────────────────────────────────────────────────────
    _vhead "SSH Configuration"
    local ssh_key="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/mrhis-installer/id_rsa}"
    if [ -f "${ssh_key}" ]; then
        _vok "SSH private key exists: ${ssh_key}"
    else
        _vwarn "SSH private key not found: ${ssh_key}  (run the installer once to generate it)"
    fi
    if [ -f "${ssh_key}.pub" ]; then
        _vok "SSH public key exists: ${ssh_key}.pub"
    else
        _vfail "SSH public key not found: ${ssh_key}.pub"
    fi

    # ── IP address validation ──────────────────────────────────────────────────
    _vhead "IP Address Validation"
    _valid_ip() { [[ "${1:-}" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; }
    local ip_var ip_val
    for ip_var in IDM_IP SAT_IP AAP_IP HOST_INT_IP CMDB_ENDPOINT_IP; do
        ip_val="${!ip_var:-}"
        [ -z "${ip_val}" ] && continue
        if _valid_ip "${ip_val}"; then
            _vok "${ip_var} is a valid IP: ${ip_val}"
        else
            _vfail "${ip_var} is not a valid IP address: ${ip_val}"
        fi
    done

    # Satellite service-plane policy: internal 10.168.0.0/16 only (eth1).
    if [[ "${choice}" =~ ^(3|4|5|7)$ ]]; then
        if [[ "${MRHIS_ENFORCE_SAT_INTERNAL_NETWORK:-1}" == "1" ]]; then
            if [[ "${SAT_IP:-}" =~ ^10\.168\. ]]; then
                _vok "SAT_IP is on internal service network: ${SAT_IP}"
            else
                _vfail "SAT_IP must be within 10.168.0.0/16 when Satellite services are enabled (current: ${SAT_IP:-unset})"
            fi
            if [[ "${CMDB_ENDPOINT_IP:-}" =~ ^10\.168\. ]]; then
                _vok "CMDB_ENDPOINT_IP is on internal service network: ${CMDB_ENDPOINT_IP}"
            else
                _vfail "CMDB_ENDPOINT_IP must be within 10.168.0.0/16 for ansible-cmdb exposure (current: ${CMDB_ENDPOINT_IP:-unset})"
            fi
        else
            _vwarn "MRHIS_ENFORCE_SAT_INTERNAL_NETWORK=0; internal SAT_IP policy is disabled (current SAT_IP=${SAT_IP:-unset})"
        fi
    fi

    # ── FQDN validation ────────────────────────────────────────────────────────
    _vhead "Hostname (FQDN) Validation"
    _valid_fqdn() {
        [[ "${1:-}" =~ ^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$ ]]
    }
    local hn_var hn_val
    for hn_var in IDM_HOSTNAME SAT_HOSTNAME AAP_HOSTNAME; do
        hn_val="${!hn_var:-}"
        [ -z "${hn_val}" ] && continue
        if _valid_fqdn "${hn_val}"; then
            _vok "${hn_var} is a valid FQDN: ${hn_val}"
        else
            _vfail "${hn_var} is not a valid FQDN (must contain ≥1 dot): ${hn_val}"
        fi
    done

    # ── Storage ────────────────────────────────────────────────────────────────
    _vhead "Storage Requirements (/var/lib/libvirt)"
    local avail_gb
    avail_gb=$(df -BG /var/lib/libvirt 2>/dev/null | awk 'NR==2 {gsub(/G/,"",$4); print $4}') || avail_gb=""
    if [ -n "${avail_gb:-}" ] && [[ "${avail_gb}" =~ ^[0-9]+$ ]]; then
        if [ "${avail_gb}" -ge 300 ]; then
            _vok "${avail_gb} GB free (≥300 GB required)"
        else
            _vfail "Only ${avail_gb} GB free — need ≥300 GB"
        fi
    else
        _vwarn "Could not determine free space on /var/lib/libvirt"
    fi

    # ── Memory ────────────────────────────────────────────────────────────────
    _vhead "Memory Requirements"
    local mem_gb
    mem_gb=$(awk '/MemTotal/{print int($2/1024/1024)}' /proc/meminfo 2>/dev/null) || mem_gb=""
    if [ -n "${mem_gb:-}" ] && [[ "${mem_gb}" =~ ^[0-9]+$ ]]; then
        if [ "${mem_gb}" -ge 64 ]; then
            _vok "System RAM: ${mem_gb} GB (≥64 GB recommended)"
        else
            _vwarn "System RAM: ${mem_gb} GB — ≥64 GB recommended; may be constrained"
        fi
    else
        _vwarn "Could not read /proc/meminfo"
    fi

    # ── Connectivity ──────────────────────────────────────────────────────────
    _vhead "Connectivity Tests"
    if curl -sSf --connect-timeout 5 "https://api.access.redhat.com/ping" -o /dev/null 2>&1; then
        _vok "Red Hat CDN reachable (api.access.redhat.com)"
    else
        _vfail "Cannot reach Red Hat CDN — check internet / proxy connectivity"
    fi
    if nslookup redhat.com >/dev/null 2>&1; then
        _vok "DNS resolution working"
    else
        _vwarn "DNS resolution may not be working"
    fi

    # ── Summary ────────────────────────────────────────────────────────────────
    _vhead "Summary"
    printf "\n  Passed:   ${_vGREEN}%d${_vNC}\n" "${VPASS}"
    printf   "  Warnings: ${_vYELLOW}%d${_vNC}\n" "${VWARN}"
    printf   "  Failed:   ${_vRED}%d${_vNC}\n\n"  "${VFAIL}"

    if [ "${VFAIL}" -eq 0 ]; then
        printf "${_vGREEN}✓ All critical checks passed!${_vNC}\n\n"
        local env_arg=""
        [ -n "${PRESEED_ENV_FILE:-}" ] && [ -f "${PRESEED_ENV_FILE}" ] && \
            env_arg=" --env-file ${PRESEED_ENV_FILE}"
        printf "To deploy:\n  %s --non-interactive --menu-choice %s%s\n\n" \
            "$(basename "${BASH_SOURCE[0]}")" "${choice}" "${env_arg}"
        [ "${VWARN}" -gt 0 ] && \
            printf "Note: %d warning(s) above — review before deploying.\n\n" "${VWARN}"
        return 0
    else
        if is_demo; then
            printf "${_vYELLOW}⚠ DEMO mode: tolerating %d failed preflight check(s); continuing for non-production runs.${_vNC}\n\n" \
                "${VFAIL}"
            return 0
        fi
        printf "${_vRED}✗ %d critical check(s) failed — fix issues above before deploying.${_vNC}\n\n" \
            "${VFAIL}"
        return 1
    fi
}

generate_env_template() {
    local output_path="${1:-${SCRIPT_DIR}/mrhis-headless.env.template}"
    local tmp_template=""

    # If a Jinja2 template exists in the repo, prefer using it. When Ansible
    # and a vaulted env file are available, render a filled env via the
    # playbook; otherwise copy the raw Jinja2 template as a starter file.
    if [ -f "${SCRIPT_DIR}/templates/mrhis-headless.env.j2" ]; then
        if command -v ansible-playbook >/dev/null 2>&1 && [ -f "${ANSIBLE_ENV_FILE}" ] && [ -r "${ANSIBLE_VAULT_PASS_FILE:-}" ]; then
            local vault_arg=(--vault-password-file "${ANSIBLE_VAULT_PASS_FILE}")
            print_step "Rendering headless env from templates/mrhis-headless.env.j2 via Ansible -> ${output_path}"
            if ansible-playbook "${SCRIPT_DIR}/playbooks/render-templates-local.yml" "${vault_arg[@]}" -e "ansible_env_file=${ANSIBLE_ENV_FILE}" -e "output_headless=${output_path}" -e "inventory_dest=/tmp/mrhis.inventory.render" -e "controller_host=$(hostname -f)" >/dev/null 2>&1; then
                print_success "Rendered headless env: ${output_path}"
                return 0
            else
                print_warning "Ansible rendering failed; falling back to copying Jinja2 template."
            fi
        fi
        print_step "Copying Jinja2 template to ${output_path}"
        install -D -m 0600 "${SCRIPT_DIR}/templates/mrhis-headless.env.j2" "${output_path}" || return 1
        print_success "Copied template: ${output_path}"
        return 0
    fi

    tmp_template="$(mktemp)" || return 1
    cat > "${tmp_template}" <<'ENV_TEMPLATE_EOF'
#!/bin/bash
# MRHIS Headless Environment Configuration Template
#
# Usage:
#   1. Copy this file:  cp mrhis-headless.env.template /etc/mrhis/headless.env
#   2. Fill it in:      nano /etc/mrhis/headless.env
#   3. Validate:        ./mrhis_install.sh --validate --menu-choice 5 \
#                                         --env-file /etc/mrhis/headless.env
#   4. Deploy:          ./mrhis_install.sh --non-interactive --menu-choice 5 \
#                                         --env-file /etc/mrhis/headless.env
#
# Security:
#   chmod 600 /etc/mrhis/headless.env
#   Never commit this file with real credentials to version control.

# =============================================================================
# CORE CREDENTIALS  (required for almost all menu choices)
# =============================================================================
# Red Hat CDN / subscription-manager credentials
RH_USER="${RH_USERNAME:-}"
RH_PASS="${RH_PASSWORD:-}"

# Local admin user and password for every managed VM
ADMIN_USER="admin"
ADMIN_PASS="${AAP_ADMIN_PASSWORD:-${ADMIN_PASSWORD:-${AAP_ADMIN_PASS:-}}}"

# Root password for kickstart-provisioned VMs
ROOT_PASS="${ROOT_PASSWORD:-${ADMIN_PASS}}"

# =============================================================================
# IdM CONFIGURATION  (required for menu choices 3, 4, 5, 7)
# =============================================================================
IDM_IP="10.168.128.3"               # Static IP on the internal bridge network
IDM_HOSTNAME="idm.example.com"      # FQDN — must contain at least one dot
IDM_ALIAS="idm"                     # Short hostname
DOMAIN="example.com"                # Base domain / Kerberos realm base
IDM_DS_PASS="${IDM_DS_PASSWORD:-}"  # Directory Server (LDAP) password

# =============================================================================
# SATELLITE CONFIGURATION  (required for menu choices 3, 4, 5, 7)
# =============================================================================
SAT_IP="10.168.128.1"
SAT_HOSTNAME="satellite.example.com"
SAT_ALIAS="satellite"
SAT_ORG="Default_Organization"      # Satellite organization name
SAT_LOC="Default_Location"          # Satellite location name
SAT_ADMIN_PASS="${AAP_ADMIN_PASSWORD:-${ADMIN_PASS}}"

# =============================================================================
# AAP (Ansible Automation Platform) CONFIGURATION  (required for 3, 4, 5, 7)
# =============================================================================
AAP_IP="10.168.128.2"
AAP_HOSTNAME="aap.example.com"
AAP_ALIAS="aap"
AAP_ADMIN_PASS="${AAP_ADMIN_PASSWORD:-${ADMIN_PASS}}"

# Red Hat Automation Hub offline token
HUB_TOKEN="${AAP_HUB_TOKEN:-}"

# (Optional) Separate API token for ansible.cfg galaxy_server
# VAULT_CONSOLE_REDHAT_TOKEN="${CONSOLE_REDHAT_TOKEN:-}"

# =============================================================================
# PLATFORM PROVIDER CONFIGURATION (optional)
# Set `MRHIS_TARGET_PLATFORM` to one of: libvirt, vmware, nutanix, openshift,
# openshift-virt, aws, azure, gcp, baremetal. Provide provider-specific
# credentials below when deploying to cloud or remote platforms.
# =============================================================================
# MRHIS_TARGET_PLATFORM="libvirt"
#
# libvirt
# LIBVIRT_URI="qemu:///system"
# LIBVIRT_POOL="default"
#
# VMware vCenter (vSphere)
# VMWARE_HOST="vcenter.example.com"
# VMWARE_USER="administrator@vsphere.local"
# VMWARE_PASS=""
#
# Nutanix Prism
# NUTANIX_ENDPOINT="https://prism.example.com:9440"
# NUTANIX_USER=""
# NUTANIX_PASS=""
#
# OpenShift / OCP
# OPENSHIFT_API_URL="https://api.ocp.example.com:6443"
# OPENSHIFT_TOKEN=""
#
# AWS
# AWS_REGION="us-east-1"
# AWS_ACCESS_KEY_ID=""
# AWS_SECRET_ACCESS_KEY=""
#
# Azure
# AZURE_SUBSCRIPTION_ID=""
# AZURE_TENANT_ID=""
# AZURE_CLIENT_ID=""
# AZURE_CLIENT_SECRET=""
#
# GCP
