# IDM_MEMORY_MB="16384"
# SAT_VCPUS="8"
# SAT_MEMORY_MB="32768"
# AAP_VCPUS="8"
# AAP_MEMORY_MB="16384"

# =============================================================================
# FEATURE FLAGS  (optional — uncomment to override)
# =============================================================================
# DEMO_MODE="0"                           # 1 = minimal/demo VM specs
# MRHIS_AUTO_CONFIG_ON_CONTAINER_ONLY="1"
# MRHIS_RETRY_FAILED_PHASES_ONCE="1"
