mrhis_mesh_node_specs() {
    local include_optional="${1:-1}"

    printf '%s\n' "satellite:${SAT_IP}"
    printf '%s\n' "aap:${AAP_IP}"
    printf '%s\n' "idm:${IDM_IP}"

    if [ "${include_optional}" = "1" ]; then
        # Only include optional nodes in mesh/readiness when they have a usable
        # IP; requested-but-unset nodes should not block 100% mesh validation.
        if [ -n "${GITTEA_IP:-}" ] && { [ -n "${CLI_GITTEA:-}" ] || [ -n "${GITTEA_HOSTNAME:-}" ] || [ -n "${GITTEA_IP:-}" ]; }; then
            printf '%s\n' "gittea:${GITTEA_IP}"
        fi
        if [ -n "${OPENSHIFT_IP:-}" ] && { [ -n "${CLI_OPENSHIFT:-}" ] || [ -n "${OPENSHIFT_HOSTNAME:-}" ] || [ -n "${OPENSHIFT_IP:-}" ] || [ -n "${CLI_OPENSHIFT_IMPLICIT:-}" ]; }; then
            printf '%s\n' "openshift:${OPENSHIFT_IP}"
        fi
    fi
}

wait_for_post_vm_settle() {
    local timeout="${1:-${MRHIS_POST_VM_SSH_READY_TIMEOUT:-1200}}"
    local interval="${MRHIS_POST_VM_SSH_READY_INTERVAL:-5}"
    local start_ts now elapsed
    local name ip spec
    local total ready pct filled
    local bar pending use_ansi prev_pct printed_once
    local -a node_specs=()
    local -a pending_nodes=()

    mapfile -t node_specs < <(mrhis_mesh_node_specs 1)
    total="${#node_specs[@]}"
    [ "${total}" -gt 0 ] || return 0

    print_step "Skipping fixed settle delay: waiting for node ping+SSH readiness from installer (timeout=${timeout}s)."
    start_ts="$(date +%s)"
    # Detect if stdout is a terminal; enable in-place updates only for TTYs
    if [ -t 1 ]; then
        use_ansi=1
    else
        use_ansi=0
    fi
    prev_pct=-1
    # Status file to allow a single-line "live" tail of progress.
    status_file="${MRHIS_STATUS_FILE:-/var/log/MRHIS/status.current}"
    mkdir -p "$(dirname "${status_file}")" 2>/dev/null || true

    while :; do
        ready=0
        pending_nodes=()
        for spec in "${node_specs[@]}"; do
            name="${spec%%:*}"
            ip="${spec#*:}"

            if [ -z "${ip}" ]; then
                pending_nodes+=("${name}(ip-unset)")
                continue
            fi

            if ping -c 1 -W 1 "${ip}" >/dev/null 2>&1 && probe_ssh_endpoint "${ip}"; then
                ready=$((ready + 1))
            else
                pending_nodes+=("${name}(${ip})")
            fi
        done

        pct=$(( ready * 100 / total ))
        filled=$(( pct / 5 ))
        printf -v bar '%*s' "${filled}" ''
        bar="${bar// /#}"
        printf -v bar '%-20s' "${bar}"
        pending="${pending_nodes[*]}"
        # Build a single-line status string usable for TTY printing, logging,
        # and an always-updated status file that can be tailed.
        pending_str="$( [ ${#pending_nodes[@]} -gt 0 ] && printf ' pending: %s' "${pending}" || true )"
        status_line="$(printf '[STEP] Node readiness: [%s] %d%% (%d/%d ready)%s' "${bar}" "${pct}" "${ready}" "${total}" "${pending_str}")"

        if [ "${use_ansi}" -eq 1 ]; then
            # Terminal: overwrite the same line so user sees a progress bar
            printf '\r\033[K%s' "${status_line}"
        else
            # Not a TTY (e.g. logging to file): avoid spamming identical lines.
            # Only print when percentage changes (or first time).
            if [ "${pct}" -ne "${prev_pct}" ] || [ "${printed_once}" != "1" ]; then
                printf '%s\n' "${status_line}"
                prev_pct=${pct}
                printed_once=1
            fi
        fi

        # Update the single-line status file atomically so `tail -F` shows latest state.
        {
            printf '%s\n' "${status_line}" > "${status_file}.tmp" && mv "${status_file}.tmp" "${status_file}"
        } 2>/dev/null || printf '%s\n' "${status_line}" > "${status_file}" 2>/dev/null || true

        if [ "${ready}" -eq "${total}" ]; then
            printf '\n'
            print_success "All requested nodes are ping+SSH ready from installer."
            return 0
        fi

        now="$(date +%s)"
        elapsed=$(( now - start_ts ))
        if [ "${elapsed}" -ge "${timeout}" ]; then
            printf '\n'
            print_warning "Timed out waiting for ping+SSH readiness on: ${pending}"
            return 1
        fi

        sleep "${interval}"
    done
}

print_mrhis_health_summary() {
    local vm state ip
    local -a vms=("satellite:${SAT_IP}" "aap:${AAP_IP}" "idm:${IDM_IP}")
    if [ -n "${CLI_GITTEA:-}" ] || [ -n "${GITTEA_IP:-}" ] || [ -n "${GITTEA_HOSTNAME:-}" ]; then
        vms+=("gittea:${GITTEA_IP:-}")
    fi

    echo ""
    echo "================ MRHIS Health Summary ================"
    for spec in "${vms[@]}"; do
        vm="${spec%%:*}"
        ip="${spec#*:}"
        if sudo virsh dominfo "$vm" >/dev/null 2>&1; then
            state="$(sudo virsh domstate "$vm" 2>/dev/null | tr -d '[:space:]' || true)"
        else
            state="undefined"
        fi

        if probe_ssh_endpoint "$ip"; then
            echo "  - ${vm} (${ip}) state=${state:-unknown} ssh=up"
        else
            echo "  - ${vm} (${ip}) state=${state:-unknown} ssh=down"
        fi
    done
    echo "====================================================="
    echo ""
}

run_deferred_aap_callback() {
    ensure_ssh_keys || {
        print_warning "AAP callback cannot start: failed to ensure SSH keys at ${AAP_SSH_KEY_DIR}."
        return 1
    }

    AAP_SSH_CALLBACK_ENABLED=1
    print_step "AAP VM is installing. SSH callback will begin as soon as the VM is reachable."
    print_step "Grab a cup of coffee and sit back, or come back after lunch — we will continue to configure this environment while you wait."
    print_step "Live monitor is active: you will see AAP callback progress (percent + ETA). If no state progress is detected, this step will fail fast for troubleshooting."

    if run_aap_setup_on_vm "aap"; then
        print_success "AAP setup orchestration complete via SSH callback."
        create_aap_credentials
    else
        print_warning "AAP setup failed or timed out. Check ${AAP_SETUP_LOG_LOCAL} for details."
        AAP_SSH_CALLBACK_ENABLED=0
        return 1
    fi

    if [ "${AAP_HTTP_PID:-0}" -gt 0 ] 2>/dev/null && kill "${AAP_HTTP_PID}" 2>/dev/null; then
        print_success "AAP bundle HTTP server stopped (PID ${AAP_HTTP_PID})."
    fi
    AAP_HTTP_PID=""
    close_aap_bundle_firewall
    AAP_SSH_CALLBACK_ENABLED=0
    return 0
}

# ─── Inventory + host_vars generation ─────────────────────────────────────────
# Generate inventory from current env vars so the container
# always has a correct, up-to-date inventory regardless of who cloned the repo.
generate_mrhis_inventory() {
    if [ -f "${ANSIBLE_ENV_FILE}" ]; then
        load_ansible_env_file || return 1
    fi
    normalize_shared_env_vars

    local include_satellite=0
    local include_aap=0
    local include_idm=0
    local include_gittea=0
    local include_openshift=0
    local include_rhis_nodes=0

    mrhis_component_selected satellite && include_satellite=1
    mrhis_component_selected aap && include_aap=1
    mrhis_component_selected idm && include_idm=1
    mrhis_component_selected gittea && include_gittea=1
    mrhis_component_selected openshift && include_openshift=1
    if [ "${include_satellite}" -eq 1 ] || [ "${include_aap}" -eq 1 ] || [ "${include_idm}" -eq 1 ]; then
        include_rhis_nodes=1
    fi

    # Prefer Ansible-based template rendering when available. This will use
    # the vaulted env file to render `templates/mrhis-inventory.j2` into
    # the configured inventory path. Fall back to the legacy sed-based
    # generation if Ansible is not available or rendering fails.
    if command -v ansible-playbook >/dev/null 2>&1 && [ -f "${SCRIPT_DIR}/templates/mrhis-inventory.j2" ]; then
        print_step "Rendering inventory using Ansible template (templates/mrhis-inventory.j2)"
        local vault_arg=()
        if [ -r "${ANSIBLE_VAULT_PASS_FILE:-}" ]; then
            vault_arg=(--vault-password-file "${ANSIBLE_VAULT_PASS_FILE}")
        fi
        # Pass controller_host so the template can use the installer's FQDN
        local controller_host_local
        controller_host_local="$(hostname -f 2>/dev/null || hostname)"
        if ansible-playbook "${SCRIPT_DIR}/playbooks/render-templates-local.yml" "${vault_arg[@]}" \
            -e "ansible_env_file=${ANSIBLE_ENV_FILE}" \
            -e "inventory_dest=${MRHIS_INVENTORY_FILE}" \
            -e "output_headless=${SCRIPT_DIR}/mrhis-headless.env.template" \
            -e "controller_host=${controller_host_local}" \
            -e "include_satellite=${include_satellite}" \
            -e "include_aap=${include_aap}" \
            -e "include_idm=${include_idm}" \
            -e "include_gittea=${include_gittea}" \
            -e "include_openshift=${include_openshift}" \
            -e "include_rhis_nodes=${include_rhis_nodes}" \
            >/dev/null 2>&1; then
            if [ -f "${MRHIS_INVENTORY_FILE}" ]; then
                print_success "Inventory generated via Ansible templates: ${MRHIS_INVENTORY_FILE}"
                mkdir -p "${SCRIPT_DIR}/local/roles/inventory" || true
                install -D -m 0644 "${MRHIS_INVENTORY_FILE}" "${SCRIPT_DIR}/local/roles/inventory/$(basename "${MRHIS_INVENTORY_FILE}")" || true
                return 0
            fi
        else
            print_warning "Ansible template rendering failed; falling back to legacy inventory generation."
        fi
    fi

    mkdir -p "${MRHIS_INVENTORY_DIR}" "${SCRIPT_DIR}/local/roles/inventory" || return 1

    local controller_host
    local inventory_basename
    local template_file
    local tmp_hosts
    local controller_host_e host_int_ip_e installer_user_e sat_host_e sat_alias_e sat_ip_e aap_host_e aap_alias_e aap_ip_e idm_host_e idm_alias_e idm_ip_e admin_user_e global_admin_e global_admin_password_e domain_e gittea_host_e gittea_ip_e gittea_user_e
    local sat_connect_host aap_connect_host idm_connect_host openshift_connect_host

    # Global behavior uses internal MRHIS addressing (10.168.x.x) for stable
    # node-to-node trust and predictable Ansible reachability across rebuilds.
    resolve_vm_connect_host() {
        local vm_name="$1"
        local fallback_host="$2"
        local fallback_ip="$3"
        # shellcheck disable=SC2034
        vm_name="${vm_name}"
        # shellcheck disable=SC2034
        fallback_host="${fallback_host}"
        printf '%s' "${fallback_ip}"
        return 0
    }
    controller_host="$(hostname -f 2>/dev/null || hostname)"

    inventory_basename="$(basename "${MRHIS_INVENTORY_FILE}")"
    template_file="${MRHIS_INVENTORY_FILE}.SAMPLE"
    [ -f "${template_file}" ] || template_file="${MRHIS_INVENTORY_FILE}"
    [ -f "${template_file}" ] || template_file="${MRHIS_INVENTORY_DIR}/hosts.SAMPLE"
    [ -f "${template_file}" ] || template_file="${SCRIPT_DIR}/local/vars/external_inventory/hosts.yml"
    [ -f "${template_file}" ] || template_file="${SCRIPT_DIR}/inventory/hosts.SAMPLE"
    tmp_hosts="$(mktemp "${ANSIBLE_ENV_DIR}/.hosts.XXXXXX")" || return 1
    controller_host_e="$(sed_escape_replacement "${controller_host}")"
    host_int_ip_e="$(sed_escape_replacement "${HOST_INT_IP:-10.168.0.1}")"
    installer_user_e="$(sed_escape_replacement "${INSTALLER_USER:-${ADMIN_USER:-admin}}")"
    sat_host_e="$(sed_escape_replacement "${SAT_HOSTNAME:-satellite.${DOMAIN:-prod.spg}}")"
    sat_alias_e="$(sed_escape_replacement "${SAT_ALIAS:-satellite}")"
    sat_connect_host="$(resolve_vm_connect_host "satellite" "${SAT_HOSTNAME:-satellite}" "${SAT_IP:-10.168.128.1}")"
    sat_ip_e="$(sed_escape_replacement "${sat_connect_host}")"
    aap_host_e="$(sed_escape_replacement "${AAP_HOSTNAME:-aap.${DOMAIN:-prod.spg}}")"
    aap_alias_e="$(sed_escape_replacement "${AAP_ALIAS:-aap}")"
    aap_connect_host="$(resolve_vm_connect_host "aap" "${AAP_HOSTNAME:-aap}" "${AAP_IP:-10.168.128.2}")"
    aap_ip_e="$(sed_escape_replacement "${aap_connect_host}")"
    idm_host_e="$(sed_escape_replacement "${IDM_HOSTNAME:-idm.${DOMAIN:-prod.spg}}")"
    idm_alias_e="$(sed_escape_replacement "${IDM_ALIAS:-idm}")"
    idm_connect_host="$(resolve_vm_connect_host "idm" "${IDM_HOSTNAME:-idm}" "${IDM_IP:-10.168.128.3}")"
    idm_ip_e="$(sed_escape_replacement "${idm_connect_host}")"
    # Template defaults for external_inventory use different fallback values
    domain_e="$(sed_escape_replacement "${DOMAIN:-prod.spg}")"
    gittea_host_e="$(sed_escape_replacement "${GITTEA_HOSTNAME:-gittea.prod.spg}")"
    gittea_ip_e="$(sed_escape_replacement "${GITTEA_IP:-10.168.128.4}")"
    gittea_user_e="$(sed_escape_replacement "${GITTEA_USER:-admin}")"
    openshift_connect_host="$(resolve_vm_connect_host "openshift" "${OPENSHIFT_HOSTNAME:-openshift}" "${OPENSHIFT_IP:-10.168.128.5}")"
    local openshift_host_e openshift_alias_e openshift_ip_e openshift_user_e
    openshift_host_e="$(sed_escape_replacement "${OPENSHIFT_HOSTNAME:-openshift.prod.spg}")"
    openshift_alias_e="$(sed_escape_replacement "${OPENSHIFT_ALIAS:-openshift}")"
    openshift_ip_e="$(sed_escape_replacement "${openshift_connect_host}")"
    openshift_user_e="$(sed_escape_replacement "${OPENSHIFT_USER:-admin}")"
    admin_user_e="$(sed_escape_replacement "${ADMIN_USER:-admin}")"
    global_admin_e="$(sed_escape_replacement "${GLOBAL_ADMIN:-${ADMIN_USER:-admin}}")"
    global_admin_password_e="$(sed_escape_replacement "${GLOBAL_ADMIN_PASSWORD:-${AAP_ADMIN_PASS:-${ADMIN_PASS:-}}}")"

    if [ -f "${template_file}" ]; then
        sed \
            -e "s|{{CONTROLLER_HOST}}|${controller_host_e}|g" \
            -e "s|{{HOST_INT_IP}}|${host_int_ip_e}|g" \
            -e "s|{{INSTALLER_USER}}|${installer_user_e}|g" \
            -e "s|{{SAT_HOSTNAME}}|${sat_host_e}|g" \
            -e "s|{{SAT_ALIAS}}|${sat_alias_e}|g" \
            -e "s|{{SAT_IP}}|${sat_ip_e}|g" \
            -e "s|{{AAP_HOSTNAME}}|${aap_host_e}|g" \
            -e "s|{{AAP_ALIAS}}|${aap_alias_e}|g" \
            -e "s|{{AAP_IP}}|${aap_ip_e}|g" \
            -e "s|{{IDM_HOSTNAME}}|${idm_host_e}|g" \
            -e "s|{{IDM_ALIAS}}|${idm_alias_e}|g" \
            -e "s|{{IDM_IP}}|${idm_ip_e}|g" \
            -e "s|{{ADMIN_USER}}|${admin_user_e}|g" \
            "${template_file}" > "${tmp_hosts}"

        # Some external inventory templates use shell-style placeholders
        # like ${IDM_HOSTNAME:-idm.prod.spg}. Replace those too so the
        # generated inventory contains concrete values (no unresolved
        # ${...} tokens) which cause Ansible to treat hostnames/users as
        # invalid literal strings.
        if grep -q "\${" "${tmp_hosts}" 2>/dev/null; then
            sed -i \
                -e "s|\\\${DOMAIN:-[^}]*}|${domain_e}|g" \
                -e "s|\\\${INSTALLER_IP:-[^}]*}|${host_int_ip_e}|g" \
                -e "s|\\\${INSTALLER_USER:-[^}]*}|${installer_user_e}|g" \
                -e "s|\\\${SAT_HOSTNAME:-[^}]*}|${sat_host_e}|g" \
                -e "s|\\\${SAT_IP:-[^}]*}|${sat_ip_e}|g" \
                -e "s|\\\${SAT_USER:-[^}]*}|${admin_user_e}|g" \
                -e "s|\\\${AAP_HOSTNAME:-[^}]*}|${aap_host_e}|g" \
                -e "s|\\\${AAP_IP:-[^}]*}|${aap_ip_e}|g" \
                -e "s|\\\${AAP_USER:-[^}]*}|${admin_user_e}|g" \
                -e "s|\\\${IDM_HOSTNAME:-[^}]*}|${idm_host_e}|g" \
                -e "s|\\\${IDM_IP:-[^}]*}|${idm_ip_e}|g" \
                -e "s|\\\${IDM_USER:-[^}]*}|${admin_user_e}|g" \
                -e "s|\\\${GITTEA_HOSTNAME:-[^}]*}|${gittea_host_e}|g" \
                -e "s|\\\${GITTEA_IP:-[^}]*}|${gittea_ip_e}|g" \
                -e "s|\\\${GITTEA_USER:-[^}]*}|${gittea_user_e}|g" \
                -e "s|\\\${OPENSHIFT_HOSTNAME:-[^}]*}|${openshift_host_e}|g" \
                -e "s|\\\${OPENSHIFT_IP:-[^}]*}|${openshift_ip_e}|g" \
                -e "s|\\\${OPENSHIFT_USER:-[^}]*}|${openshift_user_e}|g" \
                "${tmp_hosts}" || true
        fi
    else
        cat > "${tmp_hosts}" <<INVENTORY_EOF
# MRHIS Ansible Inventory — generated by run_mrhis_install_sequence.sh on $(date '+%Y-%m-%d %H:%M')
# Do NOT commit this file; it contains host-specific values derived from env.yml.

[ansibledev]
${controller_host}

[libvirt]
${controller_host}

[installer]
${controller_host} ansible_host=${HOST_INT_IP:-10.168.0.1} ansible_user=${INSTALLER_USER:-${USER}} ansible_become=true

[mrhis:children]
satellite
aap
idm


[satellite]
${SAT_HOSTNAME:-satellite} ansible_host=${sat_connect_host} ansible_user=${GLOBAL_ADMIN:-${ADMIN_USER:-admin}} ansible_become=true
${SAT_ALIAS:-satellite} ansible_host=${sat_connect_host} ansible_user=${GLOBAL_ADMIN:-${ADMIN_USER:-admin}} ansible_become=true

[satellite:children]
satellite

[aap]
${AAP_HOSTNAME:-aap} ansible_host=${aap_connect_host} ansible_user=${GLOBAL_ADMIN:-${ADMIN_USER:-admin}} ansible_become=true
${AAP_ALIAS:-aap} ansible_host=${aap_connect_host} ansible_user=${GLOBAL_ADMIN:-${ADMIN_USER:-admin}} ansible_become=true

[aap_hosts:children]
aap

[platform_installer:children]
aap

[idm]
${IDM_HOSTNAME:-idm} ansible_host=${idm_connect_host} ansible_user=${GLOBAL_ADMIN:-${ADMIN_USER:-admin}} ansible_become=true
${IDM_ALIAS:-idm} ansible_host=${idm_connect_host} ansible_user=${GLOBAL_ADMIN:-${ADMIN_USER:-admin}} ansible_become=true

[fullstack:children]
satellite
aap
idm
gittea
openshift

[osp:children]
openstack

[git]
gittea

[idm_primary:children]
idm

[all:vars]
ansible_ssh_common_args='-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no'
global_admin_password: "${global_admin_password_e}"
INVENTORY_EOF
    fi

    # Keep inventory aligned to selected CLI scope/components.
    awk -v inc_sat="${include_satellite}" -v inc_aap="${include_aap}" -v inc_idm="${include_idm}" -v inc_gittea="${include_gittea}" -v inc_openshift="${include_openshift}" '
        BEGIN { section="" }
        /^\[.*\]$/ {
            section=$0
            keep=1
            if (section == "[satellite]" || section == "[satellite:children]") keep=(inc_sat==1)
            else if (section == "[aap]" || section == "[aap_hosts:children]" || section == "[platform_installer:children]") keep=(inc_aap==1)
            else if (section == "[idm]" || section == "[idm_primary:children]") keep=(inc_idm==1)
            else if (section == "[gittea]") keep=(inc_gittea==1)
            else if (section == "[git]") keep=(inc_gittea==1)
            else if (section == "[openshift]") keep=(inc_openshift==1)
            else if (section == "[fullstack:children]") keep=((inc_sat==1) || (inc_aap==1) || (inc_idm==1) || (inc_gittea==1) || (inc_openshift==1))
            else if (section == "[mrhis:children]") keep=((inc_sat==1) || (inc_aap==1) || (inc_idm==1))
            else if (section == "[osp:children]") keep=(inc_openshift==1)
            if (keep) print $0
            next
        }
        {
            if (section == "[mrhis:children]") {
                if (($0 == "satellite" && inc_sat==1) || ($0 == "aap" && inc_aap==1) || ($0 == "idm" && inc_idm==1) || $0 ~ /^\s*$/) print $0
            } else if (section == "[fullstack:children]") {
                if (($0 == "satellite" && inc_sat==1) || ($0 == "aap" && inc_aap==1) || ($0 == "idm" && inc_idm==1) || ($0 == "gittea" && inc_gittea==1) || ($0 == "openshift" && inc_openshift==1) || $0 ~ /^\s*$/) print $0
            } else if (section == "[osp:children]") {
                if (($0 == "openstack" && inc_openshift==1) || $0 ~ /^\s*$/) print $0
            } else {
                if (keep) print $0
            }
        }
    ' "${tmp_hosts}" > "${tmp_hosts}.filtered" && mv -f "${tmp_hosts}.filtered" "${tmp_hosts}"

    if [ "${include_gittea}" -eq 1 ] && ! grep -q '^\[gittea\]$' "${tmp_hosts}" 2>/dev/null; then
        cat >> "${tmp_hosts}" <<EOF

[git]
gittea

[gittea]
${GITTEA_HOSTNAME:-gittea.${DOMAIN:-prod.spg}} ansible_host=${GITTEA_IP:-10.168.128.4} ansible_user=${GITTEA_USER:-admin} ansible_become=true
EOF
    fi

    if [ "${include_openshift}" -eq 1 ] && ! grep -q '^\[openshift\]$' "${tmp_hosts}" 2>/dev/null; then
        cat >> "${tmp_hosts}" <<EOF

[osp:children]
openstack

[openshift]
${OPENSHIFT_HOSTNAME:-openshift.${DOMAIN:-prod.spg}} ansible_host=${openshift_connect_host} ansible_user=${OPENSHIFT_USER:-admin} ansible_become=true
${OPENSHIFT_ALIAS:-openshift} ansible_host=${openshift_connect_host} ansible_user=${OPENSHIFT_USER:-admin} ansible_become=true
EOF
    fi

    sync_inventory_target() {
        local target="$1"
        local target_dir
        target_dir="$(dirname "$target")"
        mkdir -p "$target_dir" || return 1
        if [ -f "$target" ] && cmp -s "${tmp_hosts}" "$target"; then
            print_step "Inventory unchanged: ${target}"
            return 0
        fi
        install -D -m 0644 "${tmp_hosts}" "$target" 2>/dev/null || {
            sudo install -D -m 0644 "${tmp_hosts}" "$target" >/dev/null 2>&1 || return 1
        }
        print_success "Generated inventory: ${target}"
    }

    sync_inventory_target "${MRHIS_INVENTORY_FILE}" || { rm -f "${tmp_hosts}"; return 1; }
    sync_inventory_target "${SCRIPT_DIR}/local/roles/inventory/${inventory_basename}" || { rm -f "${tmp_hosts}"; return 1; }
    rm -f "${tmp_hosts}"
}

# Generate actual host_vars/*.yml files from current env vars so playbooks
# can find per-node connection details without additional prompts.
# Passwords are referenced via the vault extra-vars loaded at runtime from
# /mrhis/vars/vault/env.yml (decrypted by --vault-password-file automatically).
generate_mrhis_host_vars() {
    if [ -f "${ANSIBLE_ENV_FILE}" ]; then
        load_ansible_env_file || return 1
    fi
    normalize_shared_env_vars

    local ext_inv_hv_dir="${SCRIPT_DIR}/local/vars/external_inventory/host_vars"
    local ext_inv_gv_dir="${SCRIPT_DIR}/local/vars/external_inventory/group_vars"
    mkdir -p "${MRHIS_HOST_VARS_DIR}" "${SCRIPT_DIR}/local/roles/host_vars" "${ext_inv_hv_dir}" "${ext_inv_gv_dir}" || return 1
    local sat_pre_use_idm_value="${SATELLITE_PRE_USE_IDM:-false}"
    local sat_use_non_idm_certs_value="${SAT_USE_NON_IDM_CERTS:-}"
    case "${sat_pre_use_idm_value}" in
        1|true|TRUE|yes|YES|on|ON) sat_pre_use_idm_value="true" ;;
        *) sat_pre_use_idm_value="false" ;;
    esac
    case "${sat_use_non_idm_certs_value}" in
        1|true|TRUE|yes|YES|on|ON) sat_use_non_idm_certs_value="true" ;;
        0|false|FALSE|no|NO|off|OFF) sat_use_non_idm_certs_value="false" ;;
        *)
            if [ "${sat_pre_use_idm_value}" = "true" ]; then
                sat_use_non_idm_certs_value="false"
            else
                sat_use_non_idm_certs_value="true"
            fi
            ;;
    esac
    local sat_internal_url="https://{{ sat_ip | default('10.168.128.1') }}"
    local primary_dir="${MRHIS_HOST_VARS_DIR}"
    local container_dir="${SCRIPT_DIR}/local/roles/host_vars"

    write_hostvars_pair() {
        local file_name="$1"
        local fqdn_name="$2"       # FQDN inventory hostname (may be empty)
        local src="${primary_dir}/${file_name}"
        local dst="${container_dir}/${file_name}"
        [ -f "$src" ] || return 1
        if [ ! -f "$dst" ] || ! cmp -s "$src" "$dst"; then
            install -D -m 0644 "$src" "$dst" 2>/dev/null || {
                sudo install -D -m 0644 "$src" "$dst" >/dev/null 2>&1 || return 1
            }
            print_step "Synced host_vars artifact: ${dst}"
        fi
        # The external inventory uses shared group_vars for common values, so
        # keep the per-host file as a minimal compatibility stub.
        if [ -n "${fqdn_name}" ]; then
            local fqdn_dst="${ext_inv_hv_dir}/${fqdn_name}.yml"
            if [ ! -f "${fqdn_dst}" ] || ! cmp -s /dev/null "${fqdn_dst}"; then
                cat > "${fqdn_dst}" <<'EOF'
---
# External inventory host-specific overrides are now shared via group_vars.
EOF
            fi
        fi
        return 0
    }

        cat > "${ext_inv_gv_dir}/all.yml" <<'EOF'
---
# Shared defaults for the external inventory.

ansible_user: "{{ global_admin | default(admin_user | default('admin')) }}"
ansible_become: true
ansible_connection: ssh
ansible_ssh_private_key_file: "{{ mrhis_installer_ssh_private_key_file | default('~/.ssh/id_rsa') }}"
EOF

        cat > "${ext_inv_gv_dir}/aap.yml" <<'EOF'
---
# AAP host defaults shared by all external inventory AAP entries.

ansible_password: "{{ aap_admin_pass | default(global_admin_password) | default('') }}"
ansible_become_password: "{{ aap_admin_pass | default(global_admin_password) | default('') }}"
aap_admin_user: "{{ ansible_user }}"
aap_admin_password: "{{ aap_admin_pass | default(global_admin_password) | default('') }}"
aap_single_host_mode: true
aap_gateway_mode: "local-container"
aap_gateway_host: "{{ inventory_hostname }}"
aap_gateway_url: "https://{{ inventory_hostname }}/"
platform_deployment_type: "container"
aap_topology: "standalone"
platform_installer_config:
    deployment_type: "container"
    topology: "standalone"
EOF

        cat > "${ext_inv_gv_dir}/satellite.yml" <<'EOF'
---
# Satellite host defaults shared by all external inventory Satellite entries.

ansible_password: "{{ sat_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
ansible_become_password: "{{ sat_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
satellite_username: "{{ sat_admin_user | default(global_admin | default(admin_user | default('admin'))) }}"
satellite_password: "{{ sat_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
satellite_organization: "{{ sat_org | default('REDHAT') }}"
satellite_location: "{{ sat_loc | default('CORE') }}"
satellite_url: "https://{{ ansible_host }}"
sat_firewalld_interface: "{{ sat_firewalld_interface | default('eth0') }}"
satellite_pre_use_idm: "{{ satellite_pre_use_idm | default(false) | bool }}"
use_non_idm_certs: "{{ use_non_idm_certs | default(true) | bool }}"
sat_ssl_certs_dir: "{{ sat_ssl_certs_dir | default('/root/.sat_ssl/') }}"
ipa_client_dns_servers: "{{ idm_ip | default('10.168.128.3') }}"
ipa_server_fqdn: "{{ idm_hostname | default('idm.prod.spg') }}"
EOF

        cat > "${ext_inv_gv_dir}/idm.yml" <<'EOF'
---
# IdM host defaults shared by all external inventory IdM entries.

ansible_password: "{{ idm_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
ansible_become_password: "{{ idm_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
idm_realm: "{{ idm_realm | default('PROD.SPG') }}"
idm_domain: "{{ idm_domain | default('prod.spg') }}"
idm_user_groups:
    - name: "{{ idm_admins_group | default('mrhis-admins') }}"
        description: "MRHIS Infrastructure Administrators"
        state: present
        user_list:
            - mrhis-operator
    - name: "{{ idm_content_managers_group | default('content-managers') }}"
        description: "MRHIS Content Managers (Satellite, Repos, Lifecycle)"
        state: present
        user_list:
            - satellite-svc
    - name: "{{ idm_automation_engineers_group | default('automation-engineers') }}"
        description: "MRHIS Automation Engineers (Ansible, AAP)"
        state: present
        user_list:
            - aap-svc
    - name: "{{ idm_system_services_group | default('system-services') }}"
        description: "MRHIS System Service Accounts"
        state: present
idm_users:
    - login: satellite-svc
        first: Satellite
        last: "Service Account"
        displayname: "Satellite Service User"
        email:
            - "satellite-svc@{{ idm_domain | default(domain | default('localdomain')) }}"
        random: true
        state: present
    - login: aap-svc
        first: AAP
        last: "Service Account"
        displayname: "AAP Service User"
        email:
            - "aap-svc@{{ idm_domain | default(domain | default('localdomain')) }}"
        random: true
        state: present
    - login: mrhis-operator
        first: MRHIS
        last: Operator
        displayname: "MRHIS Operator User"
        email:
            - "mrhis-operator@{{ idm_domain | default(domain | default('localdomain')) }}"
        password: "{{ aap_admin_pass | default(global_admin_password | default(idm_admin_pass | default(''))) }}"
        state: present
idm_password_policies:
    - group_name: global_policy
        minlife: "0"
        maxlife: "365"
        minclasses: "3"
        minlength: "12"
        history: "6"
        state: present
EOF

    # Installer / controller host
    # ansible_user must come from env.yml installer_user for consistent behavior
    # across operators and hosts.
    # aap_remote_user is the admin account on the remote AAP VM → admin_user.
    cat > "${primary_dir}/installer.yml" <<EOF
# installer.yml — generated by run_mrhis_install_sequence.sh
ansible_user: "{{ installer_user }}"
aap_remote_user: "{{ admin_user | default('${ADMIN_USER:-admin}') }}"
ansible_ssh_private_key_file: "{{ mrhis_installer_ssh_private_key_file | default('~/.ssh/id_rsa') }}"
EOF
    write_hostvars_pair "installer.yml" "" || return 1

    # Satellite
    cat > "${primary_dir}/satellite.yml" <<EOF
# satellite.yml — generated by run_mrhis_install_sequence.sh
ansible_user: "{{ admin_user | default('${ADMIN_USER:-admin}') }}"
ansible_password: "{{ sat_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
ansible_become: true
ansible_become_password: "{{ sat_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
ansible_connection: ssh
ansible_ssh_private_key_file: "{{ mrhis_installer_ssh_private_key_file | default('~/.ssh/id_rsa') }}"
satellite_username: "{{ sat_admin_user | default(admin_user | default('${ADMIN_USER:-admin}')) }}"
satellite_password: "{{ sat_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
satellite_organization: "{{ sat_org | default('${SAT_ORG:-REDHAT}') }}"
satellite_location: "{{ sat_loc | default('${SAT_LOC:-CORE}') }}"
satellite_url: "${sat_internal_url}"
sat_firewalld_interface: "{{ sat_firewalld_interface | default('eth0') }}"
satellite_pre_use_idm: "{{ satellite_pre_use_idm | default(${sat_pre_use_idm_value}) | bool }}"
use_non_idm_certs: "{{ use_non_idm_certs | default(${sat_use_non_idm_certs_value}) | bool }}"
sat_ssl_certs_dir: "{{ sat_ssl_certs_dir | default('${SAT_SSL_CERTS_DIR:-/root/.sat_ssl/}') }}"
ipa_client_dns_servers: "{{ idm_ip | default('${IDM_IP:-10.168.128.3}') }}"
ipa_server_fqdn: "{{ idm_hostname | default('${IDM_HOSTNAME:-idm.${DOMAIN:-localdomain}}') }}"
EOF
    write_hostvars_pair "satellite.yml" "${SAT_HOSTNAME:-}" || return 1

    # AAP
    cat > "${primary_dir}/aap.yml" <<EOF
# aap.yml — generated by run_mrhis_install_sequence.sh
ansible_user: "{{ admin_user | default('${ADMIN_USER:-admin}') }}"
ansible_become: true
ansible_become_pass: "{{ aap_admin_pass | default(global_admin_password) | default('') }}"
ansible_ssh_private_key_file: "{{ mrhis_installer_ssh_private_key_file | default('~/.ssh/id_rsa') }}"
aap_admin_user: "{{ ansible_user }}"
aap_admin_password: "{{ aap_admin_pass | default(global_admin_password) | default('') }}"
# Standalone AAP model: all platform services run as containers on this single host.
# The automation gateway is a local container on the AAP node (not a separate VM).
aap_single_host_mode: true
aap_gateway_mode: "local-container"
aap_gateway_host: "{{ aap_hostname | default('${AAP_HOSTNAME:-aap.${DOMAIN:-localdomain}}') }}"
aap_gateway_url: "https://{{ aap_hostname | default('${AAP_HOSTNAME:-aap.${DOMAIN:-localdomain}}') }}/"
platform_deployment_type: "${AAP_DEPLOYMENT_TYPE:-container}"
aap_topology: "${AAP_TOPOLOGY:-standalone}"
platform_installer_config:
    deployment_type: "${AAP_DEPLOYMENT_TYPE:-container}"
    topology: "${AAP_TOPOLOGY:-standalone}"
EOF
    write_hostvars_pair "aap.yml" "${AAP_HOSTNAME:-}" || return 1

    # IdM
    cat > "${primary_dir}/idm.yml" <<EOF
# idm.yml — generated by run_mrhis_install_sequence.sh
ansible_user: "{{ admin_user | default('${ADMIN_USER:-admin}') }}"
ansible_password: "{{ idm_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
ansible_become: true
ansible_become_password: "{{ idm_admin_pass | default(aap_admin_pass | default(global_admin_password)) | default('') }}"
idm_realm: "{{ idm_realm | default('${IDM_REALM:-$(echo "${DOMAIN:-}" | tr '[:lower:]' '[:upper:]')}') }}"
idm_domain: "{{ idm_domain | default('${IDM_DOMAIN:-${DOMAIN:-}}') }}"
idm_user_groups:
    - name: "{{ idm_admins_group | default('mrhis-admins') }}"
      description: "MRHIS Infrastructure Administrators"
      state: present
      user_list:
          - mrhis-operator
    - name: "{{ idm_content_managers_group | default('content-managers') }}"
      description: "MRHIS Content Managers (Satellite, Repos, Lifecycle)"
      state: present
      user_list:
          - satellite-svc
    - name: "{{ idm_automation_engineers_group | default('automation-engineers') }}"
      description: "MRHIS Automation Engineers (Ansible, AAP)"
      state: present
      user_list:
          - aap-svc
    - name: "{{ idm_system_services_group | default('system-services') }}"
      description: "MRHIS System Service Accounts"
      state: present
idm_users:
    - login: satellite-svc
      first: Satellite
      last: "Service Account"
      displayname: "Satellite Service User"
      email:
          - "satellite-svc@{{ idm_domain | default(domain | default('localdomain')) }}"
      random: true
      state: present
    - login: aap-svc
      first: AAP
      last: "Service Account"
      displayname: "AAP Service User"
      email:
          - "aap-svc@{{ idm_domain | default(domain | default('localdomain')) }}"
      random: true
      state: present
    - login: mrhis-operator
      first: MRHIS
      last: Operator
      displayname: "MRHIS Operator User"
      email:
          - "mrhis-operator@{{ idm_domain | default(domain | default('localdomain')) }}"
      password: "{{ aap_admin_pass | default(global_admin_password | default(idm_admin_pass | default(''))) }}"
      state: present
idm_password_policies:
    - group_name: global_policy
      minlife: "0"
      maxlife: "365"
      minclasses: "3"
      minlength: "12"
      history: "6"
      state: present
EOF
    write_hostvars_pair "idm.yml" "${IDM_HOSTNAME:-}" || return 1

    # Optional Gitea host_vars
    cat > "${primary_dir}/gittea.yml" <<EOF
# gittea.yml — generated by run_mrhis_install_sequence.sh
ansible_user: "{{ gittea_admin_user | default('${GITTEA_ADMIN_USER:-admin}') }}"
ansible_password: "{{ gittea_admin_pass | default(global_admin_password) | default('') }}"
ansible_become: true
ansible_become_password: "{{ gittea_admin_pass | default(global_admin_password) | default('') }}"
gittea_repo_url: "{{ gittea_repo_url | default('${GITTEA_REPO_URL:-https://github.com/go-gitea/gitea.git}') }}"
EOF
    write_hostvars_pair "gittea.yml" "${GITTEA_HOSTNAME:-}" || true

    chmod 0644 "${primary_dir}"/*.yml 2>/dev/null || true
    chmod 0644 "${container_dir}"/*.yml 2>/dev/null || true
    print_success "Generated host_vars in ${primary_dir}/ and synced local/roles/host_vars/"
}

# Keep Satellite UI + provided services pinned to the internal network.
# - Registration/CDN/Insights can still use eth0 from inside the guest.
# - Service endpoints managed by this automation should remain on eth1/SAT_IP.
enforce_satellite_internal_service_network() {
    if [ "${SAT_FIREWALLD_INTERFACE:-eth0}" != "eth0" ]; then
        print_warning "SAT_FIREWALLD_INTERFACE was '${SAT_FIREWALLD_INTERFACE}'; forcing to 'eth0' for external firewall ingress control."
        SAT_FIREWALLD_INTERFACE="eth0"
    fi

    if [[ "${MRHIS_ENFORCE_SAT_INTERNAL_NETWORK:-1}" == "1" ]]; then
        if [[ ! "${SAT_IP:-}" =~ ^10\.168\. ]]; then
            print_warning "SAT_IP='${SAT_IP:-unset}' is outside 10.168.0.0/16. Refusing to continue with Satellite service configuration."
            return 1
        fi
    fi

    SATELLITE_URL_INTERNAL="https://${SAT_IP:-10.168.128.1}"
    print_step "Satellite network policy: UI/services => ${SATELLITE_URL_INTERNAL} on eth1; firewall ingress interface => ${SAT_FIREWALLD_INTERFACE}."
    return 0
}

# ─── Local Ansible role runner ────────────────────────────────────────────────
# Invoke a role from local/roles/ directly on the installer host (no container).
# Returns 0 on success, 1 if ansible-playbook is unavailable or the playbook is
# missing (callers should then fall back to their native bash implementation).
#
# Usage: run_local_role <role_name> [target_limit] [extra ansible-playbook args...]
#   role_name    — must match a sub-dir under local/roles/ that has run.yml
#   target_limit — inventory limit (default: installer); use colon-separated groups
#                  e.g. "scenario_satellite:aap:idm"
#   extra args   — passed verbatim to ansible-playbook (e.g. --extra-vars "...")
#
# Environment consumed (all optional):
#   ANSIBLE_VAULT_PASS_FILE  — path to vault password file
#   ANSIBLE_ENV_FILE         — path to vault-encrypted vars file (passed as @extra-vars)
#   MRHIS_INVENTORY_FILE      — override default inventory
run_local_role() {
    local role="${1:?run_local_role: role name required}"
    local target="${2:-installer}"
    shift 2 || true
    local extra_args=("$@")

    local playbook="${SCRIPT_DIR}/local/roles/${role}/run.yml"
    local ansible_cfg="${SCRIPT_DIR}/local/roles/ansible.cfg"
    local inventory="${MRHIS_INVENTORY_FILE:-${SCRIPT_DIR}/local/roles/inventory/hosts.yml}"

    if [ ! -f "${playbook}" ]; then
        print_warning "run_local_role: playbook not found: ${playbook} — falling back to bash"
        return 1
    fi

    if ! command -v ansible-playbook >/dev/null 2>&1; then
        print_warning "run_local_role: ansible-playbook not in PATH — falling back to bash"
        return 1
    fi

    local -a vault_arg=()
    if [ -f "${ANSIBLE_VAULT_PASS_FILE:-}" ]; then
        vault_arg=(--vault-password-file "${ANSIBLE_VAULT_PASS_FILE}")
    fi

    local -a vault_vars=()
    if [ -f "${ANSIBLE_ENV_FILE:-}" ]; then
        vault_vars=(--extra-vars "@${ANSIBLE_ENV_FILE}")
    fi

    print_step "Running Ansible role '${role}' (limit: ${target})"
    ANSIBLE_CONFIG="${ansible_cfg}" ansible-playbook \
        --inventory "${inventory}" \
        --limit "${target}" \
        "${vault_arg[@]}" \
        "${vault_vars[@]}" \
        "${extra_args[@]}" \
        "${playbook}"
}

# ─── Container playbook runner ─────────────────────────────────────────────────
# Run one mrhis-builder playbook inside the provisioner container.
# Usage: run_container_playbook <playbook_path_inside_container> <--limit GROUP> [extra args...]
# The vault env.yml is passed as @extra-vars so all vault keys become Ansible vars.
run_container_playbook() {
    local playbook="$1"; shift
    local limit_flag="$1"; shift      # typically "--limit idm_primary" etc.
    local limit_group="$1"; shift
    local extra_args=("$@")

    # Ensure container is up; start it if not
    ensure_container_running || return 1

    local vault_file="/mrhis/vars/vault/$(basename "${ANSIBLE_ENV_FILE}")"
    local vault_pass="/mrhis/vars/vault/$(basename "${ANSIBLE_VAULT_PASS_FILE}")"
    local ansible_log_file="/mrhis/vars/vault/${AAP_ANSIBLE_LOG_BASENAME}"
    local -a podman_user_args=()

    print_step "Running ${playbook} --limit ${limit_group} inside container '${MRHIS_CONTAINER_NAME}'"

    # If vault password file is readable, use it. If not readable as default
    # container user, try root. Otherwise fall back to prompting.
    local vault_arg=()
    if podman exec "${MRHIS_CONTAINER_NAME}" test -r "${vault_pass}" 2>/dev/null; then
        vault_arg=(--vault-password-file "${vault_pass}")
    elif podman exec --user 0 "${MRHIS_CONTAINER_NAME}" test -r "${vault_pass}" 2>/dev/null; then
        vault_arg=(--vault-password-file "${vault_pass}")
        podman_user_args=(--user 0)
        print_step "Vault password file requires container root access; executing playbook as root."
    else
        vault_arg=(--ask-vault-pass)
    fi

    print_step "Ansible log: ${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}"
    print_step "Ansible config: ${MRHIS_ANSIBLE_CFG_HOST}"

    podman exec -it -e "ANSIBLE_CONFIG=${MRHIS_ANSIBLE_CFG_CONTAINER}" -e "ANSIBLE_LOG_PATH=${ansible_log_file}" "${podman_user_args[@]}" "${MRHIS_CONTAINER_NAME}" \
        ansible-playbook \
            --inventory "${MRHIS_CONTAINER_INVENTORY_FILE}" \
            "${vault_arg[@]}" \
            --extra-vars "@${vault_file}" \
            --limit "${limit_group}" \
            "${extra_args[@]}" \
            "${playbook}"
}

stage_satellite_manifest() {
    # shellcheck disable=SC2086
    local staged_host_path
    if [ -n "${SAT_MANIFEST_PATH:-}" ]; then
        if [ -f "${SAT_MANIFEST_PATH}" ]; then
            staged_host_path="${SAT_MANIFEST_PATH}"
        else
            print_warning "SAT_MANIFEST_PATH is set but does not exist: ${SAT_MANIFEST_PATH}"
            return 0
        fi
    else
        # Try to discover manifest in primary location first
        staged_host_path="$(ls -1t ${HOME}/Downloads/manifest_*.zip 2>/dev/null | head -1 || true)"
        
        # If not found in Downloads, check libvirt images directory as fallback
        if [ -z "${staged_host_path}" ] && [ -d "/var/lib/libvirt/images" ]; then
            staged_host_path="$(ls -1t /var/lib/libvirt/images/manifest_*.zip 2>/dev/null | head -1 || true)"
            if [ -n "${staged_host_path}" ]; then
                print_step "Manifest not found in ${HOME}/Downloads/, using fallback location: ${staged_host_path}"
            fi
        fi
    fi
    if [ -z "${staged_host_path}" ]; then
        return 0   # No manifest found — silent skip; portal-generated manifests are used instead
    fi

    print_step "Manifest detected: ${staged_host_path}"

    # Stage to KVM files directory (for libvirt file serving)
    if [ ! -d "${FILES_DIR}" ]; then
        sudo mkdir -p "${FILES_DIR}" && sudo chmod 0755 "${FILES_DIR}" || {
            print_warning "Could not create FILES_DIR at ${FILES_DIR}; skipping KVM files staging."
        }
    fi
    cp -f "${staged_host_path}" "${FILES_DIR}/manifest.zip" 2>/dev/null || \
        print_warning "Could not copy manifest to ${FILES_DIR}."

    # Stage to vault/conf dir — mounted as /mrhis/vars/vault/ inside the container
    if [ ! -d "${ANSIBLE_ENV_DIR}" ]; then
        mkdir -p "${ANSIBLE_ENV_DIR}" && chmod 0755 "${ANSIBLE_ENV_DIR}" || {
            print_warning "Could not create ANSIBLE_ENV_DIR at ${ANSIBLE_ENV_DIR}; skipping manifest staging."
            return 0
        }
    fi
    cp -f "${staged_host_path}" "${ANSIBLE_ENV_DIR}/manifest.zip" || {
        print_warning "Could not copy manifest to ${ANSIBLE_ENV_DIR}; manifest will not be auto-imported."
        return 0
    }

    MRHIS_STAGED_MANIFEST_CONTAINER_PATH="/mrhis/vars/vault/manifest.zip"
    export MRHIS_STAGED_MANIFEST_CONTAINER_PATH
    print_success "Manifest staged — container path: ${MRHIS_STAGED_MANIFEST_CONTAINER_PATH}"
}

# ─── Post-install config-as-code orchestration ────────────────────────────────
# Called automatically after all VMs are running.  Regenerates inventory and
# host_vars from the current env, starts the provisioner container, then runs
# the mrhis-builder playbooks in dependency order: IdM → Satellite → AAP.
run_mrhis_config_as_code() {
    print_step "===== MRHIS Config-as-Code Phase ====="
    print_step "Generating fresh inventory and host_vars from env.yml..."
    local idm_status="not-run"
    local satellite_status="not-run"
    local aap_status="not-run"
    local gitea_status="not-run"
    local idm_auth_fallback_status="not-needed"
    local satellite_auth_fallback_status="not-needed"
    local aap_auth_fallback_status="not-needed"
    local gitea_auth_fallback_status="not-needed"
    local phase_auth_fallback_status="not-needed"
    local any_failed=0
    local use_local_exec=0
    local component_scope="${MRHIS_COMPONENT_SCOPE:-all}"
    local run_idm=1
    local run_satellite=1
    local run_aap=1
    local run_gitea=0
    local run_openshift=0
    local -a phase_gate_targets=()

    case "${component_scope}" in
        all)
            run_idm=1
            run_satellite=1
            run_aap=1
            run_gitea=1
            run_openshift=1
            ;;
        fullstack)
            run_idm=1
            run_satellite=1
            run_aap=1
            run_gitea=1
            run_openshift=1
            ;;
        rhis)
            run_idm=1
            run_satellite=1
            run_aap=1
            run_gitea=0
            run_openshift=0
            ;;
        gittea)
            run_idm=0
            run_satellite=0
            run_aap=0
            run_gitea=1
            ;;
        openshift|openstack)
            run_idm=0
            run_satellite=0
            run_aap=0
            run_gitea=0
            run_openshift=1
            ;;
        idm)
            run_idm=1
            run_satellite=0
            run_aap=0
            ;;
        satellite)
            run_idm=0
            run_satellite=1
            run_aap=0
            ;;
        aap)
            run_idm=0
            run_satellite=0
            run_aap=1
            ;;
        rhis-aap)
            run_idm=0
            run_satellite=0
            run_aap=0
            ;;
        *)
            print_warning "Unknown MRHIS_COMPONENT_SCOPE='${component_scope}', defaulting to full flow."
            run_idm=1
            run_satellite=1
            run_aap=1
            component_scope="all"
            ;;
    esac
    print_step "Component scope: ${component_scope}"
    if [ "${MRHIS_EXECUTION_MODE:-local}" = "local" ]; then
        print_step "Execution mode: local ${USER} repo (local-first reruns/fallbacks enabled)"
        use_local_exec=1
        MRHIS_LOCAL_ROLE_FALLBACK=1
        MRHIS_ENABLE_CONTAINER_HOTFIXES=0
        generate_local_roles_ansible_cfg || true
    else
        print_step "Execution mode: mrhis_provisioner"
    fi

    load_ansible_env_file || true
    normalize_shared_env_vars
    enforce_satellite_internal_service_network || return 1

    # Keep installer-host /etc/hosts aligned with current external/NAT VM IPs.
    sync_mrhis_external_hosts_entries || true

    generate_mrhis_inventory     || { print_warning "Inventory generation failed; skipping config-as-code."; return 1; }
    generate_mrhis_host_vars     || { print_warning "host_vars generation failed; skipping config-as-code."; return 1; }
    # Enable Gitea/OpenShift phases when requested via CLI flag or env vars
    if [ -n "${CLI_GITTEA:-}" ] || [ -n "${GITTEA_HOSTNAME:-}" ] || [ -n "${GITTEA_IP:-}" ]; then
        run_gitea=1
    fi
    if [ -n "${CLI_OPENSHIFT:-}" ] || [ -n "${OPENSHIFT_API_URL:-}" ]; then
        run_openshift=1
    fi
    if [ "${run_idm}" -eq 1 ]; then
        phase_gate_targets+=("idm:${IDM_IP}")
    fi
    if [ "${run_satellite}" -eq 1 ]; then
        phase_gate_targets+=("satellite:${SAT_IP}")
    fi
    if [ "${run_gitea}" -eq 1 ]; then
        phase_gate_targets+=("gittea:${GITTEA_IP}")
    fi
    if [ "${run_aap}" -eq 1 ]; then
        phase_gate_targets+=("aap:${AAP_IP}")
    fi
    if [ "${#phase_gate_targets[@]}" -gt 0 ]; then
        print_step "Phase gate: waiting for selected component prerequisites"
        if ! MRHIS_PREFLIGHT_DEMO_TOLERATE=0 preflight_config_as_code_targets "${phase_gate_targets[@]}"; then
            case "${component_scope}" in
                all|fullstack|rhis)
                    print_step "Phase gate failed for scope '${component_scope}'; attempting VM provisioning before retry"
                    if is_demo; then
                        print_warning "Cause hint: DEMO runs can start with undefined VMs; provisioning now before SSH bootstrap."
                    fi
                    create_mrhis_vms || return 1
                    MRHIS_PREFLIGHT_DEMO_TOLERATE=0 preflight_config_as_code_targets "${phase_gate_targets[@]}" || return 1
                    ;;
                *)
                    return 1
                    ;;
            esac
        fi
    fi

    # Re-sync installer/user/root trust only after selected targets are actually reachable.
    # This avoids long SSH retry loops against undefined/down VMs in DEMO mode.
    print_step "Pre-flight: refreshing MRHIS SSH trust baseline before config-as-code"
    if ! setup_mrhis_ssh_mesh "${component_scope}"; then
        print_warning "SSH trust baseline refresh did not fully converge; continuing with phase auth fallback logic."
    fi

    # Ensure root auth fallback path is reliable even on reruns where guest-side
    # passwords drifted from current vault values.
    print_step "Pre-flight: normalizing VM root passwords for auth fallback reliability"
    fix_vm_root_passwords || print_warning "Root password pre-flight normalization did not complete cleanly; continuing."

    # Run server-bootstrap checks only after SSH readiness gates pass for the
    # selected scope. This prevents early failures while guests are still booting.
    if [ -z "${MRHIS_SERVER_BOOTSTRAP_CHECKS_DONE:-}" ] && is_enabled "${MRHIS_ENABLE_SERVER_BOOTSTRAP_CHECKS:-1}"; then
        MRHIS_SERVER_BOOTSTRAP_CHECKS_DONE=1
        run_phase_playbook_with_auth_fallback "Config-start — server-bootstrap checks" "idm:scenario_satellite:aap" "${SCRIPT_DIR}/playbooks/server-bootstrap.yml" || print_warning "Server-bootstrap checks at config start reported issues or could not complete."
    fi

    # Local fallback used by pre-container bootstrap routines. This avoids
    # relying on global helper availability if top-level conditional blocks
    # skipped earlier function definitions during script startup.
    bootstrap_ssh_exec() {
        local _user="$1" _host="$2" _pass="$3" _cmd="$4" _extra_opts="${5:-}"
        local _ssh_opts="-x -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no -o ConnectTimeout=12 -o PreferredAuthentications=password,keyboard-interactive,publickey -o NumberOfPasswordPrompts=3"
        local _key_path="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/id_rsa}"
        local _allow_password_fallback="${MRHIS_ALLOW_SSHPASS:-0}"

        if is_demo; then
            _allow_password_fallback=1
        fi
        [ -n "${_extra_opts}" ] && _ssh_opts="${_extra_opts} ${_ssh_opts}"

        if [ -r "${_key_path}" ] && ssh -i "${_key_path}" -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
            return 0
        fi
        if ssh -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
            return 0
        fi
        if [ "${_allow_password_fallback}" = "1" ] && [ -n "${_pass}" ] && command -v sshpass >/dev/null 2>&1; then
            sshpass -p "${_pass}" ssh ${_ssh_opts} "${_user}@${_host}" "${_cmd}"
            return $?
        fi
        return 1
    }

    # ---- Pre-container bootstrap helpers -----------------------------------
    run_satellite_precontainer_bootstrap() {
        local sat_target_ip="${SAT_IP:-10.168.128.1}"
        local sat_target_host="${SAT_HOSTNAME:-satellite}"
        local sat_target_short_host="${sat_target_host%%.*}"
        local ssh_key="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/mrhis-installer/id_rsa}"
        local root_auth_pass="${ROOT_PASS:-${ADMIN_PASS:-}}"
        local admin_user="${ADMIN_USER:-admin}"
        local admin_auth_pass="${ADMIN_PASS:-}"
        local rh_user_q=""
        local rh_pass_q=""
        local admin_user_q=""
        local admin_pass_q=""
        local remote_cmd=""
        local remote_cmd_esc=""
        local run_sat_upgrade="${MRHIS_SAT_PRECONTAINER_DNF_UPGRADE:-0}"

        if ! is_enabled "${MRHIS_SAT_PRECONTAINER_BOOTSTRAP:-1}"; then
            print_step "Satellite pre-container bootstrap disabled (MRHIS_SAT_PRECONTAINER_BOOTSTRAP=0)."
            return 0
        fi

        remote_cmd_esc="$(printf '%s' "${remote_cmd}" | sed "s/'/'\\''/g")"

        [ "${run_satellite}" -eq 1 ] || return 0

        # Ensure RHSM credentials are available from persisted env.yml even when
        # the current shell session did not export them.
        if { [ -z "${RH_USER:-}" ] || [ -z "${RH_PASS:-}" ]; } && [ -f "${ANSIBLE_ENV_FILE}" ]; then
            load_ansible_env_file || true
            normalize_shared_env_vars
        fi

        if [ -z "${RH_USER:-}" ] || [ -z "${RH_PASS:-}" ]; then
            print_warning "Skipping Satellite pre-container bootstrap: RH_USER/RH_PASS is not set."
            return 1
        fi

        printf -v rh_user_q '%q' "${RH_USER}"
        printf -v rh_pass_q '%q' "${RH_PASS}"
        printf -v admin_user_q '%q' "${ADMIN_USER:-admin}"
        printf -v admin_pass_q '%q' "${ADMIN_PASS:-}"

        # Ensure we have a usable SSH key path for root login first.
        if [ ! -r "${ssh_key}" ]; then
            ssh_key="${HOME}/.ssh/id_rsa"
        fi

                                remote_cmd="set -euo pipefail; \
hostnamectl set-hostname ${sat_target_host}; \
# ensure PATH includes puppet/tools so installer processes can find keytool if symlinked
export PATH=/opt/puppetlabs/bin:/usr/local/bin:/usr/bin:\$PATH; \
if grep -Eq '^[[:space:]]*${sat_target_ip}[[:space:]]+' /etc/hosts; then sed -i -E '/^[[:space:]]*${sat_target_ip}[[:space:]]+/d' /etc/hosts; fi; \
echo \"${sat_target_ip} ${sat_target_host} ${sat_target_short_host}\" >> /etc/hosts; \
nmcli device modify eth1 ipv4.addresses ${sat_target_ip}/16 ipv4.method manual >/dev/null 2>&1 || true; \
nmcli device up eth1 >/dev/null 2>&1 || true; \
if ! subscription-manager identity >/dev/null 2>&1; then \
    subscription-manager register --username ${rh_user_q} --password ${rh_pass_q} --force; \
fi; \
subscription-manager refresh || true; \
subscription-manager repos --enable=rhel-9-for-x86_64-baseos-rpms --enable=rhel-9-for-x86_64-appstream-rpms --enable=satellite-6.18-for-rhel-9-x86_64-rpms --enable=satellite-maintenance-6.18-for-rhel-9-x86_64-rpms; \
dnf clean all; \
if command -v foreman-maintain >/dev/null 2>&1; then foreman-maintain packages unlock >/dev/null 2>&1 || true; fi; \
if [ \"${run_sat_upgrade}\" = \"1\" ]; then dnf upgrade -y; fi; \
if ! rpm -q satellite >/dev/null 2>&1; then dnf install -y ${DNF_FLAGS} satellite; fi; \
# Ensure Java/keytool available for Puppet keystore providers: prefer existing JVM keytool, otherwise install
if ! command -v keytool >/dev/null 2>&1; then \
    _kt=\"\$(find /usr/lib/jvm -type f -name keytool -print -quit || true)\"; \
    if [ -n \"\${_kt}\" ] && [ -x \"\${_kt}\" ]; then \
        ln -sf \"\${_kt}\" /usr/bin/keytool || true; \
        ln -sf \"\${_kt}\" /usr/local/bin/keytool || true; \
        ln -sf \"\${_kt}\" /opt/puppetlabs/bin/keytool || true; \
        ln -sf \"\${_kt}\" /opt/puppetlabs/puppet/bin/keytool || true; \
    else \
        dnf install -y ${DNF_FLAGS} java-17-openjdk-headless java-17-openjdk || dnf install -y ${DNF_FLAGS} java-17-openjdk-headless || true; \
        _kt2=\"\$(command -v keytool 2>/dev/null || true)\"; \
        if [ -n \"\${_kt2}\" ]; then \
            ln -sf \"\${_kt2}\" /usr/bin/keytool || true; \
            ln -sf \"\${_kt2}\" /usr/local/bin/keytool || true; \
            ln -sf \"\${_kt2}\" /opt/puppetlabs/bin/keytool || true; \
            ln -sf \"\${_kt2}\" /opt/puppetlabs/puppet/bin/keytool || true; \
        fi; \
    fi; \
fi; \
# final fallback: if package provided keytool path exists, link it
if [ -x /usr/bin/keytool ]; then :; else \
    _kt3=\"\$(rpm -ql java-17-openjdk-headless 2>/dev/null | grep '/usr/lib/jvm/.*/bin/keytool$' | head -n1 || true)\"; \
    if [ -n \"\${_kt3}\" ] && [ -x \"\${_kt3}\" ]; then \
        ln -sf \"\${_kt3}\" /usr/bin/keytool || true; ln -sf \"\${_kt3}\" /usr/local/bin/keytool || true; \
    fi; \
fi; \
# Persist PATH for system processes that read /etc/environment
echo 'PATH="/opt/puppetlabs/bin:/usr/local/bin:/usr/bin:/sbin:/bin"' > /etc/environment || true; \
hash -r || true; \
/opt/puppetlabs/bin/puppet config set path /usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/opt/puppetlabs/bin --section main >/dev/null 2>&1 || true; \
[ -x /usr/bin/keytool ] || { echo \"ERROR: keytool is still unavailable after Java install\"; exit 1; }; \
if command -v foreman-maintain >/dev/null 2>&1; then foreman-maintain packages unlock >/dev/null 2>&1 || true; fi; \
satellite-installer --scenario satellite --skip-checks-i-know-better --foreman-initial-organization \"${SAT_ORG:-REDHAT}\" --foreman-initial-location \"${SAT_LOC:-CORE}\" --foreman-initial-admin-username ${admin_user_q} --foreman-initial-admin-password ${admin_pass_q} --foreman-proxy-http true --foreman-proxy-templates true --foreman-proxy-dhcp true --foreman-proxy-dhcp-interface \"${SAT_PROVISIONING_INTERFACE:-eth1}\" --foreman-proxy-dhcp-managed true --foreman-proxy-dhcp-gateway \"${SAT_PROVISIONING_GW:-${INTERNAL_GW:-10.168.0.1}}\" --foreman-proxy-dhcp-nameservers \"${SAT_PROVISIONING_DNS_PRIMARY:-${SAT_IP:-10.168.128.1}}\" --foreman-proxy-dhcp-range \"${SAT_PROVISIONING_DHCP_START:-10.168.130.1} ${SAT_PROVISIONING_DHCP_END:-10.168.255.254}\" --foreman-proxy-tftp true --foreman-proxy-tftp-managed true --foreman-proxy-tftp-servername \"${SAT_IP:-10.168.128.1}\" --enable-foreman-plugin-remote-execution --enable-foreman-compute-libvirt --enable-foreman-plugin-openscap --enable-foreman-proxy-plugin-openscap --enable-foreman-plugin-ansible --enable-foreman-proxy-plugin-ansible"

    print_step "Pre-container Satellite bootstrap: register, clear package locks when possible, upgrade, install satellite, then run first-pass satellite-installer"

        local _sat_bootstrap_attempt=1
        local _sat_bootstrap_max_attempts=4
        while [ "${_sat_bootstrap_attempt}" -le "${_sat_bootstrap_max_attempts}" ]; do
            print_step "Satellite pre-container bootstrap attempt ${_sat_bootstrap_attempt}/${_sat_bootstrap_max_attempts}"

            if [ -r "${ssh_key}" ] && timeout 12 ssh -i "${ssh_key}" -o BatchMode=yes -o ConnectTimeout=8 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no "root@${sat_target_ip}" 'echo ready' >/dev/null 2>&1; then
                if ssh -i "${ssh_key}" -o ConnectTimeout=12 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no "root@${sat_target_ip}" "${remote_cmd}"; then
                    print_success "Satellite pre-container bootstrap complete on ${sat_target_host} (${sat_target_ip})."
                    return 0
                fi
            fi

            # Fallback: try key-based or password fallback (sshpass) if enabled
            if bootstrap_ssh_exec "root" "${sat_target_ip}" "${root_auth_pass}" "${remote_cmd}" "-o ConnectTimeout=12"; then
                print_success "Satellite pre-container bootstrap complete with key/password fallback on ${sat_target_host} (${sat_target_ip})."
                return 0
            fi

            # Secondary fallback: run as admin and escalate with sudo -S using ADMIN_PASS.
            if [ -n "${admin_auth_pass}" ] && bootstrap_ssh_exec "${admin_user}" "${sat_target_ip}" "${admin_auth_pass}" "printf '%s\\n' '${admin_auth_pass}' | sudo -S -p '' bash -lc '${remote_cmd_esc}'" "-o ConnectTimeout=12"; then
                print_success "Satellite pre-container bootstrap complete via ${admin_user} + sudo -S fallback on ${sat_target_host} (${sat_target_ip})."
                return 0
            fi

            if [ "${_sat_bootstrap_attempt}" -lt "${_sat_bootstrap_max_attempts}" ]; then
                print_warning "Satellite pre-container bootstrap attempt ${_sat_bootstrap_attempt} failed (possible reboot/login transition). Waiting 45s before retry."
                sleep 45
            fi
            _sat_bootstrap_attempt=$((_sat_bootstrap_attempt + 1))
        done

        print_warning "Satellite pre-container bootstrap failed before container phase after ${_sat_bootstrap_max_attempts} attempts."
        return 1
    }

    run_aap_precontainer_bootstrap() {
        local aap_target_ip="${AAP_IP:-10.168.128.2}"
        local aap_target_host="${AAP_HOSTNAME:-aap}"
        local ssh_key="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/mrhis-installer/id_rsa}"
        local root_auth_pass="${ROOT_PASS:-${ADMIN_PASS:-}}"
        local admin_user="${ADMIN_USER:-admin}"
        local admin_auth_pass="${ADMIN_PASS:-}"
        local rh_user_q=""
        local rh_pass_q=""
        local remote_cmd=""
        local remote_cmd_esc=""
        local run_aap_upgrade="${MRHIS_AAP_PRECONTAINER_DNF_UPGRADE:-1}"

        if ! is_enabled "${MRHIS_AAP_PRECONTAINER_BOOTSTRAP:-1}"; then
            print_step "AAP pre-container bootstrap disabled (MRHIS_AAP_PRECONTAINER_BOOTSTRAP=0)."
            return 0
        fi

        [ "${run_aap}" -eq 1 ] || return 0

        # Ensure RHSM credentials are available from persisted env.yml even when
        # the current shell session did not export them.
        if { [ -z "${RH_USER:-}" ] || [ -z "${RH_PASS:-}" ]; } && [ -f "${ANSIBLE_ENV_FILE}" ]; then
            load_ansible_env_file || true
            normalize_shared_env_vars
        fi

        if [ -z "${RH_USER:-}" ] || [ -z "${RH_PASS:-}" ]; then
            print_warning "Skipping AAP pre-container bootstrap: RH_USER/RH_PASS is not set."
            return 1
        fi

        printf -v rh_user_q '%q' "${RH_USER}"
        printf -v rh_pass_q '%q' "${RH_PASS}"

        # Ensure we have a usable SSH key path for root login first.
        if [ ! -r "${ssh_key}" ]; then
            ssh_key="${HOME}/.ssh/id_rsa"
        fi

        remote_cmd="set -euo pipefail; \
        hostnamectl set-hostname ${aap_target_host}; \
        grep -q \"${aap_target_ip}.*${aap_target_host}\" /etc/hosts || echo \"${aap_target_ip} ${aap_target_host} aap\" >> /etc/hosts; \
        nmcli device modify eth1 ipv4.addresses ${aap_target_ip}/16 ipv4.method manual >/dev/null 2>&1 || true; \
        nmcli device up eth1 >/dev/null 2>&1 || true; \
        if ! subscription-manager identity >/dev/null 2>&1; then \
            subscription-manager register --username ${rh_user_q} --password ${rh_pass_q} --force; \
        fi; \
        subscription-manager refresh || true; \
        dnf clean all; \
        if [ \"${run_aap_upgrade}\" = \"1\" ]; then dnf install -y ${DNF_FLAGS} nginx nginx-core nginx-filesystem redhat-logos-httpd || true; dnf upgrade ${DNF_FLAGS} -y; fi; \
        true"

        remote_cmd_esc="$(printf '%s' "${remote_cmd}" | sed "s/'/'\\''/g")"

        if [ -r "${ssh_key}" ] && timeout 10 ssh -i "${ssh_key}" -o BatchMode=yes -o ConnectTimeout=6 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no "root@${aap_target_ip}" 'echo ready' >/dev/null 2>&1; then
            if ssh -i "${ssh_key}" -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no "root@${aap_target_ip}" "${remote_cmd}"; then
                print_success "AAP pre-container bootstrap complete on ${aap_target_host} (${aap_target_ip})."
                return 0
            fi
        fi

        # Fallback: try key-based or password fallback (sshpass) if enabled
        if bootstrap_ssh_exec "root" "${aap_target_ip}" "${root_auth_pass}" "${remote_cmd}"; then
            print_success "AAP pre-container bootstrap complete with key/password fallback on ${aap_target_host} (${aap_target_ip})."
            return 0
        fi

        # Secondary fallback: run as admin and escalate with sudo -S using ADMIN_PASS.
        if [ -n "${admin_auth_pass}" ] && bootstrap_ssh_exec "${admin_user}" "${aap_target_ip}" "${admin_auth_pass}" "printf '%s\\n' '${admin_auth_pass}' | sudo -S -p '' bash -lc '${remote_cmd_esc}'"; then
            print_success "AAP pre-container bootstrap complete via ${admin_user} + sudo -S fallback on ${aap_target_host} (${aap_target_ip})."
            return 0
        fi

        print_warning "AAP pre-container bootstrap failed before container phase."
        return 1
    }

    if [ "${run_satellite}" -eq 1 ]; then
        if [ "${MRHIS_DEFER_COMPONENT_INSTALL:-0}" = "1" ]; then
            print_step "Skipping pre-container Satellite bootstrap due to MRHIS_DEFER_COMPONENT_INSTALL=1 (deferred to first-boot)."
        else
            run_satellite_precontainer_bootstrap || return 1
        fi
    fi

    if [ "${run_aap}" -eq 1 ]; then
        if [ "${MRHIS_DEFER_COMPONENT_INSTALL:-0}" = "1" ]; then
            print_step "Skipping pre-container AAP bootstrap due to MRHIS_DEFER_COMPONENT_INSTALL=1 (deferred to first-boot)."
        else
            run_aap_precontainer_bootstrap || return 1
        fi
    fi

    # Pull latest image and ensure container is running with fresh mounts
    if [ "${use_local_exec}" -eq 0 ]; then
        print_step "Ensuring MRHIS provisioner container is running..."
        podman pull "${MRHIS_CONTAINER_IMAGE}" 2>/dev/null || true
        podman images -f "dangling=true" -q | xargs --no-run-if-empty podman rmi 2>/dev/null && \
            print_step "Cleaned up dangling container images." || true
        ensure_container_running || { print_warning "Could not start provisioner container; skipping config-as-code."; return 1; }
    else
        print_step "Local ${USER} repo selected: skipping mandatory provisioner container bootstrap."
    fi

    # Keep visible progress terminals attached for both VM console output and
    # Ansible/script activity whenever a GUI desktop session is available.
    ensure_live_progress_monitors || true

    if [ "${use_local_exec}" -eq 0 ]; then
        case "${component_scope}" in
            satellite)
                launch_single_vm_console_monitor_auto "satellite" || print_warning "Automatic Satellite console reattach failed; continuing config-as-code."
                ;;
            idm)
                launch_single_vm_console_monitor_auto "idm" || print_warning "Automatic IdM console reattach failed; continuing config-as-code."
                ;;
            aap)
                launch_single_vm_console_monitor_auto "aap" || print_warning "Automatic AAP console reattach failed; continuing config-as-code."
                ;;
            *)
                reattach_vm_consoles || print_warning "Automatic VM console reattach failed; continuing config-as-code."
                ;;
        esac
    fi

    local vault_file="/mrhis/vars/vault/$(basename "${ANSIBLE_ENV_FILE}")"
    local vault_pass_file="/mrhis/vars/vault/$(basename "${ANSIBLE_VAULT_PASS_FILE}")"
    local ansible_log_file="/mrhis/vars/vault/${AAP_ANSIBLE_LOG_BASENAME}"
    local vault_arg=()
    local -a podman_user_args=()
    local use_interactive_vault_prompt=0
    local staged_vault_pass_host=""
    local staged_vault_pass_file=""

    # ---- Vault / container execution context --------------------------------
    cleanup_staged_vaultpass() {
        # By default remove the staged vault password file to avoid leaving
        # sensitive data on disk. Set MRHIS_KEEP_STAGED_VAULTPASS=1 to
        # retain the file for manual reruns/debugging.
        if [ -n "${staged_vault_pass_host:-}" ] && [ -f "${staged_vault_pass_host}" ]; then
            if [ "${MRHIS_KEEP_STAGED_VAULTPASS:-0}" = "1" ]; then
                print_step "Retaining staged vault password file: ${staged_vault_pass_host} (MRHIS_KEEP_STAGED_VAULTPASS=1)"
                return 0
            fi
            rm -f "${staged_vault_pass_host}" 2>/dev/null || true
            print_step "Removed temporary staged vault password file: ${staged_vault_pass_host}"
        fi
        return 0
    }

    if [ "${MRHIS_EXECUTION_MODE:-local}" = "local" ]; then
        if [ -r "${ANSIBLE_VAULT_PASS_FILE}" ]; then
            vault_arg=(--vault-password-file "${ANSIBLE_VAULT_PASS_FILE}")
        elif is_noninteractive; then
            print_warning "Vault password file not readable at ${ANSIBLE_VAULT_PASS_FILE}."
            print_warning "NONINTERACTIVE mode cannot prompt for a vault password."
            return 1
        else
            vault_arg=(--ask-vault-pass)
            use_interactive_vault_prompt=1
        fi
    elif podman exec "${MRHIS_CONTAINER_NAME}" test -r "${vault_pass_file}" 2>/dev/null; then
        vault_arg=(--vault-password-file "${vault_pass_file}")
    elif podman exec --user 0 "${MRHIS_CONTAINER_NAME}" test -r "${vault_pass_file}" 2>/dev/null; then
        vault_arg=(--vault-password-file "${vault_pass_file}")
        podman_user_args=(--user 0)
        print_step "Vault password file requires container root access; executing config-as-code phases as root."
    else
        # Attempt to stage a short-lived container-readable copy in the mounted vault dir.
        if [ -r "${ANSIBLE_VAULT_PASS_FILE}" ]; then
            staged_vault_pass_host="${ANSIBLE_ENV_DIR}/${STAGED_VAULT_PASS_BASENAME}"
            cp -f "${ANSIBLE_VAULT_PASS_FILE}" "${staged_vault_pass_host}" 2>/dev/null || staged_vault_pass_host=""
            if [ -n "${staged_vault_pass_host}" ] && [ -f "${staged_vault_pass_host}" ]; then
                # Start with the most secure mode: owner-only permissions.
                chmod 0600 "${staged_vault_pass_host}" 2>/dev/null || true
                staged_vault_pass_file="/mrhis/vars/vault/$(basename "${staged_vault_pass_host}")"

                # 1) Can the container read it as the default container user?
                if podman exec "${MRHIS_CONTAINER_NAME}" test -r "${staged_vault_pass_file}" 2>/dev/null; then
                    vault_arg=(--vault-password-file "${staged_vault_pass_file}")
                    print_step "Using temporary container-readable vault password file for this run. (0600 accepted by container)"

                # 2) If not, can we run the check as container root (if allowed)?
                elif podman exec --user 0 "${MRHIS_CONTAINER_NAME}" test -r "${staged_vault_pass_file}" 2>/dev/null; then
                    vault_arg=(--vault-password-file "${staged_vault_pass_file}")
                    podman_user_args=(--user 0)
                    print_step "Using temporary vault password file (container root access) for this run. (0600 owned file readable by root)"

                else
                    # 3) Compatibility fallback: relax to world-readable and re-check.
                    chmod 0644 "${staged_vault_pass_host}" 2>/dev/null || true
                    if podman exec "${MRHIS_CONTAINER_NAME}" test -r "${staged_vault_pass_file}" 2>/dev/null; then
                        vault_arg=(--vault-password-file "${staged_vault_pass_file}")
                        print_warning "Using temporary vault password file with relaxed permissions (0644) so container can read it. Consider providing the vault file inside the container or adjusting UID mapping for improved security."
                    elif podman exec --user 0 "${MRHIS_CONTAINER_NAME}" test -r "${staged_vault_pass_file}" 2>/dev/null; then
                        vault_arg=(--vault-password-file "${staged_vault_pass_file}")
                        podman_user_args=(--user 0)
                        print_warning "Using temporary vault password file (0644) with container root exec fallback. Consider providing the vault file inside the container or adjusting UID mapping for improved security."
                    else
                        cleanup_staged_vaultpass
                        staged_vault_pass_host=""
                        staged_vault_pass_file=""
                    fi
                fi
            fi
        fi

        if [ "${#vault_arg[@]}" -gt 0 ]; then
            :
        elif is_noninteractive; then
            cleanup_staged_vaultpass
            print_warning "Vault password file not readable in container at ${vault_pass_file}."
            print_warning "NONINTERACTIVE mode cannot prompt for a vault password."
            print_warning "Fix permissions/ownership on ${ANSIBLE_VAULT_PASS_FILE} and retry."
            return 1
        else
            vault_arg=(--ask-vault-pass)
            use_interactive_vault_prompt=1
            print_warning "Vault password file not readable in container at ${vault_pass_file}."
            print_warning "Falling back to interactive vault password prompt for config-as-code phases."
        fi
    fi

    local inv="--inventory ${MRHIS_CONTAINER_INVENTORY_FILE}"
    local sat_pre_use_idm="${SATELLITE_PRE_USE_IDM:-false}"
    local sat_use_non_idm_certs="${SAT_USE_NON_IDM_CERTS:-}"
    local idm_async_timeout="${IDM_ASYNC_TIMEOUT:-14400}"
    local idm_async_delay="${IDM_ASYNC_DELAY:-15}"
    local sat_installer_timeout="${SAT_INSTALLER_TIMEOUT:-7200}"
    local sat_installer_verbose="${SAT_INSTALLER_VERBOSE:-true}"
    local sat_ipa_dns="${IDM_IP:-10.168.128.3}"
    local sat_ipa_fqdn="${IDM_HOSTNAME:-idm.${DOMAIN:-localdomain}}"
    case "${sat_pre_use_idm}" in
        1|true|TRUE|yes|YES|on|ON) sat_pre_use_idm="true" ;;
        *) sat_pre_use_idm="false" ;;
    esac
    case "${sat_use_non_idm_certs}" in
        1|true|TRUE|yes|YES|on|ON) sat_use_non_idm_certs="true" ;;
        0|false|FALSE|no|NO|off|OFF) sat_use_non_idm_certs="false" ;;
        *)
            if [ "${sat_pre_use_idm}" = "true" ]; then
                sat_use_non_idm_certs="false"
            else
                sat_use_non_idm_certs="true"
            fi
            ;;
    esac
    local sat_ssl_certs_dir="${SAT_SSL_CERTS_DIR:-/root/.sat_ssl/}"
    case "${sat_ssl_certs_dir}" in
        */) ;;
        *) sat_ssl_certs_dir="${sat_ssl_certs_dir}/" ;;
    esac
    local evars="--extra-vars @${vault_file} --extra-vars {\"satellite_disconnected\":${SATELLITE_DISCONNECTED:-false},\"register_to_satellite\":${REGISTER_TO_SATELLITE:-false},\"satellite_pre_use_idm\":${sat_pre_use_idm},\"use_non_idm_certs\":${sat_use_non_idm_certs},\"sat_ssl_certs_dir\":\"${sat_ssl_certs_dir}\",\"async_timeout\":${idm_async_timeout},\"async_delay\":${idm_async_delay},\"satellite_url\":\"https://${SAT_HOSTNAME}\"}"
    local manual_evars="--extra-vars @${vault_file} --extra-vars '{\"satellite_disconnected\":${SATELLITE_DISCONNECTED:-false},\"register_to_satellite\":${REGISTER_TO_SATELLITE:-false},\"satellite_pre_use_idm\":${sat_pre_use_idm},\"use_non_idm_certs\":${sat_use_non_idm_certs},\"sat_ssl_certs_dir\":\"${sat_ssl_certs_dir}\",\"async_timeout\":${idm_async_timeout},\"async_delay\":${idm_async_delay},\"satellite_url\":\"https://${SAT_HOSTNAME}\"}'"
    local local_manual_evars="--extra-vars @${ANSIBLE_ENV_FILE} --extra-vars '{\"satellite_disconnected\":${SATELLITE_DISCONNECTED:-false},\"register_to_satellite\":${REGISTER_TO_SATELLITE:-false},\"satellite_pre_use_idm\":${sat_pre_use_idm},\"use_non_idm_certs\":${sat_use_non_idm_certs},\"sat_ssl_certs_dir\":\"${sat_ssl_certs_dir}\",\"async_timeout\":${idm_async_timeout},\"async_delay\":${idm_async_delay},\"satellite_url\":\"https://${SAT_HOSTNAME}\"}'"
    local manual_vault_arg="${vault_arg[*]}"
    local local_manual_vault_arg="--vault-password-file ${ANSIBLE_VAULT_PASS_FILE}"
    if [ -z "${manual_vault_arg}" ]; then
        manual_vault_arg="--ask-vault-pass"
    fi
    if [ ! -r "${ANSIBLE_VAULT_PASS_FILE}" ]; then
        local_manual_vault_arg="--ask-vault-pass"
    fi

    # Per-phase extras for copy-paste manual reruns — must mirror what run_phase_playbook injects.
    # IdM: bypass the rhc 'Configure remediation' block (GPG fails on RHEL 10 for rhc-worker-playbook)
    local manual_idm_extras="--extra-vars '{\"rhc_insights\":{\"remediation\":\"absent\"},\"idm_repository_ids\":${IDM_REPOSITORY_IDS_JSON},\"async_timeout\":${idm_async_timeout},\"async_delay\":${idm_async_delay}}'"
    if [ -n "${IPADM_PASSWORD:-}" ]; then
        manual_idm_extras+=" -e 'ipadm_password=${IPADM_PASSWORD}' -e 'ipaadmin_password=${IPAADMIN_PASSWORD:-${IPADM_PASSWORD}}'"
    fi

    # Satellite: supply sat_repository_ids, firewall settings, and CDN registration vars
    local _sat_manual_json="{\"sat_repository_ids\":${SAT_REPOSITORY_IDS_JSON},\"sat_firewalld_zone\":\"${SAT_FIREWALLD_ZONE}\",\"sat_firewalld_interface\":\"${SAT_FIREWALLD_INTERFACE}\",\"sat_firewalld_services\":${SAT_FIREWALLD_SERVICES_JSON},\"satellite_pre_use_idm\":${sat_pre_use_idm},\"use_non_idm_certs\":${sat_use_non_idm_certs},\"sat_ssl_certs_dir\":\"${sat_ssl_certs_dir}\",\"ipa_client_dns_servers\":\"${sat_ipa_dns}\",\"ipa_server_fqdn\":\"${sat_ipa_fqdn}\",\"sat_installer_timeout\":${sat_installer_timeout},\"sat_installer_verbose\":${sat_installer_verbose}}"
    local manual_satellite_extras="--extra-vars '${_sat_manual_json}'"
    local manual_podman_env="-e ANSIBLE_CONFIG=${MRHIS_ANSIBLE_CFG_CONTAINER}"

    # ---- Nested ansible/podman helper wrappers ------------------------------
    run_ansible_shell_in_container() {
        local target="$1"
        local shell_cmd="$2"
        local root_auth_pass="${3:-}"
        local extra_args="${4:-}"

        if [ "${MRHIS_EXECUTION_MODE:-local}" = "local" ]; then
            local local_inv="--inventory ${MRHIS_INVENTORY_FILE}"
            local local_cfg="${SCRIPT_DIR}/local/roles/ansible.cfg"
            local local_evars="--extra-vars @${ANSIBLE_ENV_FILE} --extra-vars {\"satellite_disconnected\":${SATELLITE_DISCONNECTED:-false},\"register_to_satellite\":${REGISTER_TO_SATELLITE:-false},\"satellite_pre_use_idm\":${sat_pre_use_idm},\"use_non_idm_certs\":${sat_use_non_idm_certs},\"sat_ssl_certs_dir\":\"${sat_ssl_certs_dir}\",\"async_timeout\":${idm_async_timeout},\"async_delay\":${idm_async_delay},\"satellite_url\":\"https://${SAT_HOSTNAME}\"}"
            local local_vault_arg=""
            [ -f "${local_cfg}" ] || local_cfg="${MRHIS_ANSIBLE_CFG_HOST}"
            if [ -r "${ANSIBLE_VAULT_PASS_FILE}" ]; then
                local_vault_arg="--vault-password-file ${ANSIBLE_VAULT_PASS_FILE}"
            else
                local_vault_arg="--ask-vault-pass"
            fi

            if [ -n "${root_auth_pass}" ]; then
                ANSIBLE_CONFIG="${local_cfg}" ANSIBLE_LOG_PATH="${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}" \
                    ansible "${target}" ${local_inv} ${local_vault_arg} ${local_evars} \
                    -e "ansible_user=root" \
                    -e "ansible_password=${root_auth_pass}" \
                    -e "ansible_become=false" \
                    -e "ansible_become_password=${root_auth_pass}" \
                    -m shell -a "${shell_cmd}" ${extra_args}
            else
                ANSIBLE_CONFIG="${local_cfg}" ANSIBLE_LOG_PATH="${ANSIBLE_ENV_DIR}/${AAP_ANSIBLE_LOG_BASENAME}" \
                    ansible "${target}" ${local_inv} ${local_vault_arg} ${local_evars} \
                    -m shell -a "${shell_cmd}" ${extra_args}
            fi
            return $?
        fi

        if [ -n "${root_auth_pass}" ]; then
            if [ "$use_interactive_vault_prompt" = "1" ]; then
                podman exec -it -e "ANSIBLE_CONFIG=${MRHIS_ANSIBLE_CFG_CONTAINER}" -e "ANSIBLE_LOG_PATH=${ansible_log_file}" "${podman_user_args[@]}" "${MRHIS_CONTAINER_NAME}" \
                    ansible "${target}" ${inv} "${vault_arg[@]}" ${evars} \
                    -e "ansible_user=root" \
                    -e "ansible_password=${root_auth_pass}" \
                    -e "ansible_become=false" \
                    -e "ansible_become_password=${root_auth_pass}" \
                    -m shell -a "${shell_cmd}" ${extra_args}
            else
                podman exec -e "ANSIBLE_CONFIG=${MRHIS_ANSIBLE_CFG_CONTAINER}" -e "ANSIBLE_LOG_PATH=${ansible_log_file}" "${podman_user_args[@]}" "${MRHIS_CONTAINER_NAME}" \
                    ansible "${target}" ${inv} "${vault_arg[@]}" ${evars} \
                    -e "ansible_user=root" \
                    -e "ansible_password=${root_auth_pass}" \
                    -e "ansible_become=false" \
                    -e "ansible_become_password=${root_auth_pass}" \
                    -m shell -a "${shell_cmd}" ${extra_args}
            fi
        else
            if [ "$use_interactive_vault_prompt" = "1" ]; then
                podman exec -it -e "ANSIBLE_CONFIG=${MRHIS_ANSIBLE_CFG_CONTAINER}" -e "ANSIBLE_LOG_PATH=${ansible_log_file}" "${podman_user_args[@]}" "${MRHIS_CONTAINER_NAME}" \
                    ansible "${target}" ${inv} "${vault_arg[@]}" ${evars} \
                    -m shell -a "${shell_cmd}" ${extra_args}
            else
                podman exec -e "ANSIBLE_CONFIG=${MRHIS_ANSIBLE_CFG_CONTAINER}" -e "ANSIBLE_LOG_PATH=${ansible_log_file}" "${podman_user_args[@]}" "${MRHIS_CONTAINER_NAME}" \
                    ansible "${target}" ${inv} "${vault_arg[@]}" ${evars} \
                    -m shell -a "${shell_cmd}" ${extra_args}
            fi
        fi
    }

    # ---- Container hotfix / compatibility helpers ---------------------------
    ensure_satellite_chrony_template() {
        local _tpl_path="/mrhis/mrhis-builder-satellite/roles/satellite_pre/templates/chrony.j2"
        local _local_tpl_path="${SCRIPT_DIR}/local/roles/mrhis-builder-satellite/roles/satellite_pre/templates/chrony.j2"
        local _mk_cmd='mkdir -p /mrhis/mrhis-builder-satellite/roles/satellite_pre/templates && cat > /mrhis/mrhis-builder-satellite/roles/satellite_pre/templates/chrony.j2 <<'"'"'EOF'"'"'
# MRHIS fallback chrony template (auto-generated when upstream template is missing)
driftfile /var/lib/chrony/drift
makestep 1.0 3
rtcsync
logdir /var/log/chrony
pool 2.rhel.pool.ntp.org iburst
EOF'

        # In local mode the container is not running; check local repo path first.
        if [ -f "${_local_tpl_path}" ]; then
            return 0
        fi

        if podman exec "${MRHIS_CONTAINER_NAME}" test -f "${_tpl_path}" 2>/dev/null; then
            return 0
        fi

        print_warning "chrony.j2 is missing in mrhis-builder-satellite; applying fallback template workaround."

        # Try creating in local path first (local mode)
        if mkdir -p "$(dirname "${_local_tpl_path}")" 2>/dev/null && \
           cat > "${_local_tpl_path}" <<'CHRONY_TPL'
# MRHIS fallback chrony template (auto-generated when upstream template is missing)
driftfile /var/lib/chrony/drift
makestep 1.0 3
rtcsync
logdir /var/log/chrony
pool 2.rhel.pool.ntp.org iburst
CHRONY_TPL
        then
            print_success "Fallback chrony.j2 created locally in mrhis-builder-satellite templates."
            return 0
        fi

        if podman exec "${MRHIS_CONTAINER_NAME}" bash -lc "${_mk_cmd}" >/dev/null 2>&1 || \
           podman exec --user 0 "${MRHIS_CONTAINER_NAME}" bash -lc "${_mk_cmd}" >/dev/null 2>&1; then
            print_success "Fallback chrony.j2 created in mrhis-builder-satellite templates."
            return 0
        fi

        print_warning "Failed to create fallback chrony.j2; will skip tags_satellite_pre_chrony."
        return 1
    }

