        local _mk_cmd='mkdir -p /mrhis/mrhis-builder-idm/roles/idm_pre/templates && cat > /mrhis/mrhis-builder-idm/roles/idm_pre/templates/chrony.j2 <<'"'"'EOF'"'"'
