    _load_env_key SAT_IMAGE_USERNAME sat_image_username
    _load_env_key SAT_IMAGE_PASSWORD sat_image_password

    # Optional OpenShift node configuration
    _load_env_key OPENSHIFT_IP openshift_ip
    _load_env_key OPENSHIFT_NETMASK openshift_netmask
    _load_env_key OPENSHIFT_GW openshift_gw
    _load_env_key OPENSHIFT_HOSTNAME openshift_hostname
    _load_env_key OPENSHIFT_ALIAS openshift_alias
    _load_env_key OPENSHIFT_DOMAIN openshift_domain
    _load_env_key OPENSHIFT_CPU openshift_cpu
    _load_env_key OPENSHIFT_MEMORY_MB openshift_memory_mb
    _load_env_key OPENSHIFT_VOLUME_GB openshift_volume_gb

    # Canonical shared password source is aap_admin_pass. Keep aliases aligned.
    if [ -n "${AAP_ADMIN_PASS:-}" ]; then
        ADMIN_PASS="${ADMIN_PASS:-${AAP_ADMIN_PASS}}"
        SAT_ADMIN_PASS="${SAT_ADMIN_PASS:-${AAP_ADMIN_PASS}}"
        SAT_INITIAL_ADMIN_PASS="${SAT_INITIAL_ADMIN_PASS:-${SAT_ADMIN_PASS}}"
        IDM_ADMIN_PASS="${IDM_ADMIN_PASS:-${AAP_ADMIN_PASS}}"
        IPADM_PASSWORD="${IPADM_PASSWORD:-${IDM_ADMIN_PASS}}"
        IPAADMIN_PASSWORD="${IPAADMIN_PASSWORD:-${IDM_ADMIN_PASS}}"
    fi
    normalize_shared_env_vars

    # Keep legacy HUB_TOKEN and dedicated vault_console_redhat_token aligned.
    if [ -z "${VAULT_CONSOLE_REDHAT_TOKEN:-}" ] && [ -n "${HUB_TOKEN:-}" ]; then
        VAULT_CONSOLE_REDHAT_TOKEN="${HUB_TOKEN}"
    fi
    if [ -z "${HUB_TOKEN:-}" ] && [ -n "${VAULT_CONSOLE_REDHAT_TOKEN:-}" ]; then
        HUB_TOKEN="${VAULT_CONSOLE_REDHAT_TOKEN}"
    fi
}

# Persist all MRHIS credentials to ~/.ansible/conf/env.yml (atomic write, chmod 600).
write_ansible_env_file() {
    mkdir -p "$ANSIBLE_ENV_DIR" || return 1
    ensure_ansible_vault || return 1
    ensure_vault_password_file || return 1
    normalize_shared_env_vars

    local tmp_env
    tmp_env="$(mktemp "${ANSIBLE_ENV_DIR}/.env.yml.XXXXXX")"
    cat > "$tmp_env" <<MRHIS_ENV_EOF
