if [ "$(id -u)" -eq 0 ]; then
    _gateway_root_patch_out="$(python3 - <<'PY'
from pathlib import Path

roles_root = Path('/home/admin/aap-setup/collections/ansible_collections/ansible/containerized_installer/roles')
files = list(roles_root.rglob('*.yml')) if roles_root.exists() else []
gateway_migrate = roles_root / 'automationgateway/tasks/migrate.yml'
hub_upload_images = roles_root / 'automationhub/tasks/upload_images.yml'

updated = 0
for path in files:
    text = path.read_text(encoding='utf-8', errors='ignore')
    new_text = text.replace('userns: keep-id', 'userns: host')
    if new_text != text:
        path.write_text(new_text, encoding='utf-8')
        updated += 1

if gateway_migrate.exists():
    import re
    text = gateway_migrate.read_text(encoding='utf-8', errors='ignore')
    original_text = text
    marker = '- name: Ensure automation gateway proxy is ready\n'
    injected = '''- name: Normalize automation gateway nginx temp ownership for root callback run
  ansible.builtin.command: podman exec automation-gateway sh -lc "chown -R 999:999 /var/lib/nginx/tmp"
  changed_when: false
  when: ansible_user_uid | int == 0

'''
    if injected not in text and marker in text:
        text = text.replace(marker, injected + marker, 1)

    # Some runs fail here with a transient 404 on the controller service-index
    # endpoint during gateway data migration. Add a readiness probe ahead of
    # the merge and harden retries/delay for the merge task.
    merge_marker = '- name: Merge organization\n'
    merge_wait_injected = '''- name: MRHIS: wait for controller service-index endpoint before merge
  ansible.builtin.uri:
    url: "https://{{ ansible_fqdn | default(inventory_hostname) }}/api/controller/v2/service-index/role-types/?page_size=1"
    method: GET
    validate_certs: false
    status_code: [200, 401, 403]
  register: _mrhis_service_index_probe
  changed_when: false
  failed_when: false
  retries: 36
  delay: 10
  until: _mrhis_service_index_probe.status is defined and _mrhis_service_index_probe.status in [200, 401, 403]

'''
    if merge_wait_injected not in text and merge_marker in text:
        text = text.replace(merge_marker, merge_wait_injected + merge_marker, 1)

    def _harden_merge_task(block):
        block = re.sub(r'(?m)^(\s*retries:\s*)\d+\s*$', r'\g<1>30', block, count=1)
        block = re.sub(r'(?m)^(\s*delay:\s*)\d+\s*$', r'\g<1>10', block, count=1)
        return block

    text = re.sub(
        r'(?ms)^- name: Merge organization\n.*?(?=^\s*- name: |\Z)',
        lambda m: _harden_merge_task(m.group(0)),
        text,
        count=1,
    )

    # Patch any direct aap-gateway-manage invocations so they run inside the
    # automation-gateway container with PYTHONHTTPSVERIFY=0 to disable TLS
    # verification for demo / self-signed cert scenarios. Only apply if the
    # patch hasn't already been added.
    if 'PYTHONHTTPSVERIFY=0' not in text:
        def _wrap_aap_manage(m):
            cmd = m.group(1).strip()
            # if it's already using podman exec, leave it alone
            if 'podman exec' in cmd:
                return m.group(0)
            # If an AAP root CA bundle exists in artifacts_user, copy it into the
            # automation-gateway container and update the container trust store
            # before running the management command. Use a host-level shell so
            # we can run podman cp and podman exec in sequence.
            safe_cmd = cmd.replace('"', '\\"')
            new_cmd = (
                "sh -lc 'if [ -f artifacts_user/aap-root-ca.pem ]; then "
                "podman cp artifacts_user/aap-root-ca.pem automation-gateway:/etc/pki/ca-trust/source/anchors/aap-root-ca.pem && "
                "podman exec automation-gateway sh -lc \"update-ca-trust extract 2>/dev/null || update-ca-certificates 2>/dev/null || true\"; "
                "fi; podman exec automation-gateway sh -lc \"PYTHONHTTPSVERIFY=0 " + safe_cmd + "\"'"
            )
            return 'ansible.builtin.command: ' + new_cmd

        text = re.sub(r'ansible\.builtin\.command:\s*(.+aap-gateway-manage[^\n]*)', _wrap_aap_manage, text)
    if text != original_text:
        gateway_migrate.write_text(text, encoding='utf-8')
        updated += 1

if hub_upload_images.exists():
    text = hub_upload_images.read_text(encoding='utf-8', errors='ignore')
    marker = '- name: Push the container images to automation hub\n'
    injected = '''- name: Normalize automation hub web nginx temp ownership for root callback run
  ansible.builtin.command: podman exec automation-hub-web sh -lc "uid=$(id -u nginx 2>/dev/null || echo 998); gid=$(id -g nginx 2>/dev/null || echo ${uid}); chown -R ${uid}:${gid} /var/lib/nginx/tmp"
  changed_when: false
  when: ansible_user_uid | int == 0

'''
    if injected not in text and marker in text:
        hub_upload_images.write_text(text.replace(marker, injected + marker, 1), encoding='utf-8')
        updated += 1

print(f'UPDATED={updated}')
PY
)"
