fi

mkdir -p /etc/ansible /var/lib/mrhis-cmdb/facts /var/www/mrhis-cmdb

# Helper: fetch Satellite-registered hosts and write ansible-cmdb stub fact files
cat > /usr/local/bin/mrhis-sat-facts.py <<'SATFACTS_EOF'
#!/usr/bin/env python3
"""Fetch all Satellite-registered hosts and write ansible-cmdb compatible fact stubs."""
import sys, json, os, ssl, base64, urllib.request

def sat_get(url, user, passwd):
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    req = urllib.request.Request(url)
    req.add_header('Authorization', 'Basic ' + base64.b64encode(f"{user}:{passwd}".encode()).decode())
    req.add_header('Accept', 'application/json')
    with urllib.request.urlopen(req, context=ctx, timeout=30) as r:
        return json.loads(r.read())

def main():
    sat_url   = os.environ.get('SAT_URL', 'https://localhost')
    user      = os.environ.get('SAT_USER', 'admin')
    passwd    = os.environ.get('SAT_PASS', 'admin')
    facts_dir = sys.argv[1] if len(sys.argv) > 1 else '/var/lib/mrhis-cmdb/facts'
    skip      = set(filter(None, os.environ.get('SKIP_HOSTS', '').split(',')))
    try:
        data = sat_get(f"{sat_url}/api/v2/hosts?per_page=1000", user, passwd)
    except Exception as e:
        print(f"  WARNING: Satellite API unreachable: {e}", file=sys.stderr); return
    written = 0
    for h in data.get('results', []):
        name = h.get('name', '')
        if not name or name in skip:
            continue
        fact_file = os.path.join(facts_dir, name)
        # Skip if ansible already gathered full live facts for this host
        if os.path.exists(fact_file):
            try:
                ex = json.loads(open(fact_file).read())
                if ex.get('ansible_facts', {}).get('ansible_hostname') and ex.get('_source') != 'satellite-api':
                    continue
            except Exception:
                pass
        # Try per-host facts from Satellite
        sat_facts = {}
        try:
            fd = sat_get(f"{sat_url}/api/v2/hosts/{h['id']}/facts?per_page=1000", user, passwd)
            results = fd.get('results', {})
            if results:
                sat_facts = next(iter(results.values()))
        except Exception:
            pass
        ip      = h.get('ip') or h.get('ip6') or sat_facts.get('ipaddress', '')
        mac     = h.get('mac') or sat_facts.get('macaddress', '')
        os_full = h.get('operatingsystem_name', '') or sat_facts.get('operatingsystem', '')
        os_name = os_full.split()[0] if os_full else 'RHEL'
        os_ver  = sat_facts.get('operatingsystemrelease', (os_full.split()[-1] if ' ' in os_full else ''))
        arch    = h.get('architecture_name') or sat_facts.get('architecture', 'x86_64')
        mem_mb  = 0
        for mkey in ('memorysize_mb', 'memorytotal'):
            raw = sat_facts.get(mkey, '')
            if raw:
                try: mem_mb = int(float(str(raw).split()[0])); break
                except Exception: pass
        fact = {
            "ansible_facts": {
                "ansible_hostname":             name.split('.')[0],
                "ansible_fqdn":                 name,
                "ansible_nodename":             name,
                "ansible_default_ipv4":         {"address": ip, "macaddress": mac},
                "ansible_interfaces":           [],
                "ansible_distribution":         os_name,
                "ansible_distribution_version": os_ver,
                "ansible_architecture":         arch,
                "ansible_processor_count":      int(sat_facts.get('processorcount', 1)),
                "ansible_memtotal_mb":          mem_mb,
                "ansible_kernel":               sat_facts.get('kernelversion', sat_facts.get('kernel', '')),
                "satellite_hostgroup":          h.get('hostgroup_name', ''),
                "satellite_environment":        h.get('environment_name', ''),
                "satellite_organization":       h.get('organization_name', ''),
                "satellite_location":           h.get('location_name', ''),
                "satellite_managed":            True,
                "satellite_registered":         h.get('subscription_status_label', 'unknown'),
                "satellite_content_view":       ((h.get('content_facet_attributes') or {}).get('content_view') or {}).get('name', ''),
                "satellite_lifecycle_env":      ((h.get('content_facet_attributes') or {}).get('lifecycle_environment') or {}).get('name', ''),
            },
            "changed": False,
            "_source": "satellite-api"
        }
        with open(fact_file, 'w') as f:
            json.dump(fact, f, indent=2)
        written += 1
    print(f"  Satellite stub facts: {written}/{len(data.get('results',[]))} hosts written")

main()
SATFACTS_EOF
chmod 0755 /usr/local/bin/mrhis-sat-facts.py

cat > /usr/local/bin/mrhis-cmdb-refresh.sh <<CMDB_REFRESH
#!/usr/bin/env bash
set -uo pipefail

INV=\$(mktemp /tmp/mrhis-cmdb-inv.XXXXXX.ini)
trap 'rm -f "\${INV}"' EXIT

FACTS=/var/lib/mrhis-cmdb/facts
OUT=/var/www/mrhis-cmdb/index.html
SAT_IP="${SAT_IP}"
AAP_IP="${AAP_IP}"
IDM_IP="${IDM_IP}"
SAT_HOSTNAME="${SAT_HOSTNAME}"
AAP_HOSTNAME="${AAP_HOSTNAME}"
IDM_HOSTNAME="${IDM_HOSTNAME}"
HOST_INT_IP="${HOST_INT_IP:-10.168.0.1}"
ADMIN_USER="${ADMIN_USER}"
ADMIN_PASS="${ADMIN_PASS}"

mkdir -p "\${FACTS}"

# ── 1. Build inventory: RHIS nodes + every Satellite-registered host ─────────
{
cat <<INV_CORE
[mrhis]
\${SAT_HOSTNAME} ansible_host=\${SAT_IP}
\${AAP_HOSTNAME} ansible_host=\${AAP_IP}
\${IDM_HOSTNAME} ansible_host=\${IDM_IP}

[satellite_managed]
INV_CORE

SKIP="\${SAT_HOSTNAME},\${AAP_HOSTNAME},\${IDM_HOSTNAME}"
curl -sS -k -u "\${ADMIN_USER}:\${ADMIN_PASS}" \
  "https://\${SAT_IP}/api/v2/hosts?per_page=1000&fields=name,ip" 2>/dev/null \
| python3 -c "
import sys,json
skip=set('\${SKIP}'.split(','))
for h in json.load(sys.stdin).get('results',[]):
    n,ip=h.get('name',''),h.get('ip','')
    if n and n not in skip and ip:
        print(f'{n} ansible_host={ip}')
" 2>/dev/null || true

cat <<INV_VARS

[all:vars]
ansible_user=\${ADMIN_USER}
ansible_password=\${ADMIN_PASS}
ansible_become=true
ansible_become_password=\${ADMIN_PASS}
ansible_ssh_common_args='-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no -o ConnectTimeout=8 -o BatchMode=yes'
INV_VARS
} > "\${INV}"

echo "[\$(date '+%F %T')] Inventory: \$(grep -c ansible_host= \${INV} 2>/dev/null || echo 0) hosts"

# ── 2. Gather live facts from all reachable hosts (best-effort) ──────────────
ansible -i "\${INV}" all -m setup --tree "\${FACTS}" --timeout 20 -o 2>/dev/null || true

# ── 3. Backfill stub facts from Satellite for unreachable hosts ──────────────
SAT_URL="https://\${SAT_IP}" \
SAT_USER="\${ADMIN_USER}" \
SAT_PASS="\${ADMIN_PASS}" \
SKIP_HOSTS="\${SKIP}" \
  /usr/local/bin/mrhis-sat-facts.py "\${FACTS}"

# ── 4. Synthetic MRHIS container node ────────────────────────────────────
container_status="down"
curl -ksSf --max-time 5 "http://\${HOST_INT_IP}:3000/" >/dev/null 2>&1 && container_status="up"
cat > "\${FACTS}/mrhis-container" <<JSON
{
    "ansible_facts": {
        "ansible_hostname": "mrhis-container",
        "ansible_fqdn": "mrhis-container",
        "ansible_nodename": "mrhis-container",
        "ansible_default_ipv4": {"address": "\${HOST_INT_IP}"},
        "mrhis_container_endpoint": "http://\${HOST_INT_IP}:3000",
        "mrhis_container_status": "\${container_status}"
    },
    "changed": false
}
JSON

# ── 5. Generate dashboard ────────────────────────────────────────────────────
ansible-cmdb -t html_fancy "\${FACTS}" > "\${OUT}"
echo "[\$(date '+%F %T')] CMDB refreshed: \$(ls \${FACTS} | wc -l) nodes"
CMDB_REFRESH

chmod 0755 /usr/local/bin/mrhis-cmdb-refresh.sh

cat > /etc/systemd/system/mrhis-cmdb-refresh.service <<'CMDB_REFRESH_SVC'
[Unit]
Description=Refresh MRHIS ansible-cmdb dashboard data
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/mrhis-cmdb-refresh.sh
CMDB_REFRESH_SVC

cat > /etc/systemd/system/mrhis-cmdb-refresh.timer <<'CMDB_REFRESH_TIMER'
[Unit]
Description=Periodic MRHIS ansible-cmdb refresh timer

[Timer]
OnBootSec=2min
OnUnitActiveSec=10min
Unit=mrhis-cmdb-refresh.service

[Install]
WantedBy=timers.target
CMDB_REFRESH_TIMER

cat > /etc/systemd/system/mrhis-cmdb-http.service <<'CMDB_HTTP_SVC'
[Unit]
Description=MRHIS CMDB Dashboard HTTP Server
After=network-online.target mrhis-cmdb-refresh.service
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=/var/www/mrhis-cmdb
ExecStart=/usr/bin/python3 -m http.server 18080 --bind 0.0.0.0
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
CMDB_HTTP_SVC

systemctl daemon-reload
systemctl enable mrhis-cmdb-refresh.timer
systemctl enable mrhis-cmdb-http.service

# Ensure firewalld is active before applying permanent rules.
# During kickstart %post the daemon may not be started yet; start it so
# firewall-cmd can connect to its socket and write the permanent config.
systemctl start firewalld 2>/dev/null || true

# Open port 18080 in the configured zone (${SAT_FIREWALLD_ZONE}) and in
# the public zone as a belt-and-suspenders fallback, then reload.
firewall-cmd --zone=${SAT_FIREWALLD_ZONE} --permanent --add-port=18080/tcp || true
firewall-cmd --zone=public --permanent --add-port=18080/tcp || true
firewall-cmd --reload || true

# Label port 18080 as http_port_t so SELinux allows python3 http.server
# to bind on it when the mrhis-cmdb-http.service starts.
semanage port -a -t http_port_t -p tcp 18080 2>/dev/null || \
    semanage port -m -t http_port_t -p tcp 18080 2>/dev/null || true
fi

${ks_perf_network_snapshot}

echo "Post-install configuration complete."
%end
POSTEOF

    cp "$tmp_ks" "$tmp_oem"
    write_file_if_changed "$tmp_ks" "$ks_file" 0644 || {
        rm -rf "$tmpdir"
        return 1
    }
    ks_changed="${MRHIS_LAST_WRITE_CHANGED:-0}"

    if [ "$ks_changed" = "0" ] && [ -f "$OEMDRV_ISO" ]; then
        rm -rf "$tmpdir"
        print_step "OEMDRV ISO unchanged: $OEMDRV_ISO"
        print_success "Generated Satellite kickstart: $ks_file"
        print_success "Created OEMDRV ISO: $OEMDRV_ISO"
        return 0
    fi

    print_step "Packaging Satellite kickstart into OEMDRV ISO"
    if command -v genisoimage >/dev/null 2>&1; then
        sudo genisoimage -output "$OEMDRV_ISO" -volid "OEMDRV" -rational-rock -joliet -full-iso9660-filenames "$tmp_oem" >/dev/null 2>&1
    else
        sudo xorriso -as mkisofs -o "$OEMDRV_ISO" -V OEMDRV -r -J "$tmp_oem" >/dev/null 2>&1
    fi

    sudo chmod 0644 "$OEMDRV_ISO"
    sudo chown qemu:qemu "$OEMDRV_ISO" 2>/dev/null || true
    rm -rf "$tmpdir"

    validate_kickstart_integrity "$ks_file" "Satellite kickstart" || return 1

    print_success "Generated Satellite kickstart: $ks_file"
    print_success "Created OEMDRV ISO: $OEMDRV_ISO"
}

generate_satellite_oemdrv_only() {
    print_step "Generating Satellite kickstart and OEMDRV ISO only"
    ensure_kickstart_prereqs_ready "satellite" || return 1
    normalize_shared_env_vars
    ensure_iso_vars || return 1
    sudo mkdir -p "${FILES_DIR}" "${KS_DIR}"
    generate_satellite_618_kickstart || {
        print_warning "Satellite kickstart/OEMDRV generation failed. Check required credentials in ${ANSIBLE_ENV_FILE}."
        return 1
    }
    print_success "Satellite OEMDRV workflow complete"
}

generate_aap_oemdrv_only() {
    print_step "Generating AAP kickstart and OEMDRV ISO only"
    ensure_kickstart_prereqs_ready "aap" || return 1
    normalize_shared_env_vars
    ensure_iso_vars || return 1
    sudo mkdir -p "${FILES_DIR}" "${KS_DIR}"
    generate_aap_kickstart || {
        print_warning "AAP kickstart/OEMDRV generation failed. Check required credentials in ${ANSIBLE_ENV_FILE}."
        return 1
    }
    print_success "AAP OEMDRV workflow complete"
}

generate_idm_kickstart_core() {
    bootstrap_ssh_keys="$(collect_bootstrap_public_keys)"
    if [ -z "${bootstrap_ssh_keys:-}" ]; then
        print_error "No bootstrap SSH public keys found. Ensure MRHIS installer key exists and re-run."
        return 1
    fi
    ks_runtime_exports="$(kickstart_runtime_exports_block "${bootstrap_ssh_keys}")"
    local ks_file="${KS_DIR}/idm.ks"
    # Compute interface MACs and prefix for IdM kickstart
    idm_ext_mac="$(get_vm_external_mac "idm")"
    idm_int_mac="$(get_vm_internal_mac "idm")"
    idm_prefix="$(netmask_to_prefix "${IDM_NETMASK}")"
    print_kickstart_effective_values "IdM" "${IDM_IP}" "${IDM_HOSTNAME}" "${IDM_NETMASK}" "${IDM_GW}"

    prepare_kickstart_shared_blocks "idm" "${IDM_HOSTNAME}" "${IDM_IP}" \
        "${idm_ext_mac}" "${idm_int_mac}" "${IDM_IP}" "${idm_prefix}" "${IDM_GW}" \
        0 1 "IdM" \
        "rhel-10-for-x86_64-baseos-rpms" \
        "rhel-10-for-x86_64-appstream-rpms"
    ks_nogpg_policy="${MRHIS_KS_NOGPG_POLICY}"
    ks_ssh_baseline="${MRHIS_KS_SSH_BASELINE}"
    ks_user_sudo_bootstrap="${MRHIS_KS_USER_SUDO_BOOTSTRAP}"
    ks_rhsm_register="${MRHIS_KS_RHSM_REGISTER}"
    ks_rhc_connect="${MRHIS_KS_RHC_CONNECT}"
    ks_repo_enable_verify="${MRHIS_KS_REPO_ENABLE_VERIFY}"
    ks_nm_dual_nic="${MRHIS_KS_NM_DUAL_NIC}"
    ks_hosts_mapping="$(kickstart_hosts_mapping_block "${SAT_IP}" "${SAT_HOSTNAME}" "${SAT_HOSTNAME%%.*}" "${AAP_IP}" "${AAP_HOSTNAME}" "${AAP_HOSTNAME%%.*}" "${IDM_IP}" "${IDM_HOSTNAME}" "${IDM_HOSTNAME%%.*}")"
    ks_trust_bootstrap_keys="${MRHIS_KS_TRUST_BOOTSTRAP_KEYS}"
    ks_creator_baseline="${MRHIS_KS_CREATOR_BASELINE}"
    ks_perf_network_snapshot="$(kickstart_perf_network_snapshot_block)"

    # Compute password hashes for kickstart (ensures non-empty rootpw in DEMO mode)
    root_pass_hash="$(kickstart_password_hash "${ROOT_PASS:-${ADMIN_PASS}}")" || return 1
    admin_pass_hash="$(kickstart_password_hash "${ADMIN_PASS}")" || return 1

    tmp_ks="$(mktemp)"

    # --- Common header ---
    cat > "$tmp_ks" <<HEADER
text
reboot
keyboard us
lang en_US.UTF-8
selinux --permissive
firewall --disabled
bootloader --append="net.ifnames=0 biosdevname=0"

rootpw --iscrypted "${root_pass_hash}"
user --name="${ADMIN_USER}" --password="${admin_pass_hash}" --iscrypted --groups=wheel

network --bootproto=dhcp --device=eth0 --interfacename=eth0:${idm_ext_mac} --activate --onboot=yes

%include /tmp/network-eth1
HEADER

    # --- eth1 (always static for internal provisioning/management network) ---
    build_internal_kickstart_network_line "eth1" "${idm_int_mac}" "${IDM_IP}" "${IDM_NETMASK}" "${IDM_GW}" "${IDM_HOSTNAME}" >> "$tmp_ks"
    echo "" >> "$tmp_ks"

    # --- Partitioning (DEMO vs production best-practice) ---
    if is_demo; then
        print_step "IdM kickstart: DEMO partition layout (/boot 2G + swap 4G + / rest)"
        cat >> "$tmp_ks" <<'DEMO_PART'
# DEMO Partitioning — minimal footprint for PoC/learning environments
# Requirements: 2 vCPU, 4 GB RAM, 30 GB raw storage
zerombr
clearpart --all --initlabel
part biosboot --fstype="biosboot" --size=1
part /boot --fstype="xfs"  --size=2048
part swap                   --size=4096
part /     --fstype="xfs"  --grow --size=1

DEMO_PART
    else
        print_step "IdM kickstart: production/best-practice LVM layout"
        cat >> "$tmp_ks" <<'STD_PART'
# Best Practice Partitioning for Red Hat IdM (LVM)
# Requirements: 4 vCPU, 16 GB RAM, 60 GB raw storage minimum
zerombr
clearpart --all --initlabel
part biosboot --fstype="biosboot" --size=1
part /boot --fstype="xfs" --size=2048
part swap  --size=8192
part pv.01 --grow --size=1
volgroup vg_system pv.01
logvol /    --fstype="xfs" --name=lv_root --vgname=vg_system --size=10240
logvol /var --fstype="xfs" --name=lv_var  --vgname=vg_system --grow --size=1

STD_PART
    fi

    # --- Packages ---
    cat >> "$tmp_ks" <<'PKGS'
%packages
@Base
@Core
ansible-core
bash-completion
bind-utils
chrony
libvirt-client
man-pages
net-tools
qemu-guest-agent
tmux
tuned
util-linux-core
xfsdump
yum
yum-utils
zip
-ntp
ipa-server
ipa-server-dns
bind-dyndb-ldap
%end

PKGS

    # --- Post-install (variable expansion required) ---
    cat >> "$tmp_ks" <<POSTEOF
%post --log=/root/ks-post.log
set -euo pipefail
set -x  # trace every command; all output captured in /root/ks-post.log

# Phase logger: writes to ks-post.log AND /dev/console (watch live: virsh console <vm>)
ks_log() { local ts; ts=\$(date +%H:%M:%S 2>/dev/null || echo "--:--:--"); printf '\n[MRHIS %s] %s\n' "\$ts" "\$*" | tee /dev/console 2>/dev/null || true; }
trap 'ec=\$?; ks_log "FAILED at line \${LINENO} (exit code \${ec}) -- see /root/ks-post.log"; exit \$ec' ERR
ks_log "=== MRHIS %post: idm: STARTED ==="

${ks_runtime_exports}

${ks_nogpg_policy}

${ks_nm_dual_nic}

${ks_hosts_mapping}

${ks_ssh_baseline}

${ks_user_sudo_bootstrap}

${ks_trust_bootstrap_keys}

if [ "${MRHIS_DEFER_COMPONENT_INSTALL:-1}" = "1" ]; then
    ks_log "Deferring component repo/package enablement to post-boot config-as-code"
    ks_log "Running RHSM/RHC registration during first boot"
${ks_rhsm_register}

${ks_rhc_connect}
else
${ks_rhsm_register}

${ks_rhc_connect}
fi

${ks_creator_baseline}

# 3. Hostname
hostnamectl set-hostname "${IDM_HOSTNAME}"

if [ "${MRHIS_DEFER_COMPONENT_INSTALL:-1}" != "1" ]; then
# 4. Repositories
${ks_repo_enable_verify}
fi

# 4.1 Verify required IdM packages from kickstart payload are present
if ! rpm -q ipa-server ipa-server-dns bind-dyndb-ldap >/dev/null 2>&1; then
    echo "ERROR: Required IdM packages missing after kickstart package phase."
    rpm -qa | grep -E '^ipa-server|^bind-dyndb-ldap' || true
    exit 1
fi

if [ "${MRHIS_DEFER_COMPONENT_INSTALL:-1}" = "1" ]; then
    ks_log "IdM component install is deferred to post-boot config-as-code"
else

# 5. IdM Server Installation (unattended)
ipa-server-install --unattended --realm="${IDM_REALM}" --domain="${IDM_DOMAIN}" --hostname="${IDM_HOSTNAME}" --admin-password="${IDM_ADMIN_PASS}" --ds-password="${IDM_DS_PASS}" --setup-dns --auto-forwarders --no-ntp

# 5.1 Post-IdM Installation: User Management, Access Control & DNS Configuration
echo "=== IDM SERVER POST-INSTALL CONFIGURATION ==="

# Wait for IdM services to be fully ready
echo "Waiting for IdM services to be ready..."
for i in {1..60}; do
    if systemctl is-active -q ipa || ipactl status 2>/dev/null | grep -q "Directory Service"; then
        echo "✓ IdM services are ready"
        break
    fi
    if [ $i -eq 60 ]; then
        echo "⚠ WARNING: IdM services did not fully start after 60 seconds (continuing anyway)"
    fi
    spinner_tick 1
done

sleep_with_spinner 3 "Finalizing IdM services setup"

# Configure ipa CLI with admin credentials
export KRB5_TRACE=/dev/null 2>/dev/null || true
echo "${IDM_ADMIN_PASS}" | kinit admin@${IDM_REALM} 2>/dev/null || true

echo "IdM users/groups/password policy are managed post-boot by config-as-code roles (idm_users/idm_user_groups/idm_password_policy)."

# --- 5.1.4 Configure Host-Based Access Control (HBAC) ---
echo "Configuring host-based access control rules..."

if [ "${IDM_ENABLE_HBAC_RULES:-1}" = "1" ]; then
    # HBAC service for SSH
    ipa hbacsvc-add ssh 2>/dev/null || echo "  ℹ SSH HBAC service already exists"
    ipa hbacsvc-add satellite-api 2>/dev/null || echo "  ℹ Satellite API HBAC service already exists"
    ipa hbacsvc-add aap-api 2>/dev/null || echo "  ℹ AAP API HBAC service already exists"

    # HBAC rule for admins to all systems
    ipa hbacrule-add --usercat=all --hostcat=all mrhis-admin-all-access 2>/dev/null || echo "  ℹ mrhis-admin-all-access rule already exists"
    ipa hbacrule-add-service mrhis-admin-all-access --hbacsvcs=ssh 2>/dev/null || echo "  ℹ SSH service already added to rule"
    ipa hbacrule-add-user mrhis-admin-all-access --groups="${IDM_ADMINS_GROUP:-mrhis-admins}" 2>/dev/null || echo "  ℹ ${IDM_ADMINS_GROUP:-mrhis-admins} already in rule"

    # HBAC rule for automation group to automation hosts
    ipa hbacrule-add --usercat=all automation-host-access 2>/dev/null || echo "  ℹ automation-host-access rule already exists"
    ipa hbacrule-add-service automation-host-access --hbacsvcs=ssh 2>/dev/null || echo "  ℹ SSH service already added"
fi

# --- 5.1.5 Configure SUDO Rules ---
echo "Configuring IdM sudo rules for infrastructure automation..."

if [ "${IDM_ENABLE_SUDO_RULES:-1}" = "1" ]; then
    # Sudo rule for MRHIS admins (full sudo access)
    ipa sudorule-add mrhis-admins-all --hostcat=all --runasusercat=all 2>/dev/null || echo "  ℹ mrhis-admins-all sudo rule already exists"
    ipa sudorule-add-user mrhis-admins-all --groups="${IDM_ADMINS_GROUP:-mrhis-admins}" 2>/dev/null || echo "  ℹ ${IDM_ADMINS_GROUP:-mrhis-admins} group already added"
    ipa sudorule-add-allow-command mrhis-admins-all --allow-cmds=ALL 2>/dev/null || echo "  ℹ ALL commands already allowed"

    # Sudo rule for content managers (restricted commands)
    ipa sudorule-add content-manager-provision --hostcat=all 2>/dev/null || echo "  ℹ content-manager-provision sudo rule already exists"
    ipa sudorule-add-user content-manager-provision --groups="${IDM_CONTENT_MANAGERS_GROUP:-content-managers}" 2>/dev/null || echo "  ℹ ${IDM_CONTENT_MANAGERS_GROUP:-content-managers} group already added"
    ipa sudorule-add-allow-command content-manager-provision --allow-cmds="/usr/bin/hammer" 2>/dev/null || echo "  ℹ hammer command already allowed"
    ipa sudorule-add-allow-command content-manager-provision --allow-cmds="/usr/bin/ansible" 2>/dev/null || echo "  ℹ ansible command already allowed"
    ipa sudorule-add-allow-command content-manager-provision --allow-cmds="/usr/bin/ansible-playbook" 2>/dev/null || echo "  ℹ ansible-playbook command already allowed"
fi

# --- 5.1.6 Enable DNS Services and Configure Zone ---
echo "Configuring IdM DNS services..."

# Ensure DNS service is running
systemctl enable --now named || true
systemctl status named >/dev/null 2>&1 && echo "✓ DNS service running" || echo "⚠ DNS service not running"

# Add DNS zone delegation records (if using subdomain)
ipa dnszone-add ${IDM_DOMAIN}. 2>/dev/null || echo "  ℹ DNS zone ${IDM_DOMAIN}. already configured"

# Add DNS forwarder for lookup optimization
ipa dnsconfig-mod --forwarder=8.8.8.8 2>/dev/null || echo "  ℹ DNS forwarders already configured"

# --- 5.1.7 Configure SSH Key Distribution ---
echo "Setting up IdM SSH key management..."

# Create SSH public key object store
mkdir -p /var/lib/mrhis-ssh-keys
chmod 0755 /var/lib/mrhis-ssh-keys

# Enable SSH key authentication in IdM user accounts
ipa config-mod --enable-sid || echo "  ℹ SID already enabled"

# --- 5.1.8 Configure LDAP Replication/Synchronization ---
echo "Configuring IdM LDAP and replication parameters..."

# Set LDAP entry cache timeout for quicker updates
ldapmodify -D "cn=directory manager" -w "${IDM_DS_PASS}" <<'LDAP_CONFIG' 2>/dev/null || echo "  ℹ LDAP cache configuration skipped"
dn: cn=config
changetype: modify
replace: nsslapd-cachememsize
nsslapd-cachememsize: 52428800
-
replace: nsslapd-dbcachesize
nsslapd-dbcachesize: 104857600
LDAP_CONFIG

# --- 5.1.9 Configure Kerberos SPN Registration ---
echo "Registering service principal names..."

# Already configured during ipa-server-install, but verify key services
klist -e 2>/dev/null | grep -q "krbtgt/${IDM_REALM}" && echo "✓ Kerberos realm configured" || echo "⚠ Kerberos not fully initialized"

# --- 5.1.10 Export IdM Configuration for Satellite Integration ---
echo "Preparing IdM integration data for Satellite..."

# Create integration config export
mkdir -p /etc/mrhis-integration
cat > /etc/mrhis-integration/idm-config.sh <<'IDM_CONFIG'
#!/bin/bash
# IdM Configuration for MRHIS Integration
export IDM_DOMAIN="${IDM_DOMAIN}"
export IDM_REALM="${IDM_REALM}"
export IDM_HOSTNAME="${IDM_HOSTNAME}"
export IDM_IP="${IDM_IP}"
export IDM_ADMIN_USER="admin"
# Satellite LDAP integration
export SAT_LDAP_URL="ldap://${IDM_HOSTNAME}:389"
export SAT_LDAP_BASE_DN="dc=$(echo ${IDM_DOMAIN} | tr '.' '\n' | sed 's/^/dc=/g' | paste -sd, -)"
export SAT_LDAP_AUTH_SOURCE_TYPE="LDAP"
# AAP LDAP integration
export AAP_LDAP_URL="ldaps://${IDM_HOSTNAME}:636"
export AAP_LDAP_BIND_DN="uid=aap-svc,cn=users,cn=accounts,\\${SAT_LDAP_BASE_DN}"
export AAP_LDAP_START_TLS=true
IDM_CONFIG

chmod 0640 /etc/mrhis-integration/idm-config.sh

# --- 5.1.11 Certificate Management for TLS/SSL ---
echo "Verifying TLS certificate configuration..."

# IdM automatically creates certificates; verify they exist
if [ -f /etc/ipa/ca.crt ]; then
    echo "✓ IdM CA certificate present: /etc/ipa/ca.crt"
    
    # Export CA cert for use by other components
    mkdir -p /usr/local/share/ca-certificates/mrhis
    cp /etc/ipa/ca.crt /usr/local/share/ca-certificates/mrhis/idm-ca.crt
    update-ca-trust 2>/dev/null || update-ca-certificates 2>/dev/null || true
    echo "✓ IdM CA installed in system trust store"
else
    echo "⚠ IdM CA certificate not found"
fi

# --- 5.1.12 Health Check & Verification ---
echo "Running IdM health checks..."

# Check IdM status
ipactl status 2>/dev/null | head -20 || echo "⚠ ipactl status unavailable"

# Verify LDAP connectivity
ldapsearch -x -H "ldap://${IDM_HOSTNAME}" -s base -b "" namingContexts >/dev/null 2>&1 && echo "✓ LDAP responding" || echo "⚠ LDAP check skipped"

# Verify DNS resolution
nslookup -type=SRV _kerberos._tcp.${IDM_DOMAIN} ${IDM_IP} 2>/dev/null | grep -q "kerberos" && echo "✓ Kerberos SRV records present" || echo "⚠ Kerberos SRV records check skipped"

# Verify HTTP/HTTPS APIs
curl -ksSf -u admin:${IDM_ADMIN_PASS} https://${IDM_HOSTNAME}/ipa/json 2>/dev/null && echo "✓ IdM JSON API responding" || echo "⚠ IdM JSON API check skipped"

echo "=== IDM SERVER POST-INSTALL CONFIGURATION COMPLETE ==="
echo "  ✓ User Groups: mrhis-admins, content-managers, automation-engineers, system-services"
echo "  ✓ Users: satellite-svc, aap-svc, mrhis-operator"
echo "  ✓ Password Policy: 12-char min, 365-day expiry, quality enforcement"
echo "  ✓ HBAC Rules: SSH access control for admins and automation"
echo "  ✓ SUDO Rules: Full admin access, limited content manager access"
echo "  ✓ DNS Services: Zone configured, forwarders enabled"
echo "  ✓ SSH Keys: Key management infrastructure ready"
echo "  ✓ Kerberos: Realm ${IDM_REALM} active"
echo "  ✓ LDAP: Configured with replication parameters"
echo "  ✓ TLS/SSL: CA certificate installed in system trust"
echo "  ✓ Integration: Satellite/AAP config exported to /etc/mrhis-integration/"

${ks_perf_network_snapshot}
%end
POSTEOF

    write_file_if_changed "$tmp_ks" "$ks_file" 0644 || return 1
    validate_kickstart_integrity "$ks_file" "IdM kickstart" || return 1
    print_success "Generated IdM kickstart: $ks_file"
}

generate_gittea_kickstart() {
    local ks_file="${KS_DIR}/gittea.ks"
    local tmp_ks
    local gittea_ext_mac gittea_int_mac gittea_prefix
    local root_pass_hash admin_pass_hash
    local bootstrap_ssh_keys
    local ks_nogpg_policy ks_ssh_baseline ks_user_sudo_bootstrap ks_rhsm_register ks_rhc_connect ks_repo_enable_verify ks_nm_dual_nic ks_hosts_mapping ks_trust_bootstrap_keys ks_creator_baseline ks_runtime_exports ks_perf_network_snapshot

    rm -f "${ks_file}" 2>/dev/null || true
    normalize_shared_env_vars
    ensure_ssh_keys >/dev/null 2>&1 || true

    gittea_ext_mac="$(get_vm_external_mac "gittea")"
    gittea_int_mac="$(get_vm_internal_mac "gittea")"
    gittea_prefix="$(netmask_to_prefix "${GITTEA_NETMASK:-${SAT_NETMASK:-255.255.0.0}}")"

    root_pass_hash="$(kickstart_password_hash "${ROOT_PASS:-${ADMIN_PASS}}")" || return 1
    admin_pass_hash="$(kickstart_password_hash "${GITTEA_ADMIN_PASS:-${ADMIN_PASS}}")" || return 1

    prepare_kickstart_shared_blocks "gittea" "${GITTEA_HOSTNAME:-gittea.${DOMAIN:-localdomain}}" "${GITTEA_IP:-10.168.128.4}" \
        "${gittea_ext_mac}" "${gittea_int_mac}" "${GITTEA_IP:-10.168.128.4}" "${gittea_prefix}" "${GITTEA_GW:-${SAT_GW:-}}" 0 0 "Gitea" "rhel-10-for-x86_64-baseos-rpms" || true

    # Populate shared kickstart fragments (parity with other node kickstarts)
    bootstrap_ssh_keys="$(collect_bootstrap_public_keys)"
    if [ -z "${bootstrap_ssh_keys:-}" ]; then
        print_error "No bootstrap SSH public keys found. Ensure MRHIS installer key exists and re-run."
        return 1
    fi
    ks_runtime_exports="$(kickstart_runtime_exports_block "${bootstrap_ssh_keys}")"
    ks_nogpg_policy="${MRHIS_KS_NOGPG_POLICY}"
    ks_ssh_baseline="${MRHIS_KS_SSH_BASELINE}"
    ks_user_sudo_bootstrap="${MRHIS_KS_USER_SUDO_BOOTSTRAP}"
    ks_rhsm_register="${MRHIS_KS_RHSM_REGISTER}"
    ks_rhc_connect="${MRHIS_KS_RHC_CONNECT}"
    ks_repo_enable_verify="${MRHIS_KS_REPO_ENABLE_VERIFY}"
    ks_nm_dual_nic="${MRHIS_KS_NM_DUAL_NIC}"
    ks_hosts_mapping="$(kickstart_hosts_mapping_block "${SAT_IP}" "${SAT_HOSTNAME}" "${SAT_HOSTNAME%%.*}" "${AAP_IP}" "${AAP_HOSTNAME}" "${AAP_HOSTNAME%%.*}" "${IDM_IP}" "${IDM_HOSTNAME}" "${IDM_HOSTNAME%%.*}")"
    ks_trust_bootstrap_keys="${MRHIS_KS_TRUST_BOOTSTRAP_KEYS}"
    ks_creator_baseline="${MRHIS_KS_CREATOR_BASELINE}"
    ks_perf_network_snapshot="$(kickstart_perf_network_snapshot_block)"

    tmp_ks="$(mktemp)"

    cat > "$tmp_ks" <<HEADER
text
reboot
keyboard us
lang en_US.UTF-8
selinux --permissive
firewall --disabled
bootloader --append="net.ifnames=0 biosdevname=0"

rootpw --iscrypted "${root_pass_hash}"
user --name="${ADMIN_USER}" --password="${admin_pass_hash}" --iscrypted --groups=wheel

network --bootproto=dhcp --device=eth0 --interfacename=eth0:${gittea_ext_mac} --activate --onboot=yes

%include /tmp/network-eth1

HEADER

    build_internal_kickstart_network_line "eth1" "${gittea_int_mac}" "${GITTEA_IP:-10.168.128.4}" "${GITTEA_NETMASK:-${SAT_NETMASK:-255.255.0.0}}" "${GITTEA_GW:-${SAT_GW:-}}" "${GITTEA_HOSTNAME:-gittea.${DOMAIN:-localdomain}}" >> "$tmp_ks"

    if is_demo; then
        cat >> "$tmp_ks" <<'DEMO_PART'
# DEMO Partitioning — minimal footprint for Gitea
zerombr
clearpart --all --initlabel
part biosboot --fstype="biosboot" --size=1
part /boot --fstype="xfs"  --size=2048
part swap                   --size=4096
part /     --fstype="xfs"  --grow --size=1

DEMO_PART
    else
        cat >> "$tmp_ks" <<'STD_PART'
# Standard partitioning for Gitea hosts
zerombr
clearpart --all --initlabel
part biosboot --fstype="biosboot" --size=1
part /boot --fstype="xfs" --size=2048
part swap  --size=8192
part pv.01 --grow --size=1
volgroup vg_system pv.01
logvol /    --fstype="xfs" --name=lv_root --vgname=vg_system --size=20480
logvol /var --fstype="xfs" --name=lv_var  --vgname=vg_system --grow --size=1

STD_PART
    fi

    cat >> "$tmp_ks" <<'PKGS'
%packages
@Base
@Core
git
nginx
openssh-server
curl
sudo
python3
%end

PKGS

    cat >> "$tmp_ks" <<POSTEOF
%post --log=/root/ks-post.log
set -euo pipefail
set -x

ks_log() { local ts; ts=$(date +%H:%M:%S 2>/dev/null || echo "--:--:--"); printf '\n[MRHIS %s] %s\n' "\$ts" "\$*" | tee /dev/console 2>/dev/null || true; }
trap 'ec=\$?; ks_log "FAILED at line \${LINENO} (exit code \${ec}) -- see /root/ks-post.log"; exit \${ec}' ERR

${ks_runtime_exports}

${ks_nogpg_policy}

${ks_nm_dual_nic}

${ks_hosts_mapping}

${ks_ssh_baseline}

${ks_user_sudo_bootstrap}

${ks_trust_bootstrap_keys}

${ks_rhsm_register}

${ks_rhc_connect}

${ks_creator_baseline}

systemctl enable --now sshd || true

%end
POSTEOF

    write_file_if_changed "$tmp_ks" "$ks_file" 0644 || return 1
    validate_kickstart_integrity "$ks_file" "Gitea kickstart" || return 1
    print_success "Generated Gitea kickstart: $ks_file"
}

