        version: "*"
    - name: "redhat.satellite"
        version: "*"
    - name: "redhat.satellite_operations"
        version: "*"
EOF
        fi

        if [ ! -f "${container_requirements_txt}" ]; then
                print_step "Bootstrapping missing artifact: local/requirements.txt"
                cat > "${container_requirements_txt}" <<'EOF'
requests>=2.28.0
jinja2>=3.0.0
PyYAML>=6.0
paramiko>=2.12.0
