check_missing_installer_host_ansible_collections() {
    local c
    local -a collections
    local -a missing=()
    local timeout_sec=20
    local collection_list_cache=""

    mapfile -t collections < <(mrhis_required_ansible_collections)

    if ! command -v ansible-galaxy >/dev/null 2>&1; then
        print_warning "ansible-galaxy is not installed yet; collection visibility check skipped."
        print_warning "Expected required collections (${#collections[@]}):"
        for c in "${collections[@]}"; do
            echo "  - ${c}"
        done
        return 0
    fi

    print_step "Pre-flight: checking installer-host required collections (timeout: ${timeout_sec}s)"
    collection_list_cache="$(timeout ${timeout_sec} ansible-galaxy collection list 2>/dev/null | awk '{print $1}' || true)"

    for c in "${collections[@]}"; do
        if ! echo "${collection_list_cache}" | grep -qx "${c}"; then
            missing+=("${c}")
        fi
    done

    if [ "${#missing[@]}" -eq 0 ]; then
        print_success "Pre-flight collection visibility: all required collections are already installed."
    else
        print_warning "Pre-flight collection visibility: ${#missing[@]} missing collection(s):"
        for c in "${missing[@]}"; do
            echo "  - ${c}"
        done
    fi

    return 0
}

ensure_installer_host_ansible_collections() {
    local cfg
    local c
    local installed=0
    local failed=0
    local server
    local -a collections
    local collection_list_cache=""
    local timeout_sec=30
    local req_timeout_sec=120
    local container_requirements_yml="${SCRIPT_DIR}/local/requirements.yml"
    local container_requirements_txt="${SCRIPT_DIR}/local/requirements.txt"

    print_step "Ensuring installer-host requirements and Ansible collections are installed"

    if ! command -v ansible-galaxy >/dev/null 2>&1; then
        print_step "Installing ansible-core for host-side collection management"
        sudo dnf install -y --nogpgcheck ansible-core || return 1
    fi

    generate_mrhis_ansible_cfg || true
    cfg="${MRHIS_ANSIBLE_CFG_HOST}"

    # Install consolidated container requirements in the same startup phase as
    # collection verification so all dependencies are aligned.
    if [ -f "${container_requirements_yml}" ]; then
        print_step "Installing Ansible collections from ${container_requirements_yml}"
        if timeout ${req_timeout_sec} bash -c "ANSIBLE_CONFIG='${cfg}' ansible-galaxy collection install -r '${container_requirements_yml}'" >/dev/null 2>&1; then
            print_success "Applied collection requirements from local/requirements.yml"
        else
            print_warning "Could not fully apply ${container_requirements_yml}; continuing with per-collection verification."
        fi
    else
        print_warning "Collection requirements file not found: ${container_requirements_yml}"
    fi

    if [ -f "${container_requirements_txt}" ]; then
        local req_line req_spec
        local py_ok=0
        local py_failed=0
        local failed_file="${SCRIPT_DIR}/failed_packages.txt"

        print_step "Installing Python requirements line-by-line from ${container_requirements_txt} (robust fallback strategy)"
        : > "${failed_file:-/dev/null}"

        while IFS= read -r req_line || [ -n "${req_line}" ]; do
            # Strip inline comments and trim whitespace.
            req_spec="$(printf '%s' "${req_line}" | sed -E 's/[[:space:]]*#.*$//' | xargs)"
            [ -n "${req_spec}" ] || continue

            # Workaround: ansible/ansible-core are installer-host managed via dnf;
            # avoid pip resolver issues on newer Python runtimes.
            case "${req_spec}" in
                ansible*|ansible-core*)
                    print_step "Skipping pip install for ${req_spec} (managed by ansible-core package on host)."
                    continue
                    ;;
            esac

            # Use robust installation with fallback strategy
            if install_package_with_fallback "${req_spec}"; then
                py_ok=$((py_ok + 1))
            else
                py_failed=$((py_failed + 1))
                printf '%s\n' "${req_spec}" >> "${failed_file}"
            fi
        done < "${container_requirements_txt}"

        if [ "${py_failed}" -eq 0 ]; then
            print_success "Applied Python requirements from local/requirements.txt (ok=${py_ok})."
            rm -f "${failed_file}" >/dev/null 2>&1 || true
        else
            print_warning "Python requirements completed with ${py_failed} unresolved package(s)."
            print_warning "Failed package list saved to: ${failed_file}"
            print_warning "Workaround: install remaining entries manually, or adjust versions for this host Python runtime."
        fi
    else
        print_warning "Python requirements file not found: ${container_requirements_txt}"
    fi

    # Required collections (normalized, unique, and alphabetically sorted).
    # NOTE: `eda_configuration` has been normalized to `infra.eda_configuration`.
    mapfile -t collections < <(mrhis_required_ansible_collections)

    # Cache collection list once with timeout to avoid repeated Galaxy queries
    print_step "Querying local Ansible collection cache (timeout: ${timeout_sec}s)..."
    collection_list_cache="$(timeout ${timeout_sec} ansible-galaxy collection list 2>/dev/null | awk '{print $1}' || true)"

    for c in "${collections[@]}"; do
        # Check cached list first (no network)
        if echo "${collection_list_cache}" | grep -qx "${c}"; then
            continue
        fi

        # Try to install from each server with timeout
        for server in published validated community_galaxy; do
            print_step "Attempting to install ${c} from ${server}..."
            if timeout ${timeout_sec} bash -c "ANSIBLE_CONFIG='${cfg}' ansible-galaxy collection install '${c}' --server '${server}'" >/dev/null 2>&1; then
                installed=$((installed + 1))
                print_step "  ✓ Installed ${c}"
                break
            fi
        done

        # Final check with timeout to see if collection is now available
        if ! timeout ${timeout_sec} ansible-galaxy collection list 2>/dev/null | awk '{print $1}' | grep -qx "${c}"; then
            failed=$((failed + 1))
            print_warning "Collection install unresolved on installer host: ${c} (tried published/validated/community_galaxy)"
        fi
    done

    if [ "${failed}" -eq 0 ]; then
        print_success "Installer-host collections verified (installed new: ${installed})."
    else
        print_warning "Installer-host collection check complete with ${failed} unresolved collection(s). Consider installing manually: ansible-galaxy collection install -r requirements.yml"
    fi

    return 0
}

# Robust pip package installation with fallback strategy:
# 1. Try: pip install --upgrade --user <package>
# 2. Fallback 1: Try installing base package without version
# 3. Fallback 2: Try: dnf install -y --skip-broken --allowerasing --best
# 4. Fallback 3: dnf with base package without version
# Returns 0 on any success; warns on all failures but doesn't exit
install_package_with_fallback() {
    local pkg_spec="$1"
    local pkg_base pkg_version timeout_sec=60
    local use_pip=1

    # Extract base package name (before any version specifier like ==, >=, <=, ~=)
    pkg_base="$(printf '%s' "${pkg_spec}" | sed -E 's/[><=!~].*//')"

    if [ -z "${pkg_spec}" ]; then
        return 0
    fi

    # Step 1: Try pip install --upgrade --user
    if [ "${use_pip}" -eq 1 ] && command -v pip3 >/dev/null 2>&1; then
        if timeout ${timeout_sec} pip3 install --upgrade --user "${pkg_spec}" >/dev/null 2>&1; then
            print_step "✓ Installed (pip): ${pkg_spec}"
            return 0
        fi

        # Fallback 1: Try base package without version via pip
        if [ "${pkg_base}" != "${pkg_spec}" ]; then
            if timeout ${timeout_sec} pip3 install --upgrade --user "${pkg_base}" >/dev/null 2>&1; then
                print_step "✓ Installed (pip base): ${pkg_base}"
                return 0
            fi
        fi

        # Fallback 2: Try via sudo python3 -m pip
        if timeout ${timeout_sec} sudo python3 -m pip install --upgrade --user "${pkg_spec}" >/dev/null 2>&1; then
            print_step "✓ Installed (sudo pip): ${pkg_spec}"
            return 0
        fi
    fi

    # Step 2: Try dnf install with skip-broken and allowerasing
    if command -v dnf >/dev/null 2>&1; then
        # First try with specific version
        if timeout ${timeout_sec} sudo dnf install -y --skip-broken --allowerasing --best "${pkg_spec}" >/dev/null 2>&1; then
            print_step "✓ Installed (dnf): ${pkg_spec}"
            return 0
        fi

        # Fallback 3: Try base package without version via dnf
        if [ "${pkg_base}" != "${pkg_spec}" ]; then
            if timeout ${timeout_sec} sudo dnf install -y --skip-broken --allowerasing --best "${pkg_base}" >/dev/null 2>&1; then
                print_step "✓ Installed (dnf base): ${pkg_base}"
                return 0
            fi
        fi
    fi

    local _mrhis_pkg_display="${pkg_spec:-<unspecified>}"
    print_warning "Could not install package (tolerated failure): ${_mrhis_pkg_display}; to debug run: sudo dnf install ${_mrhis_pkg_display} or check /var/log/dnf.log"
    return 0  # Tolerate failure
}

# Robust dnf package installation with fallback strategy:
# 1. Try: dnf install -y --skip-broken --allowerasing --best <package>
# 2. If version specified and fails, retry with base package without version
# Returns 0 on success; tolerates failures
install_dnf_package_with_fallback() {
    local pkg_spec="$1"
    local pkg_base timeout_sec=60

    if [ -z "${pkg_spec}" ]; then
        return 0
    fi

    # Extract base package name
    pkg_base="$(printf '%s' "${pkg_spec}" | sed -E 's/[><=!~].*//')"

    # Try with skip-broken and allowerasing
    if timeout ${timeout_sec} sudo dnf install -y --skip-broken --allowerasing --best "${pkg_spec}" >/dev/null 2>&1; then
        print_step "✓ Installed (dnf): ${pkg_spec}"
        return 0
    fi

    # If version specified and that failed, retry with base package
    if [ "${pkg_base}" != "${pkg_spec}" ]; then
        if timeout ${timeout_sec} sudo dnf install -y --skip-broken --allowerasing --best "${pkg_base}" >/dev/null 2>&1; then
            print_step "✓ Installed (dnf base): ${pkg_base}"
            return 0
        fi
    fi

    local _mrhis_pkg_display="${pkg_spec:-<unspecified>}"
    print_warning "Could not install package (tolerated failure): ${_mrhis_pkg_display}; to debug run: sudo dnf install ${_mrhis_pkg_display} or check /var/log/dnf.log"
    return 0  # Tolerate failure
}

# Warn if the ansible-vault password file is world-readable.
warn_insecure_vaultpass_perms() {
    if [ -z "${ANSIBLE_VAULT_PASS_FILE:-}" ]; then
        return 0
    fi
    if [ ! -f "${ANSIBLE_VAULT_PASS_FILE}" ]; then
        return 0
    fi
    local perms last
    perms="$(stat -c "%a" "${ANSIBLE_VAULT_PASS_FILE}" 2>/dev/null || true)"
    [ -n "${perms}" ] || return 0
    last="${perms: -1}"
    # Check world-read bit (octal digit & 4)
    if [ -n "${last}" ] && [ $((10#${last} & 4)) -ne 0 ]; then
        print_warning "ANSIBLE vault password file ${ANSIBLE_VAULT_PASS_FILE} is world-readable; recommended perms: 0600"
        # Attempt to harden the file permissions when possible (non-destructive)
        if chmod 0600 "${ANSIBLE_VAULT_PASS_FILE}" 2>/dev/null; then
            print_step "Adjusted permissions to 0600 for ${ANSIBLE_VAULT_PASS_FILE}"
        else
            # If chmod failed, provide actionable guidance to the operator
            if [ -w "${ANSIBLE_VAULT_PASS_FILE}" ] || [ "$(stat -c "%U" "${ANSIBLE_VAULT_PASS_FILE}" 2>/dev/null)" = "${USER:-$(whoami)}" ]; then
                print_warning "Could not modify permissions for ${ANSIBLE_VAULT_PASS_FILE}; run: chmod 0600 ${ANSIBLE_VAULT_PASS_FILE}"
            else
                print_warning "Insufficient permissions to modify ${ANSIBLE_VAULT_PASS_FILE}; run: sudo chmod 0600 ${ANSIBLE_VAULT_PASS_FILE}"
            fi
        fi
    fi
}

# Ensure SSH helper functions are always available, even if earlier optional
# setup blocks that historically defined them were skipped.
if ! declare -f mrhis_ssh_exec >/dev/null 2>&1; then
    mrhis_ssh_exec() {
        local _user="$1" _host="$2" _pass="$3" _cmd="$4" _extra_opts="${5:-}"
        local _allow_password_fallback="${MRHIS_ALLOW_SSHPASS:-0}"
        [ -n "${_user}" ] || return 1
        [ -n "${_host}" ] || return 1
        [ -n "${_cmd}" ] || return 1

        if is_demo; then
            _allow_password_fallback=1
        fi

        local _ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ForwardX11=no -o ConnectTimeout=10"
        if [ -n "${_extra_opts}" ]; then
            _ssh_opts="${_extra_opts} ${_ssh_opts}"
        fi

        local _key_path="${MRHIS_INSTALLER_SSH_PRIVATE_KEY:-${HOME}/.ssh/id_rsa}"
        if [ -n "${_key_path}" ] && [ -f "${_key_path}" ]; then
            if ssh -i "${_key_path}" -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
                return 0
            fi
        fi

        if ssh -o BatchMode=yes ${_ssh_opts} "${_user}@${_host}" "${_cmd}"; then
            return 0
        fi

        if [ "${_allow_password_fallback}" != "1" ]; then
            return 1
        fi

        if [ -n "${_pass}" ] && command -v sshpass >/dev/null 2>&1; then
            sshpass -p "${_pass}" ssh ${_ssh_opts} "${_user}@${_host}" "${_cmd}"
            return $?
        fi
        return 1
    }
fi

if ! declare -f mrhis_ssh_copy_id >/dev/null 2>&1; then
    mrhis_ssh_copy_id() {
        local _pubkey="$1" _user="$2" _host="$3" _pass="$4"
        local _allow_password_fallback="${MRHIS_ALLOW_SSHPASS:-0}"
        [ -n "${_pubkey}" ] || return 1
        [ -f "${_pubkey}" ] || return 1
        [ -n "${_user}" ] || return 1
        [ -n "${_host}" ] || return 1

        if is_demo; then
            _allow_password_fallback=1
        fi

        if ssh -o BatchMode=yes -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "${_user}@${_host}" 'true' >/dev/null 2>&1; then
            return 0
        fi

        if command -v ssh-copy-id >/dev/null 2>&1 && [ "${_allow_password_fallback}" = "1" ] && [ -n "${_pass}" ]; then
            sshpass -p "${_pass}" ssh-copy-id -i "${_pubkey}" -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "${_user}@${_host}" >/dev/null 2>&1 || return 1
            return 0
        fi

        local _pub
        _pub="$(sed -n '1p' "${_pubkey}" 2>/dev/null || true)"
        if [ -z "${_pub}" ]; then
            return 1
        fi
        if mrhis_ssh_exec "${_user}" "${_host}" "${_pass}" "mkdir -p ~/.ssh && printf '%s\n' '${_pub}' >> ~/.ssh/authorized_keys && chmod 600 ~/.ssh/authorized_keys"; then
            return 0
        fi
        return 1
    }
fi

main() {
    init_mrhis_run_logging
    warn_insecure_vaultpass_perms
    print_mrhis_header

    # Record start time and install an exit handler to print a final summary
    MRHIS_RUN_START_TS="$(date +%s)"
    on_mrhis_exit() {
        local rc=$?
        MRHIS_LAST_EXIT_CODE="$rc"
        # Avoid running summary for quick CLI-only demokill path or when
        # the user explicitly exited the interactive menu (choice 0).
        if [ -n "${CLI_DEMOKILL:-}" ] || [ -n "${MRHIS_EXITED_VIA_MENU:-}" ]; then
            return ${rc}
        fi

        echo ""
        print_step "Final summary: collecting run results and duration"
        # Print health summary and test summary if functions are available
        if declare -f print_mrhis_health_summary >/dev/null 2>&1; then
            print_mrhis_health_summary || true
        fi
        if declare -f mrhis_test_print_summary >/dev/null 2>&1; then
            mrhis_test_print_summary "${rc}" || true
        fi

        if [ -n "${MRHIS_RUN_START_TS:-}" ]; then
            local end_ts
            end_ts="$(date +%s)"
            local elapsed
            elapsed=$((end_ts - MRHIS_RUN_START_TS))
            # Format elapsed as H:MM:SS
            local hours minutes seconds
            hours=$(( elapsed / 3600 ))
            minutes=$(( (elapsed % 3600) / 60 ))
            seconds=$(( elapsed % 60 ))
            printf "Run duration: %02d:%02d:%02d (HH:MM:SS)\n" "$hours" "$minutes" "$seconds"
        fi

        return ${rc}
    }
    trap on_mrhis_exit EXIT

    parse_args "$@"
    apply_cli_overrides

    # If the caller requested --reconfigure together with component/shortcut
    # flags (e.g. --DEMO --rhis --reconfigure) we should run the
    # prompts-only reconfigure first (without dropping to the main menu),
    # then continue automatically into the requested install as a
    # non-interactive one-shot. Respect an explicit --non-interactive flag
    # from the caller (do not force interactive prompts in that case).
    if [ -n "${CLI_RECONFIGURE:-}" ] && [ -n "${CLI_MRHIS:-}${CLI_SATELLITE:-}${CLI_IDM:-}${CLI_AAP:-}${CLI_GITTEA:-}${CLI_CONFIG_SCOPE:-}" ]; then
        print_step "CLI: running reconfigure (prompts-only) before continuing to requested install"
        # Allow interactive prompting unless the caller explicitly asked
        # for non-interactive mode via --non-interactive.
        if [ -z "${CLI_NONINTERACTIVE:-}" ]; then
            NONINTERACTIVE=0
        fi
        FORCE_PROMPT_ALL=1
        prompts_only_workflow || { print_warning "Prompts-only workflow failed"; exit 1; }

        # Ensure any written vault/env values are loaded and normalized
        if [ -f "${ANSIBLE_ENV_FILE}" ]; then
            load_ansible_env_file || true
        fi
        normalize_shared_env_vars || true

        # After reconfigure completes, immediately perform the requested
        # install(s) in a hands-off, non-interactive one-shot and then exit.
        if [ -z "${CLI_NONINTERACTIVE:-}" ]; then
            NONINTERACTIVE=1
        fi
        RUN_ONCE=1

        # Determine requested install actions in the same precedence used
        # by the interactive menu. If multiple component flags were given
        # run them in a sensible order: full stack first, then any extras.
        local -a _actions=()
        if [ -n "${CLI_MRHIS:-}" ]; then _actions+=(full); fi
        if [ -n "${CLI_SATELLITE:-}" ]; then _actions+=(satellite); fi
        if [ -n "${CLI_IDM:-}" ]; then _actions+=(idm); fi
        if [ -n "${CLI_AAP:-}" ]; then _actions+=(aap); fi
        if [ -n "${CLI_GITTEA:-}" ]; then _actions+=(gittea); fi

        for _act in "${_actions[@]:-}"; do
            case "${_act}" in
                full)
                    run_container_config_only || { print_warning "Full-stack install failed"; exit 1; }
                    ;;
                satellite)
                    install_satellite_only || { print_warning "Satellite-only install failed"; exit 1; }
                    ;;
                idm)
                    install_idm_only || { print_warning "IdM-only install failed"; exit 1; }
                    ;;
                aap)
                    install_aap_only || { print_warning "AAP-only install failed"; exit 1; }
                    ;;
                gittea)
                    install_gittea_only || { print_warning "Gitea-only install failed"; exit 1; }
                    ;;
            esac
        done

        print_success "Reconfigure + requested install(s) complete"
        exit 0
    fi

    # CLI self-test: vault staging and container-readability check
    if [ -n "${CLI_SELFTEST_VAULT:-}" ]; then
        mrhis_selftest_vault_staging || exit $?
        exit 0
    fi

    # CLI-only: run prompts-only secrets setup and exit (interactive only)
    if [ -n "${CLI_SECRETS_SETUP:-}" ]; then
        print_step "CLI: running secrets setup (prompts-only)"
        if is_noninteractive; then
            print_warning "--secrets-setup requires an interactive terminal. Use --generate-env for noninteractive templating."
            exit 1
        fi
        # Force interactive prompts for secrets collection
        NONINTERACTIVE=0
        FORCE_PROMPT_ALL=1
        prompts_only_workflow || { print_warning "Prompts-only workflow failed"; exit 1; }
        print_success "Secrets setup complete"
        exit 0
    fi

    # CLI-only: run Satellite RHSM remediation preflight and exit
    if [ -n "${CLI_REMEDIATE_SATELLITE:-}" ]; then
        # Use the higher-level repair_web_uis wrapper which includes Satellite
        # remediation steps and diagnostics. This is a safer, documented entrypoint.
        repair_web_uis || exit $?
        exit 0
    fi

    # CLI-only: package approvals.env from vaulted env and exit
    if [ -n "${CLI_PACKAGE_APPROVALS:-}" ]; then
        package_approvals_env "${CLI_PACKAGE_APPROVALS_OUTDIR:-${SCRIPT_DIR}/build}" || exit $?
        exit 0
    fi

    if is_menutest; then
        run_menutest_mode
        exit $?
    fi

    # Show entry menu in interactive mode with no explicit action flag set.
    # If a CLI action flag is present we skip the initial entry prompt. Include
    # --reconfigure as an explicit fast-path so callers using it go straight to
    # the main menu/prompts flow (no intermediate entry menu).
    if ! is_noninteractive && \
         [ -z "${CLI_DEMOKILL:-}${CLI_GENERATE_ENV:-}${CLI_VALIDATE:-}${CLI_STATUS:-}${CLI_TEST:-}${CLI_MRHIS:-}${CLI_IDM:-}${CLI_SATELLITE:-}${CLI_AAP:-}${CLI_CONFIG_SCOPE:-}${CLI_RECONFIGURE:-}" ]; then
        show_entry_menu
    fi

    # CLI-only fast path: DEMOKILL should never require env/vault prompts.
    if [ -n "${CLI_DEMOKILL:-}" ]; then
        print_step "DEMOKILL requested from CLI; skipping credential prompts"
        demokill_cleanup || { print_warning "DEMOKILL failed"; exit 1; }
        print_success "Run complete"
        # Optional terminal reset for users who explicitly want it.
        if is_enabled "${MRHIS_DEMOKILL_RESET_TERMINAL:-0}"; then
            command -v reset >/dev/null 2>&1 && reset || true
        fi
        exit 0
    fi

    # CLI-only fast path: write headless env template and exit.
    if [ -n "${CLI_GENERATE_ENV:-}" ]; then
        generate_env_template "${CLI_GENERATE_ENV}"
        exit $?
    fi

    if [ ! -f "$ANSIBLE_ENV_FILE" ]; then
        load_preseed_env
    fi
    # If env.yml can be decrypted, recreate it interactively (backup then re-prompt).
    # Only do this when --reconfigure is explicitly requested; otherwise leave env.yml intact.
    if [ -n "${CLI_RECONFIGURE:-}" ]; then
        recreate_ansible_env_via_prompts_if_decryptable || true
    fi
    load_ansible_env_file || {
        print_warning "Could not load encrypted environment file: ${ANSIBLE_ENV_FILE}"
        if is_noninteractive; then
            print_warning "NONINTERACTIVE mode requires a decryptable vault env file."
            exit 1
        fi
    }
    normalize_shared_env_vars

    # Enforce RULES.md: require internal network IPs to be provided via vaulted env or CLI
    validate_rules_env() {
        # Required variables
        local missing=0
        for v in SAT_IP AAP_IP IDM_IP HOST_INT_IP INTERNAL_NETWORK; do
            if [ -z "${!v:-}" ]; then
                print_error "Required variable '${v}' is not set in ${ANSIBLE_ENV_FILE} or CLI. See docs/RULES.md." >&2
                missing=1
            fi
        done
        if [ "$missing" -eq 1 ]; then
            print_error "Vaulted environment missing required network variables. Run './MRHIS.sh --reconfigure' or populate ${ANSIBLE_ENV_FILE} via ansible-vault." >&2
            exit 2
        fi

        # Enforce internal network space (10.168.x.x) as required by RULES.md
        case "${SAT_IP}" in 10.168.*) ;; *) print_error "SAT_IP='${SAT_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac
        case "${AAP_IP}" in 10.168.*) ;; *) print_error "AAP_IP='${AAP_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac
        case "${IDM_IP}" in 10.168.*) ;; *) print_error "IDM_IP='${IDM_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac
        case "${HOST_INT_IP}" in 10.168.*) ;; *) print_error "HOST_INT_IP='${HOST_INT_IP}' is outside 10.168.x.x; aborting per RULES.md."; exit 3 ;; esac

        # Ensure INTERNAL_NETWORK is the canonical 10.168.0.0/16 (or starts with 10.168.)
        case "${INTERNAL_NETWORK}" in 10.168.*) ;; *) print_error "INTERNAL_NETWORK='${INTERNAL_NETWORK}' is not a 10.168.* network; aborting per RULES.md."; exit 3 ;; esac

        return 0
    }

    validate_rules_env || true

    # CLI-only fast path: run pre-flight validation and exit.
    if [ -n "${CLI_VALIDATE:-}" ]; then
        validate_headless_config
        exit $?
    fi

    ensure_workspace_runtime_layout || {
        print_warning "Could not initialize generated workspace runtime layout."
        exit 1
    }

    if [ -n "${CLI_STATUS:-}" ]; then
        print_phase 1 1 "Read-only status snapshot"
        print_runtime_configuration
        print_mrhis_health_summary
        MRHIS_DASHBOARD_SINGLE_SHOT=1
        show_live_status_dashboard || true
        MRHIS_DASHBOARD_SINGLE_SHOT=0
        print_success "Status snapshot complete"
        exit 0
    fi

    if [ -n "${CLI_STATUS_LIVE:-}" ]; then
        print_phase 1 1 "Live status dashboard"
        print_runtime_configuration
        print_mrhis_health_summary
        MRHIS_DASHBOARD_SINGLE_SHOT=0
        show_live_status_dashboard || true
        print_success "Live status dashboard closed"
        exit 0
    fi

    # CLI-only fast path: reopen VM console monitors without prompts.
    if [ -n "${CLI_ATTACH_CONSOLES:-}" ]; then
        print_phase 1 1 "Reattach VM console monitors"
        ensure_libvirt_access || print_warning "libvirt access check failed; console reattach may not work until access is fixed."
        launch_progress_dashboard_auto || true
        reattach_vm_consoles || {
            print_warning "Console reattach failed"
            exit 1
        }
        print_success "Console reattach request complete"
        exit 0
    fi

    # Component-specific CLI workflows: only prompt for component-specific vars
    # Note: --mrhis (full stack) is treated as non-component mode
    if { [ -z "$CLI_IDM" ] && [ -z "$CLI_SATELLITE" ] && [ -z "$CLI_AAP" ] && [ -z "${CLI_CONFIG_SCOPE:-}" ]; } || \
       [ -n "$CLI_MRHIS" ] || [ "${CLI_CONFIG_SCOPE:-}" = "all" ]; then
        # Full stack or menu-driven mode: prompt for all values
        if ! prompt_all_env_options_once; then
            if is_demo; then
                print_warning "Configuration bootstrap failed; DEMO mode tolerates missing values; continuing (not for production)."
            else
                print_warning "Configuration bootstrap failed; aborting run."
                exit 1
            fi
        fi
    else
        # Component-specific mode: load env file and let component handle its own prompting
        if [ -f "$ANSIBLE_ENV_FILE" ]; then
            load_ansible_env_file || {
                print_warning "Could not load encrypted env file; running full prompts instead"
                if ! prompt_all_env_options_once; then
                    if is_demo; then
                        print_warning "Configuration bootstrap failed; DEMO mode tolerates missing values; continuing (not for production)."
                    else
                        print_warning "Configuration bootstrap failed; aborting run."
                        exit 1
                    fi
                fi
            }
        else
            # No env file yet; run full prompts to bootstrap
            if ! prompt_all_env_options_once; then
                if is_demo; then
                    print_warning "Configuration bootstrap failed; DEMO mode tolerates missing values; continuing (not for production)."
                else
                    print_warning "Configuration bootstrap failed; aborting run."
                    exit 1
                fi
            fi
        fi
    fi
    MRHIS_PROMPTS_COMPLETED=1
    FORCE_PROMPT_ALL=0
    normalize_shared_env_vars

    if ! startup_env_precheck; then
        print_warning "Startup precheck failed: required environment values are still missing."
        exit 1
    fi

    retire_preseed_env_file
    print_runtime_configuration

	print_step "Startup: Checking libvirtd"
	ensure_libvirtd || { print_warning "libvirtd check failed"; exit 1; }

    # Verify the installer user can talk to the system libvirt socket and
    # attempt automated remediation when possible (group membership / polkit).
    ensure_libvirt_access || print_warning "libvirt access check failed; VM creation may fail until access is fixed."

	print_step "Startup: Checking ISO image tools"
	ensure_iso_tools || { print_warning "ISO image tools check failed"; exit 1; }

    print_step "Startup: Ensuring installer-host platform packages"
    ensure_platform_packages_for_virt_manager || { print_warning "Installer-host package check failed"; exit 1; }

    print_step "Startup: Enforcing installer NetworkManager DNS policy for MRHIS"
    ensure_installer_networkmanager_dns || true

    print_step "Startup: Pre-flight collection visibility"
    check_missing_installer_host_ansible_collections || true

    print_step "Startup: Ensuring installer-host Ansible collections"
    ensure_installer_host_ansible_collections || print_warning "Installer-host collection install encountered issues; continuing."

    if [ -n "${CLI_CONFIG_SCOPE:-}" ]; then
        print_phase 1 1 "Config-as-code role execution (${CLI_CONFIG_SCOPE})"
        case "${CLI_CONFIG_SCOPE}" in
            idm|satellite|aap|gittea|openshift|openstack|rhis-aap)
                run_component_config_scope "${CLI_CONFIG_SCOPE}" || {
                    print_warning "Config-as-code execution failed for scope: ${CLI_CONFIG_SCOPE}"
                    exit 1
                }
                ;;
            all|rhis|fullstack)
                if [ "${MRHIS_EXECUTION_MODE:-local}" = "container" ]; then
                    install_container || {
                        print_warning "Could not initialize provisioner container for config-as-code."
                        exit 1
                    }
                fi
                MRHIS_COMPONENT_SCOPE="${CLI_CONFIG_SCOPE}" run_mrhis_config_as_code || {
                    print_warning "Config-as-code execution failed for full stack scope."
                    exit 1
                }
                ;;
            *)
                print_warning "Unknown --config scope: ${CLI_CONFIG_SCOPE}"
                exit 1
                ;;
        esac
        print_success "Run complete"
        exit 0
    fi

    if [ -n "${CLI_TEST:-}" ]; then
        if mrhis_run_test_suite; then
            print_success "Run complete"
            exit 0
        fi
        exit 1
    fi

	while true; do
        prompt_deployment_scope
        case "$?" in
            2)
                command -v clear >/dev/null 2>&1 && clear
                echo "Exiting installation script"
                MRHIS_EXITED_VIA_MENU=1
                exit 0
                ;;
        esac

        if is_enabled "${MRHIS_GUIDED_SCOPE_FLOW:-0}"; then
            run_guided_scope_workflow
            case "$?" in
                0)
                    print_success "Run complete"
                    exit 0
                    ;;
                10)
                    DEPLOYMENT_SCOPE_PROMPTED=0
                    continue
                    ;;
                *)
                    print_warning "Guided deployment workflow failed"
                    exit 1
                    ;;
            esac
        fi

		reset_menu_view
		show_menu
        case "$choice" in
            1)
                show_platform_selection_submenu || { print_warning "Platform selection failed"; exit 1; }
                ;;
            2)
                configure_installer_rhel10_fedora || { print_warning "Configure installer failed"; exit 1; }
                ;;
            3)
                show_full_stack_build_submenu || { print_warning "Full stack build failed"; exit 1; }
                ;;
            4)
                show_install_components_submenu || { print_warning "Install components submenu failed"; exit 1; }
                ;;
            5)
                show_configure_components_csv_menu || { print_warning "Configure-only components workflow failed"; exit 1; }
                ;;
            6)
                FORCE_PROMPT_ALL=1
                prompts_only_workflow || { print_warning "Prompts-only workflow failed"; exit 1; }
                ;;
            7)
                generate_oemdrv_kickstarts_only || { print_warning "Kickstart generation failed"; exit 1; }
                ;;
            8)
                show_documentation_topics_menu || { print_warning "Documentation submenu failed"; exit 1; }
                ;;
            9)
                print_mrhis_health_summary || { print_warning "Report generation failed"; exit 1; }
                ;;
            0)
                command -v clear >/dev/null 2>&1 && clear
                echo "Exiting installation script"
                MRHIS_EXITED_VIA_MENU=1
                exit 0
                ;;
            *) print_warning "Invalid choice. Please select 0-9." ;;
        esac

        reset_menu_view

        if is_noninteractive || [ "${RUN_ONCE:-0}" = "1" ]; then
            # In one-shot/noninteractive runs, only report success after a
            # completed menu action reaches this point without triggering an
            # earlier explicit failure exit path.
            print_success "Run complete"
            exit 0
        fi

		echo ""
	done
}

if [ "${BASH_SOURCE[0]}" = "$0" ]; then
    main "$@"
fi

